-- quest_extra.lua
local ADDON_NAME = ...
OneWoW.CatalogData:Defer(ADDON_NAME, 'quest', function()
return {
[850] = {id=850,name="Kolkar Leaders",level=5,requiredLevel=5,faction="horde",expansion=6,zoneID=17,mapID=10,description="The centaurs have plagued the tauren for years. And recently, the Kolkar centaurs of the Barrens have grown into a real threat. Normally they were disorganized in these lands, but new leaders have risen among them. Rallying them. To preserve our holdings here, these centaur leaders must be destroyed. Bring me the head of Barak Kodobane. He camps west of these Forgotten Pools. Defeat him, then return to me.",starts={{npcID=3389,x=0.378,y=0.552,mapID=10},{npcID=34841,x=0.38,y=0.464,mapID=10}},ends={{npcID=3389,x=0.378,y=0.552,mapID=10},{npcID=34841,x=0.38,y=0.464,mapID=10}},coords={x=0.378,y=0.552,source="quest_giver",mapID=10},questType="standard"},
[10729] = {id=10729,name="Path of the Violet Mage",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=41,mapID=42,starts={{npcID=18253,x=0.472,y=0.75,mapID=42}},ends={{npcID=18253,x=0.472,y=0.75,mapID=42}},coords={x=0.472,y=0.75,source="quest_giver",mapID=42},questType="standard"},
[10730] = {id=10730,name="Path of the Violet Restorer",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=41,mapID=42,starts={{npcID=18253,x=0.472,y=0.75,mapID=42}},ends={{npcID=18253,x=0.472,y=0.75,mapID=42}},coords={x=0.472,y=0.75,source="quest_giver",mapID=42},questType="standard"},
[10731] = {id=10731,name="Path of the Violet Assassin",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=41,mapID=42,starts={{npcID=18253,x=0.472,y=0.75,mapID=42}},ends={{npcID=18253,x=0.472,y=0.75,mapID=42}},coords={x=0.472,y=0.75,source="quest_giver",mapID=42},questType="standard"},
[10732] = {id=10732,name="Path of the Violet Protector",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=41,mapID=42,starts={{npcID=18253,x=0.472,y=0.75,mapID=42}},ends={{npcID=18253,x=0.472,y=0.75,mapID=42}},coords={x=0.472,y=0.75,source="quest_giver",mapID=42},questType="standard"},
[13148] = {id=13148,name="Necklace Repair",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=210,description="This damaged necklace has an invoice with it that reads \"Property of Timothy Jones - Cartier and Co Fine Jewelry - Magus Commerce Exhange - Dalaran\". Perhaps you should repair it and return it to him.",questType="standard"},
[13845] = {id=13845,name="Sealed Vial of Poison",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7078,description="This vial of poison looks particularly dangerous. Perhaps someone in Dalaran might be interested in it.",questType="standard"},
[14127] = {id=14127,name="Return of the Highborne?",level=5,requiredLevel=5,faction="horde",expansion=6,zoneID=16,description="The wax seal on these orders has been freshly broken. You can't read the carefully-penned night elven script, but a small hand-drawn map indicates the nearby ruins. Underneath the map, written in a different language entirely, are a series of runes penned in a metallic, shimmering ink. Ag'tor will no doubt want to see this important piece of intelligence.",ends={{npcID=8576,x=0.268,y=0.77,zoneID=16}},questType="standard"},
[14407] = {id=14407,name="Azshara Blues",level=5,requiredLevel=5,faction="horde",expansion=6,zoneID=16,mapID=76,description="Hey! I'm glad I caught you. I come on behalf of my master, Kalec . He requires your aid. Find him under the bridge in the slums as soon as you can!",starts={{npcID=36999,x=0.594,y=0.506,mapID=76}},ends={{npcID=35867,x=0.554,y=0.52,mapID=76}},coords={x=0.594,y=0.506,source="quest_giver",mapID=76},questType="standard"},
[14428] = {id=14428,name="Amberwind's Journal",level=5,requiredLevel=5,faction="horde",expansion=6,zoneID=16,description="If my sources are trustworthy, Lorekeeper Amberwind is overseeing the Alliance investigation of the ruins to the east. I have not yet probed the extent of her abilities: I'm hoping you can give me a full report by engaging her in combat and destroying her. With a title like 'Lorekeeper,' I'm guessing Amberwind will have a journal on her that'll tell us exactly what those night elves are up to. Fetch that journal for me. No need to run back; use their own scrying stones to contact me remotely.",starts={{npcID=36596,x=0.426,y=0.238,zoneID=16}},ends={{npcID=196832,x=0.495,y=0.287,zoneID=16}},coords={x=0.426,y=0.238,source="quest_giver",zoneID=16},questType="standard"},
[14429] = {id=14429,name="Arcane De-Construction",level=5,requiredLevel=5,faction="horde",expansion=6,zoneID=16,description="Arcane constructs are creatures spawned of pure mana and intellect. In the right hands, a construct allows its user to quickly assimilate vast riches of arcane knowledge. But they're dangerous, . So intelligent! So powerful! So very vulnerable to external tampering... Let's teach these amateurs a lesson and use their own magic against them. Slay Apprentices and collect their runestones for me. Contact me via the lower scrying stone when you're done.",starts={{npcID=196832,x=0.495,y=0.287,zoneID=16}},ends={{npcID=196833,x=0.53,y=0.29,zoneID=16}},coords={x=0.495,y=0.287,source="quest_giver",zoneID=16},questType="standard"},
[14464] = {id=14464,name="Lightning Strike Assassination",level=5,requiredLevel=5,faction="horde",expansion=6,zoneID=16,mapID=76,description="The base of the tower is patrolled by the Captain's elite guards. So here's what we're going to do: we're going to grapple straight up to the top, slice-and-dice the VIPs, and bail out using my portable low-altitude parachute . I'll rig the tower to explode behind us. You be sure to grab Captain Grunwald's head for Chawg . Got it? Do NOT accept this mission unless you are prepared for UNMITIGATED BADASSERY. Is that clear?",starts={{npcID=36729,x=0.12,y=0.682,mapID=76}},ends={{npcID=36730,x=0.14,y=0.648,mapID=76}},coords={x=0.12,y=0.682,source="quest_giver",mapID=76},questType="standard"},
[24455] = {id=24455,name="Rapid Deployment",level=5,requiredLevel=5,faction="horde",expansion=6,zoneID=16,mapID=76,description="You will be reporting for active duty immediately. Captain Desoto is overseeing deployment just down the ramp at the rocket launch station. Make us rich, soldier. Dismissed!",starts={{npcID=36749,x=0.294,y=0.576,mapID=76}},ends={{npcID=36956,x=0.58,y=0.522,mapID=76}},coords={x=0.294,y=0.576,source="quest_giver",mapID=76},questType="standard"},
[24740] = {id=24740,name="Volcanic Activity",level=15,requiredLevel=15,faction="both",expansion=6,zoneID=490,mapID=78,description="Welcome. I'm Williden Marshal , and my sister and I run this expedition of explorers and scientists. You have a moment? I don't like the look of those elementals on that volcano, . We have too much equipment, too many notes... one crazed elemental could streak its way through our camp and do terrible, terrible damage. Show them that their new neighbors aren't to be trifled with. And bring back the ash that they leave behind... we might as well do a little science while we're at it.",starts={{npcID=9270,x=0.55,y=0.622,mapID=78}},ends={{npcID=9270,x=0.55,y=0.622,mapID=78}},coords={x=0.55,y=0.622,source="quest_giver",mapID=78},questType="standard"},
[24854] = {id=24854,name="Finding Stormclaw",level=15,requiredLevel=15,faction="both",expansion=6,zoneID=490,mapID=78,description="Zen'Aliri been studyin' the ways of the druid, . Hopefully one day, Zen'Aliri join the Druids of the Talon, and soar over this crater as a storm crow. But for now, my mentor says I stay here and wait. So Zen'Aliri waits. I know another druid who might be able to use your help. His name is Garl Stormclaw , and he's somewhere to the east of here, studying reagents. Maybe you go talk to him?",starts={{npcID=38269,x=0.556,y=0.606,mapID=78}},ends={{npcID=38274,x=0.71,y=0.766,mapID=78}},coords={x=0.556,y=0.606,source="quest_giver",mapID=78},questType="standard"},
[25234] = {id=25234,name="In the Rear With the Gear",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=1,description="Prisoners of the Twilight's Hammer are forced to lug around sundries for the war effort, like common pack animals. I want those supplies, and if we can free a few poor souls from the Hammer's shadowy grip, all the better. Kill the slave drivers along the road to our south and nearby slaves should make a break for it. Search the packs they leave behind for anything valuable, and destroy anything you can't carry.",starts={{npcID=39427,x=0.356,y=0.196,zoneID=616}},ends={{npcID=39427,x=0.356,y=0.196,zoneID=616}},coords={x=0.356,y=0.196,source="quest_giver",zoneID=616},questType="standard"},
[25274] = {id=25274,name="Signed in Blood",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=616,description="You're here at last, . Just in time as well. News of Ragnaros' emergence has spurred a large wave of recruits to seek membership in the Twilight's Hammer. If you're to infiltrate the cult, the time is now. We will need recruitment papers -- signed in blood by a referring Twilight member. Lure one of the new recruits away from the group and hit them with this blackjack . If you're lucky, you'll be able to steal his recruitment papers. Bring them back to me and we'll do our best to alter them.",starts={{npcID=39621,x=0.718,y=0.58,zoneID=616}},ends={{npcID=39621,x=0.718,y=0.58,zoneID=616}},coords={x=0.718,y=0.58,source="quest_giver",zoneID=616},questType="standard"},
[25276] = {id=25276,name="Your New Identity",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=616,description="There. Not my best work, but certainly not my worst. You will be known as \" damus\" among the cultists. These papers will bump you ahead of the other recruits and allow you to speak directly to the Twilight instructors. Go to the proving grounds and show these to Condenna the Pitiless . She's separating the wheat from the chaff. Show her what you're made of.",starts={{npcID=39621,x=0.718,y=0.58,zoneID=616}},ends={{npcID=39442,x=0.768,y=0.62,zoneID=616}},coords={x=0.718,y=0.58,source="quest_giver",zoneID=616},questType="standard"},
[25296] = {id=25296,name="Gather the Intelligence",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=616,description="It's me, , Ortell! Don't look directly at the outhouse... you'll give away my position. Everything's going according to plan then? Excellent! I'm going to need you to obtain some intelligence while you're here. It might not seem like much to get our hands on a map or a letter, but it may mean saving a hundred lives on our side if we can anticipate our enemy's next move.",starts={{npcID=202701,x=0.883,y=0.585,zoneID=616}},ends={{npcID=202701,x=0.883,y=0.585,zoneID=616}},coords={x=0.883,y=0.585,source="quest_giver",zoneID=616},questType="standard"},
[25297] = {id=25297,name="From the Mouth of Madness",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=616,description="I know of a draught that should jolt these gibbering former slaves back to reality. Gather some stonebloom from the rocks around Gar'gol's hovel, some bitterblossom from the shores of the nearby lake, and a darkflame ember from one of the braziers at the hovel entrance. The draught won't last long, so combine the ingredients at a twilight cauldron by the entrance to the hovel. One sip of that draught should knock some sense into the brainwashed slaves!",starts={{npcID=39434,x=0.282,y=0.298,zoneID=616}},ends={{npcID=202706,x=0.284,y=0.363,zoneID=616}},coords={x=0.282,y=0.298,source="quest_giver",zoneID=616},questType="standard"},
[25298] = {id=25298,name="Free Your Mind, the Rest Follows",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=616,starts={{npcID=202706,x=0.284,y=0.363,zoneID=616}},ends={{npcID=39434,x=0.282,y=0.298,zoneID=616}},coords={x=0.284,y=0.363,source="quest_giver",zoneID=616},questType="standard"},
[25321] = {id=25321,name="Twilight Captivity",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5042,description="I'd been scouting behind enemy lines for nearly a day when they caught me. This attack on our frontlines is not what it appears, . I'll give you all the details, but first let's find a way to get me out of here. Only the overseers carry keys to these cages. From what I recall, they're in the middle of the crater, in the thick of it. See if you can get a key off of one of them.",starts={{npcID=40096,x=0.444,y=0.188,zoneID=616}},ends={{npcID=40096,x=0.444,y=0.188,zoneID=616}},coords={x=0.444,y=0.188,source="quest_giver",zoneID=616},questType="standard"},
[25328] = {id=25328,name="Gar'gol's Gotta Go",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=1,description="Listen, you gotta get me outta here. They're either going to eat me or turn me over to the Twilight's Hammer. Maybe both. They've padlocked me in, and Gar'gol keeps the key in his personal treasure chest. Kill Gar'gol if you have to - but get that key!",starts={{npcID=39640,x=0.272,y=0.408,zoneID=616}},ends={{npcID=39640,x=0.272,y=0.408,zoneID=616}},coords={x=0.272,y=0.408,source="quest_giver",zoneID=616},questType="standard"},
[25358] = {id=25358,name="Nerve Tonic",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=4815,description="How am I feelin', you ask? Well, after bein' yanked from the deck of our ship by a giant sea monster and then left to drown in the sea... not so good! My nerves are gettin' the best of me, to be honest. If you could round up some of the supplies that are sure to be floatin' around the nearby wrecks, I could likely whip up somethin' that'll take the edge off...",starts={{npcID=40983,x=0.572,y=0.292,zoneID=4815}},ends={{npcID=40983,x=0.572,y=0.292,zoneID=4815}},coords={x=0.572,y=0.292,source="quest_giver",zoneID=4815},questType="standard"},
[25372] = {id=25372,name="Aessina's Miracle",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=616,description="Nordu 's burning limbs part, revealing an untouched, glimmering seed.> This is the Heart of the Forest . The seed of life. Take this to your Arch Druid at Aessina's Grove - Hamuul Runetotem will know how to invoke its power. I promise you, the wilderness spirit will be silent no longer. New life will bloom from the ashes of old. Thank you, . My time is done.",starts={{npcID=41381,x=0.274,y=0.554,zoneID=616}},ends={{npcID=39858,x=0.27,y=0.626,zoneID=616}},coords={x=0.274,y=0.554,source="quest_giver",zoneID=616},questType="standard"},
[25377] = {id=25377,name="The Horde's Hoard",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=4815,mapID=201,description="It is unclear what manner of creature scrawled the seemingly random markings on this piece of parchment, but upon close inspection, some of the obscure shapes begin to look like landmarks. Scanning the sea floor, you think you recognize a few points of reference, one being a nearby sunken ship. If your guess is correct, there appears to be treasure of some kind near the wreck. You cannot help but wonder what the scaly, serpentine figure on the map might represent....",ends={{npcID=202759,x=0.579,y=0.352,mapID=201}},questType="standard"},
[25385] = {id=25385,name="Save the Wee Animals",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=616,description="Help us, ! The forest is aflame, and the wee animals can't find their way out. They can't fight for themselves, with their teeny-tiny little teeth and their soft furry paws! They're fluffy and sweet. They have wet little noses! If you don't save them, I don't want to even THINK about it. I'm not thinking!",starts={{npcID=39930,x=0.192,y=0.378,zoneID=616}},ends={{npcID=39930,x=0.192,y=0.378,zoneID=616}},coords={x=0.192,y=0.378,source="quest_giver",zoneID=616},questType="standard"},
[25388] = {id=25388,name="Crate of Crab Meat",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=4815,description="This crate, labeled 'Crab Meat', seems to have fallen from a recently sunken cargo ship. Adarrah would surely welcome such a find, considering the ordeal she's had to endure.",starts={{npcID=202871,x=0.497,y=0.408,zoneID=4815}},ends={{npcID=39883,x=0.57,y=0.288,zoneID=4815}},coords={x=0.497,y=0.408,source="quest_giver",zoneID=4815},questType="standard"},
[25389] = {id=25389,name="A Taste For Tail",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=4815,description="It could be days before we're ready to make our way to the surface, and to be honest, I'm already beginning to get hungry. I hate to be picky, but when it comes to seafood, I'm afraid there are very few things I can stomach. If you come across any lobster types, I would happily pay you what coin I have with me for their tails.",starts={{npcID=39883,x=0.57,y=0.288,zoneID=4815}},ends={{npcID=39883,x=0.57,y=0.288,zoneID=4815}},coords={x=0.57,y=0.288,source="quest_giver",zoneID=4815},questType="standard"},
[25390] = {id=25390,name="A Girl's Best Friend",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=4815,description="Let's just get it out in the open. I'm no stranger to love, . Over the years, if there's one thing I've learned, it's that love's tangible treasures last longer than the flames of passion. I've managed to collect my fair share of these gifts - gemstones, rings, necklaces, and the like, and I carry them with me wherever I go. At least I used to... When I was swept from the ship, my valuables were scattered across the sea. Help me recover them and I promise to make it worth your trouble.",starts={{npcID=39883,x=0.57,y=0.288,zoneID=4815}},ends={{npcID=39883,x=0.57,y=0.288,zoneID=4815}},coords={x=0.57,y=0.288,source="quest_giver",zoneID=4815},questType="standard"},
[25408] = {id=25408,name="Seeds of Their Demise",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=616,description="We will decimate the Twilight's Hammer by corrupting and subverting them. Seeing that you have no intention of releasing me from my bonds, I require you to collect some reagents for me. My own demonic essence has corrupted the plant life around my shrine here. I need you to harvest some bileberries from the wailing weeds that surround this tower. My little pets will attempt to harvest YOU in return. Try not to let them agitate one another.",starts={{npcID=39933,x=0.222,y=0.448,zoneID=616}},ends={{npcID=39933,x=0.222,y=0.448,zoneID=616}},coords={x=0.222,y=0.448,source="quest_giver",zoneID=616},questType="standard"},
[25419] = {id=25419,name="Lady La-La's Medallion",level=30,requiredLevel=30,faction="none",expansion=6,zoneID=4815,mapID=201,description="Dozens of crude gold links make up this heavy chain. Dangling from the center link is an opalescent fragment of what must have once been a large shell-shaped medallion. You wonder if the other fragments might be nearby, and if the medallion might be reassembled into its original state.",questType="standard"},
[25428] = {id=25428,name="Black Heart of Flame",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=616,description="Now you will use our newfound knowledge to pull Thol'embaar into the mortal plane like a babe screaming from the womb. Then you will crush him. The ritual is simple: take this charred branch , tap it on the ground three times, and utter his name aloud. You must call him from within the heart of the Inferno. Destroy him, and bring his black heart back to me.",starts={{npcID=39933,x=0.222,y=0.448,zoneID=616}},ends={{npcID=39933,x=0.222,y=0.448,zoneID=616}},coords={x=0.222,y=0.448,source="quest_giver",zoneID=616},questType="standard"},
[25467] = {id=25467,name="Kliklak's Craw",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=4815,mapID=201,description="You are pleasantly surprised to find that after being mangled and masticated by a sea crab, this map is still quite legible. It clearly indicates that a footlocker was buried in the Kelp'thar Forest behind a gigantic mollusk. A well-drawn sketch on the back of the map shows that the owner, along with his key, was eaten by an overgrown crustacean named Kliklak.",ends={{npcID=202859,x=0.466,y=0.475,mapID=201}},questType="standard"},
[25472] = {id=25472,name="The Flameseer's Staff",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=1,description="A powerful artifact known as the Flameseer's Staff was lost during the initial onslaught by the enemy forces. It was an ancient bone staff that granted its wielder power over the elements of fire. Its fragments litter the area around us. Find them and bring them to Malfurion. Perhaps the artifact's power will still be of use.",starts={{npcID=39869,x=0.476,y=0.354,zoneID=616}},ends={{npcID=39857,x=0.476,y=0.354,zoneID=616}},coords={x=0.476,y=0.354,source="quest_giver",zoneID=616},questType="standard"},
[25491] = {id=25491,name="Durable Seeds",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=1,description="This land has been scourged by fire, but it may yet renew itself. Some seeds deep in the soil may have withstood the scorching heat here in The Flamewake. These durable plants are the key to this forest's regrowth. Please, collect some of these seedlings for me.",starts={{npcID=39858,x=0.27,y=0.626,zoneID=616}},ends={{npcID=39858,x=0.27,y=0.626,zoneID=616}},coords={x=0.27,y=0.626,source="quest_giver",zoneID=616},questType="standard"},
[25493] = {id=25493,name="Fresh Bait",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=616,description="I was stunned to discover that Twilight's Hammer had located - and imprisoned - the great turtle ancient Tortolla. As we speak he is chained above the murky waters of the Ashen Lake. Freeing Tortolla from his bonds will not be easy. But we will take it one step at a time. Head into the Flamewake and collect for me heaps of core hound entrails . I will explain why later. And beware of Nemesis the Usurper while you are there! His time will come, but we are not yet prepared.",starts={{npcID=39858,x=0.27,y=0.626,zoneID=616}},ends={{npcID=39858,x=0.27,y=0.626,zoneID=616}},coords={x=0.27,y=0.626,source="quest_giver",zoneID=616},questType="standard"},
[25494] = {id=25494,name="A Champion's Collar",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=616,description="This little guy is a true menace now, isn't he? We're going to have to give him a nice spiked collar if he's going to be a fighting pup. The basilisk matriarch has made her lair off of the road to Winterspring. Bring me her spiked hide and we'll fashion a collar for our little killer here.",starts={{npcID=39406,x=0.9,y=0.564,zoneID=616}},ends={{npcID=39406,x=0.9,y=0.564,zoneID=616}},coords={x=0.9,y=0.564,source="quest_giver",zoneID=616},questType="standard"},
[25503] = {id=25503,name="Blackfin's Booty",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=4815,description="Our self-proclaimed king will stop at nothing to acquire my family fortune. He has threatened and harassed me to no end. I can't take it anymore! I've buried the treasure and fed the map to Blackfin. That should keep my cousin's grubby little mitts off of our precious heirlooms!",ends={{npcID=202916,x=0.551,y=0.549,zoneID=4815}},questType="standard"},
[25507] = {id=25507,name="Hell's Shells",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=616,description="Fresh and stinking, these innards will prove to be irresistible for Nemesis, the befouled turtle god created by Twilight's Hammer. Nemesis must eventually be destroyed, but first, we must collect a piece of his fiery armored shell. With it, we'll be able to work some magic to free the true ancient. Go into the Flamewake and drop this bait near Nemesis. It will distract him. Pry off a piece of his shell... then run, if you hope to survive the encounter.",starts={{npcID=39858,x=0.27,y=0.626,zoneID=616}},ends={{npcID=39858,x=0.27,y=0.626,zoneID=616}},coords={x=0.27,y=0.626,source="quest_giver",zoneID=616},questType="standard"},
[25599] = {id=25599,name="Cindermaul, the Portal Master",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=616,description="Twilight's Hammer is using these corridors, and others like them, to move supplies from the elemental planes up into Azeroth. In order to seal these passages off, we're going to need to know how they're constructed. Find for me the Tome of Openings , used by the elementals to open gates between the planes. Cindermaul the Portal Master should have one. You'll have to kill him. Careful! He's probably got some tricks up his sleeve...",starts={{npcID=40834,x=0.262,y=0.418,zoneID=616}},ends={{npcID=40834,x=0.262,y=0.418,zoneID=616}},coords={x=0.262,y=0.418,source="quest_giver",zoneID=616},questType="standard"},
[25602] = {id=25602,name="Can't Start a Fire Without a Spark",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=4815,description="Mack's still out of it, and I fear we may lose him if I can't get this fire started. With the wood being soaked, we'll need something special to get it going. There's an abandoned camp nearby with a barrel of explosives in it. There's no way I can recover it on my own. Would you mind hauling it back for us? For Mack?",starts={{npcID=39884,x=0.572,y=0.288,zoneID=4815}},ends={{npcID=39884,x=0.572,y=0.288,zoneID=4815}},coords={x=0.572,y=0.288,source="quest_giver",zoneID=4815},questType="standard"},
[25656] = {id=25656,name="Scrambling for Eggs",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=1,description="There's a pattern to these Wormwing attacks. While groups make a showy assault on the shrine itself, others swoop into the nearby nests and make off with eggs from all the flying creatures of Hyjal. These animals are under our protection. Before we find out why the Wormwing are doing this, it's up to us to rescue as many eggs as we can from their talons.",starts={{npcID=41006,x=0.422,y=0.454,zoneID=616}},ends={{npcID=41006,x=0.422,y=0.454,zoneID=616}},coords={x=0.422,y=0.454,source="quest_giver",zoneID=616},questType="standard"},
[25664] = {id=25664,name="A Prayer and a Wing",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=616,description="A winged visage? Could it be...? , there's no time to waste. You may have been speaking to Aviana herself, trying to return to us. I'll need something from Aviana's past to reach out to her. High atop the ridge overlooking this shrine, you'll find a series of huge nests belonging to Blaithe, an ancient bird of prey that was once her consort. For ten thousand years he's been mad with grief. Go to one of his roosts, and use this call to summon him. Kill Blaithe and bring me one of his feathers.",starts={{npcID=41005,x=0.444,y=0.462,zoneID=616}},ends={{npcID=41005,x=0.444,y=0.462,zoneID=616}},coords={x=0.444,y=0.462,source="quest_giver",zoneID=616},questType="standard"},
[25732] = {id=25732,name="A Bone to Pick",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=4815,description="We did it! Gnaws is down, and I have our shiney! That's good news. Darn shiney is cursed treasure - makes everyone who touches it a skeleton. That's bad news. These cursed pirates say the Gilblin King has the secret to remove the hex. That's good news. I can't step foot outside the reef or I'll be cursed forever. That's bad news.",starts={{npcID=46458,x=0.584,y=0.486,zoneID=4815}},ends={{npcID=46458,x=0.584,y=0.486,zoneID=4815}},coords={x=0.584,y=0.486,source="quest_giver",zoneID=4815},questType="standard"},
[25758] = {id=25758,name="A Gap in Their Armor",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=1,description="Do you see what they're doing here? They're affixing armored plates onto the Dragonkin. A page out of Deathwing's book, I suppose. Those Twilight Juggernauts look like they'll be invincible once they're complete. There's got to be a way around that armor plating! Run out there and fetch some of the Twilight armor plates that are waiting to be installed. We'll figure out how to beat this.",starts={{npcID=41006,x=0.422,y=0.454,zoneID=616}},ends={{npcID=41006,x=0.422,y=0.454,zoneID=616}},coords={x=0.422,y=0.454,source="quest_giver",zoneID=616},questType="standard"},
[25761] = {id=25761,name="Disassembly",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=616,description="We have to stop these juggernauts before they're completely encased in armor. Right now they're vulnerable, but only if we pry aside the plates and hack at the marred flesh beneath. Take my shiv, and jam it between the plates of armored juggernauts to deprive them of their armor. Once they break from their trance, you're in for a tough fight - keep prying loose that armor and stop those juggernauts!",starts={{npcID=41006,x=0.422,y=0.454,zoneID=616}},ends={{npcID=41006,x=0.422,y=0.454,zoneID=616}},coords={x=0.422,y=0.454,source="quest_giver",zoneID=616},questType="standard"},
[25776] = {id=25776,name="Sethria's Demise",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=616,description="While you've been raiding Sethria 's nest, messages have been flying back and forth between here and the shrine. Skylord Omnuron was at first reluctant, but I've persuaded my fellow druids to risk a direct assault on Sethria herself. Everyone agreed to my plan... provided YOU spearhead the attack. Take this signal rocket and engage Sethria on the far ridge. When she reveals her true colors and shifts to her dragon form, fire the rocket and backup will arrive to help you!",starts={{npcID=41006,x=0.422,y=0.454,zoneID=616}},ends={{npcID=41006,x=0.422,y=0.454,zoneID=616}},coords={x=0.422,y=0.454,source="quest_giver",zoneID=616},questType="standard"},
[25812] = {id=25812,name="Spelunking",level=30,requiredLevel=30,faction="alliance",expansion=6,zoneID=4815,mapID=201,description="Hurry, ! Make your way to that cavern at once. We shall go behind you to ensure that you are not followed.",starts={{npcID=40105,x=0.462,y=0.468,mapID=201}},ends={{npcID=41324,x=0.638,y=0.598,mapID=201}},coords={x=0.462,y=0.468,source="quest_giver",mapID=201},questType="standard"},
[25904] = {id=25904,name="The Hammer and the Key",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=616,description="My Nemesis. Still lives. The servants of fire still come. We must pursue. Into their den. The ogres know the way. Slay the Field Captains. Recover the Glyph of Opening . This is the way.",starts={{npcID=41504,x=0.42,y=0.608,zoneID=616}},ends={{npcID=41504,x=0.42,y=0.608,zoneID=616}},coords={x=0.42,y=0.608,source="quest_giver",zoneID=616},questType="standard"},
[26000] = {id=26000,name="Spelunking",level=30,requiredLevel=30,faction="horde",expansion=6,zoneID=4815,mapID=201,description="Hurry, ! Make your way to that cavern at once. We shall go behind you to ensure that you are not followed.",starts={{npcID=40105,x=0.462,y=0.468,mapID=201}},ends={{npcID=41863,x=0.638,y=0.598,mapID=201}},coords={x=0.462,y=0.468,source="quest_giver",mapID=201},questType="standard"},
[26096] = {id=26096,name="Scalding Shrooms",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5145,description="We think that we have a use for the merciless ones that your friend from the cave delivered to us. But I need a preservative for it. Down below in the Scalding Chasm are some mushrooms with the properties that I need. Bring some back up to me and I'll see what I can do.",starts={{npcID=41639,x=0.426,y=0.378,zoneID=5145}},ends={{npcID=41639,x=0.426,y=0.378,zoneID=5145}},coords={x=0.426,y=0.378,source="quest_giver",zoneID=5145},questType="standard"},
[26111] = {id=26111,name="... It Will Come",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5145,description="I now imbue you with the energies of the corrupting faceless. Swim down to my luring totem in the trench to the northeast. Release the energies through it. Bring back the brain of their leader. Call forth to Ick'thys the Unfathomable... it will come!",starts={{npcID=41600,x=0.426,y=0.378,zoneID=5145}},ends={{npcID=41600,x=0.426,y=0.378,zoneID=5145}},coords={x=0.426,y=0.378,source="quest_giver",zoneID=5145},questType="standard"},
[26140] = {id=26140,name="Communing with the Ancient",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5145,description="Place the dead merciless one upon your head to pose as one of their slaves. Enter L'ghorek . Commune with the ancient.",starts={{npcID=41600,x=0.426,y=0.378,zoneID=5145}},ends={{npcID=42197,x=0.386,y=0.448,zoneID=5145}},coords={x=0.426,y=0.378,source="quest_giver",zoneID=5145},questType="standard"},
[26141] = {id=26141,name="Runestones of Binding",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5145,description="ON THE OTHER... SIDE OF... MY CHAMBER THERE... ARE... CANDIDATES FOR ASCENSION. WE WILL NEED... THEIR... RUNESTONES OF BINDING... TO CREATE A... MEANS OF CONTROLLING... A BOUND ELEMENTAL.",starts={{npcID=42197,x=0.386,y=0.448,zoneID=5145}},ends={{npcID=42197,x=0.386,y=0.448,zoneID=5145}},coords={x=0.386,y=0.448,source="quest_giver",zoneID=5145},questType="standard"},
[26194] = {id=26194,name="Defending the Rift",level=30,requiredLevel=30,faction="horde",expansion=6,zoneID=5145,mapID=204,description="The whispers of the elements are crowding my thoughts, ... The Throne of Tides is under siege! I cannot stand idly by while the naga threaten Neptulon's realm. We must find a way to join forces with him. Nazgrim will escort me to the depths where I can commune directly with Neptulon. I must ask you to take a more violent path. Keep the enemy forces distracted until I arrive safely at entrance to the Throne of Tides. May the spirits see us through, .",starts={{npcID=41600,x=0.426,y=0.378,mapID=204}},ends={{npcID=44540,x=0.696,y=0.344,mapID=204}},coords={x=0.426,y=0.378,source="quest_giver",mapID=204},questType="standard"},
[26259] = {id=26259,name="Blood of the Earthwarder",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5042,description="When Deathwing escaped to Deepholm , his corruption was extreme, but perhaps not yet absolute. The cultists at Deathwing's Fall harvest and shape the corrupted blood he left behind into living organisms to draw from their power. What if a trace of the Earthwarder's essence remains? After all, Neltharion was the aspect of earth before he was the aspect of death. Gather samples from the living blood the cultists have created and we'll see if any trace of the Earthwarder remains.",starts={{npcID=43397,x=0.496,y=0.53,zoneID=5042}},ends={{npcID=43397,x=0.496,y=0.53,zoneID=5042}},coords={x=0.496,y=0.53,source="quest_giver",zoneID=5042},questType="standard"},
[26296] = {id=26296,name="Evidence Collection",level=5,requiredLevel=5,faction="alliance",expansion=6,zoneID=1581,description="The material of this bandana is identical to the material found at the Furlbrow murder scene. You should collect more red bandanas as evidence and return what you find to Captain Alpert .",ends={{npcID=42425,x=0.42,y=0.64,zoneID=40}},questType="standard"},
[26297] = {id=26297,name="The Dawning of a New Day",level=5,requiredLevel=5,faction="alliance",expansion=6,zoneID=40,mapID=52,description="It looks like the meeting the shadowy figure spoke of is starting soon. The homeless are starting to mobilize. I need you to attend the rally and gather information, . Go to the center of Moonbrook and listen in on the rally. Return to me with whatever you find out.",starts={{npcID=42425,x=0.42,y=0.64,mapID=52}},ends={{npcID=42425,x=0.42,y=0.64,mapID=52}},coords={x=0.42,y=0.64,source="quest_giver",mapID=52},questType="standard"},
[26354] = {id=26354,name="Captain Sanders' Hidden Treasure",level=5,requiredLevel=5,faction="alliance",expansion=6,zoneID=40,description="The clue to the treasure reads: Good work, matey! Now ye need to head due east. East up the bluffs, east to the road. Look for the ol' chimney ruins near the side of the road. There you'll find an old barrel with your next clue.",starts={{npcID=35,x=0.26,y=0.477,zoneID=40},{npcID=307070,x=0.26,y=0.478,zoneID=40},{npcID=307330,x=0.259,y=0.477,zoneID=40}},ends={{npcID=36,x=0.405,y=0.479,zoneID=40},{npcID=307307,x=0.405,y=0.479,zoneID=40},{npcID=307619,x=0.406,y=0.478,zoneID=40}},coords={x=0.26,y=0.477,source="quest_giver",zoneID=40},questType="standard"},
[26355] = {id=26355,name="Captain Sanders' Hidden Treasure",level=5,requiredLevel=5,faction="alliance",expansion=6,zoneID=40,description="Searching through the barrel you discover another piece of parchment. This one reads: Now from this here barrel, face ye North. Straight as the crow flies, keep ye walkin' till you see the empty jug next to the lone windmill on the sea bluffs. If ye poke around that jug , ye just might find what you're lookin' for.",starts={{npcID=36,x=0.405,y=0.479,zoneID=40},{npcID=307307,x=0.405,y=0.479,zoneID=40},{npcID=307619,x=0.406,y=0.478,zoneID=40}},ends={{npcID=34,x=0.407,y=0.171,zoneID=40},{npcID=307277,x=0.407,y=0.171,zoneID=40},{npcID=307621,x=0.407,y=0.171,zoneID=40}},coords={x=0.405,y=0.479,source="quest_giver",zoneID=40},questType="standard"},
[26394] = {id=26394,name="Continue to Stormwind",level=1,requiredLevel=1,faction="alliance",expansion=6,zoneID=1519,description="For a small fee, you can take a gryphon to Stormwind, so you can deliver Argus' note to Osric. You won't get there faster any other way. If that sounds acceptable, then just speak to me again when you're ready for the ride. I'll charge you a little, but trust me; it'll be worth it!",starts={{npcID=42983,x=0.418,y=0.646,zoneID=12},{npcID=43000,x=0.818,y=0.664,zoneID=12}},ends={{npcID=1323,x=0.77,y=0.612,zoneID=1519}},coords={x=0.418,y=0.646,source="quest_giver",zoneID=12},questType="standard"},
[26395] = {id=26395,name="Dungar Longdrink",level=1,requiredLevel=1,faction="alliance",expansion=6,zoneID=1519,description=", I gathered into this crate everything Argus asked for. Can you take it to him? If you've already spoken to Bartlett at Goldshire, then you can take a gryphon back to him. Dungar Longdrink is our gryphon master, over in the trade district. Speak with Dungar, then get this crate to Argus as fast as you can. We don't want our fighting men and women in Goldshire to go without fresh equipment!",starts={{npcID=1323,x=0.77,y=0.612,zoneID=1519}},ends={{npcID=352,x=0.71,y=0.726,zoneID=1519}},coords={x=0.77,y=0.612,source="quest_giver",zoneID=1519},questType="standard"},
[26410] = {id=26410,name="Explosive Bonding Compound",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5042,description="This guy's the son of the Earthen leader! He almost made it to the temple when he got ambushed by more rock flayers than I can count! We know that the Earthen Stonefather has the middle fragment of the World Pillar. Maybe if we were to heal his son, the Stonefather would give us the fragment? My heals won't work on Flint here. But if we were to get some of the quartzite resin off of these monsters, I think I can make an explosive compound that will bond and cauterize his wounds.",starts={{npcID=42574,x=0.464,y=0.572,zoneID=5042}},ends={{npcID=42574,x=0.464,y=0.572,zoneID=5042}},coords={x=0.464,y=0.572,source="quest_giver",zoneID=5042},questType="standard"},
[26427] = {id=26427,name="Without a Captain or Crew",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5042,description="Not sure who you're with, but you don't look like one of... them. I'm not sure what happened. I slept through supper and woke up to a ship full of dead people and murderers. Not sure if you want to kill me or not, but I'll spare you the trouble. I can keep steering the ship for a while longer. You don't die from a gut wound immediately. Just bring me some rope and some rum... no, whiskey.",starts={{npcID=43082,x=0.624,y=0.532,zoneID=5042}},ends={{npcID=43082,x=0.624,y=0.532,zoneID=5042}},coords={x=0.624,y=0.532,source="quest_giver",zoneID=5042},questType="standard"},
[26437] = {id=26437,name="Making Things Crystal Clear",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5042,description="Among the Shuddering Spires are crystals. White, chalky crystals. We can absorb these crystals into our skin. To cleanse us. Purify us. I do not stride among the stones any longer. I am one with the earth. This carries many boons, but I can no longer retrieve the crystals for myself. Bring me the crystals that I might be stronger. Carry them away from the flayers. Away from my sons. This honor should be mine.",questType="standard"},
[26502] = {id=26502,name="Thunder Stones",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5042,description="To the north lies the Fractured Front. That is where most of the heavy fighting is happening. Go into Stonehearth proper and grab all of the thunder stones that you can. Our engineers need them for the catapults. When you have enough, take them to Clay Mudaxle . Don't mind his tongue. He's old and cranky, and should have gone back into the earth thousands of years ago.",starts={{npcID=43160,x=0.282,y=0.696,zoneID=5042}},ends={{npcID=43169,x=0.246,y=0.622,zoneID=5042}},coords={x=0.282,y=0.696,source="quest_giver",zoneID=5042},questType="standard"},
[26507] = {id=26507,name="Petrified Delicacies",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5042,description="Petrified bats. Elementals of that size are picky. You're not likely to find anything better easily. To the east are basilisks. They petrify stone bats that fly too close and snack on them when they grow hungry. You may find bats scattered around their territory. I must warn you... if you show that little elemental too much attention, you're unlikely to be rid of it. It can be very... needy.",questType="standard"},
[26625] = {id=26625,name="Troggzor the Earthinator",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5042,description="You have to put an end to this now! Go back northwest onto the front and kill their battle leader, Troggzor the Earthinator. Bring me his cudgel as proof.",starts={{npcID=43168,x=0.244,y=0.624,zoneID=5042}},ends={{npcID=43168,x=0.244,y=0.624,zoneID=5042}},coords={x=0.244,y=0.624,source="quest_giver",zoneID=5042},questType="standard"},
[26766] = {id=26766,name="Big Game, Big Bait",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5042,description="We're only going to get one shot at capturing Abyssion, . Let's make it count. We'll test out the trap on the biggest of the stone dragons in the Alabaster Shelf. To lure the stone matriarch, we're going to need to gather sufficient bait. Take this knife and carve 5 sides of basilisk meat. That ought to be enough even for her appetite.",starts={{npcID=44010,x=0.644,y=0.822,zoneID=5042}},ends={{npcID=44010,x=0.644,y=0.822,zoneID=5042}},coords={x=0.644,y=0.822,source="quest_giver",zoneID=5042},questType="standard"},
[27047] = {id=27047,name="Motes",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5042,description="Some of the rarest crystals form in the most dangerous places. In the Crumbling Depths, you will find painite formations - much better than the gold that your races cherish so much. As a being of flesh and a being of small stature, you can enter the Crumbling Depths to retrieve motes of painite for me. Would you undergo that danger on my behalf?",starts={{npcID=43805,x=0.56,y=0.142,zoneID=5042}},ends={{npcID=43805,x=0.56,y=0.142,zoneID=5042}},coords={x=0.56,y=0.142,source="quest_giver",zoneID=5042},questType="standard"},
[27048] = {id=27048,name="Underground Economy",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5042,description="Hey! I need some help gatherin' crystals. The elementals trade top dollar for these things... if you help me gather all the different kinds, I'll cut you in on the profits. Use these bombs to blow out chunks from the bigger formations. I've got a nasty habit of packin' the explosives a bit thick. Mind the kick.",starts={{npcID=44968,x=0.612,y=0.262,zoneID=5042}},ends={{npcID=44968,x=0.612,y=0.262,zoneID=5042}},coords={x=0.612,y=0.262,source="quest_giver",zoneID=5042},questType="standard"},
[27051] = {id=27051,name="Through Persistence",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5042,description="The troggs did not disperse after you killed Glop. His servants recovered the growth agent that was left behind and continue to sow the seeds of corruption across the Crimson Expanse. Hunt them down and recover any of the remaining Verlock Miracle-Grow that you find. It must be disposed of.",starts={{npcID=44973,x=0.594,y=0.14,zoneID=5042}},ends={{npcID=44973,x=0.594,y=0.14,zoneID=5042}},coords={x=0.594,y=0.14,source="quest_giver",zoneID=5042},questType="standard"},
[27135] = {id=27135,name="Something that Burns",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5042,description="Alright, we need something that's going to make the compound go, \"Boom\"! I'm all out of gun powder, but I think I know what we can use instead... the heart of my fire elemental! Here, take my fire totem east to the Blood Trail. Just flip the switch on it near any of the lava pools over there and Magmatooth should be summoned. Bring back his heart and we'll be in business.",starts={{npcID=42574,x=0.464,y=0.572,zoneID=5042}},ends={{npcID=42574,x=0.464,y=0.572,zoneID=5042}},coords={x=0.464,y=0.572,source="quest_giver",zoneID=5042},questType="standard"},
[27176] = {id=27176,name="A Strange Disc",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="The etching around the surface of this object indicates that it is of ancient origins, and yet no signs of wear can be detected. A hole on its edge, full of splintered wood, indicates that it is meant to be put atop a wooden staff of some sort. Before showing this to Doctor Jones, you should find the other piece.",starts={{npcID=205266,x=0.649,y=0.295,zoneID=5034}},ends={{npcID=45180,x=0.646,y=0.286,zoneID=5034}},coords={x=0.649,y=0.295,source="quest_giver",zoneID=5034},questType="standard"},
[27179] = {id=27179,name="Field Work",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="This unfortunate pygmy was in the wrong place at the wrong time. As you ponder his bad luck, you take notice of the symbols covering his shield - far too elaborate for pygmy scrawl. Confident that Doctor Jones will find such objects of interest, you set out to find more fragments like this one.",starts={{npcID=45186,x=0.646,y=0.286,zoneID=5034}},ends={{npcID=45180,x=0.646,y=0.286,zoneID=5034}},coords={x=0.646,y=0.286,source="quest_giver",zoneID=5034},questType="standard"},
[27357] = {id=27357,name="The Captive Bride",level=15,requiredLevel=15,faction="alliance",expansion=6,zoneID=400,mapID=64,description="Of course! Lakota Windsong ! Why didn't I think of this before? Arnak kidnapped Lakota years ago and tried to force her into being his bride. She managed to escape, but in the chaos of the recent attack on Freewind Post, he took her again. She has to be around here somewhere. She's become quite the mystic in recent years. I'm guessing she'll know what to do with these tauren artifacts.",ends={{npcID=45442,x=0.39,y=0.258,mapID=64}},questType="standard"},
[27358] = {id=27358,name="The Captive Bride",level=15,requiredLevel=15,faction="horde",expansion=6,zoneID=400,mapID=64,description="Lakota Windsong ! Why did I not think of this before? Arnak kidnapped Lakota years ago and tried to force her to be his bride. With help, she was able to escape, but in the chaos of the recent attack on Freewind Post, he took her again. She must be near. She has become quite the shaman in recent years. I am sure that she will understand the significance of the rattle, the writ, and the drums.",ends={{npcID=45442,x=0.39,y=0.258,mapID=64}},questType="standard"},
[27385] = {id=27385,name="Uncle Carlin",level=15,requiredLevel=15,faction="both",expansion=6,zoneID=139,description="I'm going to play with dolly, but I don't want to play with daddy's sword after all. You'd better keep it. Even better, can you give it to my uncle Carlin? I'm not sure where he is, but sometimes I hear him crying. It sounds like he's nearby, to the north. I hope he's not crying for me! , will you find my uncle and tell him I'm alright? If you find him say I'm waiting for him, and I want to hear the story he used to tell... the one about the rabbits and the berry jam! That story's so funny!",starts={{npcID=10926,x=0.324,y=0.836,zoneID=139}},ends={{npcID=11063,x=0.354,y=0.688,zoneID=139}},coords={x=0.324,y=0.836,source="quest_giver",zoneID=139},questType="standard"},
[27386] = {id=27386,name="A Strange Historian",level=15,requiredLevel=15,faction="both",expansion=6,zoneID=139,description="That sword belonged to Joseph Redpath, Pamela's father - though you probably already knew that. I wish Joseph could again be with his daughter, but it cannot be so. His soul was twisted by the Scourge, and he became a monster. Pamela's fate is sealed, but perhaps we can change Joseph's fate. A strange gnome arrived here at this tower not long ago. Her name is Chromie . Take that sword to her. I have a feeling she will be able to help us.",starts={{npcID=11063,x=0.354,y=0.688,zoneID=139}},ends={{npcID=10667,x=0.352,y=0.68,zoneID=139}},coords={x=0.354,y=0.688,source="quest_giver",zoneID=139},questType="standard"},
[27517] = {id=27517,name="Be Prepared",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="Every adventurer worth their salt knows never to step foot in a cave, dungeon, crypt or tomb without an ample supply of rope... right? You can never have too much of this stuff! You resolve to scrounging every scrap of it you can find from the skeletons here.",starts={{npcID=205540,x=0.652,y=0.337,zoneID=5034}},ends={{npcID=45296,x=0.644,y=0.28,zoneID=5034}},coords={x=0.652,y=0.337,source="quest_giver",zoneID=5034},questType="standard"},
[27541] = {id=27541,name="Lessons From the Past",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="This unfortunate explorer has clearly suffered a bit of bad luck in the recent past. Prudence dictates that you perform the unenviable task of searching the corpse for clues that might shed light on your surroundings...",starts={{npcID=45874,x=0.634,y=0.324,zoneID=5034}},ends={{npcID=45296,x=0.644,y=0.28,zoneID=5034}},coords={x=0.634,y=0.324,source="quest_giver",zoneID=5034},questType="standard"},
[27549] = {id=27549,name="By the Light of the Stars",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="Look at this, . I tightened the clamp in the middle and crimped the wires on the edges. They may not be the most comfortable, but they should hold together. If I've translated your tablets correctly, there's something hidden here - a final piece to our puzzle. I hope your spectacles hold the key. Let me know what you find!",starts={{npcID=45296,x=0.644,y=0.28,zoneID=5034}},ends={{npcID=45296,x=0.644,y=0.28,zoneID=5034}},coords={x=0.644,y=0.28,source="quest_giver",zoneID=5034},questType="standard"},
[27623] = {id=27623,name="Colossal Guardians",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="The chest containing the scepter appears to be magically sealed and will not budge. The plaque above it depicts two giant statues holding star and moon-shaped stones sockets at their center. The two statues are pictured guarding pyramids that look like the ones outside. Perhaps it's worth your while to investigate these.",starts={{npcID=205874,x=0.397,y=0.454,zoneID=5034}},ends={{npcID=205874,x=0.397,y=0.454,zoneID=5034}},coords={x=0.397,y=0.454,source="quest_giver",zoneID=5034},questType="standard"},
[27624] = {id=27624,name="After the Fall",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="Aww, that was nothin', really. Those statues were teetering as it was - just needed a little push is all. How about you go and sort through that rubble? I've got a feeling we're close to getting this all sorted out.",starts={{npcID=45296,x=0.644,y=0.28,zoneID=5034}},ends={{npcID=45296,x=0.644,y=0.28,zoneID=5034}},coords={x=0.644,y=0.28,source="quest_giver",zoneID=5034},questType="standard"},
[27706] = {id=27706,name="The Scepter of Orsis",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="The chest below unlocks with a loud click as you insert the two stones into the plaque. Obtain the scepter and bring it back to General Ammantep .",starts={{npcID=205874,x=0.397,y=0.454,zoneID=5034}},ends={{npcID=45772,x=0.452,y=0.378,zoneID=5034}},coords={x=0.397,y=0.454,source="quest_giver",zoneID=5034},questType="standard"},
[27839] = {id=27839,name="Ancient Weapons",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="Though we aren't formally at war yet, the Neferset do not hesitate to imprison or kill all who trespass upon their territories. King Phaoris refuses to reciprocate, even when they use our lands to smuggle stolen relics from the tombs of our ancestors. My scouts report that the Neferset are about to move a major shipment of looted weapons south of here. I've instructed the laborers you recruited to assist you. Call upon them with this horn when you find the smugglers and recover the weapons.",starts={{npcID=46134,x=0.588,y=0.462,zoneID=5034}},ends={{npcID=46134,x=0.588,y=0.462,zoneID=5034}},coords={x=0.588,y=0.462,source="quest_giver",zoneID=5034},questType="standard"},
[27924] = {id=27924,name="Budd's Plan",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="I've an idea! Trust me, it's a good one this time! Get some of those shiny armor pieces the cat-people wear. This plan cannot fail. Trust me.",starts={{npcID=46875,x=0.596,y=0.72,zoneID=5034}},ends={{npcID=46875,x=0.596,y=0.72,zoneID=5034}},coords={x=0.596,y=0.72,source="quest_giver",zoneID=5034},questType="standard"},
[27928] = {id=27928,name="A Favor for the Furrier",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="The commander can be most generous to those who demonstrate their loyalty, and I know of something that you can do to curry favor with him. Before building up his... ehh... workforce, he dealt in the furs of animals. He is quite skilled in the art of leatherworking. The furrier can do wonders with even the most tattered pelts. The dried oasis to the east is said to be home to a rare breed of coyote. Their furs would make a very thoughtful gift.",starts={{npcID=47670,x=0.244,y=0.644,zoneID=5034}},ends={{npcID=47670,x=0.244,y=0.644,zoneID=5034}},coords={x=0.244,y=0.644,source="quest_giver",zoneID=5034},questType="standard"},
[27938] = {id=27938,name="The Middle Fragment",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5042,description="I present you with the key to Stonehearth. With it you may unlock the vault to my home and recover the middle fragment of the World Pillar . Keep the fragment safe, . Make certain to get it to the Temple of Earth in the middle of Deepholm as quickly as possible! Know that you are always welcome here.",starts={{npcID=44204,x=0.28,y=0.686,zoneID=5042}},ends={{npcID=42573,x=0.494,y=0.532,zoneID=5042}},coords={x=0.28,y=0.686,source="quest_giver",zoneID=5042},questType="standard"},
[27941] = {id=27941,name="Fashionism",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="We have a strict policy among our ranks, one that we take most seriously. Our troops are to dress in official uniform at all times. This helps with organization, friendly fire incidents are reduced, and it keeps the troops looking wonderful! We call it, Fashionism. We've been running low on uniforms lately. I must ask that you recover them from the troopers that have fallen in the line of duty. You should find plenty of the poor fellows east of here, at the Ruins of Ammon.",starts={{npcID=47670,x=0.244,y=0.644,zoneID=5034}},ends={{npcID=47670,x=0.244,y=0.644,zoneID=5034}},coords={x=0.244,y=0.644,source="quest_giver",zoneID=5034},questType="standard"},
[27942] = {id=27942,name="Idolatry",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="Zhere is somezhink I need handled, . My most trusted advisor has run afoul of an ancient curse. A hex zhat has transformed zhe man into a turkey, of all zhings! I haff studied for days to discover a remedy for his condition, and finally I am ready to conduct zhe ritual. I vill reqvire several idols from zhe nearby ruins. You are to brink zhem to me at vonce! Dismissed!",starts={{npcID=47159,x=0.244,y=0.642,zoneID=5034}},ends={{npcID=47159,x=0.244,y=0.642,zoneID=5034}},coords={x=0.244,y=0.642,source="quest_giver",zoneID=5034},questType="standard"},
[27943] = {id=27943,name="Angered Spirits",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="Doctor Venkman vas vone of my greatest researchers, until he had to be put out of my misery. He did leave me vizh vone of his greatest accomplishments, zhough. Against zhe properly attuned supernatural adversary, zhis veapon vill siphon zhe target's essence. It is of key importance in zhe ritual I vill be attemptink. Vhere do you come in, you ask? Simple. You have zhe priviledge of collecting zhe material. Zhe veapon is calibrated to vork on zhe Furious Specters in zhe temple to zhe east.",starts={{npcID=47159,x=0.244,y=0.642,zoneID=5034}},ends={{npcID=47159,x=0.244,y=0.642,zoneID=5034}},coords={x=0.244,y=0.642,source="quest_giver",zoneID=5034},questType="standard"},
[28105] = {id=28105,name="Kavem the Callous",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="Kavem was cruel enough before the Neferset signed up with Deathwing. His pleasure in deriving pain now borders on the insane. It is he who now holds the keys to our shackles. He dwells in the building next to us, to my right. Find him and take the key from him. Do not hesitate or show him mercy. He will slit your throat and think nothing of it.",starts={{npcID=46872,x=0.596,y=0.72,zoneID=5034}},ends={{npcID=46872,x=0.596,y=0.72,zoneID=5034}},coords={x=0.596,y=0.72,source="quest_giver",zoneID=5034},questType="standard"},
[28141] = {id=28141,name="Relics of the Sun King",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="The Seal of the Sun King serves as a defense mechanism for Ramkahen. When the barrier around Uldum fell, we began to see Wastewander outriders from Tanaris filter into our borders. They attacked this holy site on their way west and robbed it of the relics which once provided its power. Recover the relics for us. Without them we are powerless to defend against attacks from the desert.",starts={{npcID=47715,x=0.53,y=0.276,zoneID=5034}},ends={{npcID=47715,x=0.53,y=0.276,zoneID=5034}},coords={x=0.53,y=0.276,source="quest_giver",zoneID=5034},questType="standard"},
[28200] = {id=28200,name="The Element of Supplies",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="You'll notice that we're slightly ill prepared for battle. The tol'vir tribes had never seen any sort of major confrontation for thousands of years. All the combat protocols that the titans programmed into our ancestors are still there, though. Some are part of our instincts, some get passed on as tradition. But none of this can compensate for lack of supplies. We need weapons. We need armor. The best armor is lined with the skin of the riverbed crocolisks nearby. Help us gather some.",starts={{npcID=48012,x=0.588,y=0.462,zoneID=5034}},ends={{npcID=48012,x=0.588,y=0.462,zoneID=5034}},coords={x=0.588,y=0.462,source="quest_giver",zoneID=5034},questType="standard"},
[28350] = {id=28350,name="Master Trapper",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="One thing about me that you might not know, ... I come from a long line of trappers. My father taught me, as his taught him, to master the art of trapping creatures in a most merciful manner. As any master trapper will tell you, the most important ingredient in an effective trap is the bait. So let's start there. Fill this bucket with the meat scraps from almost any wild creature in Uldum .",starts={{npcID=48431,x=0.296,y=0.218,zoneID=5034}},ends={{npcID=48431,x=0.296,y=0.218,zoneID=5034}},coords={x=0.296,y=0.218,source="quest_giver",zoneID=5034},questType="standard"},
[28483] = {id=28483,name="Bleeding the Enemy",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="I will not lie to you, . We face a tremendous challenge ahead of us. As you go behind the enemy lines into Neferset City, I want you to bring back the insignia of any Neferset scum you defeat. It will be a boon to our armies to know that you've dealt a crushing blow to the enemy.",starts={{npcID=48564,x=0.52,y=0.654,zoneID=5034}},ends={{npcID=48564,x=0.52,y=0.654,zoneID=5034}},coords={x=0.52,y=0.654,source="quest_giver",zoneID=5034},questType="standard"},
[28488] = {id=28488,name="Beneath the Surface",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5042,description="Among the other precious gemstones hidden deep out of our reach in the Crumbling Depths, there are enormous ruby crystal clusters . They are infused with terrible energy. It will not be easy to obtain such a thing, for they are well guarded. But you, you are stubborn and brave. I think this is something you can do. Within the Crumbling Depths, look to where the tunnels end abruptly in stone. The clusters are found in those passages when they are to be found at all. Should you find one, return to me.",starts={{npcID=43805,x=0.56,y=0.142,zoneID=5042}},ends={{npcID=43805,x=0.56,y=0.142,zoneID=5042}},coords={x=0.56,y=0.142,source="quest_giver",zoneID=5042},questType="standard"},
[28498] = {id=28498,name="The Secret of Nahom",level=30,requiredLevel=30,faction="both",expansion=6,zoneID=5034,description="There is an old story about Nahom. It speaks of how a powerful prophet named Atulhet held off troves of enemies by channeling the power of the sun through this very temple. Most believe the tale to be just a legend, but that power... would certainly be useful to us now. The vile Neferset have ransacked Atulhet's tomb. They've taken any artifacts of power and shattered the tablets that encode his memories. Go to the Tombs of the Precursors to the east and retrieve any fragments that you find.",starts={{npcID=48761,x=0.672,y=0.428,zoneID=5034}},ends={{npcID=48761,x=0.672,y=0.428,zoneID=5034}},coords={x=0.672,y=0.428,source="quest_giver",zoneID=5034},questType="standard"},
[29091] = {id=29091,name="Freedom Movement",level=5,requiredLevel=5,faction="none",expansion=6,zoneID=17,mapID=10,questType="standard"},
[29246] = {id=29246,name="Relieving the Pain",level=32,requiredLevel=32,faction="both",expansion=6,zoneID=616,description="The Arch Druid has an immense tolerance for pain. I've treated burn victims that spend twenty-two hours a day screaming in pain, and their burns weren't even half as bad as what Hamuul has suffered. Nevertheless, I can sense that he is in greater discomfort than normal today. Bring me the hearts of the large fire elementals to the southeast. I can use them to prepare a soothing salve for our patient.",starts={{npcID=52986,x=0.274,y=0.624,zoneID=616}},ends={{npcID=52986,x=0.274,y=0.624,zoneID=616}},coords={x=0.274,y=0.624,source="quest_giver",zoneID=616},questType="standard"},
[29247] = {id=29247,name="Treating the Wounds",level=32,requiredLevel=32,faction="both",expansion=6,zoneID=616,description="We have an ample supply of medical supplies here at the Sanctuary, but we mustn't lose sight of the fact that we are at war. Hamuul isn't the only person who has need of bandages. The fiery behemoths that roam Sethria's Roost wear flame-resistant wrappings that will serve Hamuul as ably as any bandage. Bring me those wrappings, and I will prepare them for use on the Arch Druid.",starts={{npcID=52986,x=0.274,y=0.624,zoneID=616}},ends={{npcID=52986,x=0.274,y=0.624,zoneID=616}},coords={x=0.274,y=0.624,source="quest_giver",zoneID=616},questType="standard"},
[29248] = {id=29248,name="Releasing the Pressure",level=32,requiredLevel=32,faction="both",expansion=6,zoneID=616,description="Having been burned so badly, Arch Druid Hamuul is suffering from edema - swelling of the body's tissues. It takes a great deal of his attendants' effort to keep his swelling down enough for him to breathe. Normally, to reduce this swelling, we make cuts in his flesh, but he is weak, . I cannot cut him today. I need your help. Flamewaker scales will aid with the swelling, but you need a lot of them.",starts={{npcID=52986,x=0.274,y=0.624,zoneID=616}},ends={{npcID=52986,x=0.274,y=0.624,zoneID=616}},coords={x=0.274,y=0.624,source="quest_giver",zoneID=616},questType="standard"},
[37518] = {id=37518,name="The Haunted Halls",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,mapID=630,description="Now, what was it you wanted? You're here to see the Tidestone of Golganneth? Hah! Ho ho ha ha haa! Hooo my. No, only the academy's headmistress has the keys to that chamber, and she hasn't opened the door in... oh, I'd say about ten thousand years. You'd best be off to class, now. Go on, then! Into the west wing with you!",questType="standard"},
[37530] = {id=37530,name="Save Yourself",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,mapID=630,description="Of course I couldn't sit back and let them just cart you away. I will explain everything.",starts={{npcID=89009,x=0.578,y=0.434,mapID=630}},coords={x=0.578,y=0.434,source="quest_giver",mapID=630},questType="standard"},
[37729] = {id=37729,name="Pop Quiz: Advanced Rune Drawing",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,mapID=630,description="Still aching to get into the headmistress' study, eh? I suppose I can let you in... as long as you prove that you've been studying. Proper rune formation is essential when it comes to spellcasting. If you can draw a rune, you can cast a spell. I will provide outlines for you. You can simply use your feet to trace the runes.",questType="standard"},
[37857] = {id=37857,name="Runas Knows the Way",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,mapID=630,description="I wish to make it up to you for whatever I did that made you want to kill me. Hmm... your dragon complains about being weak. I know why. Runas can fix it, my friend. One of my kind, Ael'Yith, pulls ley energy from the very ground of Azsuna . I can take you to the location of his mana siphons. It's not too late to undo the harm the others have done. You've done well to trust me.",starts={{npcID=90383,x=0.538,y=0.168,mapID=630}},ends={{npcID=89978,x=0.534,y=0.162,mapID=630},{npcID=90569,x=0.534,y=0.164,mapID=630}},coords={x=0.538,y=0.168,source="quest_giver",mapID=630},questType="standard"},
[37908] = {id=37908,name="Inquisitor Ernstenbok",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7334,mapID=630,questType="standard"},
[38461] = {id=38461,name="Vignette: Guarms Mate (Fenri)",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7588,mapID=649,questType="standard"},
[38818] = {id=38818,name="The Final Judgment",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7588,mapID=649,description="In my fragmented state, I captured glimpses of a hero meting out justice to the corrupted mystics of Haustvald. I see now, this hero was you, . I know you seek my judgment, but my spirit is still fragmented. As we speak, Runeseer Faljar is calling upon dark, forbidden magics in an attempt to banish my spirit to Helheim. If he succeeds, your trial will be lost. My connection here is fading. Go, there is little time!",starts={{npcID=93234,x=0.714,y=0.424,mapID=634}},ends={{npcID=97319,x=0.652,y=0.472,mapID=649}},coords={x=0.714,y=0.424,source="quest_giver",mapID=649},questType="standard"},
[38900] = {id=38900,name="7.0 Val'sharah - Bluffs - Vignette: Nightcaller - TRACKING - twh",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[38901] = {id=38901,name="The Felsmiths",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7637,description="Ye have a knack with this felslate, . Best ship ye off to someone who knows the stuff better than I. The Illidari have a knack with all things demonic, really, and I've heard about a few miners who've set up shop out near the demons in Suramar. Pay 'em a visit. See what they have to teach ye.",ends={{npcID=92264,x=0.3,y=0.534,zoneID=7637}},questType="standard"},
[38902] = {id=38902,name="Vignette: Coruscating Bloom",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[38903] = {id=38903,name="7.0 Val'sharah - Bluffs - Vignette: Nightcaller - Interaction - TRACKING - twh",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[38904] = {id=38904,name="Return to the Broken Shore",level=10,requiredLevel=10,faction="horde",expansion=6,zoneID=7813,description="Fear not, . I'm angry, but I don't chase my own death. We will fly in and scout the ideal point of attack. The demons are still drunk on their victory, but we will put a swift end to their revelry! Take my spare mount and we will fly to the Broken Shore. There we will bring honor to our dead.",questType="standard"},
[38907] = {id=38907,name="Keepers of the Hammer",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="The Highmountain Tribes had intended to pledge our allegiance to your forces. We know war has come with the Burning Legion. However, we have been betrayed from within and must now ask for your aid. A great relic, the Hammer of Khaz'goroth, was stolen from our people by the vile drogbar. We need your help in recovering it.",ends={{npcID=93826,x=0.448,y=0.504,zoneID=7731}},questType="standard"},
[38909] = {id=38909,name="Get to High Ground",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="It is no accident that Dargrul attacked the Rivermane in force. It is their farms and their pastures that supply food for the region. Please, get Jale to Thunder Totem. With luck, Mayla will have reinforcements to send to the area. We will rally the survivors here and follow as quickly as we can.",ends={{npcID=93826,x=0.448,y=0.504,zoneID=7731}},questType="standard"},
[38910] = {id=38910,name="Rocs vs Eagles",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="High Crawliac has taught her witches how to curse our beloved eagles into the vile rocs you see assaulting the valley. There is no way to break this curse once it has taken hold. We will take to the skies and do battle with the rocs, but we need your help on the ground. Head north through Darkfeather Valley and release any eagles that you find. Every eagle you save is one less roc we must kill later.",starts={{npcID=93841,x=0.524,y=0.448,zoneID=7503}},ends={{npcID=95410,x=0.522,y=0.364,zoneID=7503}},coords={x=0.524,y=0.448,source="quest_giver",zoneID=7503},questType="standard"},
[38911] = {id=38911,name="The Rivermane Tribe",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="What has happened here requires more time than I have to explain. In short, our tribes have scattered in the wake of the attack that left the Hammer of Khaz'goroth in the hands of the barbaric drogbar. Even now the drogbar are raiding the Rivermane tribe, and I have too few braves left to send to their aid. We need a hero. Please, go to Earthmother's Bounty and lend what aid you can.",starts={{npcID=93826,x=0.448,y=0.504,zoneID=7731},{npcID=108434,x=0.446,y=0.504,zoneID=7731}},coords={x=0.448,y=0.504,source="quest_giver",zoneID=7731},questType="standard"},
[38912] = {id=38912,name="The Bloodtotem Tribe",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="The Bloodtotem are led by Torok, a volatile but useful tauren chieftain. He is wary of outsiders, but I believe you have already met an emissary to their tribe-- Oakin Ironbull --whom you rescued at Riverbend. Use that small thread and you may be able to bring the Bloodtotem back into the fold. Highmountain needs them if we are to defeat the drogbar and reclaim the Hammer of Khaz'goroth. Be on your guard, .",starts={{npcID=93826,x=0.448,y=0.504,zoneID=7731},{npcID=108434,x=0.446,y=0.504,zoneID=7731}},coords={x=0.448,y=0.504,source="quest_giver",zoneID=7731},questType="standard"},
[38913] = {id=38913,name="The Skyhorn Tribe",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="The Skyhorn people are some of the greatest pathfinders and hunters this world has ever known. They are a proud people, but should be willing to listen to reason. If the roads feel unsafe, you may ask any flight master in Highmountain to fly you there. Please, $p, go to their leader Lasan and remind him that only together, we are Highmountain .",starts={{npcID=93826,x=0.448,y=0.504,zoneID=7731},{npcID=108434,x=0.446,y=0.504,zoneID=7731}},coords={x=0.448,y=0.504,source="quest_giver",zoneID=7731},questType="standard"},
[38914] = {id=38914,name="Secrets of Highmountain",level=1,requiredLevel=1,faction="alliance",expansion=6,zoneID=7503,mapID=650,description="Now that you are familiar with our greatest hero, perhaps you are willing to assist me on a very dangerous endeavor. To this end I have sent word for one of your allies to join us. When you are ready, join us in my spirit lodge. It is up the elevators and across the southwestern most bridge.",questType="standard"},
[38915] = {id=38915,name="Battle of Snowblind Mesa",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="Your timing is fortunate. Our forces at Snowblind Mesa report seeing the Underking above ground. What is more, he is lightly guarded, and has the hammer with him. Thanks to your efforts, we can meet them in battle. Meet us at Snowblind Mesa and let us take the fight to Dargrul together.",starts={{npcID=108434,x=0.446,y=0.504,zoneID=7731}},coords={x=0.446,y=0.504,source="quest_giver",zoneID=7731},questType="standard"},
[38916] = {id=38916,name="Secrets of Highmountain",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="Mayla's father, Ulan, was our last high chieftain. He was slain trying to stop the Underking from seizing the Hammer of Khaz'goroth. I have watched Mayla all her life and can tell you she has both the courage and the strength to wear the mantle of High Chieftain. She needs only our help to realize it herself. Will you meet us at the city entrance along the southern bluff? There is a ritual that might help, but we will need your aid to survive it.",starts={{npcID=98825,x=0.512,y=0.546,zoneID=7731}},coords={x=0.512,y=0.546,source="quest_giver",zoneID=7731},questType="standard"},
[38922] = {id=38922,name="Littlefur",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="Stranger, I beseech you! My once peaceful brethren are now cursed with insatiable wrath. My nephew and I tried to leave against the Chieftain's wishes. The clan wrested him from me, and would have torn me apart if I did not flee. He is trapped in the village, and I fear the worst. Great , please save him. I am too old and too weak to do it myself.",starts={{npcID=93890,x=0.484,y=0.846,zoneID=7558}},ends={{npcID=93581,x=0.462,y=0.846,zoneID=7558}},coords={x=0.484,y=0.846,source="quest_giver",zoneID=7558},questType="standard"},
[38932] = {id=38932,name="Equipment Blueprint: Bilge Pump",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=6720,description="This appears to be a blueprint for some sort of naval equipment. We should take it back to our Shipyard and see if someone can decipher it.",ends={{npcID=93812,x=0.286,y=0.108,zoneID=6719},{npcID=94801,x=0.4,y=0.722,zoneID=6720}},questType="standard"},
[38933] = {id=38933,name="Logistical Matters",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=139,description="I think we are ready to... reintroduce ourselves to the Legion on the Broken Isles. Lord Grayson Shadowbreaker has volunteered to help coordinate our forces on the ground. You should speak with him immediately, Highlord.",questType="standard"},
[38936] = {id=38936,name="The Road to Kun-Lai",level=20,requiredLevel=20,faction="both",expansion=6,zoneID=6006,description="Lorewalker Cho has sent word that several of your companions survived the conflict in the Jade Forest and have been moved to Kun-Lai Summit to seek healing. They need your help if they are to survive! To reach Kun-Lai Summit, travel to the Valley of the Four Winds and look for the Highroad Grummle that can be found at the base of the Veiled Stair along the northeastern border. They can guide you the rest of the way.",ends={{npcID=59073,x=0.722,y=0.918,zoneID=5841}},questType="standard"},
[38938] = {id=38938,name="Unbearable",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[38943] = {id=38943,name="7.0 Val'sharah - Treasure 023 - Moonclaw Vale - twh",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[38944] = {id=38944,name="Sew It Begins",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Every time Dalaran takes us to a new shore, I get anxious over what types of fabric and cloth we might find below. Threads imbued with magic? Something demonically-tinged? Ugh, I hope it's not FURS again. You're an adventurer... and tailor to boot. Head on down there and see what you can scrounge up!",questType="standard"},
[38945] = {id=38945,name="This Should Be Simple... Right?",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="I have plenty of silk patterns that we can put this cloth to work on. Help me to prepare the materials, . We're going to put this cloth to good use and make you a new robe.",questType="standard"},
[38946] = {id=38946,name="Consult the Locals",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="Whoever wove this fabric CAN'T have intended it only for belts and shoulderpads. There must be some way to sew thread into this material. Head on down to Azsuna and try to find a tailor. We need to sew if we're going to do any real tailoring.",ends={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},questType="standard"},
[38947] = {id=38947,name="Runic Catgut",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Let me guess... thread troubles? Mm-hm. I suspected as much. My people weave sumptuous silks, but those silks can be fickle about the types of thread they'll accept. Shal'dorei silk has a bit of ley energy woven right into it. You need something that's learned to coexist with the ley energies of this land. I'm talking about owlcats, my good friend! They have what you need. You'll find them amongst the ruins of Llothien.",starts={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},ends={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},coords={x=0.6,y=0.346,source="quest_giver",zoneID=7334},questType="standard"},
[38948] = {id=38948,name="Hard Times",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="When I worked at the tailoring guild in Suramar, I would usually work off of a pattern. Something that inspired me. Unfortunately, I've run into streak of bad luck, and I'm ashamed to say that I no longer have my patterns. The naga sorceresses in the lagoon to the west, however, have expertly-sewn wristwraps. And the nightfallen to the north wear robes that we can use... if you can pry one from their greedy clutches.",questType="standard"},
[38949] = {id=38949,name="So You Think You Can Sew",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Very good, I think we're ready to begin. Lyndras steals a glance at your powerful weapon. A look of hunger washes over his face before he shakes it off and continues.> Let's prepare our materials and make the robe and bracers that you so rightfully deserve!",starts={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},ends={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},coords={x=0.6,y=0.346,source="quest_giver",zoneID=7334},questType="standard"},
[38950] = {id=38950,name="The Wayward Tailor",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Might I ask a favor, ? As I am recently without a home, shop, family, or friends, I was wondering if you might show me your floating city? I must admit, I am VERY curious about the place. I've also heard good things about their tailoring shop. I have no way of getting there myself, but certainly such a magical city has SOMEONE who can summon me. Lyndras looks at you with hopeful apprehension.>",starts={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},coords={x=0.6,y=0.346,source="quest_giver",zoneID=7334},questType="standard"},
[38951] = {id=38951,name="A Needle Need",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="This shop has almost everything we need. Unfortunately, the quality of your sewing needles is lacking. I do know where you can get better needles. The sprites of Val'sharah are covered with spines which, fortuitously, are perfect for the type of sewing we need. I hate to be such a prickler stickler, but these needles really will make a difference.",starts={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},coords={x=0.6,y=0.346,source="quest_giver",zoneID=7334},questType="standard"},
[38952] = {id=38952,name="Meticulous Precision",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="The needles are sharp, but look at them closely. Some have a curve to them, others have a spur hanging off the side. Look at this one... it's got a ninety-degree crook in it! I have no desire to sew around a corner. Tiffany Cartier in the jewelcrafting shop has a good eye for this sort of thing. Bring these needles to her, and she'll straighten them out.",ends={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},questType="standard"},
[38953] = {id=38953,name="Advanced Needlework",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="You've already learned the patterns for bracers, belts, epaulets, and of course, robes. Unfortunately, your technique was wasteful... you need a better method. That's where our needles come in. Here, I'll show you how to improve the process of these patterns.",starts={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},ends={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},coords={x=0.6,y=0.346,source="quest_giver",zoneID=7334},questType="standard"},
[38954] = {id=38954,name="Where's Lyndras?",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="That's strange. Lyndras was here one moment, and then he ran off the next. He had such a strange look on his face. Perhaps we should track him down.",ends={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},questType="standard"},
[38955] = {id=38955,name="Sew Far, Sew Good",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Your tailoring skill really is impressive and, although I don't have my patterns with me, I do have some patterns memorized. One of those patterns is for a simple bag. Follow my lead, .",starts={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},ends={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},coords={x=0.6,y=0.346,source="quest_giver",zoneID=7334},questType="standard"},
[38956] = {id=38956,name="Where's Lyndras Again?",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="Oh dear. He had just promised you that he wouldn't wander off, and then he did it again! I'm starting to think that this Lyndras character might be a bit too impetuous for my tastes. Please, go find him, before he gets into any more trouble.",ends={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},questType="standard"},
[38957] = {id=38957,name="Taking Inspiration",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="I wish I had more patterns to share, but my notebook was lost along with my shop. We'll need to come up with some patterns on our own. I've been thinking about the leather breeches that the Stormheim vrykul wear. They're certainly much thicker and heavier than anything we could sew, but their embellishing runework is quite impressive. If I had a few pairs, perhaps I could re-imagine this runework on a more... refined garment.",starts={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},ends={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},coords={x=0.6,y=0.346,source="quest_giver",zoneID=7334},questType="standard"},
[38958] = {id=38958,name="The Right Color",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="Your assistance, , if you have a moment. I've been attempting to reproduce a pattern for footwear that I spotted a while back, but I'm having trouble getting the right color for my dye. Our black dye is too dark, our blue dye is too bright, and mixing the two doesn't look right. The color I'm looking for is more of a squid-ink blue. If, in your travels, you come across any dyes of this color, would you do me the favor of bringing some to me?",questType="standard"},
[38959] = {id=38959,name="Left Behind",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="I do truly want to help you work on your tailoring, but without my patterns or my supplies, there isn't much more I can do save for teaching you what little I remember. If my memory still serves true, you're just missing a good pattern for some gloves and a hood. The first thing I need you to do is grab a few things from where you first met me. Here's what I need...",starts={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},ends={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},coords={x=0.6,y=0.346,source="quest_giver",zoneID=7334},questType="standard"},
[38960] = {id=38960,name="Lining Them Up",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Since you're heading to Azsuna, you may as well gather some lining for our projects. The bears of Azsuna are known for how soft, yet durable their fur is. Hunt them in the woods around Llothien and bring their fur back with you.",starts={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},ends={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},coords={x=0.6,y=0.346,source="quest_giver",zoneID=7334},questType="standard"},
[38961] = {id=38961,name="Eye of Azshara: The Depraved Nightfallen",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8040,description="In order to craft the gloves, we'll require a special item. This will be no easy task to recover it, . The naga of Azsuna are said to be hard at work trying to summon a terrible creature into this world. The creature's heart holds immense energy that we can use to channel into the gloves, making them incredibly powerful. I need... I mean, we need that heart if we are to produce a suitable pair of gloves for someone of your presence.",starts={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},coords={x=0.6,y=0.346,source="quest_giver",zoneID=7334},questType="dungeon"},
[38962] = {id=38962,name="The Path to Suramar City",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,description="I recall Lyndras mentioning a guild of tailors within Suramar City. Perhaps they could further our understanding of how to utilize this new cloth. Unfortunately from what I've heard, they've sided with the demons and anyone opposed to them is to be killed on sight. You must find a way to move safely within the confines of their city if we're to continue our research.",questType="standard"},
[38963] = {id=38963,name="The Final Lesson?",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Now that we have everything we need, let's work on the hood. After we're finished, we'll move onto the gloves.",starts={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},ends={{npcID=93967,x=0.6,y=0.346,zoneID=7334}},coords={x=0.6,y=0.346,source="quest_giver",zoneID=7334},questType="standard"},
[38964] = {id=38964,name="Where's Lyndras Now?",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,description="Lyndras couldn't have gone very far. I mean, we're floating a thousand feet over the sea. I heard some commotion across the way this morning near the alchemy shop. I pray that wasn't Lyndras. Could you please go over there and make sure?",questType="standard"},
[38965] = {id=38965,name="Assault on Violet Hold: Into the Hold",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7996,description="With Lyndras being locked up in Violet Hold, you feel responsible for him and must discover the truth behind his actions. Perhaps if you were able to speak with him, you could find a way to have him released from the hold and put back into your custody. Go into Violet Hold and find out what happened to Lyndras .",questType="dungeon"},
[38966] = {id=38966,name="Secret Silkweaving Methods",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,description="Okay, done mourning! Let's look through his stuff. Tanithria takes a moment to leaf through Lyndras' journal. Her eyes open wide.> Our friend has been keeping secrets from us. Look at this! Every single one of the recipes he's taught us can be improved. Let's start simple, with some bracers. I can supply most of the materials, but you'll have to talk to Alard Schmied in the blacksmithing shop to get this powdered brimstone.",questType="standard"},
[38967] = {id=38967,name="The Nightborne Connection",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Now that you're able to disguise yourself, you should go to Suramar City and try to find this guild of tailors. Good luck, , and try not to get caught.",ends={{npcID=93969,x=0.404,y=0.694,zoneID=7637}},questType="standard"},
[38968] = {id=38968,name="Proof of Loyalty",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="I see. You sound almost... sympathetic to the wretch. The nightfallen are liars and thieves. ALL of them. Lyndras included. I will not tolerate a student that has any respect or sympathy for those... things. And have you witnessed what they turn into at the depths of their depravity? If you want to get on my good side, do not return until you are covered in the blood of the withered .",starts={{npcID=93969,x=0.404,y=0.694,zoneID=7637}},ends={{npcID=93969,x=0.404,y=0.694,zoneID=7637}},coords={x=0.404,y=0.694,source="quest_giver",zoneID=7637},questType="standard"},
[38969] = {id=38969,name="Master of Silkweave",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="While Tytallo is busy exacting withered genocide, it falls on me to take care of the more mundane aspects of training. We're going to need to see how talented you are. Craft an entire set of silkweave armor for me. Leyweaver Mithrogane can provide you with a proper mannequin for displaying it.",starts={{npcID=93971,x=0.402,y=0.696,zoneID=7637}},ends={{npcID=93971,x=0.402,y=0.696,zoneID=7637}},coords={x=0.402,y=0.696,source="quest_giver",zoneID=7637},questType="standard"},
[38970] = {id=38970,name="The Queen's Grace Loom",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Great power comes only with sacrifice. Even the most masterful tailor can only do so much with silkweave. To improve your patterns any further, bargains must be made. You are prepared, , to learn about working with Imbued Silkweave. Use the teleportation crystal behind me, and speak with Azayna, the leader of our order.",starts={{npcID=93969,x=0.404,y=0.694,zoneID=7637}},ends={{npcID=93969,x=0.404,y=0.694,zoneID=7637}},coords={x=0.404,y=0.694,source="quest_giver",zoneID=7637},questType="standard"},
[38971] = {id=38971,name="Exotic Textiles",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="I'm risking my life and career to be here, tailor. I've been curious about demonic cloth, and my attempts to obtain some through approved means have been met with resistance. I simply must see this cloth for myself. I don't wish to disrupt Azayna's pact with the demons, but you - you can attack the demons without drawing attention to our guild. I'm particularly interested in a particular demon's set of robes. Bring me a scrap, and I'll teach you what I know.",questType="standard"},
[38974] = {id=38974,name="Halls of Valor: The Right Question",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=1477,description="One might ask what a leyweaver is doing standing over a dead vrykul's body. But such questions only stir up trouble. Instead let us ask what can be learned from those who have passed on. A question like that promotes progress. I assume you're here to learn from me, the pattern for Imbued Silkweave pants, yes? If that's true, then I'll need something from one who has passed on. In the Halls of Valor the great guardian, Hymdall resides. Bring me his loincloth and I will teach you my pattern.",starts={{npcID=93977,x=0.656,y=0.562,zoneID=7541}},ends={{npcID=93977,x=0.656,y=0.562,zoneID=7541}},coords={x=0.656,y=0.562,source="quest_giver",zoneID=7541},questType="dungeon"},
[38975] = {id=38975,name="Inspire Me!",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="I am, and always will be, a student of robemaking and dressmaking. You can keep your gloves, belts, and cloaks. Nothing beats a good robe. I'll share my pattern for an imbued silkweave robe with you if you can teach me some of the robe and dress patterns you've learned along your tailoring journey.",starts={{npcID=93976,x=0.402,y=0.696,zoneID=7637}},ends={{npcID=93976,x=0.402,y=0.696,zoneID=7637}},coords={x=0.402,y=0.696,source="quest_giver",zoneID=7637},questType="standard"},
[38976] = {id=38976,name="FLAG: Undying Silkweave Bracers Crafted",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[38977] = {id=38977,name="FLAG: Undying Silkweave Cinch Crafted",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[38978] = {id=38978,name="FLAG: Undying Silkweave Epaulets Crafted",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[38979] = {id=38979,name="FLAG: Undying Silkweave Slippers Crafted",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[38980] = {id=38980,name="FLAG: Undying Silkweave Gloves Crafted",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[38981] = {id=38981,name="FLAG: Undying Silkweave Hood Crafted",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[38982] = {id=38982,name="FLAG: Undying Silkweave Pantaloons Crafted",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[38983] = {id=38983,name="FLAG: Undying Silkweave Robe Crafted",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[38989] = {id=38989,name="Your Orders, General?",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=6723,description="General, your forces in Tanaan Jungle await your orders. Travel to the Planning Map there to issue your commands. For the Horde!",ends={{npcID=90481,x=0.408,y=0.732,zoneID=6720},{npcID=90481,x=0.614,y=0.458,zoneID=6723}},questType="standard"},
[38990] = {id=38990,name="The Call of Icecrown",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7543,description="I have ordered your brethren to Icecrown to prepare for the coming conflict, but I have a more important fate in mind for you. You, , will be the hand of our vengeance! Use the Death Gate to return to Acherus and I shall reveal your role in this.",questType="standard"},
[38992] = {id=38992,name="Mograine's Oath",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[38994] = {id=38994,name="TRACKING Encounter Botanist",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,description="(PH) Darkgrove has run out of places to hide. Now it is time to finish him off. If we stop him now, there may be hope for this valley yet.",questType="standard"},
[38995] = {id=38995,name="Unused",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[39000] = {id=39000,name="We Don't Need No Library Card",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=7078,description="If history is any indication, Gul'dan is training a whole generation of warlocks to marshal against us. If we act fast, we can stem the tide and make things easier on ourselves. As you and your fellow heroes venture into the depths of the Hellfire Citadel, seek out Tomes of Chaos from Gul'dan's lieutenants. They're dangerous, so don't read any of them. Not even the pictures. ESPECIALLY the pictures.",starts={{npcID=92213,x=0.276,y=0.102,zoneID=6719},{npcID=92213,x=0.408,y=0.732,zoneID=6720},{npcID=92213,x=0.32,y=0.324,zoneID=7078}},ends={{npcID=92213,x=0.276,y=0.102,zoneID=6719},{npcID=92213,x=0.408,y=0.732,zoneID=6720},{npcID=92213,x=0.32,y=0.324,zoneID=7078}},coords={x=0.276,y=0.102,source="quest_giver",zoneID=6719},questType="raid"},
[39003] = {id=39003,name="Cooking the Books",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=6662,description=", we've got to destroy these tomes. Many of them have actual tortured souls bound into the pages, so we can't just burn them. Cordana will know what to do. Take these books to my tower in Zangarra and give them to Cordana. Let me know when the deed is done.",starts={{npcID=92213,x=0.276,y=0.102,zoneID=6719},{npcID=92213,x=0.408,y=0.732,zoneID=6720},{npcID=92213,x=0.32,y=0.324,zoneID=7078}},ends={{npcID=92213,x=0.276,y=0.102,zoneID=6719},{npcID=92213,x=0.408,y=0.732,zoneID=6720},{npcID=92213,x=0.32,y=0.324,zoneID=7078}},coords={x=0.276,y=0.102,source="quest_giver",zoneID=6719},questType="standard"},
[39004] = {id=39004,name="Darkness Incarnate",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=7545,description="We have one final task before us, . We must defeat Gul'dan and unravel his plans for this world. I have no reward to offer you - I have given you everything I can. Come. When you and your allies are ready, we march on Hellfire Citadel... and end this.",starts={{npcID=92213,x=0.276,y=0.102,zoneID=6719},{npcID=92213,x=0.408,y=0.732,zoneID=6720},{npcID=92213,x=0.32,y=0.324,zoneID=7078}},ends={{npcID=92213,x=0.276,y=0.102,zoneID=6719},{npcID=92213,x=0.408,y=0.732,zoneID=6720},{npcID=92213,x=0.32,y=0.324,zoneID=7078}},coords={x=0.276,y=0.102,source="quest_giver",zoneID=6719},questType="raid"},
[39011] = {id=39011,name="Black Rook Invasion",level=10,requiredLevel=10,faction="none",expansion=6,zoneID=7558,mapID=641,description="Once, this area was peaceful and prosperous. Then we saw the first bad omens: strange ailments, spoiled crops, and the like. Now ghosts attack us from that castle across the river, and undead assassins slay our fishers so as to cut off the village's food supply. We're the last family living this close to the castle, but we daren't retreat: this river is the best route for fishers to bring their hauls in to town. Please, will you take the fight to these undead?",questType="standard"},
[39015] = {id=39015,name="Grumpy",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,mapID=641,starts={{npcID=92738,x=0.386,y=0.656,mapID=641}},ends={{npcID=92738,x=0.386,y=0.656,mapID=641}},coords={x=0.386,y=0.656,source="quest_giver",mapID=641},questType="standard"},
[39017] = {id=39017,name="Rise to the Occasion",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7543,mapID=646,description="The Lich King made a wise choice in giving you that weapon, . You've proven your strength and cunning on countless occasions and it is time that you have a position fitting for your accomplishments.",questType="standard"},
[39018] = {id=39018,name="Call of the Archmage",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=6662,description="Archmage Khadgar has a very urgent favor to ask. He is gravely concerned about additional threats this world may hold for Azeroth, and he will need your assistance pursuing them. Please see him at his tower, east of Talador, in the Zangarra swamp.",ends={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},questType="standard"},
[39019] = {id=39019,name="Call of the Archmage",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=6662,description="Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.",ends={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},questType="standard"},
[39020] = {id=39020,name="A Burning Path Through Time",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=7078,description="The blazing star shines upon the land, searing the earth and parching the landscape. This star is relentless, malevolent almost. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.",starts={{npcID=94870,x=0.418,y=0.468,zoneID=7004},{npcID=94870,x=0.334,y=0.374,zoneID=7078}},ends={{npcID=94870,x=0.418,y=0.468,zoneID=7004},{npcID=94870,x=0.334,y=0.374,zoneID=7078}},coords={x=0.418,y=0.468,source="quest_giver",zoneID=7004},questType="standard"},
[39021] = {id=39021,name="A Frozen Path Through Time",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=7078,description="The chill star shines upon the land with its cold light as even the spirits retreat to the shadows. This star is unlike any other in the skies, sapping warmth and life. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.",starts={{npcID=94870,x=0.418,y=0.468,zoneID=7004},{npcID=94870,x=0.334,y=0.374,zoneID=7078}},ends={{npcID=94870,x=0.418,y=0.468,zoneID=7004},{npcID=94870,x=0.334,y=0.374,zoneID=7078}},coords={x=0.418,y=0.468,source="quest_giver",zoneID=7004},questType="standard"},
[39022] = {id=39022,name="Call of the Archmage",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6662,description="Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.",ends={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},questType="standard"},
[39023] = {id=39023,name="Call of the Archmage",level=40,requiredLevel=40,faction="none",expansion=6,description="Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp. This will not take long.",questType="standard"},
[39024] = {id=39024,name="Call of the Archmage",level=40,requiredLevel=40,faction="none",expansion=6,description="Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp. This will not take long.",questType="standard"},
[39025] = {id=39025,name="Grasp of the Underking",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="If we have one good fortune in this it is that Dargrul has no knowledge of how to use the hammer. He keeps thinking of the hammer as a weapon instead of a tool of creation. Even so, he has imprisoned our tribesman in fists of stone summoned from the earth. Our weapons have proven useless against this magic. You might have power enough to break these fists. Can you help?",starts={{npcID=93805,x=0.386,y=0.684,zoneID=7503}},ends={{npcID=97553,x=0.412,y=0.724,zoneID=7503}},coords={x=0.386,y=0.684,source="quest_giver",zoneID=7503},questType="standard"},
[39026] = {id=39026,name="The Drogbar",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="It wasn't enough for Dargrul to just destroy this village. He has also sent his Stoneraiders to take what is left. Please champion, prove to my people that you are the hero I foresaw. Slay enough of these Stoneraiders that it breaks their resolve.",starts={{npcID=93805,x=0.386,y=0.684,zoneID=7503}},ends={{npcID=97553,x=0.412,y=0.724,zoneID=7503}},coords={x=0.386,y=0.684,source="quest_giver",zoneID=7503},questType="standard"},
[39027] = {id=39027,name="Dargrul and the Hammer",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="We are about to follow a drogbar into a cave, something we warn our children never to do. Even so, several of our warbraves have already followed Dargrul inside. Come, join us in battle and let us reclaim the Hammer of Khaz'goroth.",questType="standard"},
[39028] = {id=39028,name="REUSE ME",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7558,mapID=641,description="asdf",questType="standard"},
[39030] = {id=39030,name="Arauk Nashal 70:JP3 - Aggramar's Vault - Tracking Quest Cleared - God-King Intro",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7541,mapID=634,questType="standard"},
[39032] = {id=39032,name="A Summons from Saylanna",level=10,requiredLevel=10,faction="none",expansion=6,zoneID=7558,mapID=641,description="Sprites have always been mischievous creatures, but lately their mischief has turned to violence. One of the druids I call friend, Saylanna Riverbreeze, reports that they are assaulting the faerie dragon nesting grounds. The Lunarwing Shallows lie to the south. You will find Saylanna there.",questType="standard"},
[39033] = {id=39033,name="The Time to Strike",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=7078,description="This configuration of the stars causes an unusual vibration in the crystals strewn across Draenor, relics of the ancient Apexis. Some swear that the crystals will multiply when left unattended beneath the night sky, but none have seen the phenomenon firsthand. Regardless of the true cause, these crystals should be far more plentiful should you seek them out.",starts={{npcID=94870,x=0.418,y=0.468,zoneID=7004},{npcID=94870,x=0.334,y=0.374,zoneID=7078}},ends={{npcID=94870,x=0.418,y=0.468,zoneID=7004},{npcID=94870,x=0.334,y=0.374,zoneID=7078}},coords={x=0.418,y=0.468,source="quest_giver",zoneID=7004},questType="standard"},
[39034] = {id=39034,name="Emissary of War",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=7078,description="When the sign of the emissary shines in the night sky, the stars strengthen existing bonds and forge new ones. Friendship is still not cheaply won, and deeds will prove loyalty, but trust comes more readily during these days. Venture deep into caverns and strongholds to prove your worth.",starts={{npcID=94870,x=0.418,y=0.468,zoneID=7004},{npcID=94870,x=0.334,y=0.374,zoneID=7078}},ends={{npcID=94870,x=0.418,y=0.468,zoneID=7004},{npcID=94870,x=0.334,y=0.374,zoneID=7078}},coords={x=0.418,y=0.468,source="quest_giver",zoneID=7004},questType="standard"},
[39040] = {id=39040,name="A Call to Battle",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=7078,description="The favorite star of warlords and generals dominates the sky, offering good fortune to tacticians everywhere. Some say that the battle star hones the instincts of commanders to the point of near-prophecy. If ever you were going to test yourself on the field of battle, now is the time.",starts={{npcID=94870,x=0.418,y=0.468,zoneID=7004},{npcID=94870,x=0.334,y=0.374,zoneID=7078}},ends={{npcID=94870,x=0.418,y=0.468,zoneID=7004},{npcID=94870,x=0.334,y=0.374,zoneID=7078}},coords={x=0.418,y=0.468,source="quest_giver",zoneID=7004},questType="standard"},
[39041] = {id=39041,name="The Arena Calls",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=7078,description="This alignment of the stars is a dire sign, stirring bloodlust and calling warriors to battle to the death in close quarters. Arena masters turn a tidy profit during these days, likely not understanding why their stands are overflowing. Amidst the excitement, great rewards do await those brave, or foolhardy, enough to venture into the arena....",starts={{npcID=94870,x=0.418,y=0.468,zoneID=7004},{npcID=94870,x=0.334,y=0.374,zoneID=7078}},ends={{npcID=94870,x=0.418,y=0.468,zoneID=7004},{npcID=94870,x=0.334,y=0.374,zoneID=7078}},coords={x=0.418,y=0.468,source="quest_giver",zoneID=7004},questType="standard"},
[39042] = {id=39042,name="The Very Best",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7078,description="This alignment of the stars is truly a strange one, causing the tiniest of creatures to gain unnatural aptitude. None of our sages can explain the phenomenon, but cunning tamers have much to gain, especially by testing their skills against those of their peers.",starts={{npcID=94870,x=0.418,y=0.468,zoneID=7004},{npcID=94870,x=0.334,y=0.374,zoneID=7078}},ends={{npcID=94870,x=0.418,y=0.468,zoneID=7004},{npcID=94870,x=0.334,y=0.374,zoneID=7078}},coords={x=0.418,y=0.468,source="quest_giver",zoneID=7004},questType="standard"},
[39043] = {id=39043,name="Bitestone Enclave",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="This is an old drogbar enclave that we used to trade with. Now it is a base of operations for their raids. I need more time to gather what is left of our warbraves. Go, enter the enclave, and slay any you find in there. Buy us the time we need to gather our strength.",questType="standard"},
[39044] = {id=39044,name="Unused",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[39045] = {id=39045,name="Vignette: Zoug",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=6723,mapID=534,questType="standard"},
[39046] = {id=39046,name="Vignette: Harbormaster Korak",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=6723,mapID=534,questType="standard"},
[39047] = {id=39047,name="Call of the Illidari",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description=", Altruis requests that you meet him at Krasus' Landing at once. You must hurry. The Legion has eyes everywhere.",questType="standard"},
[39049] = {id=39049,name="Eye On the Prize",level=8,requiredLevel=8,faction="both",expansion=6,zoneID=7705,description="This demon has proved less than useful. I have been using the Scythe of Souls on it, but so far, it has resisted my inquiries. We will see how long that lasts. I have a different idea... There is a fresh inquisitor demon ahead. They are horrific fel casters who see through their floating eyes and specialize in dark pacts. If you steal its power, Jace Darkweaver could use some of it in his ritual to spy on the Legion. Better yet, you will gain its power by ripping it from its smoking corpse.",starts={{npcID=94410,x=0.338,y=0.7,zoneID=7705}},ends={{npcID=93759,x=0.388,y=0.606,zoneID=7705}},coords={x=0.338,y=0.7,source="quest_giver",zoneID=7705},questType="standard"},
[39050] = {id=39050,name="Meeting With the Queen",level=8,requiredLevel=8,faction="both",expansion=6,zoneID=7705,description="We can use some of that essence to complete my ritual. You'll be able to spy upon the Legion leaders and see what they're planning. Use the nether crucible and complete the ritual.",starts={{npcID=93759,x=0.388,y=0.606,zoneID=7705}},ends={{npcID=93759,x=0.388,y=0.606,zoneID=7705}},coords={x=0.388,y=0.606,source="quest_giver",zoneID=7705},questType="standard"},
[39051] = {id=39051,name="By Any Means",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7777,description="We need to figure out what rock Varedis is hiding under - the only way we're going to do that is by getting inside this prison. Do what you must.",questType="standard"},
[39054] = {id=39054,name="Shipbuilding",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6720,description="The first thing we need to start building ships is a blueprint. With your help, I grabbed some of the best ones from the Iron Docks before we broke out of there. Let's make sure these don't fall back into the hands of the Iron Horde. Memorize these blueprints, , and then destroy the evidence. Let me know when you are done.",starts={{npcID=94429,x=0.298,y=0.106,zoneID=6719},{npcID=94429,x=0.408,y=0.702,zoneID=6720}},ends={{npcID=94429,x=0.298,y=0.106,zoneID=6719},{npcID=94429,x=0.408,y=0.702,zoneID=6720}},coords={x=0.298,y=0.106,source="quest_giver",zoneID=6719},questType="standard"},
[39055] = {id=39055,name="Ship Shape",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6719,description="Now that we have the blueprints, let's get started on our first ship, a transport! Speak to me when you are ready to begin construction.",starts={{npcID=95002,x=0.298,y=0.106,zoneID=6719}},ends={{npcID=95002,x=0.298,y=0.106,zoneID=6719}},coords={x=0.298,y=0.106,source="quest_giver",zoneID=6719},questType="standard"},
[39056] = {id=39056,name="Naval Commander",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6719,description="We have come a long way in a short time on this shipyard, . Now it's time to run our first naval mission and control the seas of Draenor! I will need to setup shop from a high vantage point to plan out these seafaring missions. Meet me near the shipyard entrance and we can get started.",starts={{npcID=93822,x=0.282,y=0.116,zoneID=6719}},ends={{npcID=93822,x=0.282,y=0.116,zoneID=6719}},coords={x=0.282,y=0.116,source="quest_giver",zoneID=6719},questType="standard"},
[39057] = {id=39057,name="Command of the Seas",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=7078,description="Gul'dan wasted no time integrating his Shadow Council minions into every rank of the Iron Horde. The naval fleet that once owed loyalty only to Grommash is now his to command. If we want to fight back, we're going to need more than just a couple of transport ships. We must build an arsenal. We need your expertise, commander. Upgrade your dockyards and create a fleet capable of dominating the seas!",starts={{npcID=92213,x=0.276,y=0.102,zoneID=6719},{npcID=92213,x=0.408,y=0.732,zoneID=6720},{npcID=92213,x=0.32,y=0.324,zoneID=7078}},ends={{npcID=92213,x=0.276,y=0.102,zoneID=6719},{npcID=92213,x=0.408,y=0.732,zoneID=6720},{npcID=92213,x=0.32,y=0.324,zoneID=7078}},coords={x=0.276,y=0.102,source="quest_giver",zoneID=6719},questType="standard"},
[39058] = {id=39058,name="Critters of Draenor",level=1,requiredLevel=1,faction="none",expansion=6,description="I love collecting pets, and I've picked up a few unusual pets here in Draenor. What would you say to a battle? If you can defeat my humble team, I think we'll both learn a few new tricks.",questType="standard"},
[39059] = {id=39059,name="To Catch a Banshee",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=7541,description="The strange-talking vrykul said I might be able to meet you here. I have orders from Greymane. It seems he may have a lead on Sylvanas' location. He's set up a camp near the base of the mountain. We've run into some troubles, though. It looks like the Horde may have homed in on our position. We could use your help. You can take my gryphon. Just speak to me when you're ready to leave.",starts={{npcID=94346,x=0.6,y=0.512,zoneID=7541}},ends={{npcID=94318,x=0.716,y=0.598,zoneID=7541}},coords={x=0.6,y=0.512,source="quest_giver",zoneID=7541},questType="standard"},
[39060] = {id=39060,name="Combustible Contagion",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=7541,description="It is true that we may have a lead on Sylvanas. Though I want nothing more than to get my hands on the Banshee Queen, the situation here at Greywatch requires immediate attention. Yesterday, a regiment of guards returned with word of Forsaken forces in the woods. Several of them bore signs of a blight, similar to the one we endured in Gilneas. It would appear these Forsaken seek to unleash this blight upon Greywatch. Seek out their caches and destroy them, before the blight overtakes us!",starts={{npcID=94318,x=0.716,y=0.598,zoneID=7541}},ends={{npcID=94318,x=0.716,y=0.598,zoneID=7541}},coords={x=0.716,y=0.598,source="quest_giver",zoneID=7541},questType="standard"},
[39061] = {id=39061,name="Whispers from the Dark",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=7541,description="We still have little knowledge of the Horde's activities in the region, but I'm hoping you can help change that. Lately the woods have been crawling with Sylvanas' agents. The few we have taken out carried orders from her Dark Rangers, who are no doubt in command of her forces here. While you're on the hunt, keep an eye out for any scouting orders. They may help us pinpoint Sylvanas' objective in the area.",starts={{npcID=94318,x=0.716,y=0.598,zoneID=7541}},ends={{npcID=94318,x=0.716,y=0.598,zoneID=7541}},coords={x=0.716,y=0.598,source="quest_giver",zoneID=7541},questType="standard"},
[39062] = {id=39062,name="To Skold-Ashil",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=7541,description="We have her now! According to these reports, Sylvanas' forces are after something in Skold-Ashil - a vrykul town not far from here. We must make our way there and track her down. I had previously dispatched Commander Lorna Crowley and a detachment of Gilneas Brigade to scout the position. Meet up with her there and find out what Sylvanas is after. Meanwhile, I will muster the fleet to assault their outpost. We will have justice if I have to reduce their camp to rubble!",starts={{npcID=94318,x=0.716,y=0.598,zoneID=7541}},ends={{npcID=93779,x=0.636,y=0.618,zoneID=7541}},coords={x=0.716,y=0.598,source="quest_giver",zoneID=7541},questType="standard"},
[39063] = {id=39063,name="Shielded Secrets",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=7541,description="It's obvious at this point that the Horde wants something in Skold-Ashil. Unfortunately we still don't know what they're after. We think the secret lies with the shieldmaidens here, so we need to find out more about them. Some early scouting revealed that they have a method of carving their shields to tell their stories. Go into the city and find as many of these shields as you can. With luck, we will find what Sylvanas seeks.",starts={{npcID=93779,x=0.636,y=0.618,zoneID=7541}},ends={{npcID=95921,x=0.606,y=0.65,zoneID=7541}},coords={x=0.636,y=0.618,source="quest_giver",zoneID=7541},questType="standard"},
[39067] = {id=39067,name="Upgrading The Fleet",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6719,description="You have been doing a great job out there commander. However, we are going to need more experience and resources to upgrade this shipyard. Once we reach our goals, we can upgrade the capacity of the shipyard to hold more ships!",starts={{npcID=93822,x=0.282,y=0.116,zoneID=6719}},ends={{npcID=93822,x=0.282,y=0.116,zoneID=6719}},coords={x=0.282,y=0.116,source="quest_giver",zoneID=6719},questType="standard"},
[39068] = {id=39068,name="Naval Domination",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6719,description="Our naval domination continues! However, we are going to need even more experience and resources to take this shipyard to the next level. Once we reach our goals, we can upgrade the capacity of the shipyard to hold even more ships!",starts={{npcID=93822,x=0.282,y=0.116,zoneID=6719}},ends={{npcID=93822,x=0.282,y=0.116,zoneID=6719}},coords={x=0.282,y=0.116,source="quest_giver",zoneID=6719},questType="standard"},
