[39082] = {id=39082,name="Let's Get To Work",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6720,description="Now that the shipyard is complete, we need to get busy making ships! Solog ran off to the dry docks, why don't you meet him down there? He said he had a plan.",starts={{npcID=93822,x=0.282,y=0.116,zoneID=6719},{npcID=97085,x=0.282,y=0.106,zoneID=6719}},ends={{npcID=94429,x=0.298,y=0.106,zoneID=6719},{npcID=94429,x=0.408,y=0.702,zoneID=6720}},coords={x=0.282,y=0.116,source="quest_giver",zoneID=6719},questType="standard"},
