[39092] = {id=39092,name="Becoming the Ascendant",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=7541,description="Our course is now clear. We must enter the vault and prevent Sylvanas from obtaining the power to create more Val'kyr. The entrance is barred, which is likely what has kept her out so far, but you may have already uncovered the key to this barrier. You must become the next ascendant. Complete the rites as depicted on the shields and take down the barrier to the vault. I will send word to Greymane of our findings - he will wish to confront Sylvanas himself.",starts={{npcID=95921,x=0.606,y=0.65,zoneID=7541}},ends={{npcID=95804,x=0.622,y=0.68,zoneID=7541}},coords={x=0.606,y=0.65,source="quest_giver",zoneID=7541},questType="standard"},
