[39379] = {id=39379,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[39380] = {id=39380,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[39381] = {id=39381,name="Rock Troll in a Hard Place",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="We should leave this place while we have a chance. The Bloodtotem are amassing at their village to the north, and I believe they intend to kill my people. Let me know when you are ready to go, and I can take us to a safe place quickly.",ends={{npcID=95421,x=0.452,y=0.324,zoneID=7503}},questType="standard"},
[39383] = {id=39383,name="Dishonored",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="Xandris the Dishonored was among the first to betray his brethren and accept the curse of Xavius. During the great war, it was he who led the slaughter of many of my dearest friends. The last time I met him on the battlefield he fled. Help me to finally dispense justice on this foul being.",starts={{npcID=95395,x=0.61,y=0.732,zoneID=7558}},ends={{npcID=95396,x=0.628,y=0.716,zoneID=7558}},coords={x=0.61,y=0.732,source="quest_giver",zoneID=7558},questType="standard"},
[39384] = {id=39384,name="The Corruptor",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="Xandris has been slain, but there are others that must be dealt with if my grove is to be saved. During the great war, Kagraxxis took great pleasure in corrupting the lands he once called home. Were it not for the foolish mercy of my fellow druids, I would have slain him myself. Find the demon and bring justice upon him. I must entrust this task to you alone, for I sense an even darker presence here... one that requires my personal attention.",starts={{npcID=95396,x=0.628,y=0.716,zoneID=7558}},ends={{npcID=91650,x=0.65,y=0.67,zoneID=7558}},coords={x=0.628,y=0.716,source="quest_giver",zoneID=7558},questType="standard"},
[39385] = {id=39385,name="A Gift for Greymane",level=10,requiredLevel=10,faction="horde",expansion=6,zoneID=7541,description="It looks like the Gilnean infiltrators brought some heavy ordnance to the fight. It's likely they intend to use them on the walls of Dreadwake's Landing. If these could be rigged to Greymane's ship, it could make for a decisive end to his assault on the outpost.",starts={{npcID=243454,x=0.576,y=0.719,zoneID=7541}},ends={{npcID=93603,x=0.55,y=0.724,zoneID=7541}},coords={x=0.576,y=0.719,source="quest_giver",zoneID=7541},questType="standard"},
[39386] = {id=39386,name="Procuring a Prototype",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="If Addie's going to be a more permanent member of the huntin' party, then she'll need some specialty gear for someone her size. My munitions expert should have some ideas about what kind of weapon would best suit a gnome. Stop by his camp and let him know that I'll be needin' a prototype soon.",starts={{npcID=94409,x=0.4,y=0.522,zoneID=7503}},ends={{npcID=96513,x=0.576,y=0.566,zoneID=7503}},coords={x=0.4,y=0.522,source="quest_giver",zoneID=7503},questType="standard"},
[39387] = {id=39387,name="The Skies of Highmountain",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="When you are ready, join me at the base of Thunder Totem. I would be honored to have you at my side as my tribe once again swears its allegiance to the young Mayla. Together, we are Highmountain !",ends={{npcID=93826,x=0.448,y=0.504,zoneID=7731},{npcID=108434,x=0.446,y=0.504,zoneID=7731}},questType="standard"},
[39388] = {id=39388,name="Moonclaw's Wisdom",level=10,requiredLevel=10,faction="none",expansion=6,zoneID=7558,mapID=641,description="Our quick action today has stopped this aggression and saved my valley. As you requested, I will join Malfurion in the Grove of Cenarius. Still, there is much about these satyrs that I wish to tell you. This information would be most valuable to you. Please meet me in my den before departing.",questType="standard"},
[39389] = {id=39389,name="It Hungers for Blood",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7875,description="Bloodstones contain a great deal of power that can only be awakened once they are fed. Yet this stone does not feast on fish and cakes. It hungers for blood; the more powerful, the better. There's an infestation of demons just east of here. I need you to nourish my stone with their blood, so that I may unlock its power.",starts={{npcID=105816,x=0.608,y=0.306,zoneID=7334}},ends={{npcID=105816,x=0.608,y=0.306,zoneID=7334}},coords={x=0.608,y=0.306,source="quest_giver",zoneID=7334},questType="standard"},
[39390] = {id=39390,name="A Mysterious Text",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="You found a water-logged tome near the bones of a massive creature. Written in an unfamiliar language, the book is adorned with runes and alchemical symbols. Perhaps another alchemist would be able to tell you more.",starts={{npcID=243392,x=0.449,y=0.521,zoneID=7334}},coords={x=0.449,y=0.521,source="quest_giver",zoneID=7334},questType="standard"},
[39391] = {id=39391,name="Pet Rocks",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="I raise creatures born of the earth to help defend myself and my people. When I was captured, I ordered them to stay behind at our home, but they are often disobedient and likely tried to follow me. If they did, I fear the Bloodtotem may have captured them, or worse. In my current state, I can't muster the strength to find them. If you find them, it would be much appreciated.",starts={{npcID=95421,x=0.452,y=0.324,zoneID=7503}},ends={{npcID=95421,x=0.452,y=0.324,zoneID=7503}},coords={x=0.452,y=0.324,source="quest_giver",zoneID=7503},questType="standard"},
[39392] = {id=39392,name="Bear Huntin'",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="They say a single hair from the back of a bristlefur bear is sharp enough to cut a dwarf's beard. But if the fur doesn't kill ya, the maul will. Some lesser hunters have been a meal for those bears. Show me you're more than a snack and bring me back a few of those bristlefur pelts .",starts={{npcID=94409,x=0.4,y=0.522,zoneID=7503}},ends={{npcID=94409,x=0.4,y=0.522,zoneID=7503}},coords={x=0.4,y=0.522,source="quest_giver",zoneID=7503},questType="standard"},
[39394] = {id=39394,name="The Cipher of Damnation",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6723,description="Your ally and I will remove this barrier now, though it will take a greater part of our strength. What lies beyond will not be easy. Gul'dan will have empowered an elemental lord with the Cipher, driving it insane. He will use it to destroy the link between the elements and Draenor. If you destroy that elemental, we could recover the Cipher.",starts={{npcID=92120,x=0.626,y=0.31,zoneID=6723}},ends={{npcID=93658,x=0.626,y=0.276,zoneID=6723}},coords={x=0.626,y=0.31,source="quest_giver",zoneID=6723},questType="standard"},
[39395] = {id=39395,name="Oronok's Offer",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=6723,mapID=534,starts={{npcID=92338,x=0.628,y=0.278,mapID=534}},ends={{npcID=92338,x=0.628,y=0.278,mapID=534}},coords={x=0.628,y=0.278,source="quest_giver",mapID=534},questType="standard"},
[39398] = {id=39398,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[39401] = {id=39401,name="Destroying the Competition",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=6720,description="One battle does not win the war, Commander. That Transport isn't gonna hold up long against this Iron Horde navy. We are going to need another ship. Lucky for us, a local smuggler has supplied us with the plans we need to build Destroyers. We should construct one of these ships immediately!",starts={{npcID=94789,x=0.42,y=0.71,zoneID=6720}},ends={{npcID=94789,x=0.42,y=0.71,zoneID=6720}},coords={x=0.42,y=0.71,source="quest_giver",zoneID=6720},questType="standard"},
[39404] = {id=39404,name="Destroying the Competition",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6719,description="One battle does not win the war, Commander. That Transport isn't gonna hold up long against this Iron Horde navy. We are going to need another ship. Lucky for us, a local smuggler has supplied us with the plans we need to build Destroyers. We should construct one of these ships immediately!",starts={{npcID=93822,x=0.282,y=0.116,zoneID=6719}},ends={{npcID=93822,x=0.282,y=0.116,zoneID=6719}},coords={x=0.282,y=0.116,source="quest_giver",zoneID=6719},questType="standard"},
[39405] = {id=39405,name="Stories of Battle",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="The writings carried by the priestess appear to be the first part of an epic poem describing the history of Ashildir, the ancient queen of the Valkyra. If Ashildir has a connection to the shieldmaidens here, you may be able to use that to your advantage. The answer to her involvement likely lies within the remaining text.",starts={{npcID=251571,x=0.635,y=0.647,zoneID=7541}},ends={{npcID=94228,x=0.624,y=0.68,zoneID=7541}},coords={x=0.635,y=0.647,source="quest_giver",zoneID=7541},questType="standard"},
[39417] = {id=39417,name="Rating Razik",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Hemet is expecting an update on how my munitions research and development is going. I'm sure you'll be happy to tell my boss that my latest creation worked flawlessly! You can find him at his camp near the hunters' lodge.",starts={{npcID=96513,x=0.576,y=0.566,zoneID=7503}},ends={{npcID=94409,x=0.4,y=0.522,zoneID=7503}},coords={x=0.576,y=0.566,source="quest_giver",zoneID=7503},questType="standard"},
[39419] = {id=39419,name="Hex-a-Gone",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="The harpies are relentless in their pursuit to control the basin. They are able to craft bags of foul magic as quickly as we can destroy them. The Skyhorn cannot gain the upper hand as long as their hexweaver lives. She must be stopped.",starts={{npcID=94522,x=0.472,y=0.48,zoneID=7503}},ends={{npcID=94522,x=0.472,y=0.48,zoneID=7503}},coords={x=0.472,y=0.48,source="quest_giver",zoneID=7503},questType="standard"},
[39420] = {id=39420,name="Xavius Event TRACKING",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[39422] = {id=39422,name="Shipyard Report",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6719,description="Commander! We have received reports from the shipyard that things are getting serious. Can you head back to Lunarfall and check in with Merreck? Every ship we build gives us another advantage over Gul'dan's new Horde.",starts={{npcID=90309,x=0.584,y=0.602,zoneID=6723}},ends={{npcID=93822,x=0.282,y=0.116,zoneID=6719}},coords={x=0.584,y=0.602,source="quest_giver",zoneID=6723},questType="standard"},
[39423] = {id=39423,name="Shipyard Report",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=6723,description="Commander! We have received reports from the shipyard that things are getting serious. Can you head back to Frostwall and check in with Rolosh? Every ship we build gives us another advantage over Gul'dan's new Horde.",starts={{npcID=90481,x=0.408,y=0.732,zoneID=6720},{npcID=90481,x=0.614,y=0.458,zoneID=6723}},ends={{npcID=94789,x=0.42,y=0.71,zoneID=6720}},coords={x=0.408,y=0.732,source="quest_giver",zoneID=6720},questType="standard"},
[39425] = {id=39425,name="Stonedark Crystal",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Without my crystalline focus, my powers are weak. Those who captured me took it, and I know not where it is now. I'm sure one of the Feltotem has it. If you find it, please return it to me.",questType="standard"},
[39426] = {id=39426,name="Blood Debt",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="You have proven a much greater ally than the Bloodtotem ever were. With my focus crystal, my wounds are healed. I fear Frag was too far gone to revive. Torok and his Bloodtotem will suffer for what they have done to us. Let's pay them a visit before they can mount an attack against the cave of my people.",starts={{npcID=95421,x=0.452,y=0.324,zoneID=7503}},coords={x=0.452,y=0.324,source="quest_giver",zoneID=7503},questType="standard"},
[39427] = {id=39427,name="The Eagle Spirit's Blessing",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="The spear is linked to a spirit called Ohn'ahra. It has been tradition for us to speak with her and receive her blessing before going after the spear. She may also impart some knowledge. If you would accompany me to Spiritwatch Point, I will summon the Eagle Spirit and ask for its blessing in the coming fight.",ends={{npcID=110821,x=0.608,y=0.808,zoneID=7503}},questType="standard"},
[39428] = {id=39428,name="Satyr Line TRACKING",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[39429] = {id=39429,name="Assaulting the Haglands",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Proceed on foot into the Haglands and slay any harpies you find. Quell their numbers! We will provide air support and force your prey to the ground where you can deal with them. Show these witches the fury of your... well... your \"you.\"",starts={{npcID=95410,x=0.522,y=0.364,zoneID=7503}},ends={{npcID=95410,x=0.522,y=0.364,zoneID=7503}},coords={x=0.522,y=0.364,source="quest_giver",zoneID=7503},questType="standard"},
[39430] = {id=39430,name="Flasking for a Favor",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="You know, this mixing flask didn't suffer terrible damage. I'm positive it can just be repaired. I'm no expert in glass repair, but I've heard of someone who is--a tauren by the name of Barm Stonebreaker . He's a smith by trade, but those who know him say he was born to work glass. Those tauren don't work for free, so you may be in for some work yourself.",ends={{npcID=92242,x=0.552,y=0.842,zoneID=7503}},questType="standard"},
[39431] = {id=39431,name="Mending the Filter",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="Bringing back the cloth in such a manner would not be beneficial to Deucus. Perhaps there's a tailor here in Val'sharah who'd be willing to mend it for you. The priestess who helped you earlier may know of such a person.",starts={{npcID=249211,x=0.542,y=0.547,zoneID=7558}},ends={{npcID=93974,x=0.704,y=0.464,zoneID=7558}},coords={x=0.542,y=0.547,source="quest_giver",zoneID=7558},questType="standard"},
[39432] = {id=39432,name="Unknowable Power",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=6723,description="The one they call Gul'dan has ruined his own people, and now seeks to ruin what remains of mine as well. The fallen outcasts at Kra'nak have already pledged themselves to Gul'dan in a false promise of a return to the skies. He has given the most powerful of his minions the power of the Apexis, but twisted in a way that I cannot explain. Bring one of these fragments to me.",starts={{npcID=95424,x=0.604,y=0.466,zoneID=6723}},ends={{npcID=95424,x=0.604,y=0.466,zoneID=6723}},coords={x=0.604,y=0.466,source="quest_giver",zoneID=6723},questType="group"},
[39433] = {id=39433,name="Unseen Influence",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=6723,description="The corruption in the Apexis has begun to affect many of my people. We are so accustomed to the power it grants us that more succumb to the whispers every day. You must bring me more samples so I can free my people from yet another curse.",starts={{npcID=95424,x=0.604,y=0.466,zoneID=6723}},ends={{npcID=95424,x=0.604,y=0.466,zoneID=6723}},coords={x=0.604,y=0.466,source="quest_giver",zoneID=6723},questType="group"},
[39434] = {id=39434,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[39435] = {id=39435,name="Oubdob da Smasher",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39436] = {id=39436,name="Haglands Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39437] = {id=39437,name="Deep in the Cavern",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="We're getting tired of those murlocs. They skitter around the cavern like they own it. They stole some of our most precious relics and got their fishy fins all over them. Kill a few of them so they know they don't run things around here.",questType="standard"},
[39438] = {id=39438,name="Guhruhlruhlruh",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="The murlocs are usually pretty scared of us, but some bigger one led them into our cavern and they're getting too brave. Kill their leader. I think its name is something like \" Guhruhlruhlruh .\"",questType="standard"},
[39439] = {id=39439,name="Stonedark Relics",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="The murlocs managed to steal some of our sacred relics and carry them down into the lower cavern. While we warm up, do you think you could go find them?",questType="standard"},
[39440] = {id=39440,name="You Lift, Brul?",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Do you even lift? If you can carry these weights to the statue of Liftbrul and back, maybe we can talk.",questType="standard"},
[39455] = {id=39455,name="Cave of the Blood Trial",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="All Bloodtotem and distinguished guests must go through a trial of blood in the cavern beneath this outpost. I hope it's a good sign that they wish you to participate in this rite of passage. You will need to show proof of your deeds, defeat a Warmonger in single combat, then perform sacrifice at an altar deep in the cavern.",questType="standard"},
[39456] = {id=39456,name="Unexpected Allies",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="You have gained my trust. Not all drogbar are as violent as the savages led by Dargrul the Underking, nor are all tauren as bloodthirsty as the Bloodtotem. You may tell Mayla Highmountain that she has our support. The cavern we call home is yours to explore freely as well, .",starts={{npcID=99619,x=0.348,y=0.438,zoneID=7731}},ends={{npcID=93826,x=0.448,y=0.504,zoneID=7731},{npcID=108434,x=0.446,y=0.504,zoneID=7731}},coords={x=0.348,y=0.438,source="quest_giver",zoneID=7731},questType="standard"},
[39460] = {id=39460,name="Vale POI Event TRACKING",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[39461] = {id=39461,name="NOT USED",level=1,requiredLevel=1,faction="horde",expansion=6,zoneID=6723,mapID=534,questType="standard"},
[39463] = {id=39463,name="Tracking Quest: Treasure Map",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=6720,mapID=525,questType="standard"},
[39465] = {id=39465,name="Skywhisker Taskmaster",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39466] = {id=39466,name="7.0 Highmountain - Treasure 005 - Haglands",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39467] = {id=39467,name="Vignette: Sorcery and Suction",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[39468] = {id=39468,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
