[39471] = {id=39471,name="Phoenix Peak Treasure",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39472] = {id=39472,name="Cut Out the Heart",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=7541,description="This map points out the strategic locations of the Forsaken forces around Greywatch. A marker to the east indicates an apothecary camp where Dread-Riders are being supplied from. If you were to take out the apothecary in charge of creating this plague, it could stem the invasion and prevent the Dread-Riders from spreading the plague any further.",starts={{npcID=243700,x=0.724,y=0.611,zoneID=7541}},ends={{npcID=94318,x=0.716,y=0.598,zoneID=7541}},coords={x=0.724,y=0.611,source="quest_giver",zoneID=7541},questType="standard"},
[39473] = {id=39473,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[39474] = {id=39474,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[39475] = {id=39475,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
