[39478] = {id=39478,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[39479] = {id=39479,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
