[39485] = {id=39485,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[39487] = {id=39487,name="Crystal Fury",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="A drogbar stonecaster known as Gelmogg entered our sacred water caverns and aims to draw its power into himself. We must destroy him before he gets too powerful. He is in the upper caverns.",questType="standard"},
[39488] = {id=39488,name="Balance of Elements",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="The drogbar place their foul crystals in our cave to absorb the magic within, and then they collect them when they are saturated with power. We must recover the crystals so the magic might dissipate and be suffused back into the waters, or else the drogbar will find ways to corrupt the magic to their own purposes.",questType="standard"},
[39489] = {id=39489,name="Invading Spelunkers",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="The drogbar and their earthen furies have overrun the cavern. They're perverting the magic within and destroying the elementals that have forever dwelled in this place. Let's work together to remove them from this sacred cave.",starts={{npcID=96520,x=0.384,y=0.612,zoneID=7503}},coords={x=0.384,y=0.612,source="quest_giver",zoneID=7503},questType="standard"},
[39490] = {id=39490,name="Infestation",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,mapID=650,description="Those bugs are destroying our crops and attack any of us who get near them. Would you exterminate some of those vile creatures?",starts={{npcID=95191,x=0.436,y=0.598,mapID=650}},ends={{npcID=95191,x=0.436,y=0.598,mapID=650}},coords={x=0.436,y=0.598,source="quest_giver",mapID=650},questType="standard"},
[39491] = {id=39491,name="Ormgul the Pestilent",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="We've lived at peace with the drogbar for years--our tribe even more than the others. But we were betrayed in our last trade with them at Riverbend. They usually supply us with potent alchemy to prevent insects from infesting our fields. This time, led by Ormgul, they have attacked the crops that sustain us all. Ormgul the Pestilent is the one who brought the infection to our farmland. Destroy him, and bring me whatever he uses to attract the bugs to our land.",starts={{npcID=93833,x=0.436,y=0.598,zoneID=7503}},ends={{npcID=93833,x=0.436,y=0.598,zoneID=7503}},coords={x=0.436,y=0.598,source="quest_giver",zoneID=7503},questType="standard"},
[39493] = {id=39493,name="Pinerock Basin Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39494] = {id=39494,name="7.0 Highmountain - Treasure 008 - Pinerock Basin",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39495] = {id=39495,name="Hidden No More",level=8,requiredLevel=8,faction="both",expansion=6,zoneID=7705,description="Now that you've uncovered the demons, I can sense them, too. Specifically, I sense a very powerful fel lord deeper in the cave. You need to grab his power while you still can. If you can deal with their leader, we will take care of the rest of his forces in that cave.",starts={{npcID=96436,x=0.64,y=0.524,zoneID=7705}},ends={{npcID=93127,x=0.604,y=0.448,zoneID=7705}},coords={x=0.64,y=0.524,source="quest_giver",zoneID=7705},questType="standard"},
[39496] = {id=39496,name="The Flow of the River",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="We can leave Farmer Maya in charge of the farmland now that the greatest threat has been reduced. But we aren't out of hot water just yet, . The fisheries are just as important as our fields, and they are in even greater danger than the farm if what Angler Creel says is true.",starts={{npcID=93833,x=0.436,y=0.598,zoneID=7503}},ends={{npcID=95186,x=0.412,y=0.616,zoneID=7503}},coords={x=0.436,y=0.598,source="quest_giver",zoneID=7503},questType="standard"},
[39498] = {id=39498,name="High Water",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Riverbend! Is that what the Underking said? That is my home and the place where we store our winter supplies. We must make it there at all speed and warn them. Meet me there.",ends={{npcID=97662,x=0.404,y=0.716,zoneID=7503}},questType="standard"},
[39499] = {id=39499,name="Well of Souls",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=7545,description="As you defeat Gul'dan's minions, his hold over this fel citadel weakens, allowing me to teleport you and your allies deeper into the dark halls. If I only I had some Soul Remnants - four of them, let's say - none of this would be necessary, and I could harness that power to send you directly into the upper reaches of the Citadel.",questType="raid"},
[39500] = {id=39500,name="Well of Souls",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=7545,description="As you defeat Gul'dan's minions, his hold over this fel citadel weakens, allowing me to teleport you and your allies deeper into the dark halls. If I only I had some Soul Remnants - four of them, let's say - none of this would be necessary, and I could harness that power to send you directly into the upper reaches of the Citadel.",questType="raid"},
[39501] = {id=39501,name="Well of Souls",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=7545,description="As you defeat Gul'dan's minions, his hold over this fel citadel weakens, allowing me to teleport you and your allies deeper into the dark halls. If I only I had some Soul Remnants - four of them, let's say - none of this would be necessary, and I could harness that power to send you directly into the upper reaches of the Citadel.",questType="raid"},
[39502] = {id=39502,name="The Fel Spire",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=7545,description="This would all be so much simpler if we could just teleport directly to the top of the Citadel, where Gul'dan works his dark magic, wouldn't it? But while demonic power fills the halls, my magic cannot penetrate to such heights. If only I had powerful Fel Essences to work with, I could attune my magic to their defenses and bypass them. But the only place you might find such concentrated fel energy would be atop the Citadel itself. What a conundrum....",questType="raid"},
[39503] = {id=39503,name="7.0 Highmountain - Treasure 011 - Pinerock Basin",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39504] = {id=39504,name="The Fel Spire",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=7545,description="This would all be so much simpler if we could just teleport directly to the top of the Citadel, where Gul'dan works his dark magic, wouldn't it? But while demonic power fills the halls, my magic cannot penetrate to such heights. If only I had powerful Fel Essences to work with, I could attune my magic to their defenses and bypass them. But the only place you might find such concentrated fel energy would be atop the Citadel itself. What a conundrum....",questType="raid"},
[39505] = {id=39505,name="The Fel Spire",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=7545,description="This would all be so much simpler if we could just teleport directly to the top of the Citadel, where Gul'dan works his dark magic, wouldn't it? But while demonic power fills the halls, my magic cannot penetrate to such heights. If only I had powerful Fel Essences to work with, I could attune my magic to their defenses and bypass them. But the only place you might find such concentrated fel energy would be atop the Citadel itself. What a conundrum....",questType="raid"},
[39506] = {id=39506,name="Pinerock Basin Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39507] = {id=39507,name="7.0 Highmountain - Treasure 062 - Pinerock Basin",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39508] = {id=39508,name="Pinerock Basin Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39509] = {id=39509,name="Bloodied Blades of Zeth'Gol",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=6723,description="Them Bleeding Hollow orcs do blood magic - like voodoo but it hurt more. They cut their own flesh. Most of 'em carry curved ritual blades for carvin' themselves up. Bring me them blades, commander. We can turn their power against 'em.",starts={{npcID=96014,x=0.616,y=0.456,zoneID=6723}},ends={{npcID=96014,x=0.616,y=0.456,zoneID=6723}},coords={x=0.616,y=0.456,source="quest_giver",zoneID=6723},questType="standard"},
[39510] = {id=39510,name="A Little Wetwork",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=6723,description="What be left of the Iron Horde is comin' to Tanaan through Ironhold Harbor. If we knew who was comin' and when, we could use our shipyard to cause some chaos. Go to Ironhold Harbor and fish up some intelligence!",starts={{npcID=96014,x=0.616,y=0.456,zoneID=6723}},ends={{npcID=96014,x=0.616,y=0.456,zoneID=6723}},coords={x=0.616,y=0.456,source="quest_giver",zoneID=6723},questType="standard"},
[39511] = {id=39511,name="Blood of Fallen Brothers",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=6723,description="Orcs that drink Gul'dan's poison turn into fel beasts. Soulless savages. Lady Liadrin an' the Blood Knights think maybe there be a way back. They be wantin' samples of blood from freshly turned orcs. Get their blood, ! You be findin' fel orcs all over Tanaan, but the Iron Front, the Fel Forge, and the Throne of Kil'jaeden is where you find the most.",starts={{npcID=96014,x=0.616,y=0.456,zoneID=6723}},ends={{npcID=96014,x=0.616,y=0.456,zoneID=6723}},coords={x=0.616,y=0.456,source="quest_giver",zoneID=6723},questType="standard"},
[39512] = {id=39512,name="Secrets of the Shadow Council",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=6723,description="Gul'dan be growin' his Shadow Council like a spider spin a web. But some of this new blood, they not so smart. They write down the secrets but don't burn 'em. Catch his minions out in the open and bring their secrets back to me! You find them workin' with the arakkoa in da Ruins of Kra'nak or atop the Throne of Kil'jaeden.",starts={{npcID=96014,x=0.616,y=0.456,zoneID=6723}},ends={{npcID=96014,x=0.616,y=0.456,zoneID=6723}},coords={x=0.616,y=0.456,source="quest_giver",zoneID=6723},questType="standard"},
[39513] = {id=39513,name="Disarming Sha'naar",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=6723,description="Draenei at the Temple of Sha'naar would mine these mountains for perfect crystals used to channel their magics. Now demons be lootin' the place. We gotta keep those crystals out of demonic hands, commander! Attack the mines behind the temple and grab them crystals.",starts={{npcID=96014,x=0.616,y=0.456,zoneID=6723}},ends={{npcID=96014,x=0.616,y=0.456,zoneID=6723}},coords={x=0.616,y=0.456,source="quest_giver",zoneID=6723},questType="standard"},
[39514] = {id=39514,name="Harnessing Their Power",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=6723,description="Ol' Grommash Hellscream found a way to weaponize the gronn. Vol'jin wants to know how. Travel to the Iron Front and kill one of them big beasties, then bring back its war harness. You might be needin' help.",starts={{npcID=96014,x=0.616,y=0.456,zoneID=6723}},ends={{npcID=96014,x=0.616,y=0.456,zoneID=6723}},coords={x=0.616,y=0.456,source="quest_giver",zoneID=6723},questType="standard"},
[39515] = {id=39515,name="Vengeance Will Be Mine!",level=8,requiredLevel=8,faction="both",expansion=6,zoneID=7705,description="This is why the Legion fears us. We have the ability to turn their secrets against them and in so doing become stronger than they ever can be. Quickly, , teach us what you have learned.",starts={{npcID=93127,x=0.604,y=0.448,zoneID=7705}},ends={{npcID=93127,x=0.604,y=0.448,zoneID=7705}},coords={x=0.604,y=0.448,source="quest_giver",zoneID=7705},questType="standard"},
[39516] = {id=39516,name="Cry Havoc and Let Slip the Illidari!",level=8,requiredLevel=8,faction="both",expansion=6,zoneID=7705,description="This is why the Legion fears us. We have the ability to turn their secrets against them and in so doing become stronger than they ever can be.",starts={{npcID=93127,x=0.604,y=0.448,zoneID=7705}},ends={{npcID=93127,x=0.604,y=0.448,zoneID=7705}},coords={x=0.604,y=0.448,source="quest_giver",zoneID=7705},questType="standard"},
[39519] = {id=39519,name="Demonslayer of Tanaan",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=9526,description="Look to the north, . The sky is turning a sickly green. Gul'dan's summoning portals are not yet at full strength, but already the stench of demon is on the wind. Slay them, . Destroy as many beasts as you can before they find a way to Azeroth. The Temple of Sha'naar is infested, as is the Throne of Kil'jaeden, although you may find others wandering about the jungle.",starts={{npcID=93396,x=0.596,y=0.458,zoneID=6723}},ends={{npcID=93396,x=0.596,y=0.458,zoneID=6723}},coords={x=0.596,y=0.458,source="quest_giver",zoneID=6723},questType="standard"},
[39526] = {id=39526,name="Pressing the Attack",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=6723,description="We got Gul'dan's minions on the run, commander! If you be feelin' it, we should put some pressure on some of his other strongholds as well.",starts={{npcID=96014,x=0.616,y=0.456,zoneID=6723}},ends={{npcID=96014,x=0.616,y=0.456,zoneID=6723}},coords={x=0.616,y=0.456,source="quest_giver",zoneID=6723},questType="standard"},
[39529] = {id=39529,name="Tooth and Claw",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=6723,description="Beyond the meager shelter of these fortress walls, the jungle closes in. Can you feel it? That is the untamed wilderness, , calling forth our primal instincts. There is no better way to feel alive than to court death. Join me in the hunt, ! Collect teeth from the wild beasts. The ravagers in Thornmire, the raptors in Zorammarsh - even the sea creatures along the strand and the little podling plants themselves all have teeth. Bring them to me!",starts={{npcID=93396,x=0.596,y=0.458,zoneID=6723}},ends={{npcID=93396,x=0.596,y=0.458,zoneID=6723}},coords={x=0.596,y=0.458,source="quest_giver",zoneID=6723},questType="standard"},
[39531] = {id=39531,name="7.0 Highmountain - Treasure 00x - Steamy Romance Novel",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39532] = {id=39532,name="Bringing Down the Iron Horde",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=6723,description="Ever since the fall of Blackrock Foundry, Gul'dan has been turning the Iron Horde into... something worse. The orcs who once flocked to Grommash's banner, through either fear or thirst for revenge, are now embracing the fel. Wade into the battlefields of Tanaan and lay waste to Gul'dan's forces. Orc or fel orc makes no difference. Gut what remains of the Iron Horde!",starts={{npcID=93396,x=0.596,y=0.458,zoneID=6723}},ends={{npcID=93396,x=0.596,y=0.458,zoneID=6723}},coords={x=0.596,y=0.458,source="quest_giver",zoneID=6723},questType="standard"},
[39533] = {id=39533,name="Nogginclobber Arena",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39565] = {id=39565,name="Rumble in the Jungle",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=6723,description="Dem fancy cat-men gotta be shown who is da boss 'round dese parts. Kill all their champions, and ya will earn da respect of all creatures in da jungle. Y'gonna need dese totems to draw dem out.",starts={{npcID=92805,x=0.552,y=0.748,zoneID=6723}},ends={{npcID=92805,x=0.552,y=0.748,zoneID=6723}},coords={x=0.552,y=0.748,source="quest_giver",zoneID=6723},questType="standard"},
[39566] = {id=39566,name="The Search for Knowledge",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="While you were out gallivanting, did you notice any lost relics around Azsuna? My sources tell me there are treasures to be found. These rumors merit investigation!",ends={{npcID=243392,x=0.449,y=0.521,zoneID=7334}},questType="standard"},
[39567] = {id=39567,name="Bloodied Blades of Zeth'Gol",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6723,description="The Bleeding Hollow clan is infamous for their blood rituals. The brutes carve sigils into their flesh and create potions from the blood of their strongest warriors. The curved ceremonial blades they use have a power all their own. Gather some of these for me. We will deprive them of these weapons and learn something about our enemy at the same time.",starts={{npcID=90974,x=0.584,y=0.604,zoneID=6723}},ends={{npcID=90974,x=0.584,y=0.604,zoneID=6723}},coords={x=0.584,y=0.604,source="quest_giver",zoneID=6723},questType="standard"},
[39568] = {id=39568,name="A Little Wetwork",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6723,description="The shattered remnants of the Iron Horde pour into Tanaan through Ironhold Harbor. If we knew more about their fleet we could dispatch countermeasures from your shipyard in Shadowmoon. Perhaps you could gather some naval intelligence for our cause?",starts={{npcID=90974,x=0.584,y=0.604,zoneID=6723}},ends={{npcID=90974,x=0.584,y=0.604,zoneID=6723}},coords={x=0.584,y=0.604,source="quest_giver",zoneID=6723},questType="standard"},
[39569] = {id=39569,name="Breaking Their Fel Bonds",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6723,description="Gul'dan's fel poison turns already ferocious orcs into hateful, vicious creatures with no soul. But were he here to guide us, Prophet Velen wouldn't give up on the whole race. If you could find samples of their blood, maybe we can reverse the process? You'll find fel orcs all over Tanaan, but the Iron Front, the Fel Forge, and the Throne of Kil'jaeden are the most densely populated.",starts={{npcID=90974,x=0.584,y=0.604,zoneID=6723}},ends={{npcID=90974,x=0.584,y=0.604,zoneID=6723}},coords={x=0.584,y=0.604,source="quest_giver",zoneID=6723},questType="standard"},
[39570] = {id=39570,name="Secrets of the Shadow Council",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6723,description="Gul'dan has been building a spy network for himself - the so-called \"Shadow Council\". As they struggle to control Tanaan, the Shadow Council has grown careless. Their members are out in the open, recruiting arakkoa at the Ruins of Kra'nak or summoning demons at the Throne of Kil'jaeden. Find members of the Shadow Council and acquire any intelligence they were foolish enough not to destroy!",starts={{npcID=90974,x=0.584,y=0.604,zoneID=6723}},ends={{npcID=90974,x=0.584,y=0.604,zoneID=6723}},coords={x=0.584,y=0.604,source="quest_giver",zoneID=6723},questType="standard"},
[39571] = {id=39571,name="Disarming Sha'naar",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6723,description="Draenei at the Temple of Sha'naar would mine these mountains for perfect crystals to power our arcane devices. Sadly, the temple is lost to us - we have been betrayed by the Sargerei. , it is imperative that you venture into those mines and secure those crystals before the Sargerei use them in their demonic rituals. If you must kill our former brothers and sisters, so be it.",starts={{npcID=90974,x=0.584,y=0.604,zoneID=6723}},ends={{npcID=90974,x=0.584,y=0.604,zoneID=6723}},coords={x=0.584,y=0.604,source="quest_giver",zoneID=6723},questType="standard"},
[39572] = {id=39572,name="Moozy's Adventure",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,ends={{npcID=96084,x=0.4,y=0.58,zoneID=7503},{npcID=96084,x=0.46,y=0.546,zoneID=7731}},questType="standard"},
[39573] = {id=39573,name="Harnessing Their Power",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6723,description="We have always believed that the primal creatures of Draenor could not be tamed. And yet, the Iron Horde found a way to weaponize the gronn. It would be to our advantage to learn how. Venture to the Iron Front, slay a Wargronn, and retrieve its harness. You may want to find help.",starts={{npcID=90974,x=0.584,y=0.604,zoneID=6723}},ends={{npcID=90974,x=0.584,y=0.604,zoneID=6723}},coords={x=0.584,y=0.604,source="quest_giver",zoneID=6723},questType="standard"},
[39574] = {id=39574,name="Pressing the Attack",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6723,description="Gul'dan's minions are on the run, commander! If you have the strength, now would be an opportune time to press forward and assault some of his other strongholds.",starts={{npcID=90974,x=0.584,y=0.604,zoneID=6723}},ends={{npcID=90974,x=0.584,y=0.604,zoneID=6723}},coords={x=0.584,y=0.604,source="quest_giver",zoneID=6723},questType="standard"},
[39575] = {id=39575,name="The Path of Huln",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Armies are vital to the success of a war. But so are symbols. For our people, few things make for a better symbol than the blessings of our most eldest ancestors. Mayla must walk the Path of Huln. The path is dangerous, and she may only bring two people with her: a spiritwalker to guide her and a champion to protect her. Will you be the champion?",questType="standard"},
[39577] = {id=39577,name="An Ancient Secret",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Before Mayla may be pronounced High Chieftain, there is one more vision she must see. I wish to show you as well. It is an ancient secret, handed down along the Highmountain bloodline. I ask for your discretion in keeping it that way.",questType="standard"},
[39578] = {id=39578,name="Titanic Showdown",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="The tale of Huln did not end with him acquiring the Hammer of Khaz'goroth. No. For that part, we must venture deeper into this cavern. A final brazier awaits us ahead. Come, let us see what happened next.",questType="standard"},
[39579] = {id=39579,name="The Backdoor",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="This will take Mayla some time to adjust to. That being said, we should return to Thunder Totem. Just south of here is a tunnel that should take us through the old drogbar slave enclave and then to an opening beyond. We keep a small Skyhorn outpost there to watch and ensure nothing enters or leaves this vault without us knowing about it. They should be able to fly us back.",questType="standard"},
[39580] = {id=39580,name="The High Chieftain",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="I understand what Ebonhorn has been trying to tell me for a while now. Our people do not need a hammer, we need a leader. One willing to stand against any threat, even if they are terrified to do so. And between you and me, I am definitely terrified, but resolved. Let us return to Thunder Totem and prepare ourselves for war.",ends={{npcID=108434,x=0.446,y=0.504,zoneID=7731}},questType="standard"},
[39581] = {id=39581,name="Demonslayer of Tanaan",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=9526,description="Demons! Hate 'em! Gul'dan is spinning up more summoning portals with each passing hour. There's only one way to stem the tide, . Parvink smashes her gauntleted fist against her open palm.> Smash 'em! The Temple of Sha'naar is a good place to start, or head up to the Throne of Kil'jaeden if you're looking for a real challenge.",starts={{npcID=96147,x=0.578,y=0.598,zoneID=6723}},ends={{npcID=96147,x=0.578,y=0.598,zoneID=6723}},coords={x=0.578,y=0.598,source="quest_giver",zoneID=6723},questType="standard"},
[39582] = {id=39582,name="Tooth and Claw",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6723,description="These wimps lugging wood around the jungle keep talking about how dangerous it is. You know, between the ravager den to the south or the raptors that stalk Zorammarsh - hey, even the beach creatures or podlings have teeth! What do you say you and I do a little hunting? Collect teeth from wild beasts. The bigger the beast, the more teeth. Meet me back here and we'll compare our haul!",starts={{npcID=96147,x=0.578,y=0.598,zoneID=6723}},ends={{npcID=96147,x=0.578,y=0.598,zoneID=6723}},coords={x=0.578,y=0.598,source="quest_giver",zoneID=6723},questType="standard"},
[39586] = {id=39586,name="Bringing Down the Iron Horde",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6723,description="Ever since we humiliated 'em at Blackrock Foundry, the Iron Horde has been on the run. Gul'dan is converting them all into fel orcs, but I ain't scared. A bloodlusting orc is twice as strong but twice as stupid. Hey! Let's wade into the battlefields of Tanaan and lay waste to as many orcs as we can. Orc or fel orc - doesn't matter to me.",starts={{npcID=96147,x=0.578,y=0.598,zoneID=6723}},ends={{npcID=96147,x=0.578,y=0.598,zoneID=6723}},coords={x=0.578,y=0.598,source="quest_giver",zoneID=6723},questType="standard"},
[39588] = {id=39588,name="They Will Pay With Blood",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="The tauren go too far. I did not escape their outpost for fear that they would attack the cave and slaughter my people. It looks like they planned to do it all along. Slay some of the Feltotem. Thin the herd.",questType="standard"},
[39590] = {id=39590,name="Ahead of the Game",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="The watcher Yotnar keeps the vault, and he is a fickle one. Challengers come from far and wide seeking the trials, but the watcher chooses not to see. If you wish to catch his eye, show him you are worth being seen. Some of these challengers await in camps throughout the Valley of the Sword. Bring their heads to Yotnar, so that he may see them, and you.",starts={{npcID=96254,x=0.418,y=0.43,zoneID=7541}},ends={{npcID=243836,x=0.467,y=0.445,zoneID=7541}},coords={x=0.418,y=0.43,source="quest_giver",zoneID=7541},questType="standard"},
[39591] = {id=39591,name="A Trial of Valor",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="To seek the Aegis of Aggramar, a champion must complete three great trials before riding into glorious battle through the Gates of Valor. Here you will find the knowledge of the trials you must seek out, as well as the first challenge you must face. Above us, adorning the central plateau, you will find the archive for the Trial of Valor. Seek it out, and learn where your path leads.",starts={{npcID=243836,x=0.467,y=0.445,zoneID=7541}},ends={{npcID=96257,x=0.466,y=0.444,zoneID=7541},{npcID=243836,x=0.467,y=0.445,zoneID=7541}},coords={x=0.467,y=0.445,source="quest_giver",zoneID=7541},questType="standard"},
[39592] = {id=39592,name="A Trial of Will",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="Upon the highest point of the plateau above, you will find the archive device for the Trial of Will. Seek it out to learn what awaits you in Thorim's Peak. Be on your guard, outsider. The one called Skovald has left behind many of his army, and they will no doubt be unfriendly.",starts={{npcID=243836,x=0.467,y=0.445,zoneID=7541}},ends={{npcID=96257,x=0.466,y=0.444,zoneID=7541},{npcID=243836,x=0.467,y=0.445,zoneID=7541}},coords={x=0.467,y=0.445,source="quest_giver",zoneID=7541},questType="standard"},
[39593] = {id=39593,name="The Shattered Watcher",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="When your adversary - the one called Skovald- completed his first trial, he used his ill-begotten powers to sunder my physical body. I cannot allow a contender to pass through the vault while I remain unwhole. His forces have no doubt scattered my pieces through the plateau which they currently desecrate. Bring them back to me, so that I may properly guide your trial.",starts={{npcID=243836,x=0.467,y=0.445,zoneID=7541}},ends={{npcID=243836,x=0.467,y=0.445,zoneID=7541}},coords={x=0.467,y=0.445,source="quest_giver",zoneID=7541},questType="standard"},
[39594] = {id=39594,name="A Trial of Might",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="I owe you my gratitude for helping make me whole again, outsider. It is clear that you are worthy to take on the trials. Go now into the vault. There you will find the archive for the first trial you must undertake. I will meet you inside.",questType="standard"},
[39595] = {id=39595,name="Blood and Gold",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="The challengers gathered in the Valley of the Sword have brought with them offerings to the watchers of the vault. It might be a good idea to take some of these offerings with you to help in appeasing Yotnar .",ends={{npcID=96257,x=0.466,y=0.444,zoneID=7541},{npcID=96258,x=0.464,y=0.448,zoneID=7541},{npcID=243836,x=0.467,y=0.445,zoneID=7541}},questType="standard"},
[39597] = {id=39597,name="The Blessing of the Watchers",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="As is your due for passing the Trial of Might, I will grant you the blessing of the watchers . Furthermore, to aid you in your trials to come, I will bestow upon your artifact the power of the vault's keeper. May it serve you well in your time of need. Speak to me when you are ready to receive this gift.",starts={{npcID=96258,x=0.464,y=0.448,zoneID=7541}},ends={{npcID=96254,x=0.418,y=0.43,zoneID=7541}},coords={x=0.464,y=0.448,source="quest_giver",zoneID=7541},questType="standard"},
[39601] = {id=39601,name="I Sunk Your Battleship",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6723,description="Commander, we must expand our fleet if we hope to stand a chance against the Iron Horde. We have heard reports from Tanaan that a new Alliance faction can supply us with the plans to build battleships. Head out there as soon as you can and investigate!",starts={{npcID=93822,x=0.282,y=0.116,zoneID=6719}},ends={{npcID=90974,x=0.584,y=0.604,zoneID=6723}},coords={x=0.282,y=0.116,source="quest_giver",zoneID=6719},questType="standard"},
[39602] = {id=39602,name="Where's Lyndras: Sewer Sleuthing",level=45,requiredLevel=45,faction="horde",expansion=6,zoneID=7502,description="Linzy said that Lyndras escaped down into the sewers of Dalaran. Surely there must be a clue down there as to his whereabouts. Hopefully he hasn't caused any more commotion amongst the citizens of Dalaran.",questType="standard"},
[39604] = {id=39604,name="I Sunk Your Battleship",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=6723,description="Commander, we must expand our fleet if we hope to stand a chance against the Iron Horde. We have heard reports from Tanaan that a new Horde faction can supply us with the plans to build battleships. Head out there as soon as you can and investigate!",starts={{npcID=94789,x=0.42,y=0.71,zoneID=6720}},ends={{npcID=96014,x=0.616,y=0.456,zoneID=6723}},coords={x=0.42,y=0.71,source="quest_giver",zoneID=6720},questType="standard"},
[39605] = {id=39605,name="Where's Lyndras: Downward Spiral",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,description="Flitz mentioned a manhole near Violet Hold, perhaps that would be the best place to pick up Lyndras' trail.",questType="standard"},
[39606] = {id=39606,name="Treasures of Deathwing",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,description="Neltharion's Vault? Well why didn't that spiritwalker just say so? When we were jumpin' into the cavern I thought I saw a chamber up high that might have what we are after. Have a look around this place while I see if I can't find a way up.",questType="standard"},
[39614] = {id=39614,name="Fish Out of Water",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="The drogbar are on a rampage! They're smashing everything they can find and are throwing fish to the shore. Worst of all, it is the wrong time to harvest fish. They must be returned to the waters so they can breed.",starts={{npcID=95186,x=0.412,y=0.616,zoneID=7503}},ends={{npcID=95186,x=0.412,y=0.616,zoneID=7503}},coords={x=0.412,y=0.616,source="quest_giver",zoneID=7503},questType="standard"},
[39645] = {id=39645,name="Calibration Experts",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=1537,description="It will take the cooperation of several highly skilled sorts to calibrate these burettes. Myshalla Streambreeze in Feralas has demonstrated admirable attention to detail. I loathe Ironforge, but a resident named Krimple Proxmeasure is known for his precision. And while I'd never travel to Booty Bay without a lock on my wallet, Tryks Pourtrue has proven reliable and fair... mostly.",questType="standard"},
[39646] = {id=39646,name="Albino Elderhorn",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39648] = {id=39648,name="Where Are the Children?",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=6720,description="The children have gone missing! That horrible Grumpus has been making his way throughout Draenor, snatching up children. Please save them! Our scouts have spotted him over in Frostfire Ridge .",starts={{npcID=96451,x=0.44,y=0.516,zoneID=7078},{npcID=96735,x=0.474,y=0.376,zoneID=7004}},ends={{npcID=96362,x=0.444,y=0.514,zoneID=7078},{npcID=96362,x=0.476,y=0.38,zoneID=7004}},coords={x=0.44,y=0.516,source="quest_giver",zoneID=7078},questType="standard"},
[39649] = {id=39649,name="Menacing Grumplings",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=6720,description="The grumplings are horrid creatures. They're the ones doin' the dirty work for Grumpus. If you're able to remove the threat I'm sure rescuing the children won't be much of a problem.",starts={{npcID=96451,x=0.44,y=0.516,zoneID=7078},{npcID=96735,x=0.474,y=0.376,zoneID=7004}},ends={{npcID=96362,x=0.444,y=0.514,zoneID=7078},{npcID=96362,x=0.476,y=0.38,zoneID=7004}},coords={x=0.44,y=0.516,source="quest_giver",zoneID=7078},questType="standard"},
[39651] = {id=39651,name="Grumpus",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=6720,description="One of Draenor's oldest stories is the legend of Grumpus . The story tells of a mean-spirited brute that would come in the night, in the dead of winter, and kidnap children that misbehaved. Back at his lair, he would present them with awful toys, and use their tears to spawn his minions. But Grumpus is no legend, he's real and he's taken our children! Please, you have to slay him!",starts={{npcID=96451,x=0.44,y=0.516,zoneID=7078},{npcID=96735,x=0.474,y=0.376,zoneID=7004}},ends={{npcID=96362,x=0.444,y=0.514,zoneID=7078},{npcID=96362,x=0.476,y=0.38,zoneID=7004}},coords={x=0.44,y=0.516,source="quest_giver",zoneID=7078},questType="group"},
[39652] = {id=39652,name="Where Dragons Rule",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="Thanks to your help, Thrymjaris was able to escape the clutches of that vile demon. She bid me wait for you, so that I could take you to her once you had finished dispatching your foes. She has gathered our brood at the top of Thorim's Peak to prepare for a counterattack. Would you join us?",starts={{npcID=96465,x=0.428,y=0.826,zoneID=7541}},ends={{npcID=92218,x=0.408,y=0.808,zoneID=7541}},coords={x=0.428,y=0.826,source="quest_giver",zoneID=7541},questType="standard"},
[39654] = {id=39654,name="Odyn and the Valarjar",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7813,description="Fear not, mortal, you are not dead. I was directed to collect you before your demise by Odyn himself. I will take you to Odyn now, follow me.",questType="standard"},
[39655] = {id=39655,name="If At First You Fail, Try Again!",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6719,description="Looks like that Submarine had a bit more firepower than we thought! They used First Strike to hit us before we even saw it coming. Losing ships is a part of naval battles, Commander. Luckily, we were prepared for this exact sort of situation. Speak with Yanas down at the dry docks, he should be able to help us quickly produce another Destroyer. Head back here when the ship is complete, we will have a new mission ready for you.",starts={{npcID=93822,x=0.282,y=0.116,zoneID=6719}},ends={{npcID=93822,x=0.282,y=0.116,zoneID=6719}},coords={x=0.282,y=0.116,source="quest_giver",zoneID=6719},questType="standard"},
[39656] = {id=39656,name="Wolf Pack Attack",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="It's time to attack the pack! I've preloaded the hand cannon. All you have to do is point and shoot. The critters should survive the blast and hit the ground running. The howlers will be distracted by the critters, allowing you to focus on killing the packleaders. Happy hunting!",starts={{npcID=96513,x=0.576,y=0.566,zoneID=7503}},ends={{npcID=96513,x=0.576,y=0.566,zoneID=7503}},coords={x=0.576,y=0.566,source="quest_giver",zoneID=7503},questType="standard"},
[39657] = {id=39657,name="Candy Bucket",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7078,mapID=539,starts={{npcID=243912,x=0.475,y=0.378,mapID=525},{npcID=243912,x=0.44,y=0.52,mapID=539}},ends={{npcID=243912,x=0.475,y=0.378,mapID=525},{npcID=243912,x=0.44,y=0.52,mapID=539}},coords={x=0.475,y=0.378,source="quest_giver",mapID=539},questType="standard"},
[39658] = {id=39658,name="A Gently Shaken Gift",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=1637,mapID=85,starts={{npcID=180746,x=0.334,y=0.659,mapID=87},{npcID=180746,x=0.491,y=0.782,mapID=85}},ends={{npcID=180746,x=0.334,y=0.659,mapID=87},{npcID=180746,x=0.491,y=0.782,mapID=85}},coords={x=0.334,y=0.659,source="quest_giver",mapID=85},questType="standard"},
[39659] = {id=39659,name="A Winter Veil Gift",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=1637,mapID=85,starts={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},ends={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},coords={x=0.335,y=0.66,source="quest_giver",mapID=85},questType="standard"},
[39661] = {id=39661,name="Lifespring Cavern",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="The drogbar have taken over my cavern. It is where we Rivermane practice our water magic and get much of the purest healing water in Highmountain . Meet me there and we will cleanse that sacred place of these dark-dwellers.",starts={{npcID=95956,x=0.412,y=0.616,zoneID=7503}},ends={{npcID=96520,x=0.384,y=0.612,zoneID=7503}},coords={x=0.412,y=0.616,source="quest_giver",zoneID=7503},questType="standard"},
[39663] = {id=39663,name="On Felbat Wings",level=8,requiredLevel=8,faction="both",expansion=6,zoneID=7705,description="It is time. We have dealt the Legion's forces a crippling blow from which they will never recover. Quickly, let us mount up and take the fight to Tyranna's command center.",starts={{npcID=93127,x=0.604,y=0.448,zoneID=7705}},ends={{npcID=97297,x=0.698,y=0.442,zoneID=7705}},coords={x=0.604,y=0.448,source="quest_giver",zoneID=7705},questType="standard"},
[39665] = {id=39665,name="A True Naval Commander",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6719,description="Yes! Those are the blueprints I misplaced when I was fishing last week. These instructions match my prototype equipment one for one. Take this Blast Furnace and install it on one of our ships. This should let us break the naval blocade and expand our control of the Draenor seas.",starts={{npcID=93812,x=0.286,y=0.108,zoneID=6719}},ends={{npcID=93822,x=0.282,y=0.116,zoneID=6719}},coords={x=0.286,y=0.108,source="quest_giver",zoneID=6719},questType="standard"},
[39666] = {id=39666,name="Equipping Our Fleet",level=40,requiredLevel=40,faction="alliance",expansion=6,zoneID=6719,description="Commander, our fleet is going to require some custom naval equipment if we hope to stand a chance in this war. Find Salty Jorren down at the docks, he should be able to help us out.",starts={{npcID=93822,x=0.282,y=0.116,zoneID=6719}},ends={{npcID=93812,x=0.286,y=0.108,zoneID=6719}},coords={x=0.282,y=0.116,source="quest_giver",zoneID=6719},questType="standard"},
[39667] = {id=39667,name="Where's Lyndras: Leyflame Larceny",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,description="The guards here must have seen Lyndras come through. The trail of ley dust isn't exactly hard to miss either. Perhaps one of the guards knows what became of Lyndras.",questType="standard"},
[39668] = {id=39668,name="What Horrible Presents!",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=7004,description="That mean old Grumpus has amassed a collection of odd gifts. He's deliberately trying to crush the spirit of children everywhere by giving out the worst presents imaginable. Take this spirit bomb . Toss it on some of Grumpus's unusual gifts and take them out for good! We're in this together, . Now go and save the spirit of the holiday!",starts={{npcID=96451,x=0.44,y=0.516,zoneID=7078},{npcID=96735,x=0.474,y=0.376,zoneID=7004}},ends={{npcID=96362,x=0.444,y=0.514,zoneID=7078},{npcID=96362,x=0.476,y=0.38,zoneID=7004}},coords={x=0.44,y=0.516,source="quest_giver",zoneID=7078},questType="standard"},
[39670] = {id=39670,name="Critter Scatter Shot",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="The howlers in these hills travel in packs. Three against one isn't a fight I want to pick. Luckily those wolves are no match for my engineering skills! I just put the finishing touches on the prototype of a device that will help scatter the pack. All I need now is some ammo... Snatch me some rabbits from the meadow south of here, and I'll let you be the first to try out the hand cannon.",starts={{npcID=96513,x=0.576,y=0.566,zoneID=7503}},ends={{npcID=96513,x=0.576,y=0.566,zoneID=7503}},coords={x=0.576,y=0.566,source="quest_giver",zoneID=7503},questType="standard"},
[39674] = {id=39674,name="If At First You Fail, Try Again!",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=6720,description="Looks like that Submarine had a bit more firepower than we thought! They used First Strike to hit us before we even saw it coming. Losing ships is a part of naval battles, Commander. Luckily, we were prepared for this exact sort of situation. Speak with Solog down at the dry docks, he should be able to help us quickly produce another Destroyer. Head back here when the ship is complete, we will have a new mission ready for you.",starts={{npcID=94789,x=0.42,y=0.71,zoneID=6720}},ends={{npcID=94789,x=0.42,y=0.71,zoneID=6720}},coords={x=0.42,y=0.71,source="quest_giver",zoneID=6720},questType="standard"},
[39675] = {id=39675,name="Equipping Our Fleet",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=6720,description="Commander, our fleet is going to require some custom naval equipment if we hope to stand a chance in this war. Find Kronk Rustspark down at the docks, he should be able to help us out.",starts={{npcID=94789,x=0.42,y=0.71,zoneID=6720}},ends={{npcID=94801,x=0.4,y=0.722,zoneID=6720}},coords={x=0.42,y=0.71,source="quest_giver",zoneID=6720},questType="standard"},
[39676] = {id=39676,name="A True Naval Commander",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=6720,description="Yes! Those are the blueprints I misplaced when I was fishing last week. These instructions match my prototype equipment one for one. Take this Blast Furnace and install it on one of our ships. This should let us break the naval blockade and expand our control of the Draenor seas.",starts={{npcID=94801,x=0.4,y=0.722,zoneID=6720}},ends={{npcID=94789,x=0.42,y=0.71,zoneID=6720}},coords={x=0.4,y=0.722,source="quest_giver",zoneID=6720},questType="standard"},
[39680] = {id=39680,name="Between the Hammer...",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description=", I fear that my spirit will remain bound to this place unless I am made whole again. Long ago, I discovered a cave near the coast behind Black Rook Hold. I explored the cave only to find an abominable creature that attacked me, causing me to drop my hammer as I fled. I need that hammer back if I am to be at peace.",starts={{npcID=96763,x=0.4,y=0.548,zoneID=7558}},ends={{npcID=96763,x=0.4,y=0.548,zoneID=7558}},coords={x=0.4,y=0.548,source="quest_giver",zoneID=7558},questType="standard"},
[39681] = {id=39681,name="The Properties of Leystone",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="I've never seen anything like this \"leystone\" ore. It's light, like mithril, but it carries much more of a magical energy... more even than saronite or elementium. Let's try making something with it. How about a nice pair of gauntlets?",questType="standard"},
[39682] = {id=39682,name="Grand Theft Felbat",level=8,requiredLevel=8,faction="both",expansion=6,zoneID=7814,description="You heard what Maiev said. We need to get out of here. There is an elevator shaft at the far end of these caverns. Let us make our way there.",questType="standard"},
[39683] = {id=39683,name="Forged in Fire",level=8,requiredLevel=8,faction="both",expansion=6,zoneID=7814,description="The fearsome demon, Immolanth, led a Legion army that conquered and eventually ruled a distant nexus world. Somehow, the Wardens imprisoned him, then kept him locked up in the chamber to our left. He is contained, but not for long. The demon's power is a valuable prize to any demon hunter who can defeat him. Whoever can do so will gain power beyond imagining. I believe that person could be you, .",questType="standard"},
[39684] = {id=39684,name="Beam Me Up",level=8,requiredLevel=8,faction="both",expansion=6,zoneID=7814,description="To the east is an intricate prison chamber designed to contain the beholder, Glazer . It began malfunctioning shortly after the breach. You will need to rotate the mirrors in the room to focus an energy beam onto the creature. Otherwise, we cannot break through Glazer 's impenetrable shield. Hurry. Altruis went ahead to assist the others, but we are losing the fight.",questType="standard"},
[39685] = {id=39685,name="Frozen in Time",level=8,requiredLevel=8,faction="both",expansion=6,zoneID=7814,description="The Wardens kept all kinds of dangerous monsters locked up within this Vault. Now that Gul'dan's forces have breached the walls, it's proving rather... inconvenient. Many of our forces are occupied with containing a fearsome magma destroyer in the southern chamber. With us freshly awoken from stasis, we don't have the means to take it down. However, we might be able to reactivate the room's containment field. Go join up with Kayn. Do whatever it takes to seal that chamber!",questType="standard"},
[39686] = {id=39686,name="All The Way Up",level=8,requiredLevel=8,faction="both",expansion=6,zoneID=7814,description="Kor'vas went ahead to meet up with Kayn and Altruis. Step onto the elevator when it arrives, and meet them in the Hall of Judgment above.",questType="standard"},
[39688] = {id=39688,name="Between Us and Freedom",level=8,requiredLevel=8,faction="alliance",expansion=6,zoneID=7502,description="The last of our survivors have fought their way into the final chamber ahead. Only one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax. Kill him, take his power, and claim our freedom.",questType="standard"},
[39691] = {id=39691,name="The Call of War",level=8,requiredLevel=8,faction="alliance",expansion=6,zoneID=1637,description="Today, sorrow grips Stormwind, bastion of the Light. King Varian Wrynn has fallen in battle, leaving the crown to his son Anduin. The leaders of the Alliance have gathered to pay their respects. No doubt they will have need of your unique skills. You will find the king upon the throne of Stormwind Keep, attended by one of your fellow Illidari. I am needed in Dalaran. Good luck, $p.",starts={{npcID=97296,x=0.724,y=0.472,zoneID=1519},{npcID=97296,x=0.526,y=0.882,zoneID=1637}},ends={{npcID=102585,x=0.842,y=0.336,zoneID=1519}},coords={x=0.724,y=0.472,source="quest_giver",zoneID=1519},questType="standard"},
[39692] = {id=39692,name="The Call of War",level=8,requiredLevel=8,faction="horde",expansion=6,description="The Warchief Vol'jin is expecting you. Enter Grommash Hold straight ahead, and make your introduction.",questType="standard"},
[39694] = {id=39694,name="Between Us and Freedom",level=8,requiredLevel=8,faction="both",expansion=6,zoneID=7502,description="The last of our survivors have fought their way into the final chamber ahead. Only one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax. Kill him, take his power, and claim our freedom.",questType="standard"},
[39696] = {id=39696,name="Rise, Champions",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=139,mapID=23,questType="standard"},
[39697] = {id=39697,name="Master vs. Commander",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=7078,description="I've been doing a little digging - or whatever you call digging in naval terms. Snorkeling? Gul'dan has sent his most powerful flagship on a scouting mission to the four corners of Draenor. He is mapping out all the oceanic ley-line conjunctions. This is information that I could use to upgrade your ring... But in Gul'dan's hands, it could be catastrophic. Scramble the fleet, ! Hunt down his infamous flagship, \"The Master's Call,\" and steal that map before they complete their mission. Hurry!",starts={{npcID=92213,x=0.276,y=0.102,zoneID=6719},{npcID=92213,x=0.408,y=0.732,zoneID=6720},{npcID=92213,x=0.32,y=0.324,zoneID=7078}},ends={{npcID=92213,x=0.276,y=0.102,zoneID=6719},{npcID=92213,x=0.408,y=0.732,zoneID=6720},{npcID=92213,x=0.32,y=0.324,zoneID=7078}},coords={x=0.276,y=0.102,source="quest_giver",zoneID=6719},questType="standard"},
[39698] = {id=39698,name="Making the Rounds",level=10,requiredLevel=10,faction="horde",expansion=6,zoneID=14,description="As you can see, we have spared no expense in showing our support of your great quest. Final preparations are being made - come, walk with me.",starts={{npcID=96686,x=0.614,y=0.088,zoneID=14}},ends={{npcID=96686,x=0.614,y=0.088,zoneID=14}},coords={x=0.614,y=0.088,source="quest_giver",zoneID=14},questType="standard"},
[39699] = {id=39699,name="Ironhorn Leysmithing",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="I sense great strength in you, yet you refuse to wield it. We Ironhorn use double the metal of any normal blacksmith to craft our wares. There is also a technique in how you hammer such quantities of leystone that I will instruct you on. Use our scrap metal and hammer out the pieces for a gauntlet. I will weld the pieces together when you are finished.",starts={{npcID=92242,x=0.552,y=0.842,zoneID=7503}},ends={{npcID=92242,x=0.552,y=0.842,zoneID=7503}},coords={x=0.552,y=0.842,source="quest_giver",zoneID=7503},questType="standard"},
[39702] = {id=39702,name="Legend of Black Rook Hold",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description=", have you heard of Saris Swifthammer ? He was a legendary blacksmith amongst the elves of Black Rook Hold. I wonder if any of his research still exists. I want you to travel there and see if you can discover anything about Saris, or see if he left anything we can research here at my shop.",ends={{npcID=96763,x=0.4,y=0.548,zoneID=7558}},questType="standard"},
[39716] = {id=39716,name="Smashing Squashlings",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=6719,description="The Bonefleet once raided trading ships traveling the waters of Draenor. One such ship carried farming supplies intended for Elodor. Now, they use these supplies to sow their plague into our earth. From the putrid mounds sprout vegetative horrors. These abominations must be destroyed, before they can spread across the landscape.",starts={{npcID=96705,x=0.474,y=0.374,zoneID=7004},{npcID=96705,x=0.442,y=0.518,zoneID=7078}},ends={{npcID=96362,x=0.476,y=0.38,zoneID=7004},{npcID=96362,x=0.444,y=0.514,zoneID=7078}},coords={x=0.474,y=0.374,source="quest_giver",zoneID=7004},questType="standard"},
[39718] = {id=39718,name="Paradise Lost",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Archmage Khadgar was planning an expedition to Azsuna - you should seek him out at Krasus' Landing in Dalaran immediately.",questType="standard"},
[39719] = {id=39719,name="Mutiny on the Boneship",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=6719,description="Each year, around this time, there is a strange surge of spiritual energy across Draenor. Beckoned by this phenomenon, a ghastly fleet of undead pirates emerges from the mist. We call it the Bonefleet. The Bonefleet is led by a savage pirate known as Bonerender. He seeks nothing more than the complete destruction of all of the living of Draenor. Seek out Bonerender and defeat him, before he sails back into the mist once again.",starts={{npcID=96705,x=0.474,y=0.374,zoneID=7004},{npcID=96705,x=0.442,y=0.518,zoneID=7078}},ends={{npcID=96362,x=0.476,y=0.38,zoneID=7004},{npcID=96362,x=0.444,y=0.514,zoneID=7078}},coords={x=0.474,y=0.374,source="quest_giver",zoneID=7004},questType="group"},
[39720] = {id=39720,name="Foul Fertilizer",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=6719,description="The Bonefleet wants nothing more than to spread their undead curse onto dry land. Like a sickness, it will slowly overtake the landscape if left unchecked. The stench of undeath permeates the barrels of fertilizer they use to sow their dread crops. They are the source of the spreading plague, and must be destroyed.",starts={{npcID=96705,x=0.474,y=0.374,zoneID=7004},{npcID=96705,x=0.442,y=0.518,zoneID=7078}},ends={{npcID=96362,x=0.476,y=0.38,zoneID=7004},{npcID=96362,x=0.444,y=0.514,zoneID=7078}},coords={x=0.474,y=0.374,source="quest_giver",zoneID=7004},questType="standard"},
[39721] = {id=39721,name="Culling the Crew",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=6719,description="If we're going to protect Draenor from the Bonefleet menace, we'll need to thin out the crew. See to a swift reduction in their numbers, and we might just push them back into the sea for another year.",starts={{npcID=96705,x=0.474,y=0.374,zoneID=7004},{npcID=96705,x=0.442,y=0.518,zoneID=7078}},ends={{npcID=96362,x=0.476,y=0.38,zoneID=7004},{npcID=96362,x=0.444,y=0.514,zoneID=7078}},coords={x=0.474,y=0.374,source="quest_giver",zoneID=7004},questType="standard"},
[39726] = {id=39726,name="...And the Anvil",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="If you truly wish to see my work then you'll have to go and retrieve it as my shop has been raided of everything I've made. The breastplates of the Black Rook soldiers were one of my greatest accomplishments. They're light, yet strong and offer great mobility Relinquish my cursed brethren of their breastplates and bring them back to me. I will explain the finer points of how I made them upon your return.",questType="standard"},
[39729] = {id=39729,name="The Knowledge of Black Rook",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="You have honored me with your help and now I wish to return those favors to you. On that pedestal there is all my research. Take it with you and learn from it so you may carry on my legacy. Thank you again, .",starts={{npcID=96763,x=0.4,y=0.548,zoneID=7558}},coords={x=0.4,y=0.548,source="quest_giver",zoneID=7558},questType="standard"},
[39731] = {id=39731,name="The Tranquil Forest",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Archmage Khadgar sent word about Val'sharah not long ago. It sounds like he has good news. You should meet him on Krasus' Landing in Dalaran as soon as you are able.",questType="standard"},
[39733] = {id=39733,name="The Lone Mountain",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Our sources tell us that a Highmountain tauren emissary has recently arrived in Dalaran. We don't know his intentions, but his people could be an invaluable contact in the region. Khadgar is greeting the emissary at Krasus' Landing in Dalaran - you should seek him out.",ends={{npcID=97666,x=0.59,y=0.654,zoneID=7503}},questType="standard"},
[39735] = {id=39735,name="Stormheim",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=7502,description="Sky Admiral Rogers has sent word for you to meet her in Dalaran. She should be waiting for you in the Violet Citadel. It sounded important.",ends={{npcID=96644,x=0.188,y=0.426,zoneID=1519}},questType="standard"},
[39741] = {id=39741,name="Into Our Ranks",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8022,description="I feel that we should quickly welcome Akama into our ranks. It's important that the others see him treated as one of us, rather than as an outsider. Kor'vas Bloodthorn has proven herself invaluable, time and time again. Her skills in combat are unquestioned and unparalleled. You will find no champion better suited to destroying our enemies. It is time to officially raise them up as champions.",questType="standard"},
[39742] = {id=39742,name="Vault of the Wardens",level=8,requiredLevel=8,faction="none",expansion=6,zoneID=7814,mapID=679,questType="standard"},
[39746] = {id=39746,name="A Ring Unbroken",level=10,requiredLevel=10,faction="horde",expansion=6,zoneID=8046,description="Our defeat at the Broken Shore was decisive. The Burning Legion has a foothold on Azeroth, and the best of our armies are retreating in tatters. The elders of the Earthen Ring have called an emergency council near the heart of our world - the Maelstrom. , your triumphs throughout Azeroth and Draenor are the stuff of legend. We need you more than ever. Join me at the Maelstrom. Stormcaller Mylra will be flying there shortly - find her at Krasus' Landing here in Dalaran.",ends={{npcID=96527,x=0.47,y=0.52,zoneID=5042},{npcID=96527,x=0.362,y=0.752,zoneID=8046}},questType="standard"},
[39756] = {id=39756,name="A Sound Plan",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=139,description="The Legion still believes us crippled from the Broken Shore. They think we are unable to fight back. Let's prove them wrong. We've been hard at work mapping out the Broken Isles, learning everything we can about each region for our imminent assault. Once you've had a chance to peruse the map, you should leave for Dalaran at once and charge into the maw of the beast. We will end this madness for good. Light help us all.",questType="standard"},
[39762] = {id=39762,name="Feltotem Warlock",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39763] = {id=39763,name="For Whom the Fel Tolls",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,description="You wish me to help you understand this rock? First you do something for me. The legion has brought many of its fel machines to conquer this world. Those machines are powered by cores filled with fel energy. And those cores are carried by the lowliest of their minions for distribution. Bring me some cores and I'll give you the information you need.",questType="standard"},
[39764] = {id=39764,name="Shiny, But Deadly",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Soulkeeper Uriah and I were transporting demon prisoners to Allari in Azsuna when our caravan was attacked by kobolds. Those mindless vermin made off with the soul chambers that house our demonic captives. The crystals may be shiny, but they're also deadly. If they are damaged in any way, the demons trapped within may escape. Head into the cave nearby and recover the soul chambers before it's too late.",questType="standard"},
[39765] = {id=39765,name="Wax On, Wax Off",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="I've been dead for centuries without having my grave so disturbed... The leader of the local kobolds has stolen my skull from my grave and wears it upon his head! He's down in the cave below, but a gate blocks your path from retrieving it directly. Kobolds know their leadership by the skulls they wear, and they are unintelligent enough to believe you their leader if you have one yourself. Kill one of their Skullcaptains and recover his Skull of Bossing Around , and they may let you into the cave.",starts={{npcID=96984,x=0.546,y=0.45,zoneID=7503}},ends={{npcID=96984,x=0.546,y=0.45,zoneID=7503}},coords={x=0.546,y=0.45,source="quest_giver",zoneID=7503},questType="standard"},
[39768] = {id=39768,name="Candle to the Grave",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="These kobolds are taking advantage of the attacks against the Skyhorn tribe. They disturb our graves and steal anything they can get their paws on. I can do nothing to stop them! Please rid this sacred burial ground of the kobold.",starts={{npcID=96984,x=0.546,y=0.45,zoneID=7503}},ends={{npcID=96984,x=0.546,y=0.45,zoneID=7503}},coords={x=0.546,y=0.45,source="quest_giver",zoneID=7503},questType="standard"},
[39769] = {id=39769,name="The Gates of Wax",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Go talk to the Bluewax Gatekeeper and see if he will let you through to the Candleking. If you can get through by donning the skull, the smell will be worth it.",starts={{npcID=96984,x=0.546,y=0.45,zoneID=7503}},ends={{npcID=97130,x=0.552,y=0.418,zoneID=7503}},coords={x=0.546,y=0.45,source="quest_giver",zoneID=7503},questType="standard"},
[39770] = {id=39770,name="Burn the Candle at Both Ends [NOT USED]",level=10,requiredLevel=10,faction="none",expansion=6,zoneID=7503,mapID=650,description="You no come in yet! You need yellow candle and green candle before let in to Candleking!",questType="standard"},
[39771] = {id=39771,name="The Voice of Thunder",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8046,description="The White Tiger has prepared a series of challenges for everyone who wants to possess the weapons of the storm. Now you know of their power - these are the very artifacts that Ra-den himself wielded during the age of the Titans. Come! I have led arena teams to victory across three continents. With me in your corner, you cannot lose!",starts={{npcID=96541,x=0.338,y=0.748,zoneID=7745},{npcID=96541,x=0.342,y=0.748,zoneID=8046}},ends={{npcID=96541,x=0.338,y=0.748,zoneID=7745},{npcID=96541,x=0.342,y=0.748,zoneID=8046}},coords={x=0.338,y=0.748,source="quest_giver",zoneID=7745},questType="standard"},
[39772] = {id=39772,name="Can't Hold a Candle To You",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Okay guess you can go say hi to Candleking now.",starts={{npcID=97130,x=0.552,y=0.418,zoneID=7503}},ends={{npcID=96984,x=0.546,y=0.45,zoneID=7503}},coords={x=0.552,y=0.418,source="quest_giver",zoneID=7503},questType="standard"},
[39773] = {id=39773,name="The Soulkeeper's Fate",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Soulkeeper Uriah was injured in the kobold attack, but insisted on venturing further into the cave to recover the stolen soul shards. He told me to wait here with our remaining supplies until he returned, but I fear the worst. Please find Uriah. He is the only one who knows how to trap the demons.",questType="standard"},
[39774] = {id=39774,name="Demon Detainment",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="The demons that escaped must be detained. Killing them is not an option. Uriah was entrusted to deliver the prisoners to Allari for interrogation, and I will not let him fail. I've seen Uriah trap many demons. It seems... complicated, but I think I can pull it off. I'll just need you to subdue them first.",questType="standard"},
[39775] = {id=39775,name="Stormforged Grapple Launcher",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,mapID=634,questType="standard"},
[39776] = {id=39776,name="Battle Worms",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Snowmane Village behind us was caught completely off guard by the scale of this attack. I will hold the drogbar line here so the civilians have time to prepare their evacuation. The drogbar are using worms to burrow their way to the surface and deploy their troops. I am giving you command of our forces. Use them to slay these worms and cut off enemy reinforcements.",starts={{npcID=93846,x=0.532,y=0.64,zoneID=7503}},ends={{npcID=93846,x=0.532,y=0.64,zoneID=7503}},coords={x=0.532,y=0.64,source="quest_giver",zoneID=7503},questType="standard"},
[39777] = {id=39777,name="Buy Us Time",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="We need time to evacuate Snowmane Village. Can you take the fight to these Mightstone drogbar and cull their numbers? I will direct my healers to get everyone that is unable to fight to safety.",starts={{npcID=97344,x=0.532,y=0.64,zoneID=7503}},ends={{npcID=97344,x=0.532,y=0.64,zoneID=7503}},coords={x=0.532,y=0.64,source="quest_giver",zoneID=7503},questType="standard"},
[39780] = {id=39780,name="The Underking",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Mayla already chased the Underking into his cave. That is something we tell our children never to do. Reckless child, but hey, who wants to live forever? Let us join her in battle.",starts={{npcID=97407,x=0.532,y=0.686,zoneID=7503}},ends={{npcID=93846,x=0.532,y=0.64,zoneID=7503}},coords={x=0.532,y=0.686,source="quest_giver",zoneID=7503},questType="standard"},
[39781] = {id=39781,name="Neltharion's Lair: Death to the Underking",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7546,description="I will direct my people to clear a path through this rubble and assault Dargrul's forces directly. It will be a ruse. Navarrogg proposed a plan that I believe has merit. He knows of a side entrance that might lead directly to Dargrul. Muster what allies of yours you can and strike at them through this side passage. Recover the Hammer of Khaz'goroth before that villain brings the mountain down on top of us. We will provide the distraction you need to get a shot.",starts={{npcID=93846,x=0.532,y=0.64,zoneID=7503}},ends={{npcID=250548,zoneID=7546}},coords={x=0.532,y=0.64,source="quest_giver",zoneID=7503},questType="dungeon"},
[39783] = {id=39783,name="Battle Pet - Terky",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=6720,mapID=525,questType="standard"},
[39785] = {id=39785,name="[PH] Walrus Tusks",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7541,mapID=634,questType="standard"},
[39786] = {id=39786,name="A Stone Cold Gamble",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="The second target is a basilisk called Stonefang that lives off the bank of the nearby river. I put a bigger wager on him, so if you can take him out I'll make sure you get a cut. I'll need his jaw to verify the kill. Hurry, before those tauren get him first!",starts={{npcID=107674,x=0.512,y=0.57,zoneID=7541}},ends={{npcID=107674,x=0.512,y=0.57,zoneID=7541}},coords={x=0.512,y=0.57,source="quest_giver",zoneID=7541},questType="group"},
[39787] = {id=39787,name="Rigging the Wager",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="Care to help settle a bet, chum? Those tauren are Skyhorn, and they fancy themselves big-time hunters. I bet them a pretty penny that they wouldn't be able to take out some of the biggest beasts in Stormheim . If you take em out before they do, I'll split the wager. Deal? The first is a big eagle nesting in the foothills. They call him Spitefeather. You can bait him with some meat, but he's up pretty high, so you'll need a grapple gun to get there. I think there's one of them layin around here...",starts={{npcID=107674,x=0.512,y=0.57,zoneID=7541}},ends={{npcID=107674,x=0.512,y=0.57,zoneID=7541}},coords={x=0.512,y=0.57,source="quest_giver",zoneID=7541},questType="group"},
[39788] = {id=39788,name="The Runewood's Revenge",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="The Bonespeakers...they are corrupt... hungry for power. Cut them from my woods...",starts={{npcID=93231,x=0.684,y=0.542,zoneID=7541}},ends={{npcID=93231,x=0.684,y=0.542,zoneID=7541}},coords={x=0.684,y=0.542,source="quest_giver",zoneID=7541},questType="standard"},
[39789] = {id=39789,name="Eating Into Our Business",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="Greetings traveler! You are welcome to rest at our camp, but if you plan on sticking around a while, I have a proposition for you. As you can see, the land here has been very good to us, providing a great natural bounty. Lately, however, the worg have become problematic, and are thinning the herds to unacceptable levels. I can't take care of them all, so I will offer a bounty for every worg slain in the mesa. Return to me when you have culled their pack a bit.",starts={{npcID=97258,x=0.514,y=0.568,zoneID=7541}},ends={{npcID=107675,x=0.514,y=0.57,zoneID=7541}},coords={x=0.514,y=0.568,source="quest_giver",zoneID=7541},questType="standard"},
[39790] = {id=39790,name="Infernal Brimstone Theory",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,description="I've gone through all the research ye gathered for me and I've come up with a theory. As we know, the ore in this world develops over time, through pressure and environmental changes. But the Infernal Brimstone ye gave me had its growth accelerated through demonic magic, much like the saronite of Icecrown. If we're wantin' to test this out, we'll have to get the help of some magic-users. Take this brimstone back and go see Matthew Rabis . He may know how to breathe life into it.",questType="standard"},
[39791] = {id=39791,name="Lay Them to Rest",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="I would ask a favor, outsider. As you step through the graves of ancient heroes, you will no doubt come across spirits of the restless dead, agitated by the Bonespeakers misdeeds. They must be returned to the earth where they are buried, so that they may be judged as well. Take this bough - it carries with it the essence of the Runewood. Channel its power into a weakened spirit, and it will return to rest.",starts={{npcID=93231,x=0.684,y=0.542,zoneID=7541}},ends={{npcID=93446,x=0.682,y=0.486,zoneID=7541},{npcID=97270,x=0.698,y=0.456,zoneID=7541}},coords={x=0.684,y=0.542,source="quest_giver",zoneID=7541},questType="standard"},
[39792] = {id=39792,name="A Stack of Racks",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="So while we're waiting here, maybe you could fetch us up some grub. Them tauren were runnin low on meats, so I'm sure they'd be thankful to have more. I hear that musken ribs are the specialty here. The wild musken here are too lean for any good meat, but across the river there are some nice fat ones. Maybe you should check those out! Don't worry, I'm pretty sure there aren't any dragons over there...",starts={{npcID=107675,x=0.514,y=0.57,zoneID=7541}},ends={{npcID=107675,x=0.514,y=0.57,zoneID=7541}},coords={x=0.514,y=0.57,source="quest_giver",zoneID=7541},questType="standard"},
[39793] = {id=39793,name="Only the Finest",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="Say, you're a pretty good hunter, eh? Maybe you could help these tauren out by stocking them with some rare furs. I'm sure they'd appreciate it when they got back! I hear that Stormheim goat hair can be woven into all kinds of things. The rarest are from the silver-tail goats. I think I saw some in that mountain over there. Why don't you go and fetch some? I'm sure them tauren would pay you handsomely!",starts={{npcID=107675,x=0.514,y=0.57,zoneID=7541}},ends={{npcID=107675,x=0.514,y=0.57,zoneID=7541}},coords={x=0.514,y=0.57,source="quest_giver",zoneID=7541},questType="standard"},
[39796] = {id=39796,name="To Haustvald",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="Your next steps are clear, your feet know the way. Follow them to Haustvald and meet your fate! It is the tree you seek, the heart of the mystic Runewood. He will offer guidance, and probably leaves.",starts={{npcID=92539,x=0.602,y=0.508,zoneID=7541}},ends={{npcID=93231,x=0.684,y=0.542,zoneID=7541}},coords={x=0.602,y=0.508,source="quest_giver",zoneID=7541},questType="standard"},
[39799] = {id=39799,name="Our Next Move",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7543,description="Have you seen the fog that surrounds us? The chill winds of Acherus have provided us with a perfect concealment from the prying eyes of the Legion! Under cover of this fog we've been able to send out scouting teams who've put together a fairly comprehensive map of the Broken Isles. Choose where we shall begin our assault. You, of course, shall have the honor of spearheading our efforts, but the rest of the Ebon Blade will follow your lead.",questType="standard"},
[39800] = {id=39800,name="Greymane's Gambit",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=7541,mapID=634,description="The Skyfire is prepared to make way to Stormheim . Should we become engaged, I will require my best fighters on the front line. This includes you, .",starts={{npcID=96663,x=0.186,y=0.508,mapID=84}},ends={{npcID=90749,x=0.336,y=0.51,mapID=634}},coords={x=0.186,y=0.508,source="quest_giver",mapID=634},questType="standard"},
[39801] = {id=39801,name="The Splintered Fleet",level=10,requiredLevel=10,faction="horde",expansion=6,zoneID=7541,description="Preparations have been made, and we are ready to set sail. We must strike out at once. Do not dally, or you will be left behind.",starts={{npcID=96686,x=0.614,y=0.088,zoneID=14}},ends={{npcID=91473,x=0.36,y=0.276,zoneID=7541}},coords={x=0.614,y=0.088,source="quest_giver",zoneID=14},questType="standard"},
[39803] = {id=39803,name="The Trials Continue",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="Havi 's voice continues in your head as the raven stares on> If valor you seek, then to the bones you must speak! But first you must prepare!",starts={{npcID=97074,x=0.48,y=0.546,zoneID=7541}},ends={{npcID=92539,x=0.602,y=0.508,zoneID=7541}},coords={x=0.48,y=0.546,source="quest_giver",zoneID=7541},questType="standard"},
[39804] = {id=39804,name="Speaking of Bones",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="The Trial of Valor will be your next test, and test you it will! But only a fool fights on an empty stomach. Are you a fool, outsider? No? Then lend these old bones a hand and butcher the moose for our meal. I will spin you a tale of rocks, trees and spirits.",starts={{npcID=92539,x=0.602,y=0.508,zoneID=7541}},ends={{npcID=92539,x=0.602,y=0.508,zoneID=7541}},coords={x=0.602,y=0.508,source="quest_giver",zoneID=7541},questType="standard"},
[39808] = {id=39808,name="Sepulcher of the Sky Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39809] = {id=39809,name="Path of Huln Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39810] = {id=39810,name="Whitewater Wash Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39811] = {id=39811,name="Whitewater Wash Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39812] = {id=39812,name="Whitewater Wash Treasure",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39813] = {id=39813,name="Earthmother's Bounty Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39814] = {id=39814,name="Lifespring Cavern Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39815] = {id=39815,name="Sylvan Falls Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39816] = {id=39816,name="Champion: Thassarian",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7543,description="Deathlord, I've found our wayward knight. He wishes to return to the Ebon Blade, in particular he wishes to speak with you himself. He should be here momentarily.",questType="standard"},
[39817] = {id=39817,name="The Brimstone's Secret",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,description="While you were gathering what I asked of you, I did a little testing on the brimstone. It reacted rather violently when I channeled onto it. Careful casting went into making the creature from whom you took this. Unless you have a host of demon spell-casters at your disposal, recreating such a creature would be impossible. That's all I have to tell you. Go now and leave me before my hunger takes over.",questType="standard"},
[39818] = {id=39818,name="Champion: Nazgrim",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7543,description="Deathlord, I've found our wayward knight. He wishes to return to the Ebon Blade, in particular he wishes to speak with you himself. He should be here momentarily.",questType="standard"},
[39819] = {id=39819,name="Bloodhunt Highland Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39820] = {id=39820,name="Bloodhunt Highland Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39821] = {id=39821,name="Bloodhunt Highland Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39822] = {id=39822,name="Bloodhunt Highland Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39823] = {id=39823,name="Bloodhunt Highland Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39824] = {id=39824,name="7.0 Highmountain - Treasure 025 - Skyhorn Waterfall",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39825] = {id=39825,name="Stonedark Grotto Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39826] = {id=39826,name="Witchwood Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39827] = {id=39827,name="Haglands Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39830] = {id=39830,name="Hellfire Citadel: Hellfire and Brimstone",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,description="When Khadgar's group stormed Hellfire Citadel, they faced many foes that commanded demons, but none more powerful than Archimonde himself. Perhaps there's somethin' on his corpse that can answer the final questions of unlocking the mystery of this brimstone.",questType="standard"},
[39832] = {id=39832,name="Plans and Preparations",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7543,description="Your weapon is stronger than ever, but it will need many more souls in order to reach its true potential. Siouxsie has been collecting reports from the scouts, she will direct you to our enemies and their screaming souls will empower your weapon further.",questType="standard"},
[39837] = {id=39837,name="An Unworthy Task",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7588,description="This place is Helheim , the realm of the unworthy dead. Here, the spirits of the dishonorable spend eternity in an endless futile battle, always seeking glory but never able to attain it. We should not be here. We must find a way out. I will scout ahead - you should try and release some of these captive spirits here. Perhaps one may have some answers for us.",starts={{npcID=97319,x=0.652,y=0.472,zoneID=7588}},ends={{npcID=91531,x=0.646,y=0.436,zoneID=7588}},coords={x=0.652,y=0.472,source="quest_giver",zoneID=7588},questType="standard"},
[39846] = {id=39846,name="7.0 Dalaran - Treasure 001 - Burnt Cart",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7502,mapID=627,questType="standard"},
[39847] = {id=39847,name="Sign This",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Ah, a fellow scribe! You don't look too dim, so how 'bout you and I work together in an effort to discover what we can about the Broken Isles? (That's the big mass of islands we're floating over.) However! I never agree to a partnership without getting all the requisite legalities out of the way. Sign this for me and we're in business.",questType="standard"},
[39848] = {id=39848,name="A Desperate Bargain",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7588,description="It looks like your friend didn't make it. A pity, but we must move on. You'll want to plead our case to Helya. She is the ruler here. I would accompany you, but I'm afraid I wouldn't help your case. Meet me when you are finished. I will see if I can find the whereabouts of my shieldmaidens.",starts={{npcID=97419,x=0.648,y=0.442,zoneID=7588},{npcID=97480,x=0.466,y=0.492,zoneID=7588}},ends={{npcID=244559,x=0.342,y=0.282,zoneID=7588}},coords={x=0.648,y=0.442,source="quest_giver",zoneID=7588},questType="standard"},
[39849] = {id=39849,name="To Light the Way",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7588,description="Helya must think her challenge unwinnable. We will show her different. I am unsure what she did, but Helya has weakened you somehow. I have seen similar effects on my shieldmaidens, and now they are trapped by Helya's minions. I may know a way, however. The Kvaldir ships carry special lanterns bound to this place to navigate through the fog. It is said that the light of these lanterns can release bonds of the spirit. There is a kvaldir ship nearby. See if you can find one there.",starts={{npcID=97480,x=0.466,y=0.492,zoneID=7588}},ends={{npcID=97480,x=0.466,y=0.492,zoneID=7588}},coords={x=0.466,y=0.492,source="quest_giver",zoneID=7588},questType="standard"},
[39850] = {id=39850,name="Sundered",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7588,description="I imagine the power of your weapon will be what allows us to defeat Geir, but right now you are too weak for the confrontation. We must reclaim the missing pieces of your spirit. Helya must have scattered them throughout her realm to keep them from you. If you can find them, shine the lantern and they should be set free. Be careful, though. It is unlikely that Helya left your spirit fragments unguarded.",starts={{npcID=97480,x=0.466,y=0.492,zoneID=7588}},ends={{npcID=97480,x=0.466,y=0.492,zoneID=7588}},coords={x=0.466,y=0.492,source="quest_giver",zoneID=7588},questType="standard"},
[39851] = {id=39851,name="Allies in Death",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7588,description="Our power alone may not be enough to fight the behemoth, Geir. Fortunately, Faljar was kind enough to send our allies into Helheim with us. Earlier, I had discovered several of them being tortured by the elemental forces of Helheim . You may think the dead can't drown, but with Helya's power, this is not the case. I could not release them then, but now that you possess the waylight, you may be able to. Seek them out and free them from an eternity of suffering!",starts={{npcID=97480,x=0.466,y=0.492,zoneID=7588}},ends={{npcID=97480,x=0.466,y=0.492,zoneID=7588}},coords={x=0.466,y=0.492,source="quest_giver",zoneID=7588},questType="standard"},
[39852] = {id=39852,name="[PH] Collect Weapons",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7541,mapID=634,questType="standard"},
[39853] = {id=39853,name="Victory is Eternal",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7588,description="There is no more cause for hesitation. Now is the time to strike. We will defeat this foul behemoth and meet Helya's bargain. The path out of Helheim awaits, outsider. Prepare yourself.",starts={{npcID=97480,x=0.466,y=0.492,zoneID=7588}},coords={x=0.466,y=0.492,source="quest_giver",zoneID=7588},questType="standard"},
[39855] = {id=39855,name="Paid in Lifeblood",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="We have fulfilled Helya's bargain. Now, we see if she will keep to her word. When you are ready, we should proceed to the throne. If you have any other business here, I would suggest finishing it now. I will follow your lead, outsider.",ends={{npcID=92539,x=0.602,y=0.508,zoneID=7541}},questType="standard"},
[39856] = {id=39856,name="Vignette: Wraithtalon",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[39857] = {id=39857,name="The Eternal Nemesis",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7588,description="You say that you do not belong here among the unworthy, outsider, but your spirit fragments so easily. How am I to know you speak the truth? I cannot, so you must show me. Bring yourself to the eternal battlefield and face my champion. If you manage to defeat him, then I may grant you a pardon.",starts={{npcID=244559,x=0.342,y=0.282,zoneID=7588}},ends={{npcID=97480,x=0.466,y=0.492,zoneID=7588}},coords={x=0.342,y=0.282,source="quest_giver",zoneID=7588},questType="standard"},
[39859] = {id=39859,name="Note-Eating Goats",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="I've followed Hemet on all his expeditions from Stranglethorn to Nagrand to... Nagrand again, taking notes on his grand adventures and turning them into timeless literary tales. But my heart is really in the hunt. I want nothing more than to put down the pen, and pick up a rifle! Hemet promised to teach me how to hunt once I finish his latest novel, but the goats around here ate my first draft! I have no hope of becoming a hunter if my manuscript isn't recovered.",starts={{npcID=94434,x=0.4,y=0.522,zoneID=7503}},ends={{npcID=94409,x=0.4,y=0.522,zoneID=7503}},coords={x=0.4,y=0.522,source="quest_giver",zoneID=7503},questType="standard"},
[39860] = {id=39860,name="Rite of Blood",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Oakin Ironbull vouches for you. He's capable, for a Rivermane. You also brought with you proof of your own strength, albeit rather inconclusive proof. Before we allow you to move freely within our territory, you must complete the Rite of Blood, which you have already begun. If you succeed--and I doubt you will--talk to me. Enter the depths of the cave. Defeat whatever foe appears and return to me.",questType="standard"},
[39861] = {id=39861,name="Tying Up Loose Ends",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="Malfurion Stormrage managed to make landfall in Val'sharah and has already taken care of things there. It seems our fortune is finally turning around! He's waiting for you as we speak in Lorlathil. Life is so magical when everything goes according to plan.",ends={{npcID=91462,x=0.546,y=0.728,zoneID=7558}},questType="standard"},
[39862] = {id=39862,name="The Siegebrul",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Worms do not like battle or the surface. They only go where their master tells them. So, when in war, kill the master. Siegebrul Olgrul is the master of worms for the Mightstone drogbar who attack us from the north. Slay him.",starts={{npcID=97301,x=0.532,y=0.64,zoneID=7503}},ends={{npcID=97301,x=0.532,y=0.64,zoneID=7503}},coords={x=0.532,y=0.64,source="quest_giver",zoneID=7503},questType="standard"},
[39864] = {id=39864,name="Stormheim",level=10,requiredLevel=10,faction="horde",expansion=6,zoneID=7502,description="Nathanos Blightcaller , Champion of the Banshee Queen herself, sent for you in Dalaran. He should be waiting for you in the Violet Citadel. It sounded urgent.",ends={{npcID=96683,x=0.612,y=0.088,zoneID=14}},questType="standard"},
[39867] = {id=39867,name="I'm Not Lion!",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="I've hunted many exotic beasts in my day, but I've never seen a lion like the one I encountered while scouting the basin. The beast's amber eyes locked on mine, luring me closer. I was helpless to this predator's enchanting gaze. It was only when the lion pounced did the stupor break. I've told Hemet of this magical beast, but he laughs. I'm not lying, ! The lion exists. If you find the beast, bring me a trophy of your kill, and I'll reward you handsomely.",starts={{npcID=95438,x=0.4,y=0.522,zoneID=7503}},ends={{npcID=95438,x=0.4,y=0.522,zoneID=7503}},coords={x=0.4,y=0.522,source="quest_giver",zoneID=7503},questType="group"},
[39869] = {id=39869,name="Toll for the Soul",level=10,requiredLevel=10,faction="none",expansion=6,zoneID=7812,mapID=634,description="As foretold, you have arrived... Helya is foolish to think I'll let her ferry me into Helheim. Odyn has already smiled upon me, my soul belongs in Valhallas. Make no mistake, I am not a prisoner. Before my death Odyn appeared to me in the form of a raven. He praised my battles in life and gave me a quest no vrykul could refuse. The Helerjar arrived... and I let them slay me. Prisoner-- nay, I am a liberator, sent by Odyn to free the souls of Valarjar.",questType="dungeon"},
[39873] = {id=39873,name="I Have a Bad Feeling About This",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="You have no reason to trust me. My cousins led by Dargrul have gone mad with power. But I ask you to investigate something. I have a feeling something terrible is about to befall Highmountain , and that Torok and his Bloodtotem are going to be responsible. If you don't believe me, look for yourself at the northern side of Cliff's Edge.",starts={{npcID=97667,x=0.39,y=0.372,zoneID=7503}},ends={{npcID=243402,x=0.39,y=0.373,zoneID=7503}},coords={x=0.39,y=0.372,source="quest_giver",zoneID=7503},questType="standard"},
[39874] = {id=39874,name="Some Enchanted Evening",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Welcome! It's nice to see familiar faces returning to Dalaran. You might remember Ildine, Vanessa, and me from Northrend. Archmage Starsinger is in charge of the shop, but he's away on Kirin Tor business at the moment. He's a fine fellow... mostly. Your arrival is fortunate. We've run into a problem that we'd love to solve before the archmage returns. Interested in lending a hand?",questType="standard"},
[39875] = {id=39875,name="The Last Few",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="As you can see, , we're hard at work producing enchants for the battle against the Legion. Since you're here, we could really use your help wrapping up one of our orders. If you could, acquire some vellums and start enchanting them with Versatility. Here, I'll teach you the formula.",questType="standard"},
[39876] = {id=39876,name="Helping the Hunters",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="Now, while I continue to fill the rest of our orders, I'd really appreciate it if you would deliver these vellums to Jace Darkweaver down in Azsuna. He and the other demon hunters have been fighting back the Legion for quite some time and could use this as quickly as possible. Thanks, !",ends={{npcID=90317,x=0.432,y=0.436,zoneID=7334}},questType="standard"},
[39877] = {id=39877,name="In the Loop",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="We could use your help down here, . Some of our hunters would benefit greatly from having those vellums applied to their rings right now. Here take a few. I'll give the rest to one of my other soldiers to hand out. My hunters probably won't stop to let you apply the enchants, so you'll just have to do your enchanting even if they're in the midst of battle.",starts={{npcID=90317,x=0.432,y=0.436,zoneID=7334}},ends={{npcID=90317,x=0.432,y=0.436,zoneID=7334}},coords={x=0.432,y=0.436,source="quest_giver",zoneID=7334},questType="standard"},
[39878] = {id=39878,name="Thunder Struck",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="I've made contact with a potential source of new enchantments down in Highmountain. The tauren of Thunder Totem command the spirits to imbue items with great power. Seek out an enchanter named Twaintail and see if he will share his knowledge with us. Taurens are known for their sharing... right?",ends={{npcID=98017,x=0.466,y=0.604,zoneID=7503},{npcID=98017,x=0.442,y=0.452,zoneID=7731}},questType="standard"},
[39879] = {id=39879,name="Strong Like the Earth",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="There are many types of spirits in this world, . Some benevolent, some troubled. They all resonate with different reagents which we use to enchant our armor. One such reagent are the crystals of the ambershards. They are a violent creature born of the earth and have recently been disturbed by the drogbar. However, disturbed or not, the crystals they bear are of great use to my people for enchantments. Bring me some and I'll show you what I mean.",starts={{npcID=98017,x=0.466,y=0.604,zoneID=7503},{npcID=98017,x=0.442,y=0.452,zoneID=7731}},ends={{npcID=98017,x=0.466,y=0.604,zoneID=7503},{npcID=98017,x=0.442,y=0.452,zoneID=7731}},coords={x=0.466,y=0.604,source="quest_giver",zoneID=7503},questType="standard"},
[39880] = {id=39880,name="Waste Not",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="While fighting the ambershards for their crystals, you may come across enchanted armor from our fallen braves. The ambershards care not for such things, but our tribe does not believe in letting anything go to waste. I'd like you to retrieve our braves' armor and disenchant them into the components from which they were imbued. Bring me back the reagents so my tribe may use them to enchant new armor.",starts={{npcID=98017,x=0.466,y=0.604,zoneID=7503},{npcID=98017,x=0.442,y=0.452,zoneID=7731}},ends={{npcID=98017,x=0.466,y=0.604,zoneID=7503},{npcID=98017,x=0.442,y=0.452,zoneID=7731}},coords={x=0.466,y=0.604,source="quest_giver",zoneID=7503},questType="standard"},
[39881] = {id=39881,name="Fey Enchantments",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="The new dusts and crystals we've found in these lands are fascinating, as I'm sure you've already surmised. I'm positive we can expand their usefulness to more of our armor. I'd like you to go back out into the field and talk to a dryad in Val'sharah. Apparently she may be able to clue us into some enchantments for shoulder pieces. Her name is Nalamya . You'll find her near the Temple of Elune.",ends={{npcID=98156,x=0.544,y=0.576,zoneID=7558}},questType="standard"},
[39882] = {id=39882,name="Darkheart Thicket: The Glamour Has Faded",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7673,description="I once taught the night elves how to enchant their armor to strengthen themselves against the evils of this land. One elf in particular garnered my favor. Arch-Druid Glaidalis is his name. He now resides in the forest known as the Darkheart Thicket, plotting to undo this world with this awful blight. Before his betrayal, I gave him my book of enchantments to study. I would very much like it back. I trust you with this task, enchanter. Bring my book back to me.",starts={{npcID=98156,x=0.544,y=0.576,zoneID=7558}},ends={{npcID=98156,x=0.544,y=0.576,zoneID=7558}},coords={x=0.544,y=0.576,source="quest_giver",zoneID=7558},questType="dungeon"},
[39883] = {id=39883,name="Cloaked in Tradition",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="You have seen the ways of the tauren of Thunder Totem... speaking with the spirits, gathering from the land, and letting nothing go to waste. These are potent forces crucial to your quest to aid the Broken Isles. Here, take this journal back to your enchanter friend. It contains the lessons I have imparted unto you. Perhaps it will serve to help the greater cause of defeating the Legion.",starts={{npcID=98017,x=0.466,y=0.604,zoneID=7503},{npcID=98017,x=0.442,y=0.452,zoneID=7731}},coords={x=0.466,y=0.604,source="quest_giver",zoneID=7503},questType="standard"},
[39884] = {id=39884,name="No Longer Worthy",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="The elves of Black Rook Hold have decided to turn their backs on us. They stay inside their keep, attacking any outsider who dare try to enter. Such behavior is intolerable... especially after all the help they've received from my folk and the others of this land. I want you to do me a favor, . Take their enchanted sigils and reduce them to dust. Bring me back the dust as proof of your deeds.",starts={{npcID=98156,x=0.544,y=0.576,zoneID=7558}},ends={{npcID=98156,x=0.544,y=0.576,zoneID=7558}},coords={x=0.544,y=0.576,source="quest_giver",zoneID=7558},questType="standard"},
[39889] = {id=39889,name="Led Astray",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="The night elves are no fools, but the elves of Black Rook follow their commanders with blind loyalty. I've no doubt that the blame for their apathy rests heavily upon their commanders. I know of two of their leaders, who as we speak continue to command their troops to do nothing against the blight encroaching upon my home. Go to Black Rook Hold and slay Trelan Shieldbreaker and Starlys Strongbow . Let them be an example for those who can help, but wish to remain cowardly.",starts={{npcID=98156,x=0.544,y=0.576,zoneID=7558}},ends={{npcID=98156,x=0.544,y=0.576,zoneID=7558}},coords={x=0.544,y=0.576,source="quest_giver",zoneID=7558},questType="standard"},
[39891] = {id=39891,name="Cursed, But Convenient",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="I need you to return to Azsuna at once, . I've only just heard of an enchantress within the Crumbled Palace who knows of many rare enchantments. Go to her and see what you can learn at once.",ends={{npcID=107139,x=0.468,y=0.408,zoneID=7334}},questType="standard"},
[39903] = {id=39903,name="An Enchanting Home",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="The more I learn about the Broken Isles, the more convinced I am that it is a land of wonders! Ildine and I were just discussing rumors of a dwelling in Stormheim that was once the home to a vrykul enchantress called Tigrid. It is said the site is perfectly preserved, and her enchantments were so potent that they persist to this day! Investigating the home might uncover valuable knowledge, .",ends={{npcID=98367,x=0.394,y=0.426,zoneID=7541}},questType="standard"},
[39904] = {id=39904,name="Halls of Valor: Revenge of the Enchantress",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="For many centuries, even after death, I was capable of weaving enduring enchantments. But since the theft of my enchanting rod by a greedy king, I can barely sustain the little magic I have left. If you can recover my enchanting rod from the god-king's ghost, I will reward you in kind.",starts={{npcID=98367,x=0.394,y=0.426,zoneID=7541}},ends={{npcID=98367,x=0.394,y=0.426,zoneID=7541}},coords={x=0.394,y=0.426,source="quest_giver",zoneID=7541},questType="dungeon"},
[39905] = {id=39905,name="Ringing True",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="While your presence here would continue to be of value to us, your master in Dalaran has called for you. I'd like to thank you again for all you've done for us. My hunters have been reminded that they're not alone in this war.",starts={{npcID=90317,x=0.432,y=0.436,zoneID=7334}},coords={x=0.432,y=0.436,source="quest_giver",zoneID=7334},questType="standard"},
[39906] = {id=39906,name="Prepping For Battle",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="To earn my mark, , you must first prove yourself in battle to me. There is a naga I wish to kill, but I am not strong enough to slay him. Before we go into battle together, I need your help as an enchanter to become stronger. I'm sure by now you have a bevy of enchantments in your repertoire. Make some for me so that I may become strong enough again to make a difference in this world.",starts={{npcID=98159,x=0.468,y=0.408,zoneID=7334}},ends={{npcID=98159,x=0.468,y=0.408,zoneID=7334}},coords={x=0.468,y=0.408,source="quest_giver",zoneID=7334},questType="standard"},
[39907] = {id=39907,name="Elven Enchantments",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="You have earned the marks of my most trusted companions. You have also returned my love to me. I am fortunate to have met you, . Now return to your master and let him know of what you have learned.",starts={{npcID=107139,x=0.468,y=0.408,zoneID=7334}},coords={x=0.468,y=0.408,source="quest_giver",zoneID=7334},questType="standard"},
[39910] = {id=39910,name="The Druid's Debt",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="In order to grant you my mark, , I must first be made strong enough to come to your aid should you need it. Within the ruins of Nar'thalas, my idols sit dormant. As I've said, I'm not strong enough to get them myself. But you are strong, I can sense it. Strong enough to take on those honor-less naga who plague my home. Find my idols and return them to me. Do this and I will grant you my mark.",starts={{npcID=98381,x=0.468,y=0.408,zoneID=7334}},ends={{npcID=98381,x=0.468,y=0.408,zoneID=7334}},coords={x=0.468,y=0.408,source="quest_giver",zoneID=7334},questType="standard"},
[39914] = {id=39914,name="Sentinel's Final Duty",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="Now that I'm stronger, it's time to test your mettle, and mine. As I mentioned earlier, there is a powerful naga I wish to kill. His name is Fathom-Commander Eksis . He was responsible for slaying many of my kin before he retreated into hiding, commanding his troops from the shadows. I've finally discovered his whereabouts in a cave just east of here. Let us bring vengeance upon him for my lost brothers and sisters.",starts={{npcID=98159,x=0.468,y=0.408,zoneID=7334}},ends={{npcID=98159,x=0.468,y=0.408,zoneID=7334}},coords={x=0.468,y=0.408,source="quest_giver",zoneID=7334},questType="standard"},
[39916] = {id=39916,name="Turnabout Betrayal",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="Enchantress Ilanya remembers me? I made a fool's bargain ten millennia ago. I learned of the queen's alliance with the Legion and betrayed my heart to join their side. I was transformed into a monstrosity, only to die in battle against the mortals. Now the Legion returns, but I linger as an impotent spirit. Be my vessel and slay the demons ahead of us. Take their demonic runes and render them to dust.",starts={{npcID=98675,x=0.638,y=0.302,zoneID=7334}},ends={{npcID=98675,x=0.638,y=0.302,zoneID=7334}},coords={x=0.638,y=0.302,source="quest_giver",zoneID=7334},questType="standard"},
[39918] = {id=39918,name="The Absent Priestess",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="After my betrayal, I never thought I could bear to look upon my love again. But thanks to you, , I can at last return. Go and speak to Enchantress Ilanya . I will let her know that you are worthy of my mark.",starts={{npcID=98698,x=0.364,y=0.34,zoneID=7334}},ends={{npcID=107139,x=0.468,y=0.408,zoneID=7334}},coords={x=0.364,y=0.34,source="quest_giver",zoneID=7334},questType="standard"},
[39920] = {id=39920,name="On Azure Wings",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7334,description="I have some exciting news of my own to report, . Ildine and I had an excursion to Azsuna and made contact with the blue dragons at the Azurewing Repose. One of the dragons, Kharmeera , is an enchanter who expressed interest in working with you to perfect some of our enchantments. I understand you were just down there working with the elves, but if you wouldn't mind returning, Kharmeera would enjoy working with you too.",ends={{npcID=99420,x=0.472,y=0.264,zoneID=7334}},questType="standard"},
[39921] = {id=39921,name="Neltharion's Lair: Rod of Azure",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7546,description="Before we can begin though, there is a small favor I need to ask of you. I'm rather ashamed about this matter, to be honest, but it must be done in order for us to work together. When I was summoned to this land, I hadn't been given a chance to collect my things. Most importantly, I left behind my enchanting rod. Instead of retrieving it I believe it would be much simpler to reconstruct it. Here's what we'll need...",starts={{npcID=99420,x=0.472,y=0.264,zoneID=7334}},ends={{npcID=99420,x=0.472,y=0.264,zoneID=7334}},coords={x=0.472,y=0.264,source="quest_giver",zoneID=7334},questType="dungeon"},
[39923] = {id=39923,name="Down to the Core",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="The ring enchantments you know now are good, but I know of better ones that exist. That is to say, I know of stronger enchantments that would be suitable for rings. According to legend, there are four constructs whose cores were imbued with magical enchantments. These constructs now patrol the streets of Suramar City. If you were to gather some friends and defeat these constructs, you could take their cores for us to study.",starts={{npcID=99420,x=0.472,y=0.264,zoneID=7334}},ends={{npcID=99420,x=0.472,y=0.264,zoneID=7334}},coords={x=0.472,y=0.264,source="quest_giver",zoneID=7334},questType="group"},
[39931] = {id=39931,name="Smashing Herbs",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Now that the formalities are out of the way, let's have you do something actually useful. On the islands below, there's a plethora of new and exotic herbs that we've yet to experiment with. I'd like you to get some of those herbs and create some new pigments from them. Once you have enough, come back to me and I'll see what you've come up with.",questType="standard"},
[39932] = {id=39932,name="Fish Ink",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="You know, herbs aren't the only ways to obtain ink. Other materials can be inkified. Slightly related! I've been tinkering with the idea of creating my own type of Darkmoon card. Surely if those troggish carnival people can do it, then so can I. To do so, we'll need some special reagents. Go down to Azsuna and collect some oils for me, then mill them into a suitable ink.",questType="standard"},
[39933] = {id=39933,name="The Card Shark",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="We have the pigment, but we still require one more ingredient. Visitors at the Legerdemain Lounge will often play card games, and occasionally their cards are discarded. Go see if you can find some loose cards that players may have gotten rid of between matches.",questType="standard"},
[39934] = {id=39934,name="Our New Allies",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="Have you seen those demon hunters yet? I'm not entirely sold on their allegiance to our cause, but while we have them, we may as well exploit them. Everybody needs glyphs, you know. Go see what you can discover about them. Azsuna is as good a place as any to start. Perhaps my genius has worn off on you and you'll be able to create your own recipes based on what you learn.",ends={{npcID=89398,x=0.432,y=0.432,zoneID=7334}},questType="standard"},
[39935] = {id=39935,name="The Price of Power",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8625,description="You wish to learn what it is to be a demon hunter? That may take some time. The first thing you can do is fight alongside us. Battle the demons with us and observe how we use their strength against them. Return to me when you are finished.",starts={{npcID=89398,x=0.432,y=0.432,zoneID=7334}},ends={{npcID=89398,x=0.432,y=0.432,zoneID=7334}},coords={x=0.432,y=0.432,source="quest_giver",zoneID=7334},questType="standard"},
[39936] = {id=39936,name="Inscription of the Body",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="We demon hunters must keep our darkness at bay, lest we succumb to it and become demons ourselves. That is the purpose of marking our skin the way we do. Up to the north, a demon hunter by the name of Baric Stormrunner is preparing to strengthen his markings. Go to him and learn how we keep our demons at bay.",starts={{npcID=89398,x=0.432,y=0.432,zoneID=7334}},ends={{npcID=97736,x=0.54,y=0.154,zoneID=7334}},coords={x=0.432,y=0.432,source="quest_giver",zoneID=7334},questType="standard"},
[39937] = {id=39937,name="Opposites Repel",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="There's a balance that must be struck, , when becoming a demon hunter. In order to maintain that balance, we must infuse ourselves with opposite forces of nature. Fel energy is counteracted by arcane energy. We mark our bodies with arcane runes to keep our fel forces in check. You are a scribe, yes? Then you should have no trouble mixing a suitable ley pigment from the ley dust on the creatures in the ruins up ahead.",starts={{npcID=97736,x=0.54,y=0.154,zoneID=7334}},ends={{npcID=97736,x=0.54,y=0.154,zoneID=7334}},coords={x=0.54,y=0.154,source="quest_giver",zoneID=7334},questType="standard"},
[39938] = {id=39938,name="Containing the Demon Within",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="Now that we have all the essential pieces, let's begin the ritual. I'll instruct you on how to help me. It is pivotal that you follow my instructions when I give them, or the ritual will fail.",starts={{npcID=97736,x=0.54,y=0.154,zoneID=7334}},ends={{npcID=98026,x=0.54,y=0.154,zoneID=7334}},coords={x=0.54,y=0.154,source="quest_giver",zoneID=7334},questType="standard"},
[39939] = {id=39939,name="Scribal Knowledge",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="We do not simply fight the demons, . We observe them. One of my best demon hunters, Zaria Shadowheart , is currently gathering intel on the demons in Felblaze Ingress. Go to her. She will teach you what she has learned from the demons invading that region.",starts={{npcID=89398,x=0.432,y=0.432,zoneID=7334}},ends={{npcID=97734,x=0.65,y=0.258,zoneID=7334}},coords={x=0.432,y=0.432,source="quest_giver",zoneID=7334},questType="standard"},
[39940] = {id=39940,name="Runes of Power",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="Look closely, scribe, and you may learn. As the demons spread out over a region, the more clever ones will inscribe runes upon the ground. The fel taint pervades this entire hillside, but the corruption is darkest around these runes, disallowing anything pure to grow ever again. Study these runes.",starts={{npcID=97734,x=0.65,y=0.258,zoneID=7334}},ends={{npcID=97734,x=0.65,y=0.258,zoneID=7334}},coords={x=0.65,y=0.258,source="quest_giver",zoneID=7334},questType="standard"},
[39941] = {id=39941,name="Control is Key",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="We demon hunters ritualistically remove our eyes in order to see the demons more clearly. Down below, a demon commander walks amongst his troops, unseen by normal eyes. He keeps the chaos in order, as we must keep our chaos in check. Destroy his warding crystal, then slay him.",starts={{npcID=97734,x=0.65,y=0.258,zoneID=7334}},ends={{npcID=97734,x=0.65,y=0.258,zoneID=7334}},coords={x=0.65,y=0.258,source="quest_giver",zoneID=7334},questType="standard"},
[39942] = {id=39942,name="Aethrem Crystal",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Professor Pallin would be interested in seeing this.>",questType="standard"},
[39943] = {id=39943,name="The Burdens of Hunting",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="There is nothing more I have to teach you, scribe. The Illidari stand behind you in the battle against the Legion.",starts={{npcID=97734,x=0.65,y=0.258,zoneID=7334},{npcID=98026,x=0.54,y=0.154,zoneID=7334}},coords={x=0.65,y=0.258,source="quest_giver",zoneID=7334},questType="standard"},
[39944] = {id=39944,name="Mysterious Messages",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="The woman at the archaeology shop just dropped off some tablets to be deciphered. Any fool can see they're written in ancient vrykul, but I lent my codex to one of my students, so I'm unable to decipher them here. His name is Nicholo Swiftfuse , and he is in Stormheim. Let him know that if he fails to decipher them, his apprenticeship shall be terminated. That is all.",ends={{npcID=97748,x=0.692,y=0.406,zoneID=7541}},questType="standard"},
[39945] = {id=39945,name="Runes Within the Ruins",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="Unfortunately, Pallin's codex isn't complete. There are many symbols here that simply cannot be deciphered with what we've learned. Looks like we'll need to go and collect more tablets down in the area that the vrykul call Haustvald.",starts={{npcID=97748,x=0.692,y=0.406,zoneID=7541}},ends={{npcID=97748,x=0.692,y=0.406,zoneID=7541}},coords={x=0.692,y=0.406,source="quest_giver",zoneID=7541},questType="standard"},
[39946] = {id=39946,name="Right Tool for the Job",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8721,description="From what little I have been able to decipher, I know that the tablets are created using a special carving tool. If we had one of those tools, along with a complete codex, we could easily create our own tablet. That would also serve to prove that my deciphering of their language has been successful. Retrieve one of those tools for me, .",starts={{npcID=97748,x=0.692,y=0.406,zoneID=7541}},ends={{npcID=97748,x=0.692,y=0.406,zoneID=7541}},coords={x=0.692,y=0.406,source="quest_giver",zoneID=7541},questType="standard"},
[39947] = {id=39947,name="Not So Complex?",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="Alright, I believe I've finished adding the missing entries into the codex. And we have the machete... err, knife. All that's left is to make our own tablet and verify my other suspicion about these tablets: I believe that they're not just simple texts, but a sort of magical device.",starts={{npcID=97748,x=0.692,y=0.406,zoneID=7541}},ends={{npcID=97748,x=0.692,y=0.406,zoneID=7541}},coords={x=0.692,y=0.406,source="quest_giver",zoneID=7541},questType="standard"},
[39948] = {id=39948,name="The Ink Flows",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description=", I need you to make a quick delivery for me. Yes, I've learned by now that such trivial tasks are beneath your skills... but I'm rather busy right now and we both know my time is much more important than yours. Deliver these contracts to Raethan , the Guard Captain in Dalaran's Underbelly.",questType="standard"},
[39949] = {id=39949,name="Once a Scribe Like You",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="These sewers are something of a... \"settling place\" for many who can't cope with the stresses of regular Dalaran life. Take, for example, the target of this particular contract. His name is Inkrot. He was once a scribe like you, but the stresses of dealing with the Professor drove him mad. Raethan hands you the contract.> This says he's stolen a jewel from Cartier and Co. Bring me the jewel. Whatever else you find on him is yours.",questType="standard"},
[39950] = {id=39950,name="An Odd Trinket",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Wait, , before you leave... did you not notice this? Raethan peels a small piece of paper from the bottom of the jewel.> This wasn't reported stolen. It appears to be a card of some kind. Must be a scribe thing. Perhaps it may be of some use to you.",questType="standard"},
[39951] = {id=39951,name="Roseate Essence",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Professor Pallin would be interested in seeing this.>",questType="standard"},
[39952] = {id=39952,name="Sallow Essence",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Professor Pallin would be interested in seeing this.>",questType="standard"},
[39953] = {id=39953,name="Halls of Valor: Vision of Valor",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7672,description="I think it's time for another field trip, . To the Halls of Valor! The Valarjar are masters of all types of runecraft. Perhaps we can find something useful for a new recipe.",questType="dungeon"},
[39954] = {id=39954,name="Mass Milling Techniques",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="A number of my previous students have been vocal in their displeasure regarding milling. They find the process \"repetitive\", \"mindless\", and even \"painful\". Have they no respect for the time-honored traditions of inscription? I suppose you count yourself among their number. Am I right? Very well. You've been a fine student so far, so I suppose there's no harm. I have a book about mass milling somewhere around the shop here. Find it, and it's yours.",questType="standard"},
[39955] = {id=39955,name="The Plot Thickens",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=1537,description="Very well, I won't deny it. The Steamy Romance Novel is mine. I only read it for the penmanship, I assure you! He writes such curvy \"B\"s... and such ample \"D\"s! In fact... you might benefit from a penmanship lesson. The author of these books is one B. Spearshaker. I believe he can be found in the library in Ironforge. Stop reading, student. You are dismissed. And give me my book back!",ends={{npcID=97762,x=0.766,y=0.088,zoneID=1537}},questType="standard"},
[39957] = {id=39957,name="Demon Ink",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,description="These sigils would make for a fantastic new tarot card. Quite powerful, in fact. We simply require an ink sturdy enough to inscribe them. Fortunately, I have students like you that excel at fetching hard-to-get items. For this project, I require ink mixed from demonic blood. The blood of the demons at Felsoul Hold will serve as a suitable base. You will also need Blood of Sargeras, of course.",questType="standard"},
[39958] = {id=39958,name="Skin Deep",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Welcome, . It's an honor to be working with someone of your caliber. In order for us to begin our work together, we'll first need to collect some materials. The Broken Isles are home to many strange, exotic creatures which no doubt have interesting hides to experiment with. We'll need scales to make mail armor with as well. Go and collect some materials for us so we may begin working.",questType="standard"},
[39959] = {id=39959,name="The Plot Thickens",level=10,requiredLevel=10,faction="horde",expansion=6,zoneID=1497,description="Very well, I won't deny it. The Steamy Romance Novel is mine. I only read it for the penmanship, I assure you! He writes such curvy \"B\"s... and such ample \"D\"s! In fact... you might benefit from a penmanship lesson. The author of these books is one F. Serbacon. I believe he can be found in the library in Undercity. Stop reading, student. You are dismissed. And give me my book back!",ends={{npcID=97766,x=0.778,y=0.388,zoneID=1497}},questType="standard"},
[39960] = {id=39960,name="The Legacy Passed On",level=10,requiredLevel=10,faction="horde",expansion=6,zoneID=1497,description="I've lost my passion, scribe. I just can't find the voice of my characters anymore. Take a look at that unfinished book over there on the table. I can't seem to finish it. Maybe you'll have an easier time with it.",starts={{npcID=97766,x=0.778,y=0.388,zoneID=1497}},ends={{npcID=97766,x=0.778,y=0.388,zoneID=1497}},coords={x=0.778,y=0.388,source="quest_giver",zoneID=1497},questType="standard"},
[39961] = {id=39961,name="An Embarrassing Revelation",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="This doesn't appear to be an inscription textbook at all... it's more of a steamy romance novel . The pages are just FILLED with tawdry tales of carnality. Could it have something to do with inscription? Either way, Professor Pallin should be confronted.",questType="standard"},
[39962] = {id=39962,name="Trouble for Okuna",level=10,requiredLevel=10,faction="none",expansion=6,zoneID=8040,mapID=630,description="Help! I need somebody... but not just anybody. I need a champion! I finally escaped the grasp of Prince Oceanus only to be hunted by his father, King Deepbeard. I was enjoying my freedom and decided to go fishing when that giant attacked. I've been running around these islands trying to avoid that creature ever since... if anyone gets this message, please send help!",questType="dungeon"},
[39964] = {id=39964,name="Pinerock Basin Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39965] = {id=39965,name="Sylvan Falls Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39966] = {id=39966,name="Riverbend Treasure",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39967] = {id=39967,name="Thunder Totem Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39968] = {id=39968,name="Thunder Totem Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39969] = {id=39969,name="Kill Azshara",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=8040,mapID=630,description="xxxxx",questType="standard"},
[39983] = {id=39983,name="Huln's War - The Arrival",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7838,description="Huln Highmountain is the origin of our strength as a tribe. He bested the Legion when last they threatened our survival and unified many disparate tribes. Live his story, and you will know why his name imbues courage in the cowardly and sows fear in the fearless.",starts={{npcID=98825,x=0.512,y=0.546,zoneID=7731}},ends={{npcID=97891,x=0.294,y=0.392,zoneID=7838}},coords={x=0.512,y=0.546,source="quest_giver",zoneID=7731},questType="standard"},
[39984] = {id=39984,name="Remnants of the Past",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="I do not know what has become of my village. Ever since the mists engulfed the harbor, my kinsfolk have changed. Some have grown violent and savage, while others have fallen into madness. Many have ventured into the mists and have yet to return. In these times, we can usually turn to our leader, Jarl Tarben. Alas, the mists have taken him as well. I do not know what will become of me. For now, I can only stay at my post and remain vigilant.",starts={{npcID=244708,x=0.63,y=0.487,zoneID=7541}},ends={{npcID=97973,x=0.59,y=0.428,zoneID=7541}},coords={x=0.63,y=0.487,source="quest_giver",zoneID=7541},questType="standard"},
[39985] = {id=39985,name="Khadgar's Discovery",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,description="Champion! Please come to the Violet Citadel immediately. I have made a discovery that I would like to share with you before the Council of Six.",questType="standard"},
[39986] = {id=39986,name="Magic Message",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,description="For the last 10,000 years, the elven city of Suramar has been sealed in an arcane barrier, much like Dalaran once was. That barrier has come down. Since then, waves of magical energy have been emanating from the city like ripples in a pond. It was in these waves that I sensed a pattern. A spell, encrypted among the chaos. I have recreated the spell here. It's not dangerous, but beyond that... I have no idea what it does!",questType="standard"},
[39987] = {id=39987,name="Trail of Echoes",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="The Nightborne could prove powerful allies against the Legion. We must aid this Thalyssra if we can. We should be able to find her by tracking her magical echoes, the same way I found her distress call. I can teleport you near the location where she recorded that message. From there, you must search for ripples in the very fabric of the arcane itself. My wand should do the trick. Follow the sparks it creates--they should lead you to places where Thalyssra used her magic.",ends={{npcID=98312,x=0.346,y=0.534,zoneID=7637}},questType="standard"},
[39988] = {id=39988,name="Huln's War - Stormrage",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7838,description="Eche'ro nuzzles your hand and turns around. It looks back, beckoning you to the south.>",starts={{npcID=98794,x=0.28,y=0.472,zoneID=7838}},ends={{npcID=97892,x=0.278,y=0.518,zoneID=7838}},coords={x=0.28,y=0.472,source="quest_giver",zoneID=7838},questType="standard"},
[39989] = {id=39989,name="Keepers of the Hammer",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,description="High Chieftain Ulan has requested your presence. We have learned that the Burning Legion has returned and know that if you are true in your purpose in facing this evil, you will need our aid. Our people have in our possession a great titan relic: the Hammer of Khaz'goroth. We intend to lend it to you for this task. When you are ready, join me at our stronghold of Thunder Totem in Highmountain .",questType="standard"},
[39990] = {id=39990,name="Huln's War - Reinforcements",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7838,description="Cenarius himself has risked much in coming here, if only briefly, to bestow a blessing upon you. He has seen what you are capable of, and has chosen you as champion in this battle. I would speak with you on this later. It is a rare gift indeed. But now, I ask for your help, Huln Highmountain . I must finish my incantations to allow dryads from beyond the veil to enter this place and lend us their aid.",starts={{npcID=97892,x=0.278,y=0.518,zoneID=7838}},ends={{npcID=97892,x=0.278,y=0.518,zoneID=7838}},coords={x=0.278,y=0.518,source="quest_giver",zoneID=7838},questType="standard"},
[39991] = {id=39991,name="Blessing of Cenarius",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39992] = {id=39992,name="Huln's War - The Nathrezim",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="I am fully occupied here organizing my troops and planning for the battle to come. While I would like to slay the Dreadlord Tichondrius myself, I will allow that honor to be yours, Huln Highmountain .",starts={{npcID=97903,x=0.312,y=0.524,zoneID=7838}},ends={{npcID=98825,x=0.512,y=0.546,zoneID=7731}},coords={x=0.312,y=0.524,source="quest_giver",zoneID=7838},questType="standard"},
[39994] = {id=39994,name="Crab Rider Grmlrml",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39995] = {id=39995,name="Rockaway Coast Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39996] = {id=39996,name="Rockaway Coast Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39997] = {id=39997,name="Rockaway Coast Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[39999] = {id=39999,name="Rockaway Coast Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40000] = {id=40000,name="A True Hunter",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="I don't know why Hemet hunts with Razik. His contraptions are unreliable at best! A true hunter doesn't need gadgets to hunt. They rely on instinct, skill, and agility. So tell me, , do you have the skills of a true hunter? Better yet, prove it. Take down some of the Bonebeak Hawks that circle the nearby meadow.",starts={{npcID=97974,x=0.576,y=0.564,zoneID=7503}},ends={{npcID=97974,x=0.576,y=0.564,zoneID=7503}},coords={x=0.576,y=0.564,source="quest_giver",zoneID=7503},questType="standard"},
[40001] = {id=40001,name="Knocking on Valor's Door",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="The Halls of Valor is your destiny to claim, but it is already in the claiming. The God-King befouls its steps with demons and wickedness. Your dragon allies have come to Halls' defense, but they need your aid. The vrykul have taken the leader of the storm dragons, the one you call Vethir . Free your dragon friend, champion, and wash the Felskorn from the Gates of Valor!",starts={{npcID=92539,x=0.602,y=0.508,zoneID=7541}},ends={{npcID=97979,x=0.658,y=0.594,zoneID=7541}},coords={x=0.602,y=0.508,source="quest_giver",zoneID=7541},questType="standard"},
[40002] = {id=40002,name="A Familiar Fate",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="We had come to defend the Halls of Valor... I was taken from the sky... I cannot break free of my bindings. Find the jailer who made this cell... Set me free, friend...",starts={{npcID=97979,x=0.658,y=0.594,zoneID=7541}},ends={{npcID=97979,x=0.658,y=0.594,zoneID=7541}},coords={x=0.658,y=0.594,source="quest_giver",zoneID=7541},questType="standard"},
[40003] = {id=40003,name="Stem the Tide",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="Skovald has profaned the Gates of Valor with his demonic allies. Among his forces his twisted mystics have conjured portals to ferry his fel allies from their blighted worlds. If we wish to stem this tide, these portals must be destroyed. I will gather my allies. Take this horn and signal when you have found a portal, and we will strike from the skies!",starts={{npcID=97979,x=0.658,y=0.594,zoneID=7541}},ends={{npcID=97986,x=0.702,y=0.694,zoneID=7541}},coords={x=0.658,y=0.594,source="quest_giver",zoneID=7541},questType="standard"},
[40004] = {id=40004,name="Break the Spine",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="To lead his tainted forces, the God-King has enlisted demons of great power to act as his lieutenants. If we wish to end his assault, we will need to take their leaders. These demons are too powerful for most mortals to face, but with the power of Stormheim at your disposal, they will prove no match for you. Take them down, and shatter the spine of Skovald's offensive!",starts={{npcID=97979,x=0.658,y=0.594,zoneID=7541}},ends={{npcID=97986,x=0.702,y=0.694,zoneID=7541}},coords={x=0.658,y=0.594,source="quest_giver",zoneID=7541},questType="standard"},
[40005] = {id=40005,name="Stormheim's Salvation",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="It would seem that the portals we destroyed down here were not the only ones. Demons still pour in from the top of the Gates of Valor's edifice, summoned by the God-King himself! I cannot face Skovald alone. Come, champion, let us take the battle to him and end this threat! For Stormheim !",starts={{npcID=97986,x=0.702,y=0.694,zoneID=7541}},ends={{npcID=97988,x=0.702,y=0.692,zoneID=7541}},coords={x=0.702,y=0.694,source="quest_giver",zoneID=7541},questType="standard"},
[40006] = {id=40006,name="Sylvan Falls Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40007] = {id=40007,name="Fields of An'she Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40008] = {id=40008,name="The Only Way Out is Through",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="I have much to tell you, but it is not safe to speak here. I cannot hold this barrier forever. If we push through, we may find shelter up ahead.",starts={{npcID=98312,x=0.346,y=0.534,zoneID=7637}},ends={{npcID=98312,x=0.346,y=0.534,zoneID=7637}},coords={x=0.346,y=0.534,source="quest_giver",zoneID=7637},questType="standard"},
[40009] = {id=40009,name="Arcane Thirst",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="My people have subsisted on the Nightwell for millennia. Ancient mana is our lifeblood - without it, we become... well, you saw them out there. I'm afraid I have been rather reckless today. Already, my senses are dulling. Without magic to feed upon, I will turn. Please... find me something to feed upon... anything...",starts={{npcID=98312,x=0.346,y=0.534,zoneID=7637}},ends={{npcID=98312,x=0.346,y=0.534,zoneID=7637}},coords={x=0.346,y=0.534,source="quest_giver",zoneID=7637},questType="standard"},
[40010] = {id=40010,name="Tapping the Leylines",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="The arcways were built to tap into the magical leylines beneath Suramar . As we learned to subsist on the Nightwell, the old facilities fell out of use. This chamber is clearly receiving power from elsewhere. There is only a trickle now, but if you can direct more leyline energy here it will help to sustain us. The closest source is to the north, near Anora Hollow.",starts={{npcID=97140,x=0.368,y=0.466,zoneID=7637}},ends={{npcID=102600,x=0.416,y=0.39,zoneID=7637}},coords={x=0.368,y=0.466,source="quest_giver",zoneID=7637},questType="standard"},
[40011] = {id=40011,name="Oculeth's Workshop",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="We need to make contact with Chief Telemancer Oculeth , the man who developed Suramar 's teleportation network. Oculeth had a workshop in old Suramar , from the age before the Sundering. He may be taking refuge there. If you find him, show him this. Hopefully you see him before he sees you...",starts={{npcID=97140,x=0.368,y=0.466,zoneID=7637}},ends={{npcID=101499,x=0.492,y=0.47,zoneID=7637}},coords={x=0.368,y=0.466,source="quest_giver",zoneID=7637},questType="standard"},
[40012] = {id=40012,name="An Old Ally",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="I was on my way to Ambervale in hopes of finding an old colleague. Arcanist Kel'danath was fascinated by the withered. He studied them for years hoping to calm their feral nature or even cure them. When one of his subjects escaped and ran amok in the royal gardens, Kel'danath was ordered to cease his research and kill all withered in his possession. He refused, and was exiled. If Kel'danath lives, he is near withered. And withered are drawn to old settlements like Ambervale.",starts={{npcID=97140,x=0.368,y=0.466,zoneID=7637}},ends={{npcID=245328,x=0.303,y=0.397,zoneID=7637}},coords={x=0.368,y=0.466,source="quest_giver",zoneID=7637},questType="standard"},
[40013] = {id=40013,name="Aethril Sample",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="This herb has clearly been absorbing magical energy from the land. Filaments of ley energy course from root to leaf. Your herbalism trainer in Dalaran will want to see this.",questType="standard"},
[40014] = {id=40014,name="Spayed by the Spade",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="The stem, leaves, and petals are dazzling, to be certain... but look at the pollination filaments, here, and the reproductive organs in the center of the bloom. They contain more energy than the rest of the plant put together. I suspect that we can more responsibly and efficiently harvest aethril by focusing on these parts. Still, it looks like this bloom has been damaged. I need undamaged parts if I'm to be sure.",questType="standard"},
[40015] = {id=40015,name="Ragged Strips of Silk",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Finely made strips of clothing, torn, tattered, and dirty: telltale signs of the withered. The feral, degenerate outcasts of nightborne society must also be harvesting the aethril... but why?",questType="standard"},
[40016] = {id=40016,name="Desperation Breeds Ingenuity",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="I believe we may be able to use this clue to our advantage, . The withered are notoriously thirsty for mana, and will stop at nothing to get it. Perhaps we can study how they use the aethril and use the results to improve our own harvesting methods.",questType="standard"},
[40017] = {id=40017,name="A Slip of the Hand",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="As you harvest the aethril, your hand brushes the flower's pollinating organs against one another, creating a reaction. You may have discovered a new herbalism technique. Your trainer in Dalaran would be a good person to discuss this with.",questType="standard"},
[40018] = {id=40018,name="Dreamleaf Sample",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="The herb is brilliantly green, paper-thin, and somewhat sticky. Your herbalism trainer in Dalaran will want to see this.",questType="standard"},
[40019] = {id=40019,name="An Empathetic Herb",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Something is different about this dreamleaf, though. It is less than pure. I have a theory. The wilds of Val'sharah have been blighted by a nightmarish curse. Sensitive herbs like this may be susceptible to such a blight. I need more information before I can draw any conclusions. Find me some healthy samples and some blight-infested samples, and we can continue.",questType="standard"},
[40020] = {id=40020,name="Twisted to Death",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="The corruption has completely taken this herb. This blight is a mysterious force whose complexities transcend the teachings of simple herbalism. An expert in such infestation will need to tell you what's really going on here.",ends={{npcID=98135,x=0.548,y=0.718,zoneID=7558}},questType="standard"},
[40021] = {id=40021,name="One Dead Plant is One Too Many",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="We must exact VENGEANCE for this. While I understand the importance of the balance between the Emerald Dream and the Nightmare, this time it's corruption has gone TOO FAR! Satyrs. I blame the satyrs for this. Make them pay! Make them pay, and Elune will reward you with her bounty!",questType="standard"},
[40022] = {id=40022,name="Choked by Nightmare",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="Another plant, killed by the blight. This one coiled so hard that it starved itself of sunlight. You should bring it to Wildcrafter Osme in Lorlathil. He won't be happy.",ends={{npcID=98135,x=0.548,y=0.718,zoneID=7558}},questType="standard"},
[40023] = {id=40023,name="The Last Straw",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="We cannot falter in our crusade against this corruption, . It is our duty as heroes. As herbalists. As hero-balists. Slaying simple satyrs will not do. We must attack their leaders. Bring this fallen herb to Shala'nir, in the northeast. Find Tur'xoran 's summoning stone, and place this herb in front of it. Then... rip off his head. Do it for the plants.",starts={{npcID=98135,x=0.548,y=0.718,zoneID=7558}},ends={{npcID=98135,x=0.548,y=0.718,zoneID=7558}},coords={x=0.548,y=0.718,source="quest_giver",zoneID=7558},questType="group"},
[40024] = {id=40024,name="Foxflower Sample",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Something about this herb catches your eye... and your nose. Your herbalism trainer in Dalaran would certainly be interested in studying some samples of this piquant new flower.",questType="standard"},
[40025] = {id=40025,name="Teeny Bite Marks",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="This herb has been chewed by some of the local wildlife. What kind of animal would eat foxflower? A bear? Perhaps your trainer in Dalaran will know.",questType="standard"},
[40026] = {id=40026,name="Chase the Culprit",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="This is a powerful herb, . Creatures will occasionally snack on some simpler herbs, but usually they avoid plants of such potency. I'm intrigued. What kind of animal would eat foxflower? A moose? You should investigate further. Find out what creature has been snacking on foxflower, and then see if you can wrestle some of the flowers from its mouth, before it escapes.",questType="standard"},
[40028] = {id=40028,name="The Pied Picker",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="As you finish gathering the foxflower, a particular part of the bloom catches your eye. One of the leaves has a small protuberance, right where it meets the stem. Further investigation suggests that this is where the foxflower's unusual smell comes from. Your herbalism trainer would be interested in seeing this.",questType="standard"},
[40029] = {id=40029,name="Fjarnskaggl Sample",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="To one not trained in herbalism, this brambly bush might appear to be entirely useless. Your training, however, reveals this to be a very special plant indeed. Your herbalism trainer in Dalaran will want to see some more samples of this.",questType="standard"},
[40030] = {id=40030,name="Ram's-Horn Trowel",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="The rune markings along the tool's grip suggest that it was left behind by a vrykul herbalist. Apparently, the vrykul are also gathering this fjarnskaggl. Your trainer, Kuhuine, mentioned that she had read about this herb in the past. Perhaps she might be interested in seeing the tools that the vrykul use to harvest it.",questType="standard"},
[40031] = {id=40031,name="Vrykul Herblore",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="This is a standard digging tool. There is not much to be learned here, except... ...this DOES suggest that the vrykul are still actively gathering this herb. The vrykul likely know much more about this herb than we do. All we need to do is find out where their knowledge is stored.",questType="standard"},
[40032] = {id=40032,name="The Missing Page",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="\"...the Cairn of the Sea, a place long-known to be beloved by the gods. He placed his offering of fjarnskaggl at the foot of the cairn, mouthed the words 'Herbs beget herbs', and received the blessing he desired.\" This may be related to the books you brought back to your herbalism trainer.",questType="standard"},
[40033] = {id=40033,name="Fjarnskaggl",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="There! It seems that there was a vrykul herbalist, Torgus , who brought a gift of fjarnskaggl to a seaside cairn - presumably in Stormheim - and by doing so received a blessing from his ancestors. It's worth a shot, though without knowing what you're getting into, you may want to bring friends with you.",questType="group"},
[40034] = {id=40034,name="Starlight Rosedust",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Despite all your training, the rose disintegrated in your hand. Your herbalism trainer in Dalaran will want to see this.",questType="standard"},
[40035] = {id=40035,name="The Gentlest Touch",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Sadly, I don't have any special techniques that can help you here. You'll simply need to practice your methods. Get back out there, and focus on a gentle touch when dealing with starlight roses.",questType="standard"},
[40036] = {id=40036,name="Jeweled Spade Handle",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="An immaculately carved spade handle lies beside the rose. Apparently the spade was more beautiful than it was durable, as the blade has completely fallen off. Your herbalism trainer may be interested in seeing this.",questType="standard"},
[40037] = {id=40037,name="The Spade's Blade",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Did you notice the script along the base of the handle, ? It says \"Herbalist Tharillon,\" in the writing of the nightborne. The handle does little for us, but perhaps the blade of this spade will give us some information on how to harvest the starlight rose without failing quite so often. I would start my search for it in Suramar.",questType="standard"},
[40038] = {id=40038,name="Insane Ramblings",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Scribbled, angry phrases on a dirty scrap of vellum. One part catches your eye: \"thinks knows how to gather herbs steal my blade slit THROAT when I just need a bit more mana maybe aethril, yes...\" Your herbalism trainer may be interested in seeing this.",questType="standard"},
[40039] = {id=40039,name="Tharillon's Fall",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="He mentions your name... his blade... aethril... I'd say that this is absolutely from Herbalist Tharillon, and by the look of it, he may have succumbed to the plight of the nightfallen. Furthermore, if he's looking for aethril, he's probably in Azsuna somewhere. Tharillon is currently our only hope for learning more about starlight roses. Seek him out, but you may want to bring friends... he likely won't go without a fight.",questType="group"},
[40040] = {id=40040,name="Felwort Sample",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="This herb bubbles and seethes with a foul energy. It is smooth, dry, and cool, yet somehow quite painful to touch. Your herbalism trainer in Dalaran will want to see this.",questType="standard"},
[40041] = {id=40041,name="Felwort Analysis",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="I sent felwort samples to some of my fellow herbalists, but haven't heard back from them yet. Could you please follow up with them and collect their analyses. Ryno Bloomfield is currently working in Un'goro Crater. Dani Earthtouch is researching Freya's influence in Sholazar Basin. Finally, Lohor has been working in the overgrown portion of Gorgrond.",questType="standard"},
[40042] = {id=40042,name="The Emerald Nightmare: Felwort Mastery",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8026,description="I have a theory on how we can better harvest this felwort, . You see, sometimes in order to understand how something comes into being, you have to work backwards. I've recently heard of the corruption of one of our greatest gods, Cenarius. I have no doubt the same corruption that lives in these herbs also resides within him now. If you were able to cleanse that corruption, find a way to understand how it works and remove it, I think we can apply that to how we harvest these herbs.",questType="raid"},
[40043] = {id=40043,name="The Hunter of Heroes",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7813,description="Helya has made a mockery of my order by creating her own \"helarjar\", powerful undead tasked with hunting down heroic warriors and taking their souls before my val'kyr can claim them. Among them is her personal champion, Vigfus Bladewind, who wields stolen blades I forged myself long ago. He has returned to Tideskorn Harbor with a full cargo of stolen souls to take to Helheim. Go there, kill him and his helarjar, and make the swords yours.",questType="standard"},
[40044] = {id=40044,name="Shadows in the Mists",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="Many of the Kvaldir here in the bay are former denizens of this harbor, cursed by the sea-witch Helya to do her bidding for all time. The ones you read about, they still walk the stagnant waters. They could be given respite, should a kind soul bring it to them at the tip of a blade. So tell me, how kind is your soul?",starts={{npcID=97973,x=0.59,y=0.428,zoneID=7541}},ends={{npcID=97973,x=0.59,y=0.428,zoneID=7541}},coords={x=0.59,y=0.428,source="quest_giver",zoneID=7541},questType="standard"},
[40045] = {id=40045,name="Nature vs. Nurture",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="I appreciate murloc-kind far too much to tell you to go kill all the adults. What we should be doing is setting up the next generation to be more peaceful; Murky is the best representative for this. Bring him to talk to the murloc tadpoles. He'll get them on our side.",starts={{npcID=98067,x=0.426,y=0.108,zoneID=7503}},ends={{npcID=98067,x=0.426,y=0.108,zoneID=7503}},coords={x=0.426,y=0.108,source="quest_giver",zoneID=7503},questType="standard"},
[40046] = {id=40046,name="Scavenging the Shallows",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="The kvaldir exist to spite Odyn, and it is here their spiteful work is done. They rob the souls of the living - the souls not yet judged - thus robbing Odyn of his champions. They bring them here to transport to Helya, though the mists obscure any indications of how. You seem to fare the mists well. Perhaps if you search the wreckage in the bay, the answer may present itself. You outsiders seem to have a knack for uncovering the most hidden of secrets.",starts={{npcID=97973,x=0.59,y=0.428,zoneID=7541}},ends={{npcID=97973,x=0.59,y=0.428,zoneID=7541}},coords={x=0.59,y=0.428,source="quest_giver",zoneID=7541},questType="standard"},
[40047] = {id=40047,name="I'll Huff, I'll Puff...",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Murky is my favorite little fella. However, in order to lead a change in the murloc population here, he needs some awesome abilities. There are a lot of pufferfish around in the water, and I think that they could be a good resource for him. Kill a few and collect their eggs for Murky.",starts={{npcID=98067,x=0.426,y=0.108,zoneID=7503}},ends={{npcID=98067,x=0.426,y=0.108,zoneID=7503}},coords={x=0.426,y=0.108,source="quest_giver",zoneID=7503},questType="standard"},
[40048] = {id=40048,name="Strings of the Puppet Masters",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="I understand you were just here to deliver the vellums, but we could use your skills as a . Our forces can only hold back the demon invasion, disallowing us to send anyone further into the enemy's camp. The stronger of their forces stay in the back, commanding from a distance. They carry enchanted runes to keep control over the frontline demons. I would very much like to study one of these runes. Please retrieve one for me, so we may learn from it and use it against the Legion.",starts={{npcID=90317,x=0.432,y=0.436,zoneID=7334}},ends={{npcID=90317,x=0.432,y=0.436,zoneID=7334}},coords={x=0.432,y=0.436,source="quest_giver",zoneID=7334},questType="standard"},
[40049] = {id=40049,name="Slime Time",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Murky's a growing boy, he needs to eat! What better than slimeweed for a young murloc? There's plenty of it around in the water amongst the murlocs; swim through it and feed Murky!",starts={{npcID=98067,x=0.426,y=0.108,zoneID=7503}},ends={{npcID=98067,x=0.426,y=0.108,zoneID=7503}},coords={x=0.426,y=0.108,source="quest_giver",zoneID=7503},questType="standard"},
[40051] = {id=40051,name="Fel Secrets",level=8,requiredLevel=8,faction="both",expansion=6,zoneID=7705,description="The demons made a grave error inscribing their secrets into this book. The fel energy emanating from it is potent. But there's only enough to enact one of the rituals. After that, the book will be consumed. It's up to you to choose which secrets we want to use against the Burning Legion.",starts={{npcID=99045,x=0.604,y=0.448,zoneID=7705}},ends={{npcID=93127,x=0.604,y=0.448,zoneID=7705}},coords={x=0.604,y=0.448,source="quest_giver",zoneID=7705},questType="standard"},
[40052] = {id=40052,name="Ancient Vrykul Mastered",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Here are those tablets back, along with their deciphered writing. You can take this codex back to Pallin, too. I'll start getting my things ready for when he calls me back to Dalaran. Learn from my example, . If I were you, I'd break free from Pallin's \"requests\" as soon as you can.",starts={{npcID=97748,x=0.692,y=0.406,zoneID=7541}},coords={x=0.692,y=0.406,source="quest_giver",zoneID=7541},questType="standard"},
[40056] = {id=40056,name="Our New Allies",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="Student! Your fellow demon hunters in Azsuna have sent for you. I can certainly appreciate your time being spent fending off the Legion, but it doesn't excuse you from your studies. While you're down there, I'd like you to come up with some new glyphs for your abilities. Surely my genius has worn off on you and you'll be able to create your own recipes based on what you learn.",ends={{npcID=89398,x=0.432,y=0.432,zoneID=7334}},questType="standard"},
[40057] = {id=40057,name="The Price of Power",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8625,description="I see, you wish to augment your powers through script. I believe we can kill two birds with one stone then. I need help here reducing the demon threat. Perhaps some more engagement with our enemy will inspire you.",starts={{npcID=89398,x=0.432,y=0.432,zoneID=7334}},ends={{npcID=89398,x=0.432,y=0.432,zoneID=7334}},coords={x=0.432,y=0.432,source="quest_giver",zoneID=7334},questType="standard"},
[40058] = {id=40058,name="Defense Symbology",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="As you know, , we demon hunters must keep our darkness at bay, lest we succumb to it and become demons ourselves. Up to the north, a demon hunter by the name of Baric Stormrunner is preparing to strengthen his markings. He could use your assistance with his ritual.",starts={{npcID=89398,x=0.432,y=0.432,zoneID=7334}},ends={{npcID=97736,x=0.54,y=0.154,zoneID=7334}},coords={x=0.432,y=0.432,source="quest_giver",zoneID=7334},questType="standard"},
[40059] = {id=40059,name="Opposites Repel",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="The ruins nearby have had an eruption of ley energies. Twisted night elves deemed \"Nightfallen\" are scavenging the area as we speak. Collect ley dust for me from the nightfallen in the ruins up ahead. The dust is infused with arcane energy that I'll need to complete my ritual.",starts={{npcID=97736,x=0.54,y=0.154,zoneID=7334}},ends={{npcID=97736,x=0.54,y=0.154,zoneID=7334}},coords={x=0.54,y=0.154,source="quest_giver",zoneID=7334},questType="standard"},
[40060] = {id=40060,name="Containing the Demon Within",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="Now that we have all the essential pieces, let's begin the ritual. I'll instruct you on how to help me throughout it. It is pivotal that you follow my instructions when I give them, or the ritual will fail.",starts={{npcID=97736,x=0.54,y=0.154,zoneID=7334}},ends={{npcID=98026,x=0.54,y=0.154,zoneID=7334}},coords={x=0.54,y=0.154,source="quest_giver",zoneID=7334},questType="standard"},
[40061] = {id=40061,name="To Know Your Enemy",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="As we fight the demons, we've also been studying them. Great understanding can come from gathering intel. I have a demon hunter near the Felblaze Ingress now gathering intel on the demons there. Go to her and see what she has learned from the demons invading that region.",starts={{npcID=89398,x=0.432,y=0.432,zoneID=7334}},ends={{npcID=97734,x=0.65,y=0.258,zoneID=7334}},coords={x=0.432,y=0.432,source="quest_giver",zoneID=7334},questType="standard"},
[40062] = {id=40062,name="Bulging Nightmare Pod",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Professor Pallin would be interested in seeing this.>",questType="standard"},
[40063] = {id=40063,name="Control is Key",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="I trust you remember why you removed your eyes? Even though we can see more clearly now, the demons have found ways to mask even their fel energies from us. A demon commander walks amongst the troops below, commanding them from the shadows. His cloak is powered by an energetic crystal. Find and destroy that crystal, then kill the commander.",starts={{npcID=97734,x=0.65,y=0.258,zoneID=7334}},ends={{npcID=97734,x=0.65,y=0.258,zoneID=7334}},coords={x=0.65,y=0.258,source="quest_giver",zoneID=7334},questType="standard"},
[40064] = {id=40064,name="Woody Seed Cluster",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Professor Pallin would be interested in seeing this.>",questType="standard"},
[40065] = {id=40065,name="Fjarnsk",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Professor Pallin would be interested in seeing this.>",questType="standard"},
[40066] = {id=40066,name="7.0 Stormheim - Treasure 032 - Blackbeak Overlook - twh",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7541,mapID=634,questType="standard"},
[40067] = {id=40067,name="7.0 Stormheim - Vignette: Boulderfall - twh",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7541,mapID=634,questType="standard"},
[40068] = {id=40068,name="7.0 Stormheim - Vignette: Egyl the Enduring - twh",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7541,mapID=634,questType="standard"},
[40069] = {id=40069,name="Fledgling Worm Guts",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="The drogbar use these caves as a place to train fledgling worms. The rockcrawlers are young and fairly weak, for now, but in time they will grow in size and strength. Without our intervention, the worms will morph into the monstrosities that the drogbar ride into battle. Their guts are also known to be quite useful, and I have need of them. Two worms, one stone.",starts={{npcID=94068,x=0.508,y=0.366,zoneID=7503}},ends={{npcID=94068,x=0.508,y=0.366,zoneID=7503}},coords={x=0.508,y=0.366,source="quest_giver",zoneID=7503},questType="standard"},
[40070] = {id=40070,name="Eagle Egg Recovery",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Eagles are revered by the Skyhorn tribe, but their numbers are dwindling. The drogbar feed their fledgling worms eagle eggs so they'll grow strong enough to ride into battle. If the drogbar continue to pilfer these eggs, the eagles may become extinct. Head deeper into the cave and recover any eagle eggs you can find.",starts={{npcID=94068,x=0.508,y=0.366,zoneID=7503}},ends={{npcID=94068,x=0.508,y=0.366,zoneID=7503}},coords={x=0.508,y=0.366,source="quest_giver",zoneID=7503},questType="standard"},
[40071] = {id=40071,name="Tamer Takedown",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="The drogbar will continue to breed vicious worms as long as their tamer lives. Korgrul is responsible for turning fledgling rockcrawlers into the monstrous siege worms that are ridden into battle. Head deep into the chasm and end his life, so that we may also see the end of these unnatural creatures.",starts={{npcID=94068,x=0.508,y=0.366,zoneID=7503}},ends={{npcID=94068,x=0.508,y=0.366,zoneID=7503}},coords={x=0.508,y=0.366,source="quest_giver",zoneID=7503},questType="standard"},
[40072] = {id=40072,name="Halls of Valor: Securing the Aegis",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7672,description="The Felskorn may be broken, but the head of the beast yet lives. The God-King will still vie for the Aegis if left unchecked. You, who have completed trials upon trials, must not let this come to pass. You must claim the Aegis over Skovald's broken bones! The Halls of Valor await!",starts={{npcID=97988,x=0.702,y=0.692,zoneID=7541}},coords={x=0.702,y=0.692,source="quest_giver",zoneID=7541},questType="dungeon"},
[40077] = {id=40077,name="The Invasion Begins",level=8,requiredLevel=8,faction="both",expansion=6,zoneID=7705,description="Our advance force of demon hunters is here and has engaged the Legion. Make our presence known. Let's send a shiver down every demon spine. Raise our colors with pride, .",starts={{npcID=93011,x=0.22,y=0.558,zoneID=7705}},ends={{npcID=98229,x=0.286,y=0.63,zoneID=7705}},coords={x=0.22,y=0.558,source="quest_giver",zoneID=7705},questType="standard"},
[40078] = {id=40078,name="A Heavy Burden",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="With Ashildir's judgment, your final trial is complete. But even Valhallas can wait, for now we must eat! Being dead works up quite an appetite. Come now, bring some of that fish to roast over the fire. It is far too heavy for me to carry.",starts={{npcID=92539,x=0.602,y=0.508,zoneID=7541}},ends={{npcID=92539,x=0.602,y=0.508,zoneID=7541}},coords={x=0.602,y=0.508,source="quest_giver",zoneID=7541},questType="standard"},
[40081] = {id=40081,name="7.0 Stormheim - Vignette: Tarben - twh",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7541,mapID=634,questType="standard"},
[40082] = {id=40082,name="7.0 Stormheim - Treasure 033 - Helmouth Shallows - twh",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7541,mapID=634,questType="standard"},
