[40094] = {id=40094,name="7.0 Stormheim - Treasure 042 - Tideskorn Harbor - twh",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7541,mapID=634,questType="standard"},
[40095] = {id=40095,name="7.0 Stormheim - Treasure 043 - Helmouth Shallows - twh",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7541,mapID=634,questType="standard"},
[40097] = {id=40097,name="7.0 Stormheim - Vignette: Sunbreeze - twh",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7541,mapID=634,questType="standard"},
[40099] = {id=40099,name="7.0 Stormheim - Treasure 044 - Tideskorn Harbor - twh",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7541,mapID=634,questType="standard"},
[40100] = {id=40100,name="7.0 Stormheim - Vignette: Eileen the Raven - twh",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7541,mapID=634,questType="standard"},
[40102] = {id=40102,name="Murlocs: The Next Generation",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="The time has come! Murky and his followers need a place to hide out and train--away from the mature murlocs--so that they can prepare to take over in the future. There's a nice cave not too far away... only problem is that it's filled with makrura. This would be a good base for the tadpoles. Murky must go show them what for! Mindmeld with Murky in his egg and show him how it's done!",starts={{npcID=98067,x=0.426,y=0.108,zoneID=7503}},ends={{npcID=98067,x=0.426,y=0.108,zoneID=7503}},coords={x=0.426,y=0.108,source="quest_giver",zoneID=7503},questType="standard"},
[40103] = {id=40103,name="7.0 ALPHA DK TEST QUEST",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7679,questType="standard"},
[40108] = {id=40108,name="7.0 Stormheim - Treasure 045 - Stormheim - twh",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7541,mapID=634,questType="standard"},
[40110] = {id=40110,name="Disrupt the Inkbinders",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7541,mapID=634,questType="standard"},
[40112] = {id=40112,name="Huln's War - Malorne's Favored",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7838,mapID=697,description="Shan'do ask for you. Sent Eche'ro beast with message on rack. Unng Ak hear Eche'ro sound fighting. You find beast? Give help, maybe feathered night elf be relieve.",starts={{npcID=97891,x=0.294,y=0.392,mapID=697}},ends={{npcID=98794,x=0.28,y=0.472,mapID=697}},coords={x=0.294,y=0.392,source="quest_giver",mapID=697},questType="standard"},
[40114] = {id=40114,name="Prephoof Compound Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40115] = {id=40115,name="Prepfoot Compound Treasure",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40116] = {id=40116,name="Prephoof Compound Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40120] = {id=40120,name="A Murky Fate",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="You may not know, but you stand upon the grounds of Morheim, home to the greatest warriors of the land. Our deeds were great, our valor legendary. It pains me that we see such an end. The creatures set upon us at nightfall. Our men fought bravely, but were vastly outnumbered. Now their corpses lie rotting in the sun, with no burial and no rites. This is not an end befitting to the glorious warriors of Morheim. Make it right, and you will have our thanks.",starts={{npcID=98587,x=0.782,y=0.586,zoneID=7541}},ends={{npcID=98587,x=0.782,y=0.586,zoneID=7541}},coords={x=0.782,y=0.586,source="quest_giver",zoneID=7541},questType="standard"},
[40121] = {id=40121,name="Ley Line Influences",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[40122] = {id=40122,name="Cenarius, Keeper of the Grove",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="Ahh, Val'sharah . It has been an age since I have set foot in these sacred woods. Too long... Our work here is simple, . We must call upon my mentor, Cenarius, and learn where he safeguards the Tears of Elune. With them, you will be one step closer to sealing Sargeras' Tomb and thwarting the Legion. You have many treacherous tasks in front of you. Consider your visit here a brief respite. Come, this will not take long.",starts={{npcID=91462,x=0.546,y=0.728,zoneID=7558}},ends={{npcID=91109,x=0.518,y=0.64,zoneID=7558}},coords={x=0.546,y=0.728,source="quest_giver",zoneID=7558},questType="standard"},
[40123] = {id=40123,name="The Nightborne Pact",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Ngh... I can ignore this wound no longer. Help me patch this up. I will explain everything.",starts={{npcID=98312,x=0.346,y=0.534,zoneID=7637}},ends={{npcID=98312,x=0.346,y=0.534,zoneID=7637}},coords={x=0.346,y=0.534,source="quest_giver",zoneID=7637},questType="standard"},
[40125] = {id=40125,name="Branch of the Arcan'dor",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="You have used the spellstone of Kel'danath to soothe countless withered. Yet it contains merely a shade of the arcan'dor's power, drawn from its slumbering seed. This fell from the tree. Though it is severed, it is not dead - invisible threads of magic bind all pieces of the arcan'dor together. I have enchanted this branch with a new iteration of Kel'danath's charm spell. With it, you can mend the arcane essence of even more withered. Use it well.",starts={{npcID=97140,x=0.368,y=0.466,zoneID=7637}},ends={{npcID=97140,x=0.368,y=0.466,zoneID=7637}},coords={x=0.368,y=0.466,source="quest_giver",zoneID=7637},questType="standard"},
[40129] = {id=40129,name="Repairing the Source",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[40130] = {id=40130,name="Washed Clean",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="Mighty though the Legion is, theirs is not the strongest power in Azeroth. There is a place where Enchantress Ilanya and I spent many blissful hours together. The love that infuses such a place is more potent than fel magic, . Go to the Nor'Danil Wellspring. Its waters can purify the fel dust you have collected... and perhaps purify me as well. I will meet you there.",starts={{npcID=98675,x=0.638,y=0.302,zoneID=7334}},ends={{npcID=98698,x=0.364,y=0.34,zoneID=7334}},coords={x=0.638,y=0.302,source="quest_giver",zoneID=7334},questType="standard"},
[40131] = {id=40131,name="Stonehide Leather Sample",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="The quality of this leather scrap appears representative of the beast hides found in the Broken Isles. Your skinning trainer in Dalaran would be interested in seeing this.",questType="standard"},
[40132] = {id=40132,name="In One Piece",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="This hide is usable, but it is mournably small. You disrespect the beast by chopping it up like this, . You make light of the gift that it gave to you. Go out into the wilds again. Skin the leathery beasts below us, and this time, bring me hides in one piece.",questType="standard"},
[40133] = {id=40133,name="Scrap of Pants",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="The mouth of this particular beast contained a piece of handsewn cloth. The fabric bears the word \"singwa\". While the term \"singwa\" is unfamiliar, it DOES happen to be the middle of the last name of a fairly notable Azerothian skinner.",ends={{npcID=94409,x=0.4,y=0.522,zoneID=7503}},questType="standard"},
[40134] = {id=40134,name="Highmountain Hides",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="So, ye're a skinner too, aye? That's great news, ! I don't think I ever knew we shared that in common. Ye've GOT ta see some o'the hides we've got here in Highmountain. Why, I'd give me spare monacle just t'get me hands on some o'those fine, silky hides...",starts={{npcID=94409,x=0.4,y=0.522,zoneID=7503}},ends={{npcID=94409,x=0.4,y=0.522,zoneID=7503}},coords={x=0.4,y=0.522,source="quest_giver",zoneID=7503},questType="standard"},
[40135] = {id=40135,name="The Freedom to Roam",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7637,description="I remember bein' young, . D'ye remember it? So much less responsibility... I could just run around as I pleased. Now, I'm pretty much stuck with my hunting crew, here in Highmountain. There're so many interestin' creatures in the other regions o'the Broken Isles, though. I'll mark yer map, you get out there and do some skinnin'!",starts={{npcID=94409,x=0.4,y=0.522,zoneID=7503}},ends={{npcID=94409,x=0.4,y=0.522,zoneID=7503}},coords={x=0.4,y=0.522,source="quest_giver",zoneID=7503},questType="standard"},
[40136] = {id=40136,name="Immaculate Stonehide Leather",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="You have been skinning for a long time now, but never have you seen a leather specimen as fine as this. Durable, pliable, beautifully colored... Your trainer in Dalaran would be VERY interested in seeing this.",questType="standard"},
[40137] = {id=40137,name="Leather for Ske'rit",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7637,description="This hide certifies that you have learned everything about leather that I can teach you, . My skills have dulled since I set up shop here in town. I have a former protege who skins the creatures of Suramar. His name is Ske'rit . His skills remain as sharp as his blade, and if there is anyone out there who can teach you, it is him.",ends={{npcID=98720,x=0.306,y=0.334,zoneID=7637}},questType="standard"},
[40138] = {id=40138,name="Trial of the Crusader: Hides of Legend",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=6622,description="Ya, I can train you. Ting is, I'm still workin' on my techniques 'ere in Suramar. In fact, you can probably help. I need ta look at a few special skins, for comparison. I need a strong white yeti pelt, a really big demon skin, and da thickest direhorn skin you can find. Do that, and I'll share my results with you and' ol' Kondal up in de city.",starts={{npcID=98720,x=0.306,y=0.334,zoneID=7637}},ends={{npcID=98720,x=0.306,y=0.334,zoneID=7637}},coords={x=0.306,y=0.334,source="quest_giver",zoneID=7637},questType="raid"},
[40139] = {id=40139,name="Halls of Valor: The Hide of Fenryr",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7672,description="While you be here, I got a favor t'ask you. I been hearin' whispers about one big, nasty wolf dat's been causin' all kinds of trouble up in de vrykul lands. His name be Fenryr. I want his hide.",starts={{npcID=98720,x=0.306,y=0.334,zoneID=7637}},ends={{npcID=98720,x=0.306,y=0.334,zoneID=7637}},coords={x=0.306,y=0.334,source="quest_giver",zoneID=7637},questType="dungeon"},
[40140] = {id=40140,name="Ske'rit's Leather Handbook",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="An' wit dat, my research be done. Ske'rit hands you a scroll casing.> Dis is what I been workin' on here in Suramar. Bring it to Kondal, so dat he can teach it to all you other skinnahs. Since you been helpin' so much, I put your name on it, . Hope you don't mind.",starts={{npcID=98720,x=0.306,y=0.334,zoneID=7637}},coords={x=0.306,y=0.334,source="quest_giver",zoneID=7637},questType="standard"},
[40141] = {id=40141,name="Stormscale Sample",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="This scale shimmers with electrical energy. Your skinning trainer in Dalaran would be interested in seeing this.",questType="standard"},
[40142] = {id=40142,name="The Core of the Stormscale",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Ahh, yes. The elusive stormscale. I have seen similar scales in Northrend, and some in Skywall, but it would appear that such a scale is common here. My colleagues that specialize in mail armor will be happy to learn this. To more efficiently harvest this type of scale, you must first understand its power. Look for broken, unusable scales on your quarry, and remove the sparks within them. Once you have seen the sparks, you will better understand the stormscale.",questType="standard"},
[40143] = {id=40143,name="Unfinished Treatise on the Properties of Stormscale",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="Tucked between the folds of this animal's hide, you find a scrap of paper. It appears to be a handwritten guide to harvesting stormscales, but too much of the manuscript has been lost to be of use. Perhaps your skinning trainer in Dalaran could help you find its owner.",questType="standard"},
[40144] = {id=40144,name="Glielle",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="One skinner makes the wilds of Azsuna her home. Her name is Glielle , and she is a night elf - or at least, she was, in life. Perhaps the scroll was hers.",ends={{npcID=98791,x=0.47,y=0.45,zoneID=7334}},questType="standard"},
[40145] = {id=40145,name="Under Down",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="I can train you, though. Everyone knows about the bright stormscales on the hippogryph's hindquarters, but did you know that they also have a few scales beneath their feathers? You just need to know where to look. Now go see if you can get some on your own.",starts={{npcID=98791,x=0.47,y=0.45,zoneID=7334}},ends={{npcID=98791,x=0.47,y=0.45,zoneID=7334}},coords={x=0.47,y=0.45,source="quest_giver",zoneID=7334},questType="standard"},
[40146] = {id=40146,name="Seymour and Agnes",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="The other skinner - pair of skinners, to be honest - that comes to mind when you show me this scroll is a student of mine, named Seymour , and his mother Agnes. Last I heard, they were in Stormheim, hunting the storm drakes.",ends={{npcID=98721,x=0.456,y=0.256,zoneID=7541}},questType="standard"},
[40147] = {id=40147,name="Mother's Prized Knife",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="The other day, Mother and I were up at the top of the nearby mountain, and she threw her skinning knife at me because the view wasn't good enough. Her knife is still up there, somewhere. I'd feel horrible just leaving it.",starts={{npcID=98721,x=0.456,y=0.256,zoneID=7541}},ends={{npcID=98721,x=0.456,y=0.256,zoneID=7541}},coords={x=0.456,y=0.256,source="quest_giver",zoneID=7541},questType="standard"},
[40148] = {id=40148,name="Red-Eyed Revenge",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="It came out of nowhere. I was waiting for mother to finish skinning her half of the drake when the biggest storm dragon I'd ever seen came and... and... Seymour finds his resolve.> I want you to kill as many of them as you can. Skin them, don't skin them, I don't care. Just get revenge for mother!",starts={{npcID=98721,x=0.456,y=0.256,zoneID=7541}},ends={{npcID=98721,x=0.456,y=0.256,zoneID=7541}},coords={x=0.456,y=0.256,source="quest_giver",zoneID=7541},questType="standard"},
[40149] = {id=40149,name="Drakol'nir Must Die",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="The dragon that took Mother's life was named Drakol'nir. Mother always wanted to wear his scale as a pendant, but we never got a chance to skin him because I couldn't kill him alone, and she didn't care much for killing. Only skinning. You... you wouldn't mind bringing it for her, would you?",starts={{npcID=98721,x=0.456,y=0.256,zoneID=7541}},ends={{npcID=98721,x=0.456,y=0.256,zoneID=7541}},coords={x=0.456,y=0.256,source="quest_giver",zoneID=7541},questType="standard"},
[40151] = {id=40151,name="Immaculate Stormscale",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,mapID=627,description="You have been skinning for a long time now, but never have you seen a scale specimen as fine as this. Your trainer in Dalaran would be VERY interested in seeing this.",questType="standard"},
[40152] = {id=40152,name="Scales for Ske'rit",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7637,description="Your skills surpass mine, . I have never even SEEN a scale such as this... let alone remove one so expertly. If you still wish to learn more, you will need to seek an even greater skinner than I. His name is Ske'rit , and he was once my student. You will find him in the wild areas of Suramar.",ends={{npcID=98720,x=0.306,y=0.334,zoneID=7637}},questType="standard"},
[40153] = {id=40153,name="Return to Karazhan: Scales of Legend",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=6297,description="I know a ting or two about scales, but I'm losin' my edge. I been starin' at stormscales so long, I be forgettin' what de other kinds look like. I need ta look at a few special scales, for comparison. I need a nether dragon scale, a nice hot black dragonscale, and da thickest piece o' insect chitin you can find. Gotta get dese stormscales outta my head, bruddah.",starts={{npcID=98720,x=0.306,y=0.334,zoneID=7637}},ends={{npcID=98720,x=0.306,y=0.334,zoneID=7637}},coords={x=0.306,y=0.334,source="quest_giver",zoneID=7637},questType="raid"},
[40154] = {id=40154,name="Eye of Azshara: The Scales of Serpentrix",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8040,description="I got ta ask you a favor. I haven't been ta Azsuna, and I don't see myself leavin' Suramar anytime soon. Problem is, dere's a big ol' serpent out dere dat's just beggin' ta be skinned. Just BEGGIN' for it.",starts={{npcID=98720,x=0.306,y=0.334,zoneID=7637}},ends={{npcID=98720,x=0.306,y=0.334,zoneID=7637}},coords={x=0.306,y=0.334,source="quest_giver",zoneID=7637},questType="dungeon"},
[40155] = {id=40155,name="Ske'rit's Scale-Skinning Suggestions",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Now dat I got all dese scales, I tink I know what I need to know. Ske'rit hands you a few pages of handwritten notes.> Here's my latest findin's on stormscales. Bring 'em to Kondal, an' read through em' togethah.",starts={{npcID=98720,x=0.306,y=0.334,zoneID=7637}},coords={x=0.306,y=0.334,source="quest_giver",zoneID=7637},questType="standard"},
[40156] = {id=40156,name="Felhide Sample",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,mapID=627,description="This demonic hide is completely unlike any standard beast hide you are accustomed to. Your skinning trainer in Dalaran would be interested in seeing this.",questType="standard"},
[40157] = {id=40157,name="An Unseemly Task",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="I'm quite impressed with what you've been able to skin in these lands, felhide in particular. But as my knowledge is limited in this area of skinning, I know of one who may have increased his skill in skinning such beasts. You can find my old apprentice, Ske'rit in Suramar. Ask him if he knows how to yield better results from skinning demons.",ends={{npcID=98720,x=0.306,y=0.334,zoneID=7637}},questType="standard"},
[40158] = {id=40158,name="Darkheart Thicket: Demons Be Different",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7673,description="Oh yes, I've seen me fair share of demons while in dese lands. And skinnin' dem ain't no easy task. Their hides are tougher than normal animals, fibrous, see? But if you be wantin' to make da most of their skins, den ya need to be practicin' more. There be a creature I've heard of in da Darkheart Thicket whose hide's as tough as a demon's. When ya go ta skin him, try cutting with da grain in one even stroke. Bring me his skin to show me you be picking up on what I'm sayin'.",starts={{npcID=98720,x=0.306,y=0.334,zoneID=7637}},ends={{npcID=98720,x=0.306,y=0.334,zoneID=7637}},coords={x=0.306,y=0.334,source="quest_giver",zoneID=7637},questType="dungeon"},
[40159] = {id=40159,name="The Emerald Nightmare: The Pestilential Hide of Nythendra",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8026,description="There is one more demon hide to gather... but it isn't that of a demon. It's a dragon. Nythendra, great green dragon, has nearly been eaten up by the Nightmare. Only a master skinner would be able to remove what bits of bug-eaten hide remain on her body. Go on then, . Show me what you've learned.",questType="standard"},
[40160] = {id=40160,name="Magic Clams",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,description="What are murlocs doing with arcane clams? Perhaps your Nightfallen allies could make use of them.",questType="standard"},
[40161] = {id=40161,name="Tapping the Underground",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,description="Have you seen them, ? These are not ordinary murlocs. They have been drawn by the ley line that flows from Azsuna into this land. Somehow they have managed to tap into its arcane current and are tapping its power for their own devious purposes. These disturbances must be stopped if the ley line is to remain intact.",questType="standard"},
[40162] = {id=40162,name="Snowblind Mesa Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40163] = {id=40163,name="Snowblind Mesa Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40164] = {id=40164,name="REUSE",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40166] = {id=40166,name="Leying with Murlocs",level=10,requiredLevel=10,faction="none",expansion=6,zoneID=7541,mapID=634,description="I have seen these Seerspine summon minor elementals, which is no small feat for a murloc, but their high summoner, Blargrrrl, is trying to summon Torretus from the river. I doubt a mere murloc has the capabilities to control an entity as powerful as Torrentus. Blargrrrl will be deeply entranced if he is trying such a feat. We'll need something powerful to halt his ritual. Infuse yourself with ley energies and return to me.",questType="standard"},
[40167] = {id=40167,name="The Story of Huln",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="You work to unite the tribes. That is no small task. It has only been done once before in the history of this mountain. Huln Highmountain last united the tribes thousands of years ago to take on the Legion during the War of the Ancients.",starts={{npcID=98825,x=0.512,y=0.546,zoneID=7731}},ends={{npcID=98825,x=0.512,y=0.546,zoneID=7731}},coords={x=0.512,y=0.546,source="quest_giver",zoneID=7731},questType="standard"},
[40168] = {id=40168,name="The Swirling Vial",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=3703,description="As you touch the vial, your mind is flooded with memories, not all of which are your own. The most vivid is a memory of exchanging a similar vial with someone in Shattrath, with A'dal's light shining behind you. Despite your best efforts however, you can't pinpoint when that might have been - maybe it hasn't been, and is yet to be?",ends={{npcID=98685,x=0.544,y=0.39,zoneID=3703}},questType="standard"},
[40169] = {id=40169,name="Crossroads Rendezvous",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="An old apprentice of mine left during the war, shortly before we were all cursed. I've recently heard that she's been seen near the Felblaze Ingress. I would very much like to speak to her once more. Go and find her. Take her journal to her and let her know that I don't blame her for what she did. And if she's willing, please bring her back to me.",starts={{npcID=107139,x=0.468,y=0.408,zoneID=7334}},ends={{npcID=98675,x=0.638,y=0.302,zoneID=7334}},coords={x=0.468,y=0.408,source="quest_giver",zoneID=7334},questType="standard"},
[40170] = {id=40170,name="Amateur Hour",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="The hunters' lodge has attracted a lot of amateurs who call themselves hunters. They're scarin' away all the prize game with their antics. While I'm a known expert with my rifle, I've yet to manage the art of negotiation. How about ya do us all a favor and tell those novice hunters to head for the hills?",starts={{npcID=94409,x=0.4,y=0.522,zoneID=7503}},ends={{npcID=94409,x=0.4,y=0.522,zoneID=7503}},coords={x=0.4,y=0.522,source="quest_giver",zoneID=7503},questType="standard"},
[40173] = {id=40173,name="The Unstable Prism",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=4395,mapID=118,description="As the prism struggles to stabilize in a single time flow, it bleeds a shadowy chill, the likes of which you haven't felt since Northrend. Surely some mage in Dalaran would be interested in this relic.",questType="standard"},
[40175] = {id=40175,name="Sleeping Bear",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40176] = {id=40176,name="From Head to Toe",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="You've been busy, . And you have some new patterns in your repertoire, I see! How about we add another?",questType="standard"},
[40177] = {id=40177,name="Leather Lady",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="I'd like you to start working with my apprentices. The first is Diane Cannings , who has focused her expertise on the softer leather armors. She's just not that into mail armor, like the twins are. Go talk to her about this new type of leather.",questType="standard"},
[40178] = {id=40178,name="Vestment Opportunity",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="While the vrykul of Northrend wore strong armor, their craftsmen always had the strongest. Go to Stormheim, search for someone who knows about leather armor, and bring their chest piece back to me.",questType="standard"},
[40179] = {id=40179,name="Stormheim Savagery",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="There's a land below - Stormheim, they call it - that's inhabited by vrykul. I remember the vrykul from my days in Northrend. What I remember most was how well-crafted their armor was. If the vrykul here are as skilled as the ones in Northrend, then I'm certain we can learn something by studying their armaments.",questType="standard"},
[40180] = {id=40180,name="Mail Men",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="The two dwarves behind me are the Glowergold brothers. They're my resident mail armor experts. While Ranid has decided to focus his skills towards lining his pockets, his brother, Thanid, still enjoys the crafting side of the trade. Introduce yourself to Thanid. You may work with him to further our knowledge of turning these stormscales into something extraordinary.",questType="standard"},
[40181] = {id=40181,name="Black Rook Bandit",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="I've heard rumors of a grand castle in Val'sharah that's known to house an impressive army. Surely, the armor they wear ain't made of sticks and hay. I'm willing to bet they've fashioned some mail armor at some point fer their troops and it's just sitting there, ripe for the taking. How about ye head over there and see what ye can \"borrow\" from their armory.",questType="standard"},
[40182] = {id=40182,name="Too Good To Pass Up",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="All types of Black Rook Hold armor are intriguing, but I'm most interested in their chest pieces. If ye can, try to find someone of importance there and... relieve them of their shirt. If it makes ye feel any better, I've heard they're all cursed, so puttin' them out of their misery is the least ye could do.",questType="standard"},
[40183] = {id=40183,name="Over Your Head",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Alright, , I'd like you to assist me with creating a helm. First we'll need to shave the hides, then tan them, and finally cut them into usable pieces. Follow my lead.",questType="standard"},
[40184] = {id=40184,name="Tauren Tanning",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="Have you heard of the Highmountain tauren tribes? They're not unlike the tauren we know on Kalimdor. I've heard they have a leatherworking master there who might be able to help us come up with some new patterns. Travel to Highmountain and see if they're willing to teach you how they craft their armor.",ends={{npcID=98948,x=0.366,y=0.788,zoneID=7731}},questType="standard"},
[40185] = {id=40185,name="Shoulder the Burden",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="During one of our recent battles, my brother, Lohrumn, was slain. His armor was taken by the drogbar. You would honor his memory by retrieving what has been stolen. I will make it worth your while, leatherworker.",starts={{npcID=98948,x=0.366,y=0.788,zoneID=7731}},ends={{npcID=98948,x=0.366,y=0.788,zoneID=7731}},coords={x=0.366,y=0.788,source="quest_giver",zoneID=7731},questType="standard"},
[40186] = {id=40186,name="Drogbar Durability",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="We are currently at war with a race known as the drogbar. We have long maintained peace with the drogbar, but lately, they have no respect for anyone but themselves. Slay them. Prove your worth as an ally of the tauren. Do this, and I will reward you with knowledge.",starts={{npcID=98948,x=0.366,y=0.788,zoneID=7731}},ends={{npcID=98948,x=0.366,y=0.788,zoneID=7731}},coords={x=0.366,y=0.788,source="quest_giver",zoneID=7731},questType="standard"},
[40187] = {id=40187,name="Links in the Chain",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="Well, , I'm afraid I'm at me wits' end with these scales. Not quite sure how to fashion the remaining pieces fer a full set. However, I've heard that the elves of Azsuna had some great crafters in their cities. Perhaps one or two of them still exist. Go there and search fer a master. Maybe they can fill in the missing patterns fer us.",ends={{npcID=98964,x=0.474,y=0.442,zoneID=7334}},questType="standard"},
[40188] = {id=40188,name="Best Served Cold",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="My partner and I both fell victim to the fallout of the Sundering. We were betrayed and abandoned by a trusted friend. That \"friend\" has recently appeared in the ruins to the east. His name is Ranaris . Go to and take revenge for us and I will grant you some of my wisdom.",starts={{npcID=98964,x=0.474,y=0.442,zoneID=7334}},ends={{npcID=98964,x=0.474,y=0.442,zoneID=7334}},coords={x=0.474,y=0.442,source="quest_giver",zoneID=7334},questType="standard"},
[40189] = {id=40189,name="Naga Know-How",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="The naga of this region wear little armor, but what they do wear is particularly durable. If you wish to make a strong shoulder piece, I would first study the naga's armor and then create a pattern of similar construct. The city nearby is overrun by naga. Slay them and bring me their armor and I will show you what I mean.",starts={{npcID=98964,x=0.474,y=0.442,zoneID=7334}},ends={{npcID=98964,x=0.474,y=0.442,zoneID=7334}},coords={x=0.474,y=0.442,source="quest_giver",zoneID=7334},questType="standard"},
[40190] = {id=40190,name="Hardening the Hide",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="Back to Highmountain for you, ! I hear they know even more efficient ways to craft our patterns. When you get there, put in a good word for me, will ya? I'd like to start a relationship the tauren, so I don't have to keep sending you back and forth.",ends={{npcID=98948,x=0.366,y=0.788,zoneID=7731}},questType="standard"},
[40191] = {id=40191,name="Stamped Stories",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="Stamped onto the leather of the tanning racks behind me are the ancient ways of our tribe's leatherworkers. They tell the stories of masters who, through perseverance - and luck, in some cases - pioneered our way of leatherworking. Read the stories and learn from them. Perhaps you'll find some insight on how to better your own methods.",starts={{npcID=98948,x=0.366,y=0.788,zoneID=7731}},ends={{npcID=98948,x=0.366,y=0.788,zoneID=7731}},coords={x=0.366,y=0.788,source="quest_giver",zoneID=7731},questType="standard"},
[40192] = {id=40192,name="Claw of the Land",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="Personal experience has taught me to use stronger materials when crafting armor pieces. They last longer, and you don't need quite as many of them. For example, I utilize the claws of the pinerock stalkers. If you acquire some for me, perhaps I can show you how better materials can increase your efficiency.",starts={{npcID=98948,x=0.366,y=0.788,zoneID=7731}},ends={{npcID=98948,x=0.366,y=0.788,zoneID=7731}},coords={x=0.366,y=0.788,source="quest_giver",zoneID=7731},questType="standard"},
[40193] = {id=40193,name="Getting the Kinks Out",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="Now listen, . Everything ye make can always be done better. I just haven't quite worked out the way to do it with these fancy new scales. Perhaps that ghost-like elf friend of yours can help ye. An' if she DOES know somethin', perhaps ye can relay that information back to us. It would certainly go towards making the shop more lucrative.",ends={{npcID=98964,x=0.474,y=0.442,zoneID=7334}},questType="standard"},
[40194] = {id=40194,name="Reclaimed Cargo",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="The same ship that my brother was on also carried shipments of exceptional mail armor. Knowing the giants, they probably had no use for them and left them scattered around their caves. If you could recover those shipments and bring them here, I can explain the techniques used to fashion them. That should give you a good idea of how to improve your processes.",starts={{npcID=98964,x=0.474,y=0.442,zoneID=7334}},ends={{npcID=98964,x=0.474,y=0.442,zoneID=7334}},coords={x=0.474,y=0.442,source="quest_giver",zoneID=7334},questType="standard"},
[40195] = {id=40195,name="A Daring Rescue",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="My brother, Taldranis , was on a ship headed here to Azsuna. The ship was ambushed by the sea giants and my brother was taken captive. I believe he still lives out his days in those horrible caves, slaving away for the giants. Go and free him, please. Take this with you, it may give him enough protection should you run into any trouble. And be careful not to get captured by the giants yourself.",questType="standard"},
[40196] = {id=40196,name="Adventuring Anxieties",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="! I was recently talking with Mei, the mount trader, and she asked me if it was possible to make a barding that could prevent adventurers from being dismounted. I'd like you to go and discuss this idea with her further. Return to me when you're finished. Perhaps we can solve this issue together.",questType="standard"},
[40197] = {id=40197,name="The Necessary Materials",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="In order to make this barding, we'll need a lot of leather. And I mean a LOT of leather. I'll solidify our plans on fitting the pieces together. You go gather the leather. Once that's done, we can begin crafting.",questType="standard"},
[40198] = {id=40198,name="Rats!",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="I tell you, , I have the worst luck sometimes. A package recently arrived from Hrul containing leatherworking patterns, and while my back was turned, some filthy rats came in and ran off with them down into the sewers! Probably building nests with them as we speak. Please, , can you go down there and see if you can retrieve any of them?",questType="standard"},
[40199] = {id=40199,name="Leather Legwork",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Good news, ! Langrom's Leather and Links recently delivered a shipment of mail armor to me. It's of the finest quality and I'd love to show it to ye, but it seems I've lost me crowbar and can't open the crate. If ye could run over to their shop and grab an extra one fer me, we can get this crate opened and go over the construction.",questType="standard"},
[40200] = {id=40200,name="Battle Bonds",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=7502,description="Do you like pets, ? I love pets. They're so cute! But what I really want is more things with which to play with them. I'm sure Lio over at the Magical Menagerie has some ideas for fun toys. You should go talk to her!",questType="standard"},
[40201] = {id=40201,name="Playthings",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Ok, so her ideas were a leash, a bed, and a FLAMING HOOP?! It sounds like they want to start a circus or something. Regardless, I love all those ideas and we should get started as soon as you're ready. Why don't you work on making the bed, and I'll work out the details for the flaming hoop.",questType="standard"},
[40202] = {id=40202,name="The Final Lessons",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description=", Hrul has requested your presence. From his message it seems as though he's ready to impart to you all the wisdom he has gained from working with the skins of this land. I envy you, ... but I'm also proud to see that you've gained so much respect with him. Go now, and good luck!",ends={{npcID=98948,x=0.366,y=0.788,zoneID=7731}},questType="standard"},
[40203] = {id=40203,name="Strength of the Past",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="As you know, the durability of your armor is only as strong as the materials you use to make them. Long ago, the black dragon, Deathwing once inhabited this very mountain. In his quest for power, his body began to tear and he had creatures make metal scales to stitch his wounds. His natural scales fell to the ground in his lair and have been there ever since. Go retrieve a scale and bring it to me. This will take all your strength to accomplish.",starts={{npcID=98948,x=0.366,y=0.788,zoneID=7731}},ends={{npcID=98948,x=0.366,y=0.788,zoneID=7731}},coords={x=0.366,y=0.788,source="quest_giver",zoneID=7731},questType="standard"},
[40204] = {id=40204,name="Evolution of the Past",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="As we make stronger armor, the creatures we battle adapt and learn to defeat us. We in turn create better armor, and they in turn learn to defeat it yet again. For centuries, my people have battled the basilisks of the mesas below. They have adapted to us as thoroughly as we have to them. Go, kill these basilisks and take from them their hides. Return them to me so I may show you how they have evolved.",starts={{npcID=98948,x=0.366,y=0.788,zoneID=7731}},ends={{npcID=98948,x=0.366,y=0.788,zoneID=7731}},coords={x=0.366,y=0.788,source="quest_giver",zoneID=7731},questType="standard"},
[40205] = {id=40205,name="Respect for the Past",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7731,description="We record the mistakes of the past so we can learn to avoid them in the present. However, recording history is not just about preventing missteps, but also to celebrate our successes. Scattered around Highmountain at sacred locations are racks with stamped leather, much like the ones here, with stories to tell. Go to these locations, pay your respect, and learn their lessons.",starts={{npcID=98948,x=0.366,y=0.788,zoneID=7731}},ends={{npcID=98948,x=0.366,y=0.788,zoneID=7731}},coords={x=0.366,y=0.788,source="quest_giver",zoneID=7731},questType="standard"},
[40206] = {id=40206,name="A Debt Paid",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="Now, I've never heard of a ghost sending a letter before, but I'll be damned if'n I didn't just receive one now. Celea has sent fer ye, . I'd best be on me way if I were ye. Might be bad luck to keep a spirit waiting.",ends={{npcID=98964,x=0.474,y=0.442,zoneID=7334}},questType="standard"},
[40207] = {id=40207,name="Scales of the Arcane",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="In my experience, dragon scale has been the strongest material I've ever had the privilege of working with. It's hard, durable and very little can go a long way. I wish to work with it again, . Being in this form, I'm bound to this area, unable to experience the world any longer. I've heard rumor of the blue dragonflight occupying parts of Azsuna. Perhaps you can speak with them and see if they can shed a scale or two.",starts={{npcID=98964,x=0.474,y=0.442,zoneID=7334}},ends={{npcID=98964,x=0.474,y=0.442,zoneID=7334}},coords={x=0.474,y=0.442,source="quest_giver",zoneID=7334},questType="standard"},
[40208] = {id=40208,name="Eye of Azshara: Scales of the Sea",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8040,description="When we first met, I spoke of the naga, and the armor they're able to craft. No grander armor is worn, however, than by their top warlords. One in particular resides within the Eye of Azshara itself. His name is Warlord Parjesh, and the hauberk he wears is one of legend. Repel his forces, and obtain his armor. Do this, and I will teach you more of the Azsunian way of leatherworking.",starts={{npcID=98964,x=0.474,y=0.442,zoneID=7334}},ends={{npcID=98964,x=0.474,y=0.442,zoneID=7334}},coords={x=0.474,y=0.442,source="quest_giver",zoneID=7334},questType="dungeon"},
[40209] = {id=40209,name="Scales of the Earth",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="While leather armor is strong on its own, integrating scales into the design is what truly sets it apart. The type of scales you use will determine how many you'll need to fully protect the wearer. And one of the strongest type of scales are basilisk scales. A fully matured basilisk has the strongest of course. Near the village of Llothien is a basilisk den. Kill the matriarch and return her scales to me.",starts={{npcID=98964,x=0.474,y=0.442,zoneID=7334}},ends={{npcID=98964,x=0.474,y=0.442,zoneID=7334}},coords={x=0.474,y=0.442,source="quest_giver",zoneID=7334},questType="standard"},
[40210] = {id=40210,name="Time Well Spent",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Unfortunately, , you have learned all that I have to teach. I am pleased we were each able to achieve our goals in this partnership. Go now and share what you've learned with your allies in Dalaran. I'm sure they'd be eager to share in your training.",starts={{npcID=98964,x=0.474,y=0.442,zoneID=7334}},coords={x=0.474,y=0.442,source="quest_giver",zoneID=7334},questType="standard"},
[40211] = {id=40211,name="Demon Flesh",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Something we haven't really explored yet, , are the creatures of Suramar. Specifically, the demons. Now I certainly don't praise what they are, but you can't ignore the fact that some of their creatures have especially tough hides. We could take a lesson from the demon hunters and use those hides to our advantage against the demons. I'll be damned though if I know the first thing about working with demon hide. Perhaps there's someone in Suramar who can help...",ends={{npcID=98969,x=0.266,y=0.716,zoneID=7637}},questType="standard"},
[40212] = {id=40212,name="Wrong End of the Knife",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="There he is! The man that isn't there! He's... he's... Wait... no, I'm sorry. My thoughts, they're just all over place lately. Ever since my exile, things have been a bit fuzzier than normal. If you wish to learn from me before I completely lose my mind, then do me a favor, and kill those traitors who sided with the demons and exiled me.",starts={{npcID=98969,x=0.266,y=0.716,zoneID=7637}},ends={{npcID=98969,x=0.266,y=0.716,zoneID=7637}},coords={x=0.266,y=0.716,source="quest_giver",zoneID=7637},questType="standard"},
[40213] = {id=40213,name="Hounds Abound",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="I'll invite him to tea. That'll show him! He'll see the leather doll and say, \"When did SHE get here?!\" I mean... sorry, . My mind goes to strange places. You want to know about the demons, the ones with durable hides? Before I was exiled I saw such beasts roaming our cities. Fel hounds, they are called. Slay them and bring me their corpses. We can discuss their hides afterwards.",starts={{npcID=98969,x=0.266,y=0.716,zoneID=7637}},ends={{npcID=98969,x=0.266,y=0.716,zoneID=7637}},coords={x=0.266,y=0.716,source="quest_giver",zoneID=7637},questType="standard"},
[40214] = {id=40214,name="Fel Tanning",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Listen, you. I'm not sure when the crazy side of me will come out again, so let's make our time together short. You want to learn how to make armor to rival the demons? Follow my instructions and you'll have an excellent grasp on the procedures.",starts={{npcID=98969,x=0.266,y=0.716,zoneID=7637}},ends={{npcID=98969,x=0.266,y=0.716,zoneID=7637}},coords={x=0.266,y=0.716,source="quest_giver",zoneID=7637},questType="standard"},
[40215] = {id=40215,name="Mounting Made Easy",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,description=", I'm glad you're here. I confess: I've been working on a secret project behind your back. Behold: the Stonehide Leather Harness! Now, we simply need to find a mount worthy of such a piece of art. The vrykul sing songs of a snow-white elderhorn with endless stamina. Find it, place the harness on it, and tame it.",questType="standard"},
[40216] = {id=40216,name="A Hunter at Heart",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Addie's one heck of a writer, but I've never seen her hold a rifle. She's keen on learning how to hunt, but who's ever heard of a gnome hunter? You seem to have a knack dealin' with amateurs, so maybe you'd be willin' to let the gnome tag along on a hunt? She could learn a thing or two by shadowing someone with your skill. Ya best start off with some small game. We don't want the lass to get discouraged.",starts={{npcID=94409,x=0.4,y=0.522,zoneID=7503}},ends={{npcID=94409,x=0.4,y=0.522,zoneID=7503}},coords={x=0.4,y=0.522,source="quest_giver",zoneID=7503},questType="standard"},
[40217] = {id=40217,name="An Offering of Ammo",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="The mountains have seen many new travelers pass through their valleys, some without an understanding of our traditions. Our leaders have turned their focus to more pressing matters, but Losro and I cannot ignore the recent arrival of hunters in the nearby basin. They hunt with guns and gadgets, forgoing the experience of hunting with a bow and arrow. While I know that some will remain stuck in their ways, perhaps an offering of arrows will encourage these outsiders to hunt the way we always have.",starts={{npcID=99905,x=0.42,y=0.468,zoneID=7731}},ends={{npcID=94409,x=0.4,y=0.522,zoneID=7503}},coords={x=0.42,y=0.468,source="quest_giver",zoneID=7731},questType="standard"},
[40218] = {id=40218,name="Debt Repaid",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7875,description="I have a few urgent matters to take care of, but soon after I will make my way to Dreadscar Rift and aid you with your summoning. You should warn Ritssyn to keep his distance. I'll be there to repay my debt to you, not to speak to the hypocrite who chose the council over his friends.",starts={{npcID=105816,x=0.608,y=0.306,zoneID=7334}},ends={{npcID=105018,x=0.556,y=0.372,zoneID=7875}},coords={x=0.608,y=0.306,source="quest_giver",zoneID=7334},questType="standard"},
[40219] = {id=40219,name="In Defiance of Deathwing",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="It was in this place, ages ago, that Huln Highmountain challenged the great Deathwing. Today we shall re-live moments of that day through the eyes of our ancestors. For this next part of the spirit journey, we must seek out the three braziers set down many ages ago so that those who would follow in the footsteps of Huln might witness his deeds.",questType="standard"},
[40220] = {id=40220,name="Thorny Dancing",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="The Thistleleaf sprites have gone completely mad. I suspect they are being manipulated by some very mischievous Thorndancers. Please, friend of the forest, seek out these seductive troublemakers and bring peace to the shallows.",starts={{npcID=93600,x=0.538,y=0.798,zoneID=7558}},ends={{npcID=93600,x=0.538,y=0.798,zoneID=7558}},coords={x=0.538,y=0.798,source="quest_giver",zoneID=7558},questType="standard"},
[40221] = {id=40221,name="Spread Your Lunarwings and Fly",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="These poor faerie dragons are being tortured! What's worse, when the thistleleaf become bored they ensnare their victims to continue their torment later. This behavior is simply unacceptable. Please free any trapped Lunarwings you can find.",starts={{npcID=93600,x=0.538,y=0.798,zoneID=7558}},ends={{npcID=93600,x=0.538,y=0.798,zoneID=7558}},coords={x=0.538,y=0.798,source="quest_giver",zoneID=7558},questType="standard"},
[40222] = {id=40222,name="The Imp Mother's Tome",level=8,requiredLevel=8,faction="both",expansion=6,zoneID=7705,description="See this giant cave? There's a terrifyingly powerful imp mother inside. But that's not the good part. The good part is what she has. Apparently, she's some kind of keeper of fel secrets. She's in there performing profane Legion rites and scribing them into a book. We need that power! We need her tome!",starts={{npcID=98711,x=0.732,y=0.338,zoneID=7705}},ends={{npcID=99045,x=0.604,y=0.448,zoneID=7705}},coords={x=0.732,y=0.338,source="quest_giver",zoneID=7705},questType="standard"},
[40224] = {id=40224,name="The Hammer in the Deep",level=10,requiredLevel=10,faction="horde",expansion=6,zoneID=7745,description="Thrall listens intently.> You found it! The Doomhammer fell to the Crumbling Depths... But the Legion remains a step ahead of us. If we hurry, we can follow the demon Geth'xun and retrieve the hammer before any more of this realm is corrupted. Therazane will open a portal directly there. Let's go!",starts={{npcID=96527,x=0.47,y=0.52,zoneID=5042},{npcID=96527,x=0.362,y=0.752,zoneID=8046}},ends={{npcID=96539,x=0.47,y=0.524,zoneID=5042},{npcID=96539,x=0.358,y=0.77,zoneID=8046},{npcID=96539,x=0.34,y=0.762,zoneID=7745}},coords={x=0.47,y=0.52,source="quest_giver",zoneID=5042},questType="standard"},
[40225] = {id=40225,name="A Ring Reforged",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8046,description="Speak with Nobundo, and take your place around the circle, . The Earthen Ring will rise again, with you as its leader! Within these stones stands the legendary Heart of Azeroth, which we can use as a base of operations. Perhaps the power of your artifact can unseal the hidden chambers...",starts={{npcID=96539,x=0.47,y=0.524,zoneID=5042},{npcID=96539,x=0.34,y=0.762,zoneID=7745},{npcID=96539,x=0.358,y=0.77,zoneID=8046}},ends={{npcID=96528,x=0.304,y=0.774,zoneID=7745},{npcID=96528,x=0.316,y=0.762,zoneID=8046}},coords={x=0.47,y=0.524,source="quest_giver",zoneID=5042},questType="standard"},
[40227] = {id=40227,name="Bad Intentions",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Suramar is lost. Our leaders struck a dark bargain, accepting the Legion as our allies. We were meant to be heroes, guardians - the people resting here. We are not like them any more. I cannot live with them. But cut off from the Nightwell, we wither and devolve into a mindless existence. An existence without release or dignity, as you can see even here... I rejected both of these options and found myself here. I will find a third way.",starts={{npcID=99093,x=0.492,y=0.438,zoneID=7637}},ends={{npcID=99093,x=0.492,y=0.438,zoneID=7637}},coords={x=0.492,y=0.438,source="quest_giver",zoneID=7637},questType="standard"},
[40228] = {id=40228,name="Scout It Out",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="You've proven that a gnome can shoot a rifle, and that's no easy feat, but a true test of Addie's skill will be to see if she can track down an elusive beast. Rumor has it that a ravenous roc circles the basin, cursed by harpy magic, but no one's seen the beast up close. Take this flare, and shoot it into the sky once you've spotted the roc. When we see the signal, the huntin' party will rush in and help bring down that magnificent bird!",starts={{npcID=94409,x=0.4,y=0.522,zoneID=7503}},ends={{npcID=94409,x=0.4,y=0.522,zoneID=7503}},coords={x=0.4,y=0.522,source="quest_giver",zoneID=7503},questType="standard"},
[40229] = {id=40229,name="Step into the Dark",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="With the threat to my people quelled, I believe it is time to introduce you to my kin. Meet me at Stonedark Grotto, and you will see where we live.",questType="standard"},
[40230] = {id=40230,name="Oh, the Clawdacity!",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="The leader of the Cavemoss makrura, Clawdayshus , has been ordering raids into the Cavemoss village to steal the young for snacks. This isn't going to do at all. In order to prove their power, Murky and the tadpoles must destroy him as well! This is a job for murlocs. Mindmeld with Murky in his egg and show him how it's done!",starts={{npcID=98067,x=0.426,y=0.108,zoneID=7503}},ends={{npcID=98067,x=0.426,y=0.108,zoneID=7503}},coords={x=0.426,y=0.108,source="quest_giver",zoneID=7503},questType="standard"},
[40235] = {id=40235,name="Abrogator Arbitrator",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=6723,description="Da bums in Highmaul refuse to see dey are on da way out. Me, I'm gettin' while da gettin' is good. Da sooner youse bring me a bunch of Apexis Crystals , da sooner I can get off dis stupid island. Da amount required is very precise!",starts={{npcID=99180,x=0.57,y=0.586,zoneID=6723}},ends={{npcID=99180,x=0.57,y=0.586,zoneID=6723}},coords={x=0.57,y=0.586,source="quest_giver",zoneID=6723},questType="standard"},
[40236] = {id=40236,name="The Dawning Light",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7902,description="It was a miracle that you were able to survive, . It is with great sorrow that I have to say that Grand Master Hight was not so lucky. His spirit now rests with the ancestors. Now we must look to a new leader for our order, our broken temple. I have spoken with the other masters and we are all of one mind on this. We all agree that new leader should be you, . You have shown strength, wisdom, courage, and kindness beyond measure. Walk with us to the temple and we will announce our decision.",starts={{npcID=99181,x=0.512,y=0.544,zoneID=7902}},ends={{npcID=100438,x=0.514,y=0.486,zoneID=7902}},coords={x=0.512,y=0.544,source="quest_giver",zoneID=7902},questType="standard"},
[40237] = {id=40237,name="Work Work Stoppage",level=40,requiredLevel=40,faction="both",expansion=6,zoneID=6723,description="We've had enough! The working conditions in the Foundry are intolerable with all the fire and the ogron and the flames and the fire elementals and infernos and marauding adventurers! But especially the heat. I've had enough! Me and the boys are going to start a work stoppage but we need to hire some security muscle and the only goon from Highmaul I could get to agree to the job only takes payment in Apexis Crystals .",starts={{npcID=99183,x=0.58,y=0.586,zoneID=6723}},ends={{npcID=99183,x=0.58,y=0.586,zoneID=6723}},coords={x=0.58,y=0.586,source="quest_giver",zoneID=6723},questType="standard"},
[40238] = {id=40238,name="A Grim Equation",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8574,description="They were waiting for us when we crashed. It was all we could do to establish our small outpost. Even now they drain the souls of our fallen to fuel their attacks. Destroy their soul coffers . Free our comrades and let them join the Light. When you have finished, find Y'mera in the field. She has been sorely missed, but she will not have fallen. Of this I am certain.",starts={{npcID=121521,x=0.4,y=0.632,zoneID=8574}},ends={{npcID=121578,x=0.318,y=0.718,zoneID=8574}},coords={x=0.4,y=0.632,source="quest_giver",zoneID=8574},questType="standard"},
[40241] = {id=40241,name="Battle Bonds",level=10,requiredLevel=10,faction="horde",expansion=6,zoneID=7502,description="Do you like pets, ? I love pets. They're so cute! But what I really want is more things with which to play with them. I'm sure Serr'ah over at the Magical Menagerie has some ideas for fun toys. You should go talk to her!",questType="standard"},
[40242] = {id=40242,name="Mellok, Son of Torok",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40243] = {id=40243,name="Break Weapon Racks",level=10,requiredLevel=10,faction="none",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40244] = {id=40244,name="That Guy in the Costume",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Aye, when we were out huntin' on the coast, we ran into this ridiculous lad in in a costume. He says he's tryin ta blend in with the murlocs... but I'm pretty sure he's just not right in the head. One of ours stayed behind to keep an eye on him when we headed back to camp... mind checkin' it out? Ye can ask Tamara over there for a ride.",starts={{npcID=94409,x=0.4,y=0.522,zoneID=7503}},ends={{npcID=98067,x=0.426,y=0.108,zoneID=7503}},coords={x=0.4,y=0.522,source="quest_giver",zoneID=7503},questType="standard"},
[40247] = {id=40247,name="Asking a Favor",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8022,description="Caria Felsoul was one of our best... before she answered the Legion's foul call. She now wields the Aldrachi Warblades - the soul-rending armaments of the ancient race's greatest champion, who fell only to Sargeras himself. We sent a party to track Caria down, but we have not heard from them in some time. Jace has nearly repaired a Legion communicator so we can make contact - we need only a power source. Could you ask Khadgar for assistance? Our friends in this world are few.",questType="standard"},
[40249] = {id=40249,name="Vengeance Will Be Ours",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8022,description="We aren't going to get our forces anywhere near the Broken Shore without getting knocked out of the sky. I think it best if you handle this matter yourself - there are none among us more capable on the field of battle. Save Allari and her men if you can, but the Aldrachi Warblades will do far more for this war than warm bodies.",questType="standard"},
[40250] = {id=40250,name="Suramar - Demon Hunter Daily - Choice Reward Summary - 1",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[40251] = {id=40251,name="Vignette: Kethrazor",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[40253] = {id=40253,name="Stop Gul'dan!",level=8,requiredLevel=8,faction="both",expansion=6,zoneID=7814,description="After his defeat at the Black Temple, we brought Illidan's lifeless body here, to be interred forever within the Vault of the Wardens. Gul'dan has found his way through our defenses and is trying to steal the Betrayer's corpse. Even in death, Illidan's body can be used by the Burning Legion. Gul'dan CANNOT succeed.",questType="standard"},
[40254] = {id=40254,name="Forged in Fire",level=8,requiredLevel=8,faction="both",expansion=6,zoneID=7814,description="The fearsome demon, Immolanth, led a Legion army that conquered and eventually ruled a distant nexus world. Somehow, the Wardens imprisoned him, then kept him locked up in the chamber to our left. He is contained, but not for long. The demon's power is a valuable prize to any demon hunter who can defeat him. Whoever can do so will gain power beyond imagining. I believe that person could be you, .",questType="standard"},
[40255] = {id=40255,name="Between Us and Freedom",level=8,requiredLevel=8,faction="alliance",expansion=6,zoneID=7502,description="The last of our survivors have fought their way into the final chamber ahead. Only one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax. Kill him, take his power, and claim our freedom.",questType="standard"},
[40256] = {id=40256,name="Between Us and Freedom",level=8,requiredLevel=8,faction="horde",expansion=6,zoneID=7502,description="The last of our survivors have fought their way into the final chamber ahead. Only one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax. Kill him, take his power, and claim our freedom.",questType="standard"},
[40258] = {id=40258,name="Suramar - Demon Hunter Daily - Choice Reward Summary - 2",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[40260] = {id=40260,name="Suramar - Demon Hunter Daily - Choice Reward Summary - 3",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[40265] = {id=40265,name="A Touch of Magic",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="I always took great pride in my home... and my enchantments. Now it seems both have fallen into ruin. I can sense the power of a potent enchanter in you, . If you would but sprinkle a bit of magic dust on my once-enchanted belongings, I'm sure you can bring them to life again.",starts={{npcID=98367,x=0.394,y=0.426,zoneID=7541}},ends={{npcID=98367,x=0.394,y=0.426,zoneID=7541}},coords={x=0.394,y=0.426,source="quest_giver",zoneID=7541},questType="standard"},
[40266] = {id=40266,name="The Lost Advisor",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="You may as well assist me while you are here. I require a potion to be made, one that will set things right. I must conserve my energy until my task is finished, lest I become like these miserable wretches scrabbling at the cobblestones. There is coin in it for you, since I will not be needing it soon. The harpies around here cannot resist cliffthorn . It is what drew them to Tel'anor in the first place. You should find plenty just outside this building.",starts={{npcID=99065,x=0.456,y=0.406,zoneID=7637}},ends={{npcID=99093,x=0.492,y=0.438,zoneID=7637}},coords={x=0.456,y=0.406,source="quest_giver",zoneID=7637},questType="standard"},
[40267] = {id=40267,name="An Unexpected Message",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=267,description="Ah, Felo'melorn. I am familiar with this weapon. For ages the Council of Tirisfal attempted to recover the blade. Its control over the primal forces of fire would be devastating in the wrong hands. As luck would have it, an associate of mine, Archmage Modera has recently uncovered some information on this artifact. This crystal contains a message from her. I suggest you start your search there. The portal over there will bring you back to the city.",ends={{npcID=99398,x=0.286,y=0.372,zoneID=267}},questType="standard"},
[40268] = {id=40268,name="Neltharion's Vault Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40269] = {id=40269,name="Torok's Bluff Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40272] = {id=40272,name="7.0 Val'sharah - Village - Medium Treasure 001 - twh",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[40273] = {id=40273,name="7.0 Val'sharah - Temple of Elune - Medium Treasure 001 - bic",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[40296] = {id=40296,name="Tracking Quest: Corridor",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[40297] = {id=40297,name="Lyana Darksorrow",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,starts={{npcID=98801,x=0.308,y=0.592,zoneID=7637}},ends={{npcID=99514,x=0.308,y=0.592,zoneID=7637}},coords={x=0.308,y=0.592,source="quest_giver",zoneID=7637},questType="standard"},
[40300] = {id=40300,name="Tools of the Trade",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="I used to visit here before the barrier was raised. While the ruling council and the Grand Magistrix argued and politicked I watched the caretakers perform their rituals and venerate the dead. I would honor the spirits here one last time. I am headed to the tombs. If some of the sacred oils, burial shrouds, or incense survived the ages then bring them to me.",starts={{npcID=99093,x=0.492,y=0.438,zoneID=7637}},ends={{npcID=99483,x=0.472,y=0.334,zoneID=7637}},coords={x=0.492,y=0.438,source="quest_giver",zoneID=7637},questType="standard"},
[40301] = {id=40301,name="Vignette: Phalanx Captain",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[40306] = {id=40306,name="The Last Chapter",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="The next step of my journey requires a tome, but I find that I am still unable to idly sit by as this place continues to fall into disrepair. I will tidy up the memorials while you go fetch me the tome. It is called the Encyclopedia Botanica and you can find it in the library near the main plaza.",starts={{npcID=99483,x=0.472,y=0.334,zoneID=7637}},ends={{npcID=99575,x=0.45,y=0.308,zoneID=7637}},coords={x=0.472,y=0.334,source="quest_giver",zoneID=7637},questType="standard"},
[40307] = {id=40307,name="Glaive Circumstances",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="I came here on a mission to slay the demon eredar, Azoran. During my infiltration, I was shot down from my felbat and captured. I'm not going to mince words, . Azoran plans to use the Burning Legion command ship to destroy Dalaran. To stop him, I will need my warglaives that were lost during my fall from the sky. I would retrieve them myself, but I'm still weakened from my imprisonment. Search for the warglaives on the northern side of the crater, where I was shot down.",starts={{npcID=99514,x=0.308,y=0.592,zoneID=7637}},ends={{npcID=99514,x=0.308,y=0.592,zoneID=7637}},coords={x=0.308,y=0.592,source="quest_giver",zoneID=7637},questType="standard"},
[40308] = {id=40308,name="Fragments of Memory",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,starts={{npcID=245688,x=0.491,y=0.343,zoneID=7637}},ends={{npcID=99483,x=0.472,y=0.334,zoneID=7637},{npcID=99575,x=0.45,y=0.308,zoneID=7637},{npcID=100096,x=0.374,y=0.476,zoneID=7637}},coords={x=0.491,y=0.343,source="quest_giver",zoneID=7637},questType="standard"},
[40310] = {id=40310,name="Shipwrecked Captive",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7334,description="I spent my life playing the pet in other peoples battles. Now it's my time to be the pet tamer! Best part of being dead is I can do this forever!",starts={{npcID=98489,x=0.492,y=0.454,zoneID=7334}},ends={{npcID=98489,x=0.492,y=0.454,zoneID=7334}},coords={x=0.492,y=0.454,source="quest_giver",zoneID=7334},questType="standard"},
[40312] = {id=40312,name="A Timely Opportunity",level=1,requiredLevel=1,faction="alliance",expansion=6,zoneID=7503,mapID=650,description="Now that the whole \"spirit journey\" thing is out of the way we can get down to business.",questType="standard"},
[40315] = {id=40315,name="End of the Line",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="I cannot call Suramar my home any more, and I refuse to become a withered abomination. There is no place for me anymore, don't you understand? We only need one last ingredient to complete the elixir. You will help me, won't you?",starts={{npcID=99575,x=0.45,y=0.308,zoneID=7637}},ends={{npcID=99575,x=0.45,y=0.308,zoneID=7637}},coords={x=0.45,y=0.308,source="quest_giver",zoneID=7637},questType="standard"},
[40317] = {id=40317,name="Tree Destroyed",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[40319] = {id=40319,name="The Final Ingredient",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="The potion is complete, . Soon our journey will be over. There is one last thing I would have you do for me, then you shall have your reward. My wife's bow was kept here, but I have not been able to find it after searching everywhere. There is potent magic in it. I fear one of the restless spirits may have taken it, but it would take a powerful force to pick up an item such as this. Be careful.",starts={{npcID=99575,x=0.45,y=0.308,zoneID=7637}},ends={{npcID=99575,x=0.45,y=0.308,zoneID=7637}},coords={x=0.45,y=0.308,source="quest_giver",zoneID=7637},questType="standard"},
[40320] = {id=40320,name="Band of Blood Brothers",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="You are the one that Toryl was bellowing about? Perhaps you can help me. When I set out to search for Throndyr, I was not alone. Three vrykul loyal to Throndyr also accompanied me. As you can plainly see, I now stand alone. Find my kin, . I cannot bear to think that they also share Throndyr's fate.",starts={{npcID=99544,x=0.69,y=0.54,zoneID=7637},{npcID=102334,x=0.722,y=0.59,zoneID=7637}},ends={{npcID=99544,x=0.69,y=0.54,zoneID=7637},{npcID=102334,x=0.722,y=0.59,zoneID=7637}},coords={x=0.69,y=0.54,source="quest_giver",zoneID=7637},questType="standard"},
[40321] = {id=40321,name="Feathersong's Redemption",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="I must confess I was not entirely honest with you, . I meant to drink the potion and join my wife. And even she was taken from her rest... I cannot fail her again. I must live and do what I can to stop this coming storm to be worthy of joining her. Come, young one. Let us take care of the harpy matriarch and restore Tel'anor to its former glory. We cannot let this poison go to waste, eh?",starts={{npcID=99575,x=0.45,y=0.308,zoneID=7637}},ends={{npcID=100779,x=0.45,y=0.238,zoneID=7637}},coords={x=0.45,y=0.308,source="quest_giver",zoneID=7637},questType="standard"},
[40322] = {id=40322,name="Bloodhunt Highland Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40323] = {id=40323,name="Cave of the Blood Trial Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40324] = {id=40324,name="Arcane Communion",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="All of Kel'danath's experiments to connect with the withered failed, and some even made them more dangerous. Until he found Theryn . His arcane essence - the very soul of the shal'dorei - had been touched by something special. But what? By weaving my arcane essence together with Theryn 's, I can create an empathic bond. This communion will bare his soul to us all - or what's left of it. We need only to feed him mana, and lots of it, in order to begin.",starts={{npcID=97140,x=0.368,y=0.466,zoneID=7637}},ends={{npcID=97140,x=0.368,y=0.466,zoneID=7637}},coords={x=0.368,y=0.466,source="quest_giver",zoneID=7637},questType="standard"},
[40325] = {id=40325,name="Scenes from a Memory",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Theryn is at the mercy of his own mind. Whatever we find in there, it may be difficult to control. I will need your help to sort through the visions, so be ready for anything. With any luck, we will discover what makes Theryn special. And... whether there is anything left of who he used to be.",starts={{npcID=97140,x=0.368,y=0.466,zoneID=7637}},ends={{npcID=97140,x=0.368,y=0.466,zoneID=7637}},coords={x=0.368,y=0.466,source="quest_giver",zoneID=7637},questType="standard"},
[40326] = {id=40326,name="Scattered Memories",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,starts={{npcID=245328,x=0.303,y=0.397,zoneID=7637}},ends={{npcID=247694,x=0.21,y=0.523,zoneID=7637}},coords={x=0.303,y=0.397,source="quest_giver",zoneID=7637},questType="standard"},
[40327] = {id=40327,name="Testing the Metal",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,mapID=630,description="Alright, if we're going to get out of here, we're going to have to maneuver around the naga and the sea giants. The naga probably won't pose much trouble for someone of your skill, but those sea giants are strong beyond belief. Just get me out of this cave safely and I can find my own way home. Hopefully this armor Celea made for me will protect me long enough to see this through.",questType="standard"},
[40328] = {id=40328,name="A Fate Worse Than Dying",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="When the Burning Legion takes a prisoner, it is not an act of mercy. While death is the destruction of the mortal body... if you are captured by the Legion, they will seek to destroy your soul. The Burning Legion uses sacrificial souls to power their demonic machinations of war. The soul engine is where the harvested souls are collected and stored. Though countless have already perished in the soul engine, you may yet save those still alive inside. Hurry and release them before it is too late!",starts={{npcID=99890,x=0.3,y=0.694,zoneID=7637}},ends={{npcID=99890,x=0.3,y=0.694,zoneID=7637}},coords={x=0.3,y=0.694,source="quest_giver",zoneID=7637},questType="standard"},
[40329] = {id=40329,name="Battle Pet Tamers: Warlords",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7078,description="You have proven yourself before but the wilds of Draenor are on another level. Defeat tamers in the wilds to prove your pet battle supremacy: Cymre Brightblade in Gorgrond, Vesharr in Spires of Arak, Tarr the Terrible in Nagrand, Taralune in Talador, Gargra in Frostfire Ridge, or Ashlei in Shadowmoon Valley. You can also defeat a visiting tamer: Erris the Collector or Kura Thunderhoof in your garrison. By defeating them will show your dominance in Draenor.",starts={{npcID=79858,x=0.324,y=0.424,zoneID=7004},{npcID=85418,x=0.288,y=0.392,zoneID=7078}},ends={{npcID=79858,x=0.324,y=0.424,zoneID=7004},{npcID=85418,x=0.288,y=0.392,zoneID=7078}},coords={x=0.324,y=0.424,source="quest_giver",zoneID=7004},questType="standard"},
[40331] = {id=40331,name="Bite of the Sashj'tar",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="If I had been by Throndyr's side when he fought the naga, he might still be alive. These serpents will regret the day that they decided to slither from their watery hole! Killing them is not enough. No! I will honor Throndyr with a necklace of naga fangs!",starts={{npcID=99544,x=0.69,y=0.54,zoneID=7637},{npcID=102334,x=0.722,y=0.59,zoneID=7637}},ends={{npcID=99544,x=0.69,y=0.54,zoneID=7637},{npcID=102334,x=0.722,y=0.59,zoneID=7637}},coords={x=0.69,y=0.54,source="quest_giver",zoneID=7637},questType="standard"},
[40332] = {id=40332,name="Beach Bonfire",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Do not let... my body lie in... the mud. Set my flesh... aflame.",starts={{npcID=99559,x=0.69,y=0.54,zoneID=7637}},ends={{npcID=102334,x=0.722,y=0.59,zoneID=7637}},coords={x=0.69,y=0.54,source="quest_giver",zoneID=7637},questType="standard"},
[40333] = {id=40333,name="Spiritwind Summit Treasure",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40334] = {id=40334,name="Fisherman's Tonic",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="If you detest these serpents as much as we do, I ask that you continue the fight against them. That will mean fighting them in their watery domain. I don't see any gills on you, so we're going to have to concoct an old tonic used by vrykul fishermen. The ingredients are plentiful around here, taken that you do not mind picking through entrails.",starts={{npcID=102334,x=0.722,y=0.59,zoneID=7637}},coords={x=0.722,y=0.59,source="quest_giver",zoneID=7637},questType="standard"},
[40335] = {id=40335,name="Sashj'tar Accord DISABLED",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,description="As far as you can decipher, the naga are recruiting the sea giants on behalf of Queen Azshara.>",questType="standard"},
[40336] = {id=40336,name="Turning the Tidemistress",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="The Tidemistress has fallen back to the elven ruins and is licking her wounds. Her guard is undoubtedly protecting her. To best her, you will have to break her defenses. Construct a ballista using the parts that you salvaged and end her once and for all.",starts={{npcID=102410,x=0.706,y=0.488,zoneID=7637}},ends={{npcID=102410,x=0.706,y=0.488,zoneID=7637}},coords={x=0.706,y=0.488,source="quest_giver",zoneID=7637},questType="standard"},
[40339] = {id=40339,name="Candle of Command",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="You no come in yet! Give orders to other kobold on Throne of Ordering Around if you want in, then maybe we talk.",starts={{npcID=97130,x=0.552,y=0.418,zoneID=7503}},ends={{npcID=97130,x=0.552,y=0.418,zoneID=7503}},coords={x=0.552,y=0.418,source="quest_giver",zoneID=7503},questType="standard"},
[40341] = {id=40341,name="Throne of the Tides: Azshara's Power",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=5042,description="Wavespeaker Adelee tracked Sharas'dal to the Throne of Tides within the Abyssal Maw, then disappeared. , if we go after her, we are almost certainly walking into a trap. But the elements are with us, my friend. The naga will not expect a shaman of your caliber! Swim to the Throne of Tides to the Northwest, within the Abyssal Depths. I will join you once you are inside. Let's find our missing shaman and get that artifact!",starts={{npcID=96530,x=0.436,y=0.632,zoneID=5144},{npcID=96530,x=0.34,y=0.792,zoneID=7745},{npcID=96530,x=0.346,y=0.76,zoneID=8046}},ends={{npcID=96539,x=0.34,y=0.762,zoneID=7745},{npcID=96539,x=0.358,y=0.77,zoneID=8046},{npcID=96539,x=0.47,y=0.524,zoneID=5042}},coords={x=0.436,y=0.632,source="quest_giver",zoneID=5144},questType="standard"},
[40342] = {id=40342,name="Surprise the Sashj'tar",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,description="The naga are preoccupied with recruiting the sea giants for Queen Azshara's battles in other lands. Now is the time to strike!",questType="standard"},
[40345] = {id=40345,name="Burn the Candle at Both Ends",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Why you come back already? Have to wait until jobs are done or I no let you through! Go back to Throne of Ordering Around and make sure they finish!",starts={{npcID=97130,x=0.552,y=0.418,zoneID=7503}},ends={{npcID=97130,x=0.552,y=0.418,zoneID=7503}},coords={x=0.552,y=0.418,source="quest_giver",zoneID=7503},questType="standard"},
[40346] = {id=40346,name="Pilfered Provisions",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,description="The sea giants are sifting through the shipwrecks looking for treasure. Anything of value that can be found would be better off in the hands of the vrykul.",questType="standard"},
[40347] = {id=40347,name="Gurbog da Basher",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[40348] = {id=40348,name="Something in the Water",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="There is something fouling these waters, . We will need to purify the waters in order to restore balance to the elemental forces below this ruin. The magic here has warped the elementals and they are beyond restoration. Release their corrupted forms so that they may be reborn pure.",starts={{npcID=99788,x=0.434,y=0.416,zoneID=7637}},ends={{npcID=99788,x=0.434,y=0.416,zoneID=7637}},coords={x=0.434,y=0.416,source="quest_giver",zoneID=7637},questType="standard"},
[40349] = {id=40349,name="Pristine Violetglass Vessel",level=10,requiredLevel=10,faction="none",expansion=6,zoneID=7502,mapID=627,description="This artifact has been restored to a remarkably excellent condition, suitable for display in Dalaran's archaeology shop.",questType="standard"},
