[40469] = {id=40469,name="Final Preparations",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="We will need supplies for our trip into Suramar . We cannot exactly stop for refreshments at the gate with you two in tow, can we? The water gardens were a place to socialize and relax. Before the patrols arrived it was rather trivial to hide some mana wine for later retrieval. That's where you come in. Fetch some supplies and bring them to your friend, then meet me at the ruins north of the city. We will be ready to depart soon.",starts={{npcID=100192,x=0.414,y=0.606,zoneID=7637}},ends={{npcID=100185,x=0.342,y=0.562,zoneID=7637}},coords={x=0.414,y=0.606,source="quest_giver",zoneID=7637},questType="standard"},
[40470] = {id=40470,name="Quality of Life",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="I am afraid, . We're so close to home, so close to salvation... Astoril says he knows the rest of the way through and can get us there safely. I believe him, but you've come this far to see us safe. Will you see this through to the end?",starts={{npcID=100331,x=0.378,y=0.616,zoneID=7637}},ends={{npcID=97140,x=0.368,y=0.466,zoneID=7637},{npcID=115736,x=0.364,y=0.458,zoneID=7637}},coords={x=0.378,y=0.616,source="quest_giver",zoneID=7637},questType="standard"},
