[40495] = {id=40495,name="Ulthalesh, the Deadwind Harvester",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=10,description="The book says the Dark Riders were last seen in a place called Manor Mistmantle. If friend can find these riders, then can get Ulthalesh! Calydus will wait here and await your return. Find Ulthalesh, friend!",starts={{npcID=101097,x=0.376,y=0.316,zoneID=7875}},ends={{npcID=100323,x=0.774,y=0.362,zoneID=10}},coords={x=0.376,y=0.316,source="quest_giver",zoneID=7875},questType="standard"},
