[41724] = {id=41724,name="Heart of the Nightmare",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=7558,description="I know only that my husband is somewhere deeper in this twisted forest. He is still alive, but it remains to be seen if he is whole. Elune herself cannot protect Xavius if he is not.",starts={{npcID=103022,x=0.694,y=0.494,zoneID=7558}},ends={{npcID=104728,x=0.662,y=0.448,zoneID=7558}},coords={x=0.694,y=0.494,source="quest_giver",zoneID=7558},questType="standard"},
[41728] = {id=41728,name="The Defense of Tian Monastery",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=5785,description="Chen's recent report indicates that Tian Monastery is under attack! , they need your help. Go speak to Tak-Tak west of the main temple. He can get you there quickly.",starts={{npcID=100438,x=0.514,y=0.486,zoneID=7902}},ends={{npcID=104784,x=0.39,y=0.25,zoneID=5785}},coords={x=0.514,y=0.486,source="quest_giver",zoneID=7902},questType="standard"},
[41729] = {id=41729,name="Slowing the Spread",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=5785,description="Reinforcements. Just what we needed! Grandmaster, the monastery is under attack. The Legion is using a foul device known as a Fel Spreader to scorch the very earth we walk on with disgusting fel energy. Destroy those machines, and we can slow their efforts.",starts={{npcID=104745,x=0.382,y=0.258,zoneID=5785}},ends={{npcID=104850,x=0.42,y=0.254,zoneID=5785}},coords={x=0.382,y=0.258,source="quest_giver",zoneID=5785},questType="standard"},
[41730] = {id=41730,name="Desperate Strike",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7902,description="Good, your timing couldn't have been better, . These foul Legion creatures have invaded our sanctuary. They have no place here on our world. Kill every demon you see, .",starts={{npcID=104784,x=0.39,y=0.25,zoneID=5785}},ends={{npcID=104850,x=0.42,y=0.254,zoneID=5785}},coords={x=0.39,y=0.25,source="quest_giver",zoneID=5785},questType="standard"},
[41731] = {id=41731,name="Storm, Earth, and Fire",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=5785,description="Tian Monastery is in bad shape. Felspreader imps are torching the grounds. Fel spikes radiate foul energy, corrupting the nearby earth. And fel magic has seeped into the monastery's ale barrels, tainting the brew. Use your abilities to snuff the flames, shatter the spikes, and destroy the tainted barrels. Sigh... hundreds of years of the finest ale... ruined. I don't wish to hear any more of it. Just get it done.",starts={{npcID=104784,x=0.39,y=0.25,zoneID=5785}},ends={{npcID=104850,x=0.42,y=0.254,zoneID=5785}},coords={x=0.39,y=0.25,source="quest_giver",zoneID=5785},questType="standard"},
[41732] = {id=41732,name="The Hand of Keletress",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7902,description="The demons' leader is up ahead, taking prisoners it is said! This dire storm, we will weather... if we fight her together!",starts={{npcID=104850,x=0.42,y=0.254,zoneID=5785}},ends={{npcID=104744,x=0.454,y=0.25,zoneID=5785},{npcID=104744,x=0.524,y=0.578,zoneID=7902}},coords={x=0.42,y=0.254,source="quest_giver",zoneID=5785},questType="standard"},
[41733] = {id=41733,name="Rebuilding the Order",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7902,description="On behalf of all the students and teachers here at Tian Monastery, thank you, Grandmaster . You have a difficult task ahead of you to rebuild our order, but we stand with you. Let us head back to the Wandering Isle.",starts={{npcID=104744,x=0.454,y=0.25,zoneID=5785},{npcID=104744,x=0.524,y=0.578,zoneID=7902}},ends={{npcID=100438,x=0.514,y=0.486,zoneID=7902}},coords={x=0.454,y=0.25,source="quest_giver",zoneID=5785},questType="standard"},
[41734] = {id=41734,name="Champion: Taran Zhu",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7902,mapID=709,starts={{npcID=104984,x=0.512,y=0.494,mapID=709}},ends={{npcID=104984,x=0.512,y=0.494,mapID=709}},coords={x=0.512,y=0.494,source="quest_giver",mapID=709},questType="standard"},
