[41739] = {id=41739,name="Champion: Aegira",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7902,mapID=709,starts={{npcID=105226,x=0.552,y=0.572,mapID=709}},ends={{npcID=102855,x=0.312,y=0.406,mapID=709},{npcID=105226,x=0.552,y=0.572,mapID=709}},coords={x=0.552,y=0.572,source="quest_giver",mapID=709},questType="standard"},
[41740] = {id=41740,name="Tech It Up A Notch",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7745,description="There are many ways to commune with the elements. In their ingenuity, the goblins have found ways to imbue their mechanical devices with the energy of elemental spirits. I do not pretend to understand. But in our hour of need, we should not hesitate to embrace a diversity of options. We are fortunate to have at our disposal the services of the one they call \"Goldmine,\" whose unorthodox research may significantly augment our power. He waits nearby.",starts={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},coords={x=0.33,y=0.6,source="quest_giver",zoneID=7745},questType="standard"},
[41741] = {id=41741,name="Troops in the Field",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7745,description="It is time for us to test the strength of your newly summoned Lesser Elementals. Look at the Scouting Map and send your champions and troops on a routine scouting mission.",starts={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},coords={x=0.33,y=0.6,source="quest_giver",zoneID=7745},questType="standard"},
