[41748] = {id=41748,name="Champion: Ritssyn Flamescowl",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7875,mapID=717,starts={{npcID=104795,x=0.658,y=0.472,mapID=717}},ends={{npcID=104795,x=0.658,y=0.472,mapID=717}},coords={x=0.658,y=0.472,source="quest_giver",mapID=717},questType="standard"},
[41749] = {id=41749,name="Given to Corruption",level=10,requiredLevel=10,faction="horde",expansion=6,zoneID=7558,description="A final favor for an old friend, perhaps? My age-old companion, Varethos , has fallen to the nightmare's torment. We once worked in unison to protect this land. His close ties to the land brought him low in this dark hour. As with all who suffer this fate, there is no restoring him. Please, , bring him peace.",starts={{npcID=92783,x=0.662,y=0.446,zoneID=7558}},ends={{npcID=92783,x=0.662,y=0.446,zoneID=7558}},coords={x=0.662,y=0.446,source="quest_giver",zoneID=7558},questType="standard"},
