[41756] = {id=41756,name="Champion: Eredar Twins",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7875,mapID=717,starts={{npcID=106228,x=0.582,y=0.402,mapID=717}},ends={{npcID=106228,x=0.582,y=0.402,mapID=717}},coords={x=0.582,y=0.402,source="quest_giver",mapID=717},questType="standard"},
[41759] = {id=41759,name="An Unlikely Ally",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="Channeling the demonic gateway will require the assistance of someone with intimate knowledge of the Burning Legion. I know of such a warlock, though I imagine her blood still boils upon hearing my name. It might be best if you are the one to request her help.",starts={{npcID=104795,x=0.658,y=0.472,zoneID=7875}},ends={{npcID=105816,x=0.608,y=0.306,zoneID=7334}},coords={x=0.658,y=0.472,source="quest_giver",zoneID=7875},questType="standard"},
[41760] = {id=41760,name="Kel'danath's Legacy",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Kel'danath discovered something incredible - the power to subdue and even control the withered. I will pick up where my old friend left off. We shall see to it that he did not die in vain. Perhaps in the end we can even find peace for the wretches who have been left to a fate worse than death. I will need more subjects. Take Kel'danath's spellstone and use it to subdue more withered.",starts={{npcID=97140,x=0.368,y=0.466,zoneID=7637}},ends={{npcID=97140,x=0.368,y=0.466,zoneID=7637}},coords={x=0.368,y=0.466,source="quest_giver",zoneID=7637},questType="standard"},
[41761] = {id=41761,name="Winter Moose Roundup",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=7731,mapID=650,questType="standard"},
[41762] = {id=41762,name="Sympathizers Among the Shal'dorei",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Elisande's decision to welcome the Legion into Suramar earned her plenty of enemies, though only some of us were bold enough to openly defy her. We have allies in the city - we just don't know how many. I need you to make contact with a spell-fencer by the name of Silgryn . He is loyal to our cause, and has been lying in wait since our failed coup. He patrols the western edge of the city. Address him by name and tell him our cause is not lost!",starts={{npcID=97140,x=0.368,y=0.466,zoneID=7637}},ends={{npcID=105071,x=0.4,y=0.708,zoneID=7637}},coords={x=0.368,y=0.466,source="quest_giver",zoneID=7637},questType="standard"},
[41763] = {id=41763,name="Close Enough to Touch",level=10,requiredLevel=10,faction="horde",expansion=6,zoneID=7558,description="He is near, , I can feel it. We must search Shala'nir for Malfurion. If we do not find him soon, I fear he will be lost to me forever. I was unsure of your worth when first we met. I know now that you will not fail me. I am... grateful.",starts={{npcID=104728,x=0.662,y=0.448,zoneID=7558}},ends={{npcID=104799,x=0.578,y=0.386,zoneID=7558}},coords={x=0.662,y=0.448,source="quest_giver",zoneID=7558},questType="standard"},
[41764] = {id=41764,name="Walking in Their Footsteps",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=1638,description="Spiritwalkers maintain balance between the world of the living and the spirit realm. We can travel into the memories of the dead to glean clues about the past. The wards Ebonhorn maintained were placed long ago by heroes who fought the darkness. By walking in their footsteps, we may locate the wards and restore them. Igrul, the drogbar known as the Scalebane, was a true friend to Huln Highmountain. Use the Water of Vision to enter his memories and find where he placed the first ward.",starts={{npcID=125454,x=0.386,y=0.69,zoneID=7503}},ends={{npcID=125454,x=0.386,y=0.69,zoneID=7503}},coords={x=0.386,y=0.69,source="quest_giver",zoneID=7503},questType="standard"},
[41765] = {id=41765,name="[NYI] Hunting Wager",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7334,mapID=630,questType="world"},
[41767] = {id=41767,name="A Daring Rescue",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8105,description="The plan is a simple one, but it will require great effort on your part. Kira and I will summon the demonic gateway, but you will have to enter alone and recover the missing council members.",starts={{npcID=105018,x=0.556,y=0.372,zoneID=7875}},ends={{npcID=105018,x=0.556,y=0.372,zoneID=7875}},coords={x=0.556,y=0.372,source="quest_giver",zoneID=7875},questType="standard"},
[41768] = {id=41768,name="Soul Beacon",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7875,description="I have bound Shinfel's soul to her staff, allowing it to serve as an anchor in this world. When we perform the ritual of summoning, it will act as a beacon, guiding Shinfel through the Twisting Nether and back to our world.",starts={{npcID=105018,x=0.556,y=0.372,zoneID=7875}},ends={{npcID=105102,x=0.544,y=0.356,zoneID=7875}},coords={x=0.556,y=0.372,source="quest_giver",zoneID=7875},questType="standard"},
[41769] = {id=41769,name="Mad Ernie the Alchemist",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7558,description="If we have any hope of curing this curse, we need to know what kind of magic we're dealing with. I know of an alchemist who earned himself quite the reputation for his unconventional methods. Shunned from Gilneas long ago, I believe Mad Ernie has taken up residence in these lands. His knowledge may be the first step to breaking this curse.",starts={{npcID=105102,x=0.544,y=0.356,zoneID=7875}},ends={{npcID=104824,x=0.392,y=0.626,zoneID=7558}},coords={x=0.544,y=0.356,source="quest_giver",zoneID=7875},questType="standard"},
[41770] = {id=41770,name="The Skies Above",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8093,description="There has been no Windlord to lead the air elementals since the death of Al'Akir. The realm of Skywall has been thrown into turmoil. The throne of Al'Akir is Thunderaan's by right, but what remains of the prince's essence within Thunderfury is diminishing. If we do not move quickly, Thunderaan may be lost forever. Take the damaged Thunderfury to Vortex Pinnacle and speak with Celestos. Celestos was a loyal servant of Al'Akir and he will share our desire to see Thunderaan reborn.",starts={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},coords={x=0.33,y=0.6,source="quest_giver",zoneID=7745},questType="standard"},
[41771] = {id=41771,name="Recharging the Blade",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8093,description="You have recovered the Blessed Blade of the Windseeker, and with it you hold all that is left of the soul of Prince Thunderaan. Thunderfury can be restored, but it will require a rare essence known as the Heart of Skywall . Vortos, the Duke of the East Winds, possesses the heart... but he will not give it willingly. Vortos must be defeated, and the Heart of Skywall must be combined with the blade. Only then can Thunderaan return and claim the Throne of Four Winds.",questType="standard"},
[41772] = {id=41772,name="Ascendant of Flames",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8125,description="As we speak, an endless war rages for control of the Firelands. Of the two aspiring Firelords, Lord Smolderon hates mortals less. If we help him defeat his rival and ascend to Firelord, he may unite with us in return. The champions of the Earthen Ring have already made their way to the Firelands. Go and meet with Rehgar Earthfury and find a way to turn an old enemy into a new ally. If anyone can succeed at this impossible task, I have faith that it is you, Farseer. May the elements be with you.",starts={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},ends={{npcID=105207,x=0.272,y=0.828,zoneID=8125}},coords={x=0.33,y=0.6,source="quest_giver",zoneID=7745},questType="standard"},
[41773] = {id=41773,name="The Firelord's Command",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8125,description="Greetings, mortal. I am Scaldius, emissary of Lord Smolderon . I have just met with others from your order. They tell me that you will bring an end to those who oppose my master. This pleases Lord Smolderon . Pyroth and his minions defy my master's rule and so an example must be made of them. You will slay Pyroth and his champions! Nothing is more humiliating than death at the hands of a mortal. Do this and Lord Smolderon will grant you audience.",starts={{npcID=105055,x=0.27,y=0.824,zoneID=8125}},ends={{npcID=105120,x=0.49,y=0.304,zoneID=8125}},coords={x=0.27,y=0.824,source="quest_giver",zoneID=8125},questType="standard"},
[41774] = {id=41774,name="The Rival Lords of Fire",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=8125,mapID=738,description="You stand before the true Lord of the Firelands, mortal. This land is mine by right, claimed from the ashes of Ragnaros himself. However, there are still some who foolishly oppose my reign. I would take great pleasure in destroying their worthless souls, but I will not honor them with death by my hands. They must be humiliated for their insolence, and there is nothing more humiliating than being slain by a mere mortal. Amuse me shaman. Prove your worth and destroy my rivals!",questType="standard"},
[41775] = {id=41775,name="The Great Stonemother",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=5042,description="In order to unite the four Elemental Lords of Azeroth, you will need to seek out Therazane and convince her to join the cause of Azeroth. However, the Stonemother currently has her hands full battling a Twilight's Hammer resurgence in Deepholm. If we lend Therazane our aid she may agree to unite with the Earthen Ring against the Burning Legion. Journey to Therazane 's Throne in the heart of Deepholm. Aid her in defeating the Twilight's Hammer and convince her to join the defense of Azeroth!",starts={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},ends={{npcID=42465,x=0.564,y=0.122,zoneID=5042}},coords={x=0.33,y=0.6,source="quest_giver",zoneID=7745},questType="standard"},
[41776] = {id=41776,name="Return of the Windlord",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8093,description="With Thunderfury recharged, Prince Thunderaan can now return to the physical realm. In a moment, I will release my master's spirit from the blessed blade. When the ritual is complete, Skywall will once again have its Windlord.",questType="standard"},
[41780] = {id=41780,name="Doom and Gloom",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7558,description="Doom curses are serious business, so much so that many warlocks didn't deal in them for some time. The magic grows stronger as time goes on, eventually leading to death. Only the caster of the curse can remove it. I can craft an elixir that will slow its progression, but you'll need to collect an assortment of ingredients first.",starts={{npcID=104824,x=0.392,y=0.626,zoneID=7558}},ends={{npcID=104824,x=0.392,y=0.626,zoneID=7558}},coords={x=0.392,y=0.626,source="quest_giver",zoneID=7558},questType="standard"},
[41781] = {id=41781,name="Herding Goats",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7558,description="In case you haven't noticed, things are a bit hectic around here. Marl's doing a good job protecting the corn fields, but the commotion gave our goats quite the scare. They dashed out of their pen as soon as the fighting started, and are now running amuck! Round them up for me and I'll do my best to figure out how to handle the curse you're dealing with.",starts={{npcID=104824,x=0.392,y=0.626,zoneID=7558}},ends={{npcID=104824,x=0.392,y=0.626,zoneID=7558}},coords={x=0.392,y=0.626,source="quest_giver",zoneID=7558},questType="standard"},
[41782] = {id=41782,name="To The Hills",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=394,description="It is said that a fragment of Ursoc's spirit, his fury and rage, remained within the claws after his death. Only those who have attained mastery of discipline have any hope of wielding them without being overwhelmed by the bear lord's fury. But you are no novice, I can see that clearly. Very well, draw water from the moonwell on the northern edge of the grove then come find me. I'll await your arrival within the broken stump of Vordrassil in Northrend.",starts={{npcID=101259,x=0.392,y=0.186,zoneID=7558},{npcID=101259,x=0.398,y=0.006,zoneID=7846}},ends={{npcID=104535,x=0.512,y=0.368,zoneID=394}},coords={x=0.392,y=0.186,source="quest_giver",zoneID=7558},questType="standard"},
[41784] = {id=41784,name="Borrowed Time",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7875,description="Don't let the aroma deceive you, this concoction is mostly safe for consumption. Whoever is afflicted should drink the entire contents of the vial, every last drop! If the elixir works, the effects should be immediate. If not, well... just tell them they drink at their own risk, alright? Keep in mind, this will only weaken the curse, not cure it.",starts={{npcID=104824,x=0.392,y=0.626,zoneID=7558}},ends={{npcID=105102,x=0.544,y=0.356,zoneID=7875}},coords={x=0.392,y=0.626,source="quest_giver",zoneID=7558},questType="standard"},
[41785] = {id=41785,name="Finding Fizzlebang",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7541,description="I have reason to believe that Wilfred Fizzlebang's sister has made her way to Stormheim. If she has half his power, but at least twice his intelligence, then we just might succeed in summoning the eredar twins.",starts={{npcID=105102,x=0.544,y=0.356,zoneID=7875}},ends={{npcID=104855,x=0.392,y=0.422,zoneID=7541}},coords={x=0.544,y=0.356,source="quest_giver",zoneID=7875},questType="standard"},
[41787] = {id=41787,name="Someone Else's Mess",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7541,description="A confession alone won't be enough to clear my name. As long as those demons run amuck, people will blame their presence on me. Someone needs to clean up the mess that warlock made. I'd do it myself, but I can't be placed at the scene of the crime. You could banish them though. That would do the trick. Use this orb on newly summoned demons to send them right back where they came from - permanently!",starts={{npcID=104855,x=0.392,y=0.422,zoneID=7541}},ends={{npcID=104855,x=0.392,y=0.422,zoneID=7541}},coords={x=0.392,y=0.422,source="quest_giver",zoneID=7541},questType="standard"},
[41788] = {id=41788,name="Coercing a Confession",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7541,description="My location has to be kept secret, at least until I have proof of my innocence. Thanks to the legacy of my family name, any time some miserable warlock summons demons they can't control, I get the blame. The scene of my latest \"crime\" is a nearby cave, where unruly imps and other nasty demons are roaming free. Find the lousy warlock who's responsible, and get him to write a confession.",starts={{npcID=104855,x=0.392,y=0.422,zoneID=7541}},ends={{npcID=104855,x=0.392,y=0.422,zoneID=7541}},coords={x=0.392,y=0.422,source="quest_giver",zoneID=7541},questType="standard"},
[41790] = {id=41790,name="The First Trial of Ursol",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=394,description="The Legion... Ursol 's eyes begin to shine intensely> Yes... I remember clearly that day long ago when my brother fell. Countless demons fell beneath his claws until, through the overwhelming numbers of the enemy, he was overtaken. My brother was the true spirit of the bear! You must prove to me that the spirit of the bear resides within you as well.",starts={{npcID=104385,x=0.506,y=0.374,zoneID=394}},ends={{npcID=104385,x=0.506,y=0.374,zoneID=394}},coords={x=0.506,y=0.374,source="quest_giver",zoneID=394},questType="standard"},
[41791] = {id=41791,name="The Second Trial of Ursol",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=394,description="Ursoc never backed down from a battle, even when faced with overwhelming odds. If you would take up his claws you will show me that you possess the same courage. Your next trial will place you against an onslaught of my followers. Defeat all of the spirits and prove that you possess the courage of the bear!",starts={{npcID=104385,x=0.506,y=0.374,zoneID=394}},ends={{npcID=104385,x=0.506,y=0.374,zoneID=394}},coords={x=0.506,y=0.374,source="quest_giver",zoneID=394},questType="standard"},
[41792] = {id=41792,name="The Third Trial of Ursol",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=394,description="You've proven to me your strength and your courage, but do you possess the ability to apply yourself when it matters most? This final trial will reveal all.",starts={{npcID=104385,x=0.506,y=0.374,zoneID=394}},ends={{npcID=104385,x=0.506,y=0.374,zoneID=394}},coords={x=0.506,y=0.374,source="quest_giver",zoneID=394},questType="standard"},
[41793] = {id=41793,name="Lulubelle on Loan",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7875,description="What you plan to do is pretty risky, you know? Summoning one sister would be difficult enough, but both of them at once? That's just asking for trouble. Luckily, I'm up for the challenge. I'll help you and the rest of the council summon those demons, and hopefully restore pride to the Fizzlebang name.",starts={{npcID=104855,x=0.392,y=0.422,zoneID=7541}},ends={{npcID=105815,x=0.554,y=0.374,zoneID=7875}},coords={x=0.392,y=0.422,source="quest_giver",zoneID=7541},questType="standard"},
[41795] = {id=41795,name="Summoning the Sisters",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7875,description="It would be best to conduct the summoning on the outskirts of Dreadscar Rift. If things do not go as planned, at least the aftermath will be contained to a small island of land that floats above our order. Once the sisters have been summoned, use the Bloodstone to enslave them. I'll let the others know it's time to begin.",starts={{npcID=105815,x=0.554,y=0.374,zoneID=7875}},ends={{npcID=105951,x=0.554,y=0.376,zoneID=7875}},coords={x=0.554,y=0.374,source="quest_giver",zoneID=7875},questType="standard"},
[41796] = {id=41796,name="Selecting a Sixth",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7875,description="With the demon sisters under your control, you have managed to weaken Mephistroth's army and gain powerful allies for the council. Our work is not done, however. Dreadscar Rift will remain a target as long as the Burning Legion remains. If we wish to protect our new home, we must rebuild the council. Both Lulubelle and Kira have proven themselves worthy to join our ranks, though only one spot remains. As First of the Black Harvest, the choice is yours.",starts={{npcID=105951,x=0.554,y=0.376,zoneID=7875}},ends={{npcID=105951,x=0.554,y=0.376,zoneID=7875}},coords={x=0.554,y=0.376,source="quest_giver",zoneID=7875},questType="standard"},
[41797] = {id=41797,name="Recruiting The Troops",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7875,description="As her name suggests, Imp Mother Dyala is adept at summoning imps. While the council controls Dreadscar Rift, her services will be ours to use as we see fit. Speak to her if you wish to train a pack of imps.",starts={{npcID=106199,x=0.666,y=0.46,zoneID=7875}},ends={{npcID=106199,x=0.666,y=0.46,zoneID=7875}},coords={x=0.666,y=0.46,source="quest_giver",zoneID=7875},questType="standard"},
[41798] = {id=41798,name="Recruiting More Troops",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7875,description="As First of the council, you have acolytes devoted to helping any way they can. Recruiter Jared is in charge of screening candidates, only selecting those that possess the skills we desire. Speak to him now.",starts={{npcID=106199,x=0.666,y=0.46,zoneID=7875}},ends={{npcID=106217,x=0.612,y=0.516,zoneID=7875}},coords={x=0.666,y=0.46,source="quest_giver",zoneID=7875},questType="standard"},
[41799] = {id=41799,name="Minions of the Darkness",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=7503,description="Oenia Skyhorn was a legendary chieftain of her tribe. Though she crossed over to the spirit realm long ago, her presence is still felt all around us. Ebonhorn told me that Oenia placed a ward here to protect the people she cared for so deeply... perhaps from the specter of the Darkness. Use the Water of Vision to journey into her echoes. Worry not that this ritual might disturb her rest. A hero like Oenia would relish a chance to aid us in the present.",starts={{npcID=125459,x=0.57,y=0.462,zoneID=7503}},ends={{npcID=125459,x=0.57,y=0.462,zoneID=7503}},coords={x=0.57,y=0.462,source="quest_giver",zoneID=7503},questType="standard"},
[41800] = {id=41800,name="Servants of the Darkness",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=7503,description="The heroes of Highmountain's past placed wards to protect our land from the insidious Old Gods. The deeds of these noble champions kept us safe for thousands of years. We must not fail their memory. Huln Highmountain himself placed the ward here at Snowblind Mesa. It must be reactivated for us to have any hope of saving Ebonhorn. Enter the echo of Huln's spirit, and let his courage lead you to the location of this ward.",starts={{npcID=125466,x=0.532,y=0.64,zoneID=7503}},ends={{npcID=125466,x=0.532,y=0.64,zoneID=7503}},coords={x=0.532,y=0.64,source="quest_giver",zoneID=7503},questType="standard"},
[41802] = {id=41802,name="The Gates of Valor",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Ye'd not normally know it, but the terraced entrance to the vrykul's Halls o' Valor is a fine place for findin' ancient artifacts. Problem is, the place is just a big mess with demons at the time. Well, ye've not got much choice. If the disc isn't elsewhere in Stormheim, it most likely lies at the Gates of Valor. Good luck, .",starts={{npcID=103484,x=0.39,y=0.386,zoneID=7334},{npcID=103484,x=0.522,y=0.526,zoneID=7541},{npcID=103484,x=0.618,y=0.878,zoneID=7558},{npcID=103484,x=0.27,y=0.7,zoneID=7637}},ends={{npcID=103484,x=0.39,y=0.386,zoneID=7334},{npcID=103484,x=0.522,y=0.526,zoneID=7541},{npcID=103484,x=0.618,y=0.878,zoneID=7558},{npcID=103484,x=0.27,y=0.7,zoneID=7637}},coords={x=0.39,y=0.386,source="quest_giver",zoneID=7334},questType="standard"},
[41803] = {id=41803,name="Asking a Favor",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8022,description="Caria Felsoul was a bright student... and a Legion traitor. In her treason she was bestowed the Aldrachi Warblades, the soul-rending blades of the Aldrachi's greatest champion - they say he only finally fell to Sargeras himself. We sent a small force to find Caria, but we have not heard word since. Jace has a Legion communicator he believes we can use to reach them- we just need a power source. Perhaps you could see if Khadgar has anything we could use? I'm afraid our allies are few.",questType="standard"},
[41804] = {id=41804,name="Ask and You Shall Receive",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="A Legion communicator? Hmmmm. You know what, I think I have something in my lockbox upstairs that is just the ticket.",questType="standard"},
[41806] = {id=41806,name="Return to Jace",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="That crystallized soul should power your communicator long enough to reach your allies. I must urge you to be cautious, . If that device is of Legion origin, then you never know who among its creators might overhear your message. I'm sure your allies eagerly await your return.",questType="standard"},
[41807] = {id=41807,name="Establishing a Connection",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Yes, that will do nicely. Release its energy to activate the communicator - it should already be configured to contact Allari and her forces. If Caria is out there, we will find her, and we will make her suffer for her transgressions.",questType="standard"},
[41815] = {id=41815,name="Curse of the Necrodark",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=7731,description="It is clear that the Old Gods have long sought to control Highmountain. Their covetous desire speaks to the power of this land, and the strength of the spirits that echo through its peaks and valleys. They will not take our sacred mountain, . Not while I draw breath. With the Highmountain tribes united, and with Baine Bloodhoof at our side, we will defeat the Darkness... once and for all. Come. Let us take back the summit from the forces that would corrupt it.",starts={{npcID=108434,x=0.446,y=0.504,zoneID=7731}},coords={x=0.446,y=0.504,source="quest_giver",zoneID=7731},questType="standard"},
[41834] = {id=41834,name="The Masks We Wear",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Many nightborne had pinned their hopes on Thalyssra deposing the Grand Magistrix. Since she disappeared, dissenting voices have grown silent. We must spread the word, discreetly, among the populace. Ly'leth Lunastre will be a perfect ally in this. She is a socialite with many connections, and she is no friend of the Legion. Ly'leth hosts a masquerade party at her estate where rumors are traded like coin - and brandished like daggers. Let us invite ourselves in.",starts={{npcID=105071,x=0.4,y=0.708,zoneID=7637}},ends={{npcID=105342,x=0.434,y=0.788,zoneID=7637}},coords={x=0.4,y=0.708,source="quest_giver",zoneID=7637},questType="standard"},
[41839] = {id=41839,name="The Taken",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[41840] = {id=41840,name="Ice and Shadow",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=7503,description="We took down one of the Necrodark. Ebonhorn found that it held a shard of ice infused with shadow essence. Perhaps the villains are using these shards as a kind of talisman. I suggest you deprive them of their trinkets. I know little of such magics, but it seemed that Ebonhorn had a use for them in mind.",starts={{npcID=130423,x=0.564,y=0.892,zoneID=7503}},ends={{npcID=105213,x=0.568,y=0.92,zoneID=7503}},coords={x=0.564,y=0.892,source="quest_giver",zoneID=7503},questType="standard"},
[41841] = {id=41841,name="The Final Ward",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=7503,description="The Necrodark are readying their ritual to give physical form to the Darkness. They've sealed themselves inside and barred our way. The shards you brought me should provide the means to bring down the barrier. Once it is done, we have to act quickly. We must restore the final ward before the Darkness can manifest. Do not hesitate. The fate of Highmountain itself hangs in the balance.",starts={{npcID=105213,x=0.568,y=0.92,zoneID=7503}},ends={{npcID=105213,x=0.568,y=0.92,zoneID=7503}},coords={x=0.568,y=0.92,source="quest_giver",zoneID=7503},questType="standard"},
[41848] = {id=41848,name="Legion Invaders",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[41849] = {id=41849,name="The Iron Fist",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7541,description="It's time to send a rescue operation to the Gates of Valor, . I will prepare our troops and send them at once. We will need a sizable army to take on the massive Legion force in Stormheim. Grandmaster, go ahead whenever you are ready. I will send our forces to meet you in the field.",starts={{npcID=100438,x=0.514,y=0.486,zoneID=7902}},ends={{npcID=105045,x=0.63,y=0.594,zoneID=7541}},coords={x=0.514,y=0.486,source="quest_giver",zoneID=7902},questType="standard"},
[41850] = {id=41850,name="The Master of Swords",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7541,description="I got bad news fer ya - we don't have time to wait for reinforcements. They're sacrificin' prisoners now! Every minute we wait here jabberin' is another life on the line! First things first, my friend Sylara is being held captive in the camp just across the road. We need ta free her - she'll be a valuable ally. We've got ta move move move!",starts={{npcID=105045,x=0.63,y=0.594,zoneID=7541}},coords={x=0.63,y=0.594,source="quest_giver",zoneID=7541},questType="standard"},
[41854] = {id=41854,name="Brick By Brick",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7902,description="Da monks be free, and we put a thorn in dat eredar lady's side. I'm back wit my friends, and lookin' forward to sleepin' in a bed tonight. Let's go back ta da Wanderin' Isle. I've never been so excited ta see a turtle in my life.",ends={{npcID=100438,x=0.514,y=0.486,zoneID=7902}},questType="standard"},
[41856] = {id=41856,name="Legion Portal",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[41859] = {id=41859,name="Rescue Efforts",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[41863] = {id=41863,name="Vengeance Will Be Ours",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8022,description="Caria lies in the very heart of Legion territory - they'll see our forces immediately if we try to launch an all-out attack. Failure is not an option. However, if you go alone you might be able to slip by unnoticed long enough to avoid the brunt of the Legion army. Remember, - this is not a rescue mission. The power of the Aldrachi Warblades could tip the scales of this war in our favor; Allari and her men are expendable if need be.",questType="standard"},
[41874] = {id=41874,name="Talked to Tyrande to Start Events",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[41875] = {id=41875,name="Found First Clue",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[41876] = {id=41876,name="Umbraxis Tracker",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[41877] = {id=41877,name="Lady Lunastre",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Our friend Ly'leth contacted me. She requested that you meet her atop the Grand Promenade as it overlooks the city. Have your disguise ready just in case, .",starts={{npcID=97140,x=0.368,y=0.466,zoneID=7637}},ends={{npcID=107632,x=0.478,y=0.83,zoneID=7637}},coords={x=0.368,y=0.466,source="quest_giver",zoneID=7637},questType="standard"},
[41878] = {id=41878,name="The Gondolier",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="I need your help. The wine you so graciously distributed to the needy was the last of my reserves. Without more, these people here will risk succumbing to their thirst, and eventually becoming withered. I am dedicated to preventing this for as long as possible. There is a woman by the name of Deline who owns and operates a small delivery service out of her gondola. Find her, identify yourself as my messenger, and offer your aid in acquiring the next shipment.",starts={{npcID=107598,x=0.364,y=0.466,zoneID=7637}},ends={{npcID=107225,x=0.512,y=0.76,zoneID=7637}},coords={x=0.364,y=0.466,source="quest_giver",zoneID=7637},questType="standard"},
[41879] = {id=41879,name="TBD",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[41880] = {id=41880,name="Den of Shadows",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[41882] = {id=41882,name="Whispers of the Darkness",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=7503,description="Before our arrival, many of our own came to neutralize the threat here. They did not know what they were walking into. Our people are now suffering from the whispers. The Old Gods seek to corrupt them and turn them against their own. Wake them from their stupor. Free them from the whispers any way you can.",starts={{npcID=97662,x=0.404,y=0.716,zoneID=7503}},ends={{npcID=105213,x=0.568,y=0.92,zoneID=7503}},coords={x=0.404,y=0.716,source="quest_giver",zoneID=7503},questType="standard"},
[41884] = {id=41884,name="Dark Tales",level=40,requiredLevel=40,faction="horde",expansion=6,zoneID=7503,description="Spiritwalker Ebonhorn is stable... for now. He once told me of the wards he maintains against the Old Gods. He placed them at key locations around this mountain, but kept them hidden from mortal eyes--even my own. Incapacitated like this, his wards cannot hold back the evil ones. No doubt this is the reason for their attack. To find the wards, we must enter the echoes of Ebonhorn's past and commune with the spirits we find there. Meet me in Riverbend, . It is there our search begins.",questType="standard"},
[41888] = {id=41888,name="Allegiance of Flame",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7745,description="My rivals lay dead and there are none within the Firelands who dare oppose my rule! As promised, I will unite with the other Elemental Lords in the defense of Azeroth. The armies of the Firelands will scorch the battlefield with the corpses of our enemies! Go now, mortal. Tell your Earthen Ring that the Firelord himself stands with you!",starts={{npcID=105120,x=0.49,y=0.304,zoneID=8125},{npcID=105594,x=0.49,y=0.304,zoneID=8125}},ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},coords={x=0.49,y=0.304,source="quest_giver",zoneID=8125},questType="standard"},
[41889] = {id=41889,name="Dazed of the Past",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Let's begin crafting this mount armor, shall we?",questType="standard"},
[41890] = {id=41890,name="Dark Side of the Moon",level=10,requiredLevel=10,faction="horde",expansion=6,zoneID=7558,description="Xavius has been this way, but his destination is unclear. The Nightmare smothers my mind! These refugees tell of an ancient Moonwell hidden in the ruins ahead. If it is uncorrupted, it will give me the focus I need. By Elune's light, we will find my husband yet. Meet me at the Moonwell at once, .",starts={{npcID=103022,x=0.694,y=0.494,zoneID=7558}},ends={{npcID=104885,x=0.668,y=0.5,zoneID=7558}},coords={x=0.694,y=0.494,source="quest_giver",zoneID=7558},questType="standard"},
[41893] = {id=41893,name="Given to Corruption",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=7558,description="A final favor for an old friend, perhaps? My age-old companion, Varethos , has fallen to the nightmare's torment. We once worked in unison to protect this land. His close ties to the land brought him low in this dark hour. As with all who suffer this fate, there is no restoring him. Please, , bring him peace.",starts={{npcID=92783,x=0.662,y=0.446,zoneID=7558}},ends={{npcID=92783,x=0.662,y=0.446,zoneID=7558}},coords={x=0.662,y=0.446,source="quest_giver",zoneID=7558},questType="standard"},
[41900] = {id=41900,name="A Promise of Earth",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7745,description="Deepholm thanks you, shaman. The Twilight's Hammer has always sought dominion over my kingdom, but this latest threat was far greater than their previous efforts. For your service to the elements of earth, I will pledge my armies to the Earthen Ring in the defense of Azeroth. I have no love for the mortal races, but this world is not the Burning Legion's to destroy. Tell your Earthen Ring that Therazane the Stonemother stands with them!",starts={{npcID=42465,x=0.564,y=0.122,zoneID=5042}},ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},coords={x=0.564,y=0.122,source="quest_giver",zoneID=5042},questType="standard"},
[41901] = {id=41901,name="Oath of the Windlord",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7745,description="You have my thanks, mortal for bringing about my rebirth. However, thanks alone would not be honorable. I know that the Earthen Ring seeks to save Azeroth from the Burning Legion. I will pledge my sword, and the armies of Skywall to the aid of Azeroth. When the time for battle arrives, and the Earthen Ring stands upon the battlefield against the Burning Legion, the Windlord shall stand with you.",ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},questType="standard"},
[41905] = {id=41905,name="Report from Tian Monastery",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7902,description="We have heard from all our temples on Pandaria, except for one. We dispatched a message by bird to Tian Monastery, but no answer has yet arrived. This silence is quite unusual. Grandmaster, I recommend that we send our champion, Chen Stormstout, to scout the situation at once.",starts={{npcID=100438,x=0.514,y=0.486,zoneID=7902}},ends={{npcID=100438,x=0.514,y=0.486,zoneID=7902}},coords={x=0.514,y=0.486,source="quest_giver",zoneID=7902},questType="standard"},
[41907] = {id=41907,name="Appropriations",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7902,description="I have come to lend my help to the Order of the Broken Temple. My job is to create a solid base of operations around here. Right now, we have wounded to tend and bellies to feed. After this, we can worry about building our defenses. Lao Shu is in charge of our supply inventory. Go and speak with him now in the inn.",starts={{npcID=104744,x=0.454,y=0.25,zoneID=5785},{npcID=104744,x=0.524,y=0.578,zoneID=7902}},ends={{npcID=98945,x=0.49,y=0.584,zoneID=7902}},coords={x=0.454,y=0.25,source="quest_giver",zoneID=5785},questType="standard"},
[41909] = {id=41909,name="Tracking the Tideskorn",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7902,description="We have sent scouts to search for our kidnapped allies, and our efforts may have finally paid off. They've tracked them to the vrykul homeland of Stormheim, but the unfamiliar territory has slowed our progress and we're in danger of losing the trail. I suggest that we send our champions immediately to assist with the tracking effort.",starts={{npcID=104744,x=0.454,y=0.25,zoneID=5785},{npcID=104744,x=0.524,y=0.578,zoneID=7902}},ends={{npcID=104744,x=0.454,y=0.25,zoneID=5785},{npcID=104744,x=0.524,y=0.578,zoneID=7902}},coords={x=0.454,y=0.25,source="quest_giver",zoneID=5785},questType="standard"},
[41910] = {id=41910,name="Freya's Spring",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7902,description="First, we need water from Freya's Spring. Once a year, on the first day of solstice, the sun hits the white-capped summit of the highest peak in Highmountain. The melting snow runs through a ravine and collects in a crystalline pool. Some say these waters grant eternal youth. Silly stories if you ask me, but we will need this rare, purified water for our brew. I suggest sending our champions to collect us a sample, for your skills will be needed elsewhere.",starts={{npcID=102996,x=0.441,y=0.659,zoneID=7541}},ends={{npcID=100438,x=0.514,y=0.486,zoneID=7902}},coords={x=0.441,y=0.659,source="quest_giver",zoneID=7541},questType="standard"},
[41911] = {id=41911,name="Amaranthine Hops",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7558,description="The hops for our brew must be a very specific, and they will also be hard to acquire. Amaranthine Hops only grow in the realm known as the Emerald Dream, meaning we can only acquire this ingredient from a druid. There is one such supplier from whom I receive this item, but she may ask for something in exchange.",starts={{npcID=102996,x=0.441,y=0.659,zoneID=7541}},ends={{npcID=100438,x=0.514,y=0.486,zoneID=7902}},coords={x=0.441,y=0.659,source="quest_giver",zoneID=7541},questType="standard"},
[41915] = {id=41915,name="The Master's Legacy",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="You work for a murderer and a thief. That design he wants? It is called the magistrix cut, and it was perfected by my husband. He was killed by Lespin for his secret. I had him entombed in a small cave north of the city, for we could not make the trip to Tel'anor. Buried with him is a tome that contains the secrets of the design. Retrieve the design and keep it out of his hands!",starts={{npcID=104394,x=0.416,y=0.6,zoneID=7637}},ends={{npcID=103181,x=0.416,y=0.71,zoneID=7637}},coords={x=0.416,y=0.6,source="quest_giver",zoneID=7637},questType="standard"},
[41916] = {id=41916,name="A Better Future",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="We must move quickly, . I must save as many of my people as I can before the attack begins. Word has gotten out in the city that there is a safe haven with us and some no longer fear exile. Venture into the Grand Promenade, champion. Find those willing to join us and let them know it is time they made their escape.",starts={{npcID=114908,x=0.416,y=0.516,zoneID=7637}},ends={{npcID=114908,x=0.416,y=0.516,zoneID=7637}},coords={x=0.416,y=0.516,source="quest_giver",zoneID=7637},questType="standard"},
[41917] = {id=41917,name="Vignette: Bear Cub",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[41918] = {id=41918,name="The Dreamer Returns",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7846,description="Arch Druid Greathoof will be expecting word on the success of our mission, but I'm afraid I must ask you to return alone. I can't rest knowing that Xavius has Lord Ursoc in his clutches. Just the thought of it makes me shake with rage! I'll find where he has been taken if I have to search every corner of Azeroth! Our paths will cross again, . Be sure of it.",starts={{npcID=104535,x=0.512,y=0.368,zoneID=394}},ends={{npcID=101195,x=0.448,y=0.516,zoneID=7846}},coords={x=0.512,y=0.368,source="quest_giver",zoneID=394},questType="standard"},
[41919] = {id=41919,name="The Shadows Reveal",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="The Fangs of the Devourer are wielded by Akaari Shadowgore, one of Kil'Jaeden's personal assassins. Every attempt on her life ends the same... she's gone before we even arrive. But not this time. We've been working with these contacts to find Akaari so we can finally take the Fangs for our own purposes. Go to each contact and tell them \"The shadows reveal.\" See what they know.",questType="standard"},
[41920] = {id=41920,name="A Matter of Finesse",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="A rune of portals ?! Who does Val'zuun think he is? It's worth the price, but those runes aren't exactly easy to come by. Unless... Archmage Celindra , the Kirin Tor's portal master, has a study in the center of town. We rogues aren't particularly welcome there, nor would she simply hand a rune over even if we were... But who said anything about asking?",questType="standard"},
[41921] = {id=41921,name="Closing In",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="The Legerdemain Lounge isn't far from here. We have agents nearby who can secure the area. Come prepared for a fight. Akaari won't go down easily.",questType="standard"},
[41922] = {id=41922,name="Traitor!",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="That lying demon SCUM! I should have known. Let's show Val'zuun what happens to people who dare cross the Uncrowned.",questType="standard"},
[41924] = {id=41924,name="Fangs of the Devourer",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="If you spare me I can use the rune of portals you provided to open a gateway to Akaari's citadel in the Twisting Nether. Of course, killing the Legion's master assassin in her own domain will be no simple feat, but surely the Fangs of the Devourer are worth the risk, no? Val'zuun smiles.> I will guide you through the citadel once you arrive, but you will have to defeat Akaari on your own.",questType="standard"},
[41932] = {id=41932,name="Legion Portal",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[41933] = {id=41933,name="Legion Portal",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[41934] = {id=41934,name="The Brand of Damnation",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8125,description="I require a symbol of my dominion as Firelord. A weapon that will strike fear into the hearts of all who dare to oppose my rule! Deep within the den of the Cinderweb, there is an ancient spear born from within the heart of the Firelands. Emberscar is a living weapon whose wicked power is beyond mortal comprehension. Prove your strength and claim Emberscar in my name! If you survive, perhaps I will aid the feeble races of humanity against the Burning Legion.",starts={{npcID=105120,x=0.49,y=0.304,zoneID=8125}},ends={{npcID=105120,x=0.49,y=0.304,zoneID=8125}},coords={x=0.49,y=0.304,source="quest_giver",zoneID=8125},questType="standard"},
[41942] = {id=41942,name="Legion Portal",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[41945] = {id=41945,name="Tianji of the Ox",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7902,description="Greetings, Grandmaster. Beside me is the Scouting Map. From it, you can direct our allies to carry out vital assignments across the Broken Isles. The first task is critical. Tianji, a renowned trainer in the ox school style of martial combat, was on her way to the Broken Isles when she was attacked. I suggest we send Chen Stormstout to help her. He will be uniquely suited to this task.",starts={{npcID=99179,x=0.528,y=0.596,zoneID=7902}},ends={{npcID=99179,x=0.528,y=0.596,zoneID=7902}},coords={x=0.528,y=0.596,source="quest_giver",zoneID=7902},questType="standard"},
[41946] = {id=41946,name="Building Our Troops",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7902,description="Our champions acquired the talents of Recruiter Tianji, a famed monk skilled in the school of the ox. She is known for her brewmaster techniques, and is a valuable addition to the temple. She is already beginning to train a new batch of pupils. Speak to her now and train an initiate of the ox.",starts={{npcID=99179,x=0.528,y=0.596,zoneID=7902}},ends={{npcID=99179,x=0.528,y=0.596,zoneID=7902}},coords={x=0.528,y=0.596,source="quest_giver",zoneID=7902},questType="standard"},
[41947] = {id=41947,name="Legion Portal",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[41951] = {id=41951,name="Legion Portal",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[41952] = {id=41952,name="Rescue Efforts",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[41954] = {id=41954,name="Rescue Efforts",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[41957] = {id=41957,name="The Vindicator's Plea",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="I've obtained a request from Vindicator Boros in Dalaran asking for our help. He has recovered a soldier who escaped from the Legion! He was injured and his wounds are resisting every healing treatment available to them. Normally this would fall to an acolyte to handle, but the soldier mentioned T'uure in his delirium! I thought the holy gem was lost! You are strong with the Light, perhaps you can succeed where they can't? If you need it, Brother Larry can provide you with a flight to Dalaran.",starts={{npcID=101314,x=0.79,y=0.41,zoneID=85}},coords={x=0.79,y=0.41,source="quest_giver",zoneID=85},questType="standard"},
[41959] = {id=41959,name="Legion Portal",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[41960] = {id=41960,name="Rescue Efforts",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[41966] = {id=41966,name="House Call",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="I thought Barrem was lost to us after the tragedy at Broken Shore, Light knows we lost far too many good soldiers just like him there. I was shocked to see he was still alive when one of our patrols arrived carrying him. They found him floating in the sea with wounds that would kill any lesser draenei. There is something about those wounds that resists everything we've done to treat them. Please, , as a brother in the Light I ask you to do all that you can to help him to recover.",questType="standard"},
[41967] = {id=41967,name="Out of the Darkness",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7543,description="Alora and I were were able to escape through one of the Legion's portals back to Azeroth but that's about as far as our luck got us. The portal put us on a small isle somewhere to the west of the Broken Shore. They saw us quickly and we made a run for the protection of the water. As I attempted to leap to safety, I was wounded. But Alora ... she tripped and I watched them drag her back. Rescue her, please! I'll mark where the camp is on your map, just don't let her go through that ordeal again.",ends={{npcID=105684,x=0.34,y=0.338,zoneID=7543}},questType="standard"},
[41978] = {id=41978,name="A Strong Defense",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[41979] = {id=41979,name="Rescue Efforts",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[41981] = {id=41981,name="Traversing the Heavens",level=10,requiredLevel=10,faction="none",expansion=6,description="If you are not opposed, , I would accompany you on your journey through Skywall. There are wonders here that my eyes have never before beheld, and it would be my great honor to join you. Our quest to resurrect the mighty Thunderaan and unite the four great elemental lords will be no easy task. Lead the way, Farseer, and I shall follow.",questType="standard"},
[41983] = {id=41983,name="[NYI] Bear Necessities",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7503,mapID=650,questType="world"},
[41986] = {id=41986,name="REUSE",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7731,mapID=650,questType="standard"},
[41987] = {id=41987,name="Garn",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[41988] = {id=41988,name="A Strong Defense",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[41989] = {id=41989,name="Blood of My Blood",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,mapID=680,description="As my darling has demonstrated, Elisande's decision to bring down the shield has sown unrest among the nightborne. Loyalists and demons march together in the streets. Fear and distrust grip our hearts. Family turns against family. I will help Thalyssra stir a new rebellion, but first we must deal with Anarys. I do not wish to spill the blood of my blood - only to help see reason. Anarys is likely brooding over our father's memorial. Bring to me alive.",starts={{npcID=105342,x=0.434,y=0.788,mapID=680}},ends={{npcID=105342,x=0.434,y=0.788,mapID=680}},coords={x=0.434,y=0.788,source="quest_giver",mapID=680},questType="standard"},
[41991] = {id=41991,name="Rescue Efforts",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[41993] = {id=41993,name="Salvation From On High",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7543,description="I was serving aboard the airship that crashed on the way to the Broken Shore. I must have blacked out as the next thing I remember was being jolted awake. I was on a broken land and above me stood a man'ari carrying a staff of darkened crystal. There is no mistaking it, that staff was T'uure! All my life I've heard stories about how T'uure flowed with the healing power of the light. Somehow the crystal has been darkened by Man'ari. We must get it back and restore it to its pure form!",starts={{npcID=105684,x=0.34,y=0.338,zoneID=7543}},ends={{npcID=106011,x=0.336,y=0.332,zoneID=7543}},coords={x=0.34,y=0.338,source="quest_giver",zoneID=7543},questType="standard"},
[41994] = {id=41994,name="Legion Portal",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[41997] = {id=41997,name="A Strong Defense",level=7,requiredLevel=7,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[42000] = {id=42000,name="Seeker of Truth",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="You may be familiar with Orik Trueheart . He has devoted his time after the Northrend campaign to learning more about Tyr. Orik has evidence of a powerful shield crafted by Tyr long ago. With the help of the Sunwalkers, we may finally be able to seek it out. Please speak to him immediately.",questType="standard"},
[42001] = {id=42001,name="Aluneth, Greatstaff of the Magna",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7879,description="Aluneth... a powerful and dangerous weapon. If tales are to be believed, Aluneth is actually the name of a very old and very powerful arcane entity, somehow bound to a staff through ancient magic. When Aegwynn relinquished Aluneth many years ago, it was entrusted to Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away in secret. Only they would know exactly where it was taken. The dragon Kalec may be our best chance. He now resides on the Council of Six.",questType="standard"},
[42002] = {id=42002,name="To Northrend",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=495,description="Naturally I've done some legwork already. I believe this Gorvold is buried at Shield Hill in the Howling Fjord. Tahu can help locate the grave, and with a short ritual we should have our answers! Meet us at Shield Hill in the Howling Fjord and we'll move on to the next step.",ends={{npcID=105724,x=0.568,y=0.786,zoneID=495}},questType="standard"},
[42003] = {id=42003,name="Kept Secret, Kept Safe",level=1,requiredLevel=1,faction="both",expansion=6,description="With the scrolls in hand, now you must set to the task of finding the staff. When Aegwynn relinquished it many years ago, it was entrusted to Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away from the hands of men. Only they would know exactly where it was taken, or how to retrieve it. The dragon Kalec may be our best chance. He now resides upon the Council of Six in Dalaran. Seek him, and your answers, there.",questType="standard"},
[42005] = {id=42005,name="The End of the Saga",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Ye should read the saga yerself, it's right here. We're here to speak to the spirit of that vrykul I spoke of. Tahu Sagewind is a powerful Seer and he should be able to bring his spirit back. It will be up to us to convince him to speak. You should speak with Tahu so we can get started.",starts={{npcID=105724,x=0.568,y=0.786,zoneID=495}},coords={x=0.568,y=0.786,source="quest_giver",zoneID=495},questType="standard"},
[42006] = {id=42006,name="A New Threat",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=65,description="If you seek the Nexus, be wary. There are strange happenings in Coldarra, and it would be best to understand them before proceeding. During my last visit to Dragonblight, I sensed unusual energies from the Azure Dragonshrine. Since this place was integral to Malygos' plans during the Nexus War, whatever is there may explain the current state of the Nexus. Here, take this image crystal. I must remain in Dalaran on Kirin Tor business, so we will speak through it. Good luck.",ends={{npcID=248398,x=0.567,y=0.691,zoneID=65}},questType="standard"},
[42007] = {id=42007,name="A Forgotten Enemy",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=65,description="The device still hums with power. It must have been abandoned not long ago. The nearby switch appears to activate it.",starts={{npcID=248398,x=0.567,y=0.691,zoneID=65}},coords={x=0.567,y=0.691,source="quest_giver",zoneID=65},questType="standard"},
[42008] = {id=42008,name="Eyes of the Dragon",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="You should travel at once to Coldarra in Borean Tundra, . There, I would recommend you scout out a few key locations and report back to me. I know the area well, and should be able to tell you how to proceed. Make haste!",questType="standard"},
[42009] = {id=42009,name="Harnessing the Arcane",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=7502,description="The energy from Aluneth lashes out from within the weakened Nexus Vault. We may be able to use this raw, chaotic energy to our advantage. If we can harness this energy and feed it into the Surge Needles, it should cause a rather... destructive reaction.",questType="standard"},
[42010] = {id=42010,name="Arcane Unleashed",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=7502,mapID=627,description="You have the power you need to destroy the Surge Needles. At the location of the breaches where the Surge Needles pierce the ground, there will be a large concentration of void energy. Focus the power of Aluneth into these points. The reaction should cause an overload, destroying the Surge Needle above. You must act quickly. The Ethereum won't sit idly by as you lay waste to their machinations.",questType="standard"},
[42011] = {id=42011,name="The Nexus Vault",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8094,description="If the Ethereum managed to capture Azuregos, then they are more powerful than I imagined. We have not always seen eye to eye, Azuregos and I, but he is still my kin. Since you seek to put an end to the ethereals and claim Aluneth, I ask that you also free my brother from their grip. With the Surge Needles destroyed, the shield has dissipated. The Nexus awaits, .",questType="standard"},
[42017] = {id=42017,name="Shrine of the Truthguard",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=139,description="We'll be flying straight to the island. My friend said that the warrior who came here before us never entered the shrine itself, since they were after one of the tombs. If a vrykul hero couldn't enter the shrine, I bet it's still protected by Tyr's power. I'm thinkin' we have a good shot at this. My pal Cato will meet us there. We might be needin' the talents of a good healer!",questType="standard"},
[42031] = {id=42031,name="Dire Growth",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7846,description="Naralex asks for you to join him. He is ready to analyze the sample that he brought back from Shaladrassil.",starts={{npcID=98002,x=0.528,y=0.514,zoneID=7846}},ends={{npcID=101195,x=0.448,y=0.516,zoneID=7846}},coords={x=0.528,y=0.514,source="quest_giver",zoneID=7846},questType="standard"},
[42032] = {id=42032,name="Sampling the Nightmare",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7846,description="There is still so much that we don't know about the Nightmare. Before we can fight it, we must understand how it spreads. Let us send our champions to the roots of Shaladrassil in Val'sharah, and ask them to bring back samples to study.",starts={{npcID=98002,x=0.528,y=0.514,zoneID=7846}},ends={{npcID=98002,x=0.528,y=0.514,zoneID=7846}},coords={x=0.528,y=0.514,source="quest_giver",zoneID=7846},questType="standard"},
[42033] = {id=42033,name="Malorne's Refuge",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="I see... it is as we have always feared. The Emerald Nightmare has found our world. We must call upon the ancient god, Malorne. Travel southeast to the shrine at Malorne's Refuge. There, we druids have kept a sacred relic for thousands of years, a gift from the white stag himself. I already sent Broll Bearmantle ahead to give word of your arrival.",starts={{npcID=101195,x=0.448,y=0.516,zoneID=7846}},ends={{npcID=105903,x=0.57,y=0.712,zoneID=7558}},coords={x=0.448,y=0.516,source="quest_giver",zoneID=7846},questType="standard"},
[42034] = {id=42034,name="Grip of Nightmare",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="Most of the druids were able to escape, but the shrine is still swarming with enemies. The shrine's leader, Sylendra Gladesong, stayed behind to recover Malorne's Idol. We must go back and help her.",starts={{npcID=105903,x=0.57,y=0.712,zoneID=7558}},ends={{npcID=105948,x=0.568,y=0.714,zoneID=7558}},coords={x=0.57,y=0.712,source="quest_giver",zoneID=7558},questType="standard"},
[42035] = {id=42035,name="Tracking the Enemy",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="The Idol may be stolen, but there is still hope. While I was trapped at the shrine, I saw the satyr raiders make off with the relic. Their tracks will still be fresh. With our heightened senses, we may still be able to pick up their trail. We must follow their signs through the forest and recover the Idol!",starts={{npcID=105948,x=0.568,y=0.714,zoneID=7558}},ends={{npcID=106883,x=0.598,y=0.75,zoneID=7558}},coords={x=0.568,y=0.714,source="quest_giver",zoneID=7558},questType="standard"},
[42036] = {id=42036,name="Idol of the Wilds",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7846,description="We were able to wrest a confession out of this one. We know that their leader took the idol into Moonclaw Vale, but he could be hiding anywhere. Surely one of these satyrs will know where it was taken. Get the information out of these satyrs, even if it's the last thing they do.",starts={{npcID=106883,x=0.598,y=0.75,zoneID=7558}},ends={{npcID=103832,x=0.448,y=0.504,zoneID=7846}},coords={x=0.598,y=0.75,source="quest_giver",zoneID=7558},questType="standard"},
[42037] = {id=42037,name="Gathering the Dreamweavers",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7846,description="Now that you've recovered the Idol of the Wilds, it's time to put it to use to commune with Malorne. However, the ritual will need the combined power of many druids. Send your champions to gather the druids of our order, and tell them to meet us in Nordrassil. We will need to do this together.",starts={{npcID=98002,x=0.528,y=0.514,zoneID=7846}},ends={{npcID=103832,x=0.448,y=0.504,zoneID=7846}},coords={x=0.528,y=0.514,source="quest_giver",zoneID=7846},questType="standard"},
[42038] = {id=42038,name="Champion: Broll Bearmantle",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7846,mapID=747,starts={{npcID=106091,x=0.486,y=0.47,mapID=747}},ends={{npcID=106091,x=0.486,y=0.47,mapID=747}},coords={x=0.486,y=0.47,source="quest_giver",mapID=747},questType="standard"},
[42039] = {id=42039,name="Champion: Sylendra Gladesong",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7846,mapID=747,starts={{npcID=106093,x=0.486,y=0.47,mapID=747}},ends={{npcID=106093,x=0.486,y=0.47,mapID=747}},coords={x=0.486,y=0.47,source="quest_giver",mapID=747},questType="standard"},
[42040] = {id=42040,name="The Way to Nordrassil",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7979,description="The time has come for us to use the Idol of the Wilds and commune with Malorne. The ritual will require a great deal of power, so we have decided to convene at Nordrassil and draw upon the World Tree's essence. There is no time to waste. The fastest path will be through the Emerald Dreamway. Go ahead, and we will follow.",starts={{npcID=103832,x=0.448,y=0.504,zoneID=7846}},ends={{npcID=106204,x=0.434,y=0.306,zoneID=7979}},coords={x=0.448,y=0.504,source="quest_giver",zoneID=7846},questType="standard"},
[42041] = {id=42041,name="Enduring the Nightmare",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7979,description="We are under attack here, ! Creatures of the Nightmare are spilling into the Dreamway as we speak. Destroy them. They cannot be allowed to linger, or else the Nightmare will take root here, too!",starts={{npcID=106204,x=0.434,y=0.306,zoneID=7979}},ends={{npcID=106204,x=0.434,y=0.306,zoneID=7979}},coords={x=0.434,y=0.306,source="quest_giver",zoneID=7979},questType="standard"},
[42042] = {id=42042,name="Teensy Weensies!",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7979,description="Oh , I'm so very very happy to see you! The woodland critters whispered there was trouble in the Dreamway so I came immediately! There are so very many teensy weensy little creatures that live here in the Emerald Dream, and they're out there, all lost and alone! Would you go out there and gather them up? You can use my flute to call them to you. Thank you, brave druid!",starts={{npcID=106136,x=0.45,y=0.322,zoneID=7979}},ends={{npcID=106136,x=0.45,y=0.322,zoneID=7979}},coords={x=0.45,y=0.322,source="quest_giver",zoneID=7979},questType="standard"},
[42043] = {id=42043,name="Cleaning Up",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7979,description="When the Nightmare spreads, it consumes the life force of all that it touches. The more it spreads, the weaker our magic becomes. In its early stages, before the taint has taken hold, we can still cleanse the affected areas. I will bless you with Elune's grace. By channeling her power, you can reverse the Nightmare's spread.",starts={{npcID=106135,x=0.43,y=0.308,zoneID=7979}},ends={{npcID=106135,x=0.43,y=0.308,zoneID=7979}},coords={x=0.43,y=0.308,source="quest_giver",zoneID=7979},questType="standard"},
[42044] = {id=42044,name="A Dying Dream",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7979,description="Deep in the heart of the swamp lies an ancient protector of the Dreamway, Witherheart . He was among the first defenders to battle against the Nightmare, but he has fallen to total corruption. It pains me to say it, but we must destroy him.",starts={{npcID=106204,x=0.434,y=0.306,zoneID=7979}},ends={{npcID=106204,x=0.434,y=0.306,zoneID=7979}},coords={x=0.434,y=0.306,source="quest_giver",zoneID=7979},questType="standard"},
[42045] = {id=42045,name="Communing With Malorne",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=616,description="Our work here is done, . We have successfully defended the Dreamway. It will be only a matter of time before it is restored to its former state. But we have more important matters at hand. Take the Idol of the Wilds and go onward to Nordrassil. With any luck, they have already gathered. We will meet you there.",starts={{npcID=106204,x=0.434,y=0.306,zoneID=7979}},ends={{npcID=106250,x=0.604,y=0.236,zoneID=616}},coords={x=0.434,y=0.306,source="quest_giver",zoneID=7979},questType="standard"},
[42046] = {id=42046,name="A New Beginning",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7846,description="If Malorne is in danger, then things are even worse than I feared. It truly is up to us now. We have very little time left. Let us reconvene in the Dreamgrove at once.",starts={{npcID=106250,x=0.604,y=0.236,zoneID=616}},ends={{npcID=101195,x=0.448,y=0.516,zoneID=7846}},coords={x=0.604,y=0.236,source="quest_giver",zoneID=616},questType="standard"},
[42047] = {id=42047,name="Champion: Hamuul Runetotem",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7846,mapID=747,starts={{npcID=107025,x=0.48,y=0.552,mapID=747}},ends={{npcID=107025,x=0.48,y=0.552,mapID=747}},coords={x=0.48,y=0.552,source="quest_giver",mapID=747},questType="standard"},
[42048] = {id=42048,name="Champion: Mylune",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7846,mapID=747,starts={{npcID=107026,x=0.57,y=0.472,mapID=747}},ends={{npcID=107026,x=0.57,y=0.472,mapID=747}},coords={x=0.57,y=0.472,source="quest_giver",mapID=747},questType="standard"},
[42049] = {id=42049,name="Powering the Portal",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7846,description="If Malorne is trapped in the Nightmare, we must try to save him. It may sound like a fool's errand, but we cannot sit by idly. There is an abandoned portal within the Emerald Dreamway, one that we druids closed long ago because it leads to the Rift of Aln. To infuse it with energy once again, we will need shards of Nightmare which can be found on satyr lieutenants. Send our champions to hunt and kill these enemies.",starts={{npcID=103832,x=0.448,y=0.504,zoneID=7846}},ends={{npcID=103832,x=0.448,y=0.504,zoneID=7846}},coords={x=0.448,y=0.504,source="quest_giver",zoneID=7846},questType="standard"},
[42050] = {id=42050,name="Defenders of the Dream",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8180,description="Never has our order faced such a difficult challenge. To succeed, we must rely on each other's strengths. However, we only have a few defenders to spare for the battle ahead. Broll, Sylendra, Zen'tabra, and Mylune have all volunteered to accompany you into the valley below, but I can only spare one. Which one will you choose to aid you in battle?",starts={{npcID=107163,x=0.612,y=0.652,zoneID=8180}},ends={{npcID=107163,x=0.612,y=0.652,zoneID=8180}},coords={x=0.612,y=0.652,source="quest_giver",zoneID=8180},questType="standard"},
[42051] = {id=42051,name="Enter Nightmare",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8180,description="The portal to the nightmare is ready, . Remulos and the others have already gone ahead. There is no telling what horrors await on the other side, . Good luck.",starts={{npcID=101195,x=0.448,y=0.516,zoneID=7846}},ends={{npcID=107132,x=0.616,y=0.654,zoneID=8180}},coords={x=0.448,y=0.516,source="quest_giver",zoneID=7846},questType="standard"},
[42052] = {id=42052,name="The Shade of Xavius",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7673,mapID=641,description="Brightwing loves nice things - rainbows, unicorns, and flowers! But enemies, Brightwing does not forget. Brightwing remembers for a long, long time those that hurt the grove. Now, we must destroy our enemies... so that the grove can be nice and happy forever! Friend, go to Darkheart Thicket beneath the roots of Shaladrassil. There, find the one named Xavius... the one who started it all. Kill him, and bring me his head.",questType="dungeon"},
[42053] = {id=42053,name="The War of the Ancients",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7902,description="To free Malorne, we must win the War of the Ancients. A millennia ago, this battle took the combined efforts of the greatest defenders of our world. To win now, we must do the same. Go upon the battlefield and defeat Legion foes, rescue and revive our allies, and free the innocent who have been caught in the battle. Every enemy defeated and every ally saved will help turn the tide in our favor!",starts={{npcID=107132,x=0.616,y=0.654,zoneID=8180}},ends={{npcID=107132,x=0.616,y=0.654,zoneID=8180},{npcID=107214,x=0.268,y=0.317,zoneID=8180},{npcID=107215,x=0.277,y=0.31,zoneID=8180}},coords={x=0.616,y=0.654,source="quest_giver",zoneID=8180},questType="standard"},
[42054] = {id=42054,name="Archimonde, The Defiler",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8180,description="We have turned the battle, ! The Burning Legion is greatly weakened. Only one task remains. Malorne is locked in battle with Archimonde , the demon that slew him ten thousand years ago. Remember, , we are trapped in Malorne 's nightmare. There is no telling what will manifest here, but we MUST do something. May Elune guide us, .",starts={{npcID=107132,x=0.616,y=0.654,zoneID=8180},{npcID=107214,x=0.268,y=0.317,zoneID=8180},{npcID=107215,x=0.277,y=0.31,zoneID=8180}},ends={{npcID=106905,x=0.66,y=0.666,zoneID=8180}},coords={x=0.616,y=0.654,source="quest_giver",zoneID=8180},questType="standard"},
[42055] = {id=42055,name="The Demi-God's Return",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7846,description="Malorne 's voice echoes in your mind.> Mortal you may be, but your valor is worthy of the ancient gods. Nature's spirit lives in you - vibrant, wild, and ferocious. I witness in you the essence of nature's spark - the WILL to survive. Our triumph here will be spoken of for ages to come, . Return to the waking world through this portal. We will speak again when we return to the Dreamgrove.",starts={{npcID=106905,x=0.66,y=0.666,zoneID=8180}},ends={{npcID=103832,x=0.448,y=0.504,zoneID=7846}},coords={x=0.66,y=0.666,source="quest_giver",zoneID=8180},questType="standard"},
[42056] = {id=42056,name="Champion: Remulos",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7846,mapID=747,starts={{npcID=103832,x=0.448,y=0.504,mapID=747}},ends={{npcID=103832,x=0.448,y=0.504,mapID=747}},coords={x=0.448,y=0.504,source="quest_giver",mapID=747},questType="standard"},
[42065] = {id=42065,name="The Twilight Master",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=5042,description="There is only one more thing that remains, Farseer . We must confront the leader of the Twilight's Hammer and put an end to their sinister plot once and for all. Without their so-called master, the remaining cultists will be forced to retreat from Deepholm. Only when The Twilight's Hammer has been crushed and Deepholm has been saved, will we have the support of Therazane against the demons of the Burning Legion.",questType="standard"},
[42068] = {id=42068,name="The Return of Twilight",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=5042,description="The Twilight's Hammer has reemerged and they are building an army to overthrow my kingdom. A ludicrous fantasy on their part, but one that I cannot take lightly. I cannot offer the mortal races my aid until the threat to Deepholm has been dealt with. If you truly wish to unite the Elemental Lords to your cause, I would see you prove it. Go. Uncover the plot that the Twilight's Hammer is hatching and put an end to their scheme!",starts={{npcID=42465,x=0.564,y=0.122,zoneID=5042}},ends={{npcID=105995,x=0.64,y=0.704,zoneID=5042}},coords={x=0.564,y=0.122,source="quest_giver",zoneID=5042},questType="standard"},
[42069] = {id=42069,name="Felbats",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7334,mapID=630,questType="standard"},
[42074] = {id=42074,name="Return of the Light",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7834,description="Excellent! There is a gateway further down this pathway and like most Legion constructs it is powered by souls. I think the death of that Inquisitor should be just enough to activate it and open the way back to where it came from. Let's go see where the path takes us, shall we?",starts={{npcID=106011,x=0.336,y=0.332,zoneID=7543}},coords={x=0.336,y=0.332,source="quest_giver",zoneID=7543},questType="standard"},
[42079] = {id=42079,name="Masquerade",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Our family commands great respect in this city, thanks to my father. Through my network of contacts, we can organize the citizens to prepare Suramar for Thalyssra's return. You must walk among the nightborne. You must earn the trust of our friends and foes alike. You must become someone else. Put this on Anarys.",starts={{npcID=105342,x=0.434,y=0.788,zoneID=7637}},ends={{npcID=105342,x=0.434,y=0.788,zoneID=7637}},coords={x=0.434,y=0.788,source="quest_giver",zoneID=7637},questType="standard"},
[42081] = {id=42081,name="In With the New",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,description="Well, here's your new conduit. Try not to break this one, I really don't feel like making another. Oh, and tell your boss, Deucus, that he owes me big time for this.",questType="standard"},
[42088] = {id=42088,name="Evacuate Snowmane",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="They just keep coming! And now my scouts report some of the drogbar have managed to sneak around our flank and are attacking Snowmane Village. Go, help the evacuation. We will hold the line here and try to buy you some time.",starts={{npcID=93846,x=0.532,y=0.64,zoneID=7503}},ends={{npcID=93846,x=0.532,y=0.64,zoneID=7503}},coords={x=0.532,y=0.64,source="quest_giver",zoneID=7503},questType="standard"},
[42096] = {id=42096,name="Champion: Naralex",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7846,mapID=747,starts={{npcID=103778,x=0.448,y=0.516,mapID=747}},ends={{npcID=103778,x=0.448,y=0.516,mapID=747}},coords={x=0.448,y=0.516,source="quest_giver",mapID=747},questType="standard"},
[42097] = {id=42097,name="Searching the Archives",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7875,description="The Black Harvest archives contain an immeasurable amount of magical knowledge that has been collected from various sources over time. It's reasonable to think that somewhere among the countless scrolls that we'll find something to aid us in our mission to rescue the remaining council members. The search may be exhausting, but it is necessary if we plan to rebuild and face the Burning Legion.",starts={{npcID=104795,x=0.658,y=0.472,zoneID=7875}},ends={{npcID=104795,x=0.658,y=0.472,zoneID=7875}},coords={x=0.658,y=0.472,source="quest_giver",zoneID=7875},questType="standard"},
[42098] = {id=42098,name="Black Rook Hold: An Unclaimed Soul",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7875,description="In order to create the anchor, we'll need to link something of Shinfel's to an unclaimed soul . The soul will act like a beacon, guiding Shinfel through the Twisting Nether, and back to Dreadscar Rift. Shinfel's staff should provide us with the link we need, but the soul will be a bit harder to find. Dwelling within Black Rook hold is an amalgam of souls, some lost and forgotten. Killing this monstrosity should provide us with the soul we need.",starts={{npcID=105018,x=0.556,y=0.372,zoneID=7875}},ends={{npcID=105018,x=0.556,y=0.372,zoneID=7875}},coords={x=0.556,y=0.372,source="quest_giver",zoneID=7875},questType="dungeon"},
[42100] = {id=42100,name="Empowering the Soul",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7875,description="Creating the anchor will require more power than our soul shards will be able to provide. Dreadscar's troops are capable of amassing a large amount of soul shards when they defeat enemies while on missions. Once we have enough, I can harvest the supply and use them to craft the anchor.",starts={{npcID=105018,x=0.556,y=0.372,zoneID=7875}},ends={{npcID=105018,x=0.556,y=0.372,zoneID=7875}},coords={x=0.556,y=0.372,source="quest_giver",zoneID=7875},questType="standard"},
[42102] = {id=42102,name="One Who's Worthy",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7875,description="If we wish to successfully summon the sisters, we'll need the help of a warlock who is skilled in summoning greater demons. We cannot afford to lose another council member due to inexperience. The Broken Isles are swarming with new blood, all hoping to make a name for themselves in this time of chaos. Hopefully among them we can find one worthy of this council.",starts={{npcID=105102,x=0.544,y=0.356,zoneID=7875}},ends={{npcID=105102,x=0.544,y=0.356,zoneID=7875}},coords={x=0.544,y=0.356,source="quest_giver",zoneID=7875},questType="standard"},
[42103] = {id=42103,name="Let it Feed",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7875,description="We can use the Bloodstone to control the sisters once they are in a weakened state, but first, we'll need to feed it. The stone grows in power when consuming the blood of demons. Luckily for us, there's no shortage of demons to kill.",starts={{npcID=104732,x=0.56,y=0.354,zoneID=7875}},ends={{npcID=104732,x=0.56,y=0.354,zoneID=7875}},coords={x=0.56,y=0.354,source="quest_giver",zoneID=7875},questType="standard"},
[42104] = {id=42104,name="The Underking Comes",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Here, I'm too slow to get these laggards to safety. Take my horn and sound the evacuation. We need to get the people out of here before the drogbar arrive. The warbraves can take it from there. For now just send them over to Spiritwalker Ebonhorn . That fool can watch over them until it is safe.",starts={{npcID=97662,x=0.404,y=0.716,zoneID=7503}},ends={{npcID=93805,x=0.386,y=0.684,zoneID=7503}},coords={x=0.404,y=0.716,source="quest_giver",zoneID=7503},questType="standard"},
[42107] = {id=42107,name="On the Trail of the Great Worm",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7813,description="We need the Gjallarhorn to compel the armies of Odyn's children to join our cause. If the great worm swallowed it, we shall dig through the very earth until we find it in its entrails!",questType="standard"},
[42110] = {id=42110,name="To the Summit!",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="Your armies have tracked the beast to the highest peak in Highmountain. It has nowhere left to run, but it is protected by foul drogbar. You must go there yourself and slay Jorhuttam!",ends={{npcID=106271,x=0.538,y=0.878,zoneID=7503}},questType="standard"},
[42113] = {id=42113,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=6720,mapID=525,questType="standard"},
[42114] = {id=42114,name="The Ritual of Tides",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7745,description="Long ago, the first Farseer of the Earthen Ring was given a vision of the elements. In the vision she foresaw the arrival of a new Farseer, one who would lead us through a time of terrible crisis and unite the elements. , I believe that you are the Farseer of this prophecy, called to lead before you were ever born. The time has come to fulfill your destiny! When you are ready, we will perform the Ritual of Tides and call upon Neptulon , the first of the four great Elemental Lords.",starts={{npcID=106316,x=0.34,y=0.314,zoneID=7745}},ends={{npcID=106291,x=0.382,y=0.3,zoneID=7745}},coords={x=0.34,y=0.314,source="quest_giver",zoneID=7745},questType="standard"},
[42120] = {id=42120,name="The Silver Hand",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=139,description="Too many know of its location, the tomb must be closed forever. First, we must reclaim the hammer. Tyrosus has lent us a force to aid in the recovery of the hammer, and some of my order will meet us there as well, but I fear even that may not be enough. I'm glad we'll have you with us. Take the portal to Dalaran Crater, then fly to Tirisfal Glades and meet us. I've marked the location on your map.",questType="standard"},
[42125] = {id=42125,name="Dark Whispers",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7875,description="Felsoul Hold is not far away, but it is well defended. Very tough to get in the normal way, but Calydus can help you sneak in! There is a portal that my kind use to haul in treasures, with it you can get in and find the skull!",ends={{npcID=101097,x=0.376,y=0.316,zoneID=7875}},questType="standard"},
[42126] = {id=42126,name="Archmage Omniara",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7879,description="Beside me is the Scouting Map. From it, you can direct our allies to carry out vital assignments across the Broken Isles. The first task is critical. Archmage Omniara, a renowned summoner, was on her way to the Hall of Guardians when she was attacked. Send Archmage Kalecgos to help her. He will be uniquely suited to this task.",questType="standard"},
[42127] = {id=42127,name="Building Our Troops",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7879,description="Archmage Omniara is a very powerful arcanist and her skills will be quite an asset to our order. She is capable of summoning multiple Water Elementals at the same time! Fortunately, she has agreed to share her knowledge with us. Speak to her now, and recruit her elementals.",questType="standard"},
[42128] = {id=42128,name="Ritual Reagents",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7875,description="The Skull of the Man'ari, oh good choice! It's very powerful and it's held by an even more powerful Dreadlord! There is a weakness, the skull has a will of its own! If we can commune with the skull we might be able to convince it to serve you instead! We will need reagents from the floating city before we can perform the ritual to commune with it. Dust from a fresh grave, dark oil, and a powerful alcohol catalyst. Oh, and blood! I sense a beast whose blood should be perfect.",starts={{npcID=101097,x=0.376,y=0.316,zoneID=7875}},coords={x=0.376,y=0.316,source="quest_giver",zoneID=7875},questType="standard"},
[42129] = {id=42129,name="The Pendant of Starlight",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7558,description="To finish my work here, I will need a magical item called the Pendant of Starlight . For centuries, the Archdruids of the Dreamgrove passed the pendant down from one guardian to the next. But one day, a naga siren used deception to take it! This pendant stores a great amount of arcane power... power I can use to heal the grove. Get it back, and I will be very grateful!",starts={{npcID=98008,x=0.376,y=0.428,zoneID=7979}},ends={{npcID=98008,x=0.376,y=0.428,zoneID=7979}},coords={x=0.376,y=0.428,source="quest_giver",zoneID=7979},questType="standard"},
[42131] = {id=42131,name="Unexpected Visitors",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8022,description="Brace yourself, . I am detecting a strange magic forming in the chamber. Something is projecting itself in.",questType="standard"},
[42132] = {id=42132,name="Last, But Not Least",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8022,description="I think you already know what I am going to tell you... It is well past time to make Allari and Jace your champions. The two of them were instrumental in the planning and preparation for the invasion of Niskara. They have earned it and you would be hard pressed to find better champions anywhere.",questType="standard"},
[42133] = {id=42133,name="Same Day Delivery",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7877,description="I've enchanted these weapons to counter the natural resistances that felhounds have to magic. In addition to that, the metal should splinter their scales on impact, allowing your allies to do increased damage to the demons. While I don't expect the enchantment to decay over time, you should do your best to deliver these weapons to those who will use them immediately. The longer they remain here, the more demons their power will attract.",starts={{npcID=108492,x=0.6,y=0.722,zoneID=7558}},ends={{npcID=107973,x=0.434,y=0.26,zoneID=7877}},coords={x=0.6,y=0.722,source="quest_giver",zoneID=7558},questType="standard"},
[42134] = {id=42134,name="Recruiting More Troops",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7877,description="Our champions acquired the talents of Recruiter Sampson , an extraordinary tracker. He has a way with animals, calling them to his side with the utmost ease. In fact, he's already beginning to fill the stables with animals that he has tracked and tamed. Speak to him now.",starts={{npcID=103023,x=0.43,y=0.468,zoneID=7877}},ends={{npcID=106446,x=0.576,y=0.33,zoneID=7877}},coords={x=0.43,y=0.468,source="quest_giver",zoneID=7877},questType="standard"},
[42137] = {id=42137,name="Champion: Yalia Sagewhisper",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7834,mapID=702,starts={{npcID=110687,x=0.47,y=0.44,mapID=630}},ends={{npcID=110687,x=0.47,y=0.44,mapID=630}},coords={x=0.47,y=0.44,source="quest_giver",mapID=702},questType="standard"},
[42138] = {id=42138,name="Champion: Zabra Hexx",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,mapID=630,starts={{npcID=110686,x=0.586,y=0.372,mapID=630}},ends={{npcID=110686,x=0.586,y=0.372,mapID=630}},coords={x=0.586,y=0.372,source="quest_giver",mapID=630},questType="standard"},
[42139] = {id=42139,name="Rise, Champions",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="The Uncrowned work behind the scenes, pulling strings here, snipping others there. It's a matter of making the right choices at the right time in the most elegant manner possible. We have all decided that you need to recruit some Shadows to send out on our most important missions. People that you can trust, or at least that you can trust to get the job done. Might I suggest that you start with Garona and Vanessa? It should prove interesting if nothing else considering recent events.",questType="standard"},
[42140] = {id=42140,name="A More Wretched Hive of Scum and Villainy",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Word on the street is that you're lookin' to recruit some more, shall we say, unsavory types? I know just the woman! No, not me... though, I could prolly do it. But not as well as Lonika Stillblade. Yeah, that Lonika. The one who founded the 'School of Roguery' in Shattrath City. So, let's send Vanessa there out to Outland and have her make Lonika an offer she can't refuse. Or, you know, give her a legit job and a nicer location for her rogue academy.",questType="standard"},
[42141] = {id=42141,name="Summoner Morn",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7745,description="Now that we have recruited champions of our order, we can use the Scouting Map to complete vital assignments across the Broken Isles. The first assignment is critical. Summoner Morn, a renowned master of the elementals, was on his way to the Heart of Azeroth when he was attacked. I suggest we send Stormcaller Mylra to help him. She will be uniquely suited to this task.",starts={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},coords={x=0.33,y=0.6,source="quest_giver",zoneID=7745},questType="standard"},
[42142] = {id=42142,name="Recruiting The Troops",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7745,description="Our champions acquired the talents of Summoner Morn, a powerful shaman. He is known for his strong affinity with earth, and is a valuable addition to our Order. He is already beginning to requisition Lesser Elementals to our cause. Speak to him now and train a Lesser Elemental .",starts={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},coords={x=0.33,y=0.6,source="quest_giver",zoneID=7745},questType="standard"},
[42147] = {id=42147,name="First Contact",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Time to put your new disguise to the test. Your first contact is Vanthir , a merchant from the common district. He is in the Grand Promenade today visiting one of his suppliers. Tell Vanthir to pay me a visit regarding a shipment of dusk lily bulbs. He will understand. Beyond that, we will need time to prepare. You should return to Thalyssra. corked bottle of faintly glowing fluid.> Give her this, with my regards. We will call upon you soon.",starts={{npcID=105342,x=0.434,y=0.788,zoneID=7637}},ends={{npcID=97140,x=0.368,y=0.466,zoneID=7637}},coords={x=0.434,y=0.788,source="quest_giver",zoneID=7637},questType="standard"},
[42158] = {id=42158,name="The Creator's Workshop",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=8161,description="My remote observation relay captured an astonishing amount of data from that tomb. If we can download its memory to my core processing systems, I should be able to locate Titanstrike... and that unsavory vrykul who took it. Since you're here, would you mind helping out? Processing that much information might overload a few failsafe mechanisms here and there, and I know you're the capable sort!",questType="standard"},
[42166] = {id=42166,name="What Is Going On Here?",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="We don't know much about the Empyrean Society's activities here, but now that you appear to be a new recruit you should be able to ask some questions and take a look around for the strange magic Archmage Vargoth detected. Let's meet up at the rotunda on the hill.",starts={{npcID=106530,x=0.66,y=0.324,zoneID=7334}},coords={x=0.66,y=0.324,source="quest_giver",zoneID=7334},questType="standard"},
[42168] = {id=42168,name="Looking into the Darkness",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Friend now is ready to perform the ritual! Remember, friend, the skull must be convinced that it is in its best interest to be in your possession. If we must force the skull into your servitude, it would be far weaker.",questType="standard"},
[42170] = {id=42170,name="The Dreamweavers",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7558,description="Assist the Druids of Val'sharah by completing 4 world quests.",ends={{npcID=106901,x=0.546,y=0.732,zoneID=7558}},questType="standard"},
[42171] = {id=42171,name="Final Exit",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="We've certainly reduced the Empyrean Society's numbers. I don't think they'll be luring any more members to their cause for a while. There's only one place we haven't investigated, and I suspect that rune we found is attuned to the door. Let's see what's inside the building.",ends={{npcID=106530,x=0.66,y=0.324,zoneID=7334}},questType="standard"},
[42175] = {id=42175,name="Growing Power",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7879,description="The Tirisgarde has need of your help now that you have grown in strength, . Meet me in the Hall of the Guardian when you are done with your adventures.",questType="standard"},
[42184] = {id=42184,name="Mission: Elemental Diplomacy",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7745,description="The Lord of Tides has united with the Earthen Ring, but the matter of uniting the remaining Elemental Lords still remains. For the next step of our campaign, I have organized a diplomatic mission to Skywall. The goal of the mission is to ascertain the current political situation in Skywall, following the defeat of Al'Akir the Windlord, and to identify any elementals who would aid our cause. The mission is currently waiting your assignment.",starts={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},coords={x=0.33,y=0.6,source="quest_giver",zoneID=7745},questType="standard"},
[42185] = {id=42185,name="Never Hunt Alone",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Prustaga is almost certainly on her way to the Temple of Storms, which is where I imbued Titanstrike with the Thunderspark. If my deductions are correct, she'll attempt to reverse the process and infuse the spark into herself, thus attaining the godlike power she craves! Hopefully Thorim isn't off cavorting with his hounds again. If Prustaga has the local vrykul on her side, things may get... complicated.",questType="standard"},
[42186] = {id=42186,name="Growing Power",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7902,description="Iron-Body Ponshu has requested your presence. Our campaign to defend the Broken Isles is getting under way, and we need you back at the Wandering Isle.",ends={{npcID=100438,x=0.514,y=0.486,zoneID=7902}},questType="standard"},
[42187] = {id=42187,name="Rise, Champions",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7902,description="We are still recovering from the attack at the Peak of Serenity. To help us rebuild the order, we should enlist the greatest champions of our class to fight by our side. I know that the two Stormstouts, Chen and Li Li, would eagerly pledge to join the cause. Speak to them and recruit them as champions, then speak to Master Hsu .",starts={{npcID=100438,x=0.514,y=0.486,zoneID=7902}},ends={{npcID=99179,x=0.528,y=0.596,zoneID=7902}},coords={x=0.514,y=0.486,source="quest_giver",zoneID=7902},questType="standard"},
[42188] = {id=42188,name="Nobundo Awaits",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7745,description="Nobundo and the other champions of the Earthen Ring have gathered down below. They are awaiting your arrival, Farseer. A great ritual is about to take place and they have requested your presence. Do not worry about your administrative duties for now, I'll take care of things here. Nobundo is waiting for you now. May the elements be with you, Farseer.",starts={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},ends={{npcID=106316,x=0.34,y=0.314,zoneID=7745}},coords={x=0.33,y=0.6,source="quest_giver",zoneID=7745},questType="standard"},
[42189] = {id=42189,name="Fire Mage - Flavor Event 01",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7502,mapID=627,questType="standard"},
[42191] = {id=42191,name="Tech It Up A Notch",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7902,description="Thanks to you, the Order of the Broken Temple is gradually re-assembling. However, there is much more work to do. As our leader, you can determine the trajectory of our order's future. Speak to Number Nine Jia. She will show you the ropes.",starts={{npcID=99179,x=0.528,y=0.596,zoneID=7902}},ends={{npcID=100438,x=0.514,y=0.486,zoneID=7902}},coords={x=0.528,y=0.596,source="quest_giver",zoneID=7902},questType="standard"},
[42192] = {id=42192,name="Fire Mage - Flavor Event 02",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7502,mapID=627,questType="standard"},
[42193] = {id=42193,name="The Gjallarhorn",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="You have proven yourself most thoroughly time and again, . There can be no doubt that you are the one to lead Odyn's armies into the final battle. You must first obtain the Gjallarhorn so that you may signal to our allies that the end times are upon us. King Svergan Stormcloak was the last known living guardian of the horn. Seek his spirit in the Field of Fallen Kings in Stormheim and see what you can learn.",ends={{npcID=106720,x=0.708,y=0.382,zoneID=7541}},questType="standard"},
[42194] = {id=42194,name="Stolen Honor",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7541,description="Safeguarding the Gjallarhorn was my duty, . I will do what is right, but first I must ask for your aid. My family was disavowed by the mystics of our time and this grave was ransacked. I cannot find peace while my family heirlooms are in the hands of the servants of the false God-King. Return them to me and I will aid you in finding the Gjallarhorn!",starts={{npcID=106720,x=0.708,y=0.382,zoneID=7541}},ends={{npcID=106720,x=0.708,y=0.382,zoneID=7541}},coords={x=0.708,y=0.382,source="quest_giver",zoneID=7541},questType="standard"},
[42197] = {id=42197,name="Champion: Duke Hydraxis",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7745,mapID=726,starts={{npcID=106520,x=0.298,y=0.34,mapID=726}},ends={{npcID=106520,x=0.298,y=0.34,mapID=726}},coords={x=0.298,y=0.34,source="quest_giver",mapID=726},questType="standard"},
[42198] = {id=42198,name="Champion: Stormcaller Mylra",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7745,mapID=726,starts={{npcID=106312,x=0.342,y=0.324,mapID=726}},ends={{npcID=106312,x=0.342,y=0.324,mapID=726}},coords={x=0.342,y=0.324,source="quest_giver",mapID=726},questType="standard"},
[42200] = {id=42200,name="Mission: Investigating Deepholm",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7745,description="In order for the Earthen Ring to bring the four Elemental Lords together in an alliance against the Burning Legion, we will need to convince Therazane the Stonemother to join forces with us. Therazane has been absent from our negotiations with the elements thus far. There have been whispers of a new threat arising from within Deepholm. If these rumors are true, she may have need of our aid. I have prepared a diplomatic mission to Deepholm to ascertain the situation. It is awaiting your assignment.",starts={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},coords={x=0.33,y=0.6,source="quest_giver",zoneID=7745},questType="standard"},
[42202] = {id=42202,name="Revenge, Served Cold",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7503,description="My village was razed by a drogbar tribe who worships the very beast you seek. No one was spared. Help me avenge my people and I will aid you in your quest to find Jorhuttam.",starts={{npcID=106271,x=0.538,y=0.878,zoneID=7503}},ends={{npcID=106271,x=0.538,y=0.878,zoneID=7503}},coords={x=0.538,y=0.878,source="quest_giver",zoneID=7503},questType="standard"},
[42204] = {id=42204,name="Jorhuttam",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7813,description="You upheld your end of your promise. I will do the same. Take these drogbar drums. Then bang on them to call upon Jorhuttam to feast. Find the Great Worm's feeding mound and use the drums to lure her out.",starts={{npcID=106271,x=0.538,y=0.878,zoneID=7503}},coords={x=0.538,y=0.878,source="quest_giver",zoneID=7503},questType="standard"},
[42208] = {id=42208,name="Return to the Firelands",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7745,description="The time has come to return to the Firelands. I need not tell you how dangerous this will be, Farseer. Ragnaros may be defeated, but the elementals of the Firelands destroy with reckless abandon. Our presence there will surely be seen as an act of aggression. I have prepared a scouting mission to the Firelands. We should send only our very best champions to make contact with the elements there. If the mission is successful, we may find the information we need to bring the Firelands into our fold.",starts={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},coords={x=0.33,y=0.6,source="quest_giver",zoneID=7745},questType="standard"},
[42210] = {id=42210,name="Scrolls of Knowledge",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7902,description="Our troops are ready! It's time to test them out in the field, and I have the perfect assignment. Number Nine Jia is a well-respected scholar. She has knowledge that can help us improve the order, however, many of her important scrolls were left behind during the attack on the Peak of Serenity. Send our champions to retrieve these documents at once!",starts={{npcID=99179,x=0.528,y=0.596,zoneID=7902}},ends={{npcID=99179,x=0.528,y=0.596,zoneID=7902}},coords={x=0.528,y=0.596,source="quest_giver",zoneID=7902},questType="standard"},
[42212] = {id=42212,name="Fire Mage - Flavor Event 03",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7502,mapID=627,questType="standard"},
[42213] = {id=42213,name="Eye of Azshara: The Tidestone of Golganneth",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Dalaran .>",starts={{npcID=106780,zoneID=8040}},questType="standard"},
[42214] = {id=42214,name="Knocked for a Loop",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="While you're focused on murlocs... Many murlocs are known to wear jewelry to attract a mate. I'm willing to bet that we can use some of the same jewels they use. Collect some of their jewelry and bring it back to me. The wetter, the better!",starts={{npcID=100538,x=0.466,y=0.414,zoneID=7334}},ends={{npcID=100538,x=0.466,y=0.414,zoneID=7334}},coords={x=0.466,y=0.414,source="quest_giver",zoneID=7334},questType="standard"},
[42220] = {id=42220,name="Shipwrecked Sailors",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=7334,questType="standard"},
[42221] = {id=42221,name="Chief Bitterbrine",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7334,mapID=630,questType="standard"},
[42222] = {id=42222,name="Empyrean Society Report",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7879,description="I find it hard to believe that Archmage Vargoth would be involved with such a malevolent group! There must be a good explanation for why he's been here... Regardless, we had best return to the Hall of the Guardian and inform Meryl about what we've uncovered here.",starts={{npcID=106530,x=0.66,y=0.324,zoneID=7334}},coords={x=0.66,y=0.324,source="quest_giver",zoneID=7334},questType="standard"},
[42223] = {id=42223,name="Scouting the Crimson Thicket",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="If you are heading east, there is something I would ask of you. While we struck camp some of our caravan left to scout around the city. Lilryia Dawnwind has been gone too long. I would be most grateful if you would go check on her safety. She said she was going to scout out the ruins of Dawncleft.",starts={{npcID=103571,x=0.304,y=0.308,zoneID=7637}},ends={{npcID=100775,x=0.618,y=0.49,zoneID=7637}},coords={x=0.304,y=0.308,source="quest_giver",zoneID=7637},questType="standard"},
[42224] = {id=42224,name="Cloaked in Moonshade",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="I do not know what Theryn found, but I know where he found it. Moonshade Sanctum, to the west. Beyond the Temple of Fal'adora. Whatever power altered Theryn's arcane essence... Whatever power allowed Kel'danath to create a spell to soothe the withered... Its source rests there. I know this as surely as if I had been there myself.",starts={{npcID=97140,x=0.368,y=0.466,zoneID=7637}},ends={{npcID=250383,x=0.174,y=0.378,zoneID=7637}},coords={x=0.368,y=0.466,source="quest_giver",zoneID=7637},questType="standard"},
[42225] = {id=42225,name="Breaking the Seal",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="You found it! But it is sealed away tight. Search the room for a way to break those seals.",starts={{npcID=250383,x=0.174,y=0.378,zoneID=7637}},ends={{npcID=250383,x=0.174,y=0.378,zoneID=7637}},coords={x=0.174,y=0.378,source="quest_giver",zoneID=7637},questType="standard"},
[42226] = {id=42226,name="Moonshade Holdout",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,starts={{npcID=250383,x=0.174,y=0.378,zoneID=7637}},ends={{npcID=107126,x=0.368,y=0.466,zoneID=7637}},coords={x=0.174,y=0.378,source="quest_giver",zoneID=7637},questType="standard"},
[42227] = {id=42227,name="Into the Crevasse",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="I have protected that seed for ten thousand years. You let it fall into the hands of the fal'dorei. I should have let you die. Repay your debt. Help me get the seed back.",starts={{npcID=107126,x=0.368,y=0.466,zoneID=7637}},ends={{npcID=107126,x=0.368,y=0.466,zoneID=7637}},coords={x=0.368,y=0.466,source="quest_giver",zoneID=7637},questType="standard"},
[42228] = {id=42228,name="The Hidden City",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Orathiss has underestimated the seed. It is sapping her power - slowing her down. We must catch her and get the seed to safety!",questType="standard"},
[42229] = {id=42229,name="Shal'Aran",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="The chamber beyond may be the perfect hiding place, now that its guardian has been dealt with. Come with me.",starts={{npcID=98312,x=0.346,y=0.534,zoneID=7637}},ends={{npcID=97140,x=0.368,y=0.466,zoneID=7637}},coords={x=0.346,y=0.534,source="quest_giver",zoneID=7637},questType="standard"},
[42230] = {id=42230,name="The Valewalker's Burden",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="The seed is awakening. Without power it will quickly wither and die. We must carry the seed out of here and plant it somewhere safe. I am not strong enough to bear this burden. But you... you are brimming with power. I can sense it. Please take the seed.",questType="standard"},
[42231] = {id=42231,name="The Mysterious Paladin",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="It appears we have been afforded a unique opportunity. A small order of paladins has come forward claiming to know the location of Tyr's tomb. They say they are the protectors of his warhammer, but that the ancient weapon is now imperiled. I'd like you to speak with Travard , their leader, to find out more about this artifact.",questType="standard"},
[42233] = {id=42233,name="Highmountain Tribes",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7731,description="Assist the Tauren of Highmountain by completing 4 world quests.",ends={{npcID=106902,x=0.382,y=0.458,zoneID=7731}},questType="standard"},
[42234] = {id=42234,name="The Valarjar",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7541,description="Assist the Vry'kul of Stormheim by completing 4 world quests.",ends={{npcID=106904,x=0.602,y=0.512,zoneID=7541}},questType="standard"},
[42235] = {id=42235,name="Invasion: Westfall",level=5,requiredLevel=5,faction="none",expansion=6,zoneID=40,mapID=52,questType="standard"},
[42236] = {id=42236,name="Invasion: Northern Barrens",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=17,mapID=10,questType="standard"},
[42237] = {id=42237,name="Invasion: Tanaris",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=440,mapID=71,questType="standard"},
[42238] = {id=42238,name="Missing Demon",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="I seem to have misplaced my imp, Daglop . If you see him, tell him to check in. Normally I would just resummon him but I'm worried blind Marius here will kill him first and ask questions later. No vision, that one.",starts={{npcID=106914,x=0.504,y=0.306,zoneID=7334}},ends={{npcID=91166,x=0.624,y=0.514,zoneID=7334}},coords={x=0.504,y=0.306,source="quest_giver",zoneID=7334},questType="standard"},
[42244] = {id=42244,name="Fate of the Queen's Reprisal",level=10,requiredLevel=10,faction="horde",expansion=6,zoneID=7502,starts={{npcID=239328,x=0.656,y=0.569,zoneID=7334}},coords={x=0.656,y=0.569,source="quest_giver",zoneID=7334},questType="standard"},
[42268] = {id=42268,name="Shipwrecked Sailors",level=10,requiredLevel=10,faction="horde",expansion=6,zoneID=7334,questType="standard"},
[42271] = {id=42271,name="Their Dying Breaths",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="I have precious little time. As we speak, my troops are defending against an onslaught of withered elves. These four whelplings are near death. Their lives are of the utmost importance to our flight, as they may be some of the last whelplings Senegos can rear. Some cracked ley crystals should bring them back to their senses.",starts={{npcID=90543,x=0.488,y=0.264,zoneID=7334}},ends={{npcID=89975,x=0.478,y=0.268,zoneID=7334}},coords={x=0.488,y=0.264,source="quest_giver",zoneID=7334},questType="standard"},
