[42462] = {id=42462,name="Legion 110 A",level=45,requiredLevel=45,faction="none",expansion=6,questType="standard"},
[42463] = {id=42463,name="Legion 110 H",level=45,requiredLevel=45,faction="none",expansion=6,questType="standard"},
