[43054] = {id=43054,name="An Ample Stockpile",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7902,description="I have gone through our stockpile several times and no matter how I try to cut corners, we come up short. A lack of food and medicine will halt our war efforts... that is simply the reality. We desperately need food or bandages. If you know how to acquire any such items, you can bring them to me.",starts={{npcID=98945,x=0.49,y=0.584,zoneID=7902}},ends={{npcID=98945,x=0.49,y=0.584,zoneID=7902}},coords={x=0.49,y=0.584,source="quest_giver",zoneID=7902},questType="standard"},
