[43061] = {id=43061,name="Silkweave Bandages",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7902,starts={{npcID=98945,x=0.49,y=0.584,zoneID=7902}},ends={{npcID=98945,x=0.49,y=0.584,zoneID=7902}},coords={x=0.49,y=0.584,source="quest_giver",zoneID=7902},questType="standard"},
[43062] = {id=43062,name="Further Training",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7902,description="You may be the Grandmaster, but mastery must be maintained through discipline. To achieve perfect harmony, you must continue your training. I would like to see your form in practice, . Go out and use your Crackling Jade Lightning, Roll, and Blackout Kick or Blackout Strike. Through discipline, we find greatness.",starts={{npcID=104744,x=0.454,y=0.25,zoneID=5785},{npcID=104744,x=0.524,y=0.578,zoneID=7902}},ends={{npcID=104744,x=0.454,y=0.25,zoneID=5785},{npcID=104744,x=0.524,y=0.578,zoneID=7902}},coords={x=0.454,y=0.25,source="quest_giver",zoneID=5785},questType="standard"},
[43070] = {id=43070,name="7.0 Suramar Collapse Scenario - Treasure 01 - Army Size Increase 01",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[43071] = {id=43071,name="7.0 Suramar Collapse Scenario - Treasure 13 - Withered Berserker Unlock 01",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[43090] = {id=43090,name="Ulduar's Oath",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7813,description="I was once leader of all of the titanforged keepers of Azeroth. We were charged by the Titans themselves to protect the world. Once I gave up on the post of Prime Designate, I gave up any measure of influence over the other keepers. Not even my own son, Thorim, is bound to heed my commands. The Gjallarhorn comes from a time before our falling out, however. A time of an ancient oath of honor. Let us invoke that oath -- I am certain Thorim will answer the call.",questType="standard"},
[43100] = {id=43100,name="Finding the Scepter",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=28,description="Very powerful, but difficult to acquire. Scepter is in the hands of Gul'dan. We must find out his plans, get close. Calydus know Gul'dan planning major operation. He has sent out a call to arms to all Shadow Council to help with big ritual. One such group at Caer Darrow, talking to the necromancers there. You should go, find out about plan.",starts={{npcID=101097,x=0.376,y=0.316,zoneID=7875}},ends={{npcID=109698,x=0.692,y=0.79,zoneID=28}},coords={x=0.376,y=0.316,source="quest_giver",zoneID=7875},questType="standard"},
[43106] = {id=43106,name="Feed Oculeth",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,starts={{npcID=98548,x=0.366,y=0.45,zoneID=7637}},ends={{npcID=98548,x=0.366,y=0.45,zoneID=7637}},coords={x=0.366,y=0.45,source="quest_giver",zoneID=7637},questType="standard"},
