[43741] = {id=43741,name="Currency Treasure - Azuregale",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[43743] = {id=43743,name="Currency Treasure - Crimson Thicket",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[43744] = {id=43744,name="Currency Treasure - Telanor",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[43746] = {id=43746,name="Currency Treasure - Moon Guard",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[43747] = {id=43747,name="Currency Treasure - Falanaar",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[43748] = {id=43748,name="Currency Treasure - Felsoul Hold",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[43750] = {id=43750,name="The Call of Battle",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7813,description="Once, the mighty titanforged keepers of Ulduar and Odyn acted as one. Ever since Odyn broke off to create the valarjar, not even Odyn's own son Thorim is bound to follow his father's advice. There is one hope to unite the forces of Skyhold and Ulduar however. The Gjallarhorn was a gift given to Hymdall before Odyn's departure. The keepers of Ulduar are oathbound to answer the call of the Gjallarhorn were it to be sounded as it would signal that the end times are upon us!",questType="standard"},
[43783] = {id=43783,name="Field Rations",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[43785] = {id=43785,name="Champion: Arator the Redeemer",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=139,mapID=23,questType="standard"},
[43792] = {id=43792,name="Degren",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[43793] = {id=43793,name="Miasu",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[43794] = {id=43794,name="Ambassador D'vwinn",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[43795] = {id=43795,name="Tracking - Rovendros Found",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[43796] = {id=43796,name="Draenei Spoken To",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[43797] = {id=43797,name="Aiding the Conclave",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7834,description="The priests of the Conclave are formidable allies. With our combined strength, we may just have a chance to slay the dreadlord, forever. Let Alonsus Faol know that we will be by your side and ready to fight when you need us.",questType="standard"},
[43806] = {id=43806,name="The Battle for Broken Shore",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=1519,description="The third fleet has shipped out ahead of us, . This gryphon will bring you to them. Good luck out there. It's clear the Legion isn't going to make this easy, but let's hope King Varian has matters well in hand.",ends={{npcID=100395,x=0.198,y=0.348,zoneID=1519}},questType="standard"},
[43808] = {id=43808,name="Moon Guard Teleporter Online!",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Ancient Mana should get it back up and running.>",starts={{npcID=252814,x=0.308,y=0.11,zoneID=7637}},ends={{npcID=252814,x=0.308,y=0.11,zoneID=7637}},coords={x=0.308,y=0.11,source="quest_giver",zoneID=7637},questType="standard"},
[43809] = {id=43809,name="Tel'anor'eporter Online!",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Ancient Mana should get it back up and running.>",starts={{npcID=252817,x=0.421,y=0.353,zoneID=7637}},ends={{npcID=252817,x=0.421,y=0.353,zoneID=7637}},coords={x=0.421,y=0.353,source="quest_giver",zoneID=7637},questType="standard"},
[43810] = {id=43810,name="Down to Business",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=8025,description="First things first, : we must set up our camp. We do not have the time or resources for a prolonged siege. It is not like we can starve them out. No, we must be swift and sure as an arrow, piercing their heart in one strike. They are drawing up their battle lines within the city, but could attack us while we are setting up our defenses. Venture forth and show them what the kaldorei have learned from thousands of years of war. Discover their weaknesses so that we may exploit them.",starts={{npcID=114838,x=0.416,y=0.514,zoneID=7637}},ends={{npcID=114838,x=0.416,y=0.514,zoneID=7637}},coords={x=0.416,y=0.514,source="quest_giver",zoneID=7637},questType="standard"},
[43811] = {id=43811,name="Lunastre Estate Teleporter Online!",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Ancient Mana should get it back up and running.>",starts={{npcID=252815,x=0.436,y=0.792,zoneID=7637}},ends={{npcID=252815,x=0.436,y=0.792,zoneID=7637}},coords={x=0.436,y=0.792,source="quest_giver",zoneID=7637},questType="standard"},
[43812] = {id=43812,name="Down to Business",level=45,requiredLevel=45,faction="horde",expansion=6,zoneID=8025,description="Time to get to business, . We cannot afford to tarry. While we are not setting up for a prolonged engagement, we must still have a war camp of some sorts. I do not expect the Nightborne to stay patiently in their city while we plant stakes. They are starting to build their defenses. Go in there and see what we are up against. You will strike them from within while we finalize our preparations.",starts={{npcID=114841,x=0.406,y=0.53,zoneID=7637}},ends={{npcID=114841,x=0.406,y=0.53,zoneID=7637}},coords={x=0.406,y=0.53,source="quest_giver",zoneID=7637},questType="standard"},
[43813] = {id=43813,name="Sanctum of Order Teleporter Online!",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Ancient Mana should get it back up and running.>",starts={{npcID=252816,x=0.434,y=0.606,zoneID=7637}},ends={{npcID=252816,x=0.434,y=0.606,zoneID=7637}},coords={x=0.434,y=0.606,source="quest_giver",zoneID=7637},questType="standard"},
[43815] = {id=43815,name="Karthax",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[43829] = {id=43829,name="Spy vs. Spy",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="SI:7 is the espionage and intel branch of the Alliance. They are based out of Stormwind City and headed up by Master Mathias Shaw. As of late, they have been acting, shall we say, peculiar. I would like for you to send some of our people out to assess the situation. It might be nothing, but I am not fond of situations that I do not fully understand. If we are going to win this war against the Burning Legion, the last thing we need is for something wholly unexpected to occur.",questType="standard"},
[43832] = {id=43832,name="Elixirs of Aid",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7503,description="We can never be too prepared for battle. The Legion will strike at any moment, and we must be ready to deal with a multitude of injuries and afflictions. Zabra and Yalia have provided me a list of their most potent potions and battle elixirs than can do everything from restore health to blind the enemy. We have an exhaustive list of ingredients that we'll need in order to craft a respectable supply.",questType="standard"},
[43841] = {id=43841,name="Convincin' Old Yancey",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Avast ye! Th' time be long overdue that we get some more pirate blood into our ranks. And I know just th' man t' do it. I'm talkin' about good old Yancey Grillsen, o' course. He's an old salt down Stranglethorn way. Send some o' your land lovin' scallywags off t' round him up.",questType="standard"},
[43851] = {id=43851,name="Recruiting More Troops",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7834,description="Word of your leadership has spread rather fast. Priests of all sorts have traveled to the temple to lend their aid. We're lucky enough to have caught the eye of Vicar Eliza . She's quite the leader in her own right, commanding countless devotees that do her bidding without question. Speak to her now.",questType="standard"},
[43852] = {id=43852,name="Fancy Lads and Buccaneers",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Aye, it warms me heart t' know that Yancey's now part o' th' crew. Why don't you be a good and see if he can sponge us up some bilge rats.",questType="standard"},
[43882] = {id=43882,name="The Nighthold: Vaults",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8025,description="The Nighthold will be a challenge to infiltrate and conquer. Even the catacombs and vaults are likely to be heavily guarded, but we must make our way in by any route possible.",ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745},{npcID=98002,x=0.528,y=0.514,zoneID=7846},{npcID=99179,x=0.528,y=0.596,zoneID=7902},{npcID=103023,x=0.43,y=0.468,zoneID=7877},{npcID=106199,x=0.666,y=0.46,zoneID=7875}},questType="raid"},
