[43897] = {id=43897,name="Sealing Fate: Immense Fortune of Gold",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,questType="standard"},
[43898] = {id=43898,name="Preparing to Move",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Thanks to your tireless efforts the Heart of Zin-Azshari is ready to withstand the full power of the Legion. The final destination in our journey has stood defiantly in front of us from the moment we began - the Nighthold, now home to none other than Gul'dan himself. Before we move on the hold, we should reunite with the Moon Guard in Shal'Aran - we still have need of their skills, and I would wager that they have unfinished business with their former brothers and sisters.",starts={{npcID=111814,x=0.626,y=0.682,zoneID=7541}},ends={{npcID=111826,x=0.378,y=0.474,zoneID=7637}},coords={x=0.626,y=0.682,source="quest_giver",zoneID=7541},questType="standard"},
[43899] = {id=43899,name="Steeds of the Damned",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7543,description="Salanar the Horseman has arrived at Ebon Hold from the Realm of Shadows. He alone has the knowledge and power to conjure the steeds of the Four Horsemen. Salanar has given us the first list of necessary components to create the steeds. I have organized a number of missions to obtain these items. Use the mission table to assign your chosen champions to the task.",questType="standard"},
[43902] = {id=43902,name="The Emerald Nightmare: Fall of Cenarius",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8026,description="While we know that the Nightmare bends the boundary between reality and dream, there is no doubt of the threat upon us. Our own allies have fallen into darkness.",ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745},{npcID=98002,x=0.528,y=0.514,zoneID=7846},{npcID=99179,x=0.528,y=0.596,zoneID=7902},{npcID=103023,x=0.43,y=0.468,zoneID=7877},{npcID=106199,x=0.666,y=0.46,zoneID=7875}},questType="raid"},
[43903] = {id=43903,name="The Emerald Nightmare: Xavius",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8026,description="The time has come to tackle the source of the Nightmare, and restore balance to the Emerald Dream. Battle into the heart of the Nightmare, and face the Nightmare Lord Xavius .",ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745},{npcID=98002,x=0.528,y=0.514,zoneID=7846},{npcID=99179,x=0.528,y=0.596,zoneID=7902},{npcID=103023,x=0.43,y=0.468,zoneID=7877},{npcID=106199,x=0.666,y=0.46,zoneID=7875}},questType="raid"},
