[43910] = {id=43910,name="The Nighthold: High Botanist Tel'arn",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7834,description="The Nightborne are adept in more than one kind of magic, and we will likely face formidable foes inside the walls of the Nighthold . Their strongest mages and warriors must fall before we can hope to face Gul'dan.",ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745},{npcID=98002,x=0.528,y=0.514,zoneID=7846},{npcID=99179,x=0.528,y=0.596,zoneID=7902},{npcID=103023,x=0.43,y=0.468,zoneID=7877},{npcID=106199,x=0.666,y=0.46,zoneID=7875}},questType="raid"},
[43911] = {id=43911,name="The Nighthold: Elisande",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7834,description="Long ago, Grand Magistrix Elisande opposed the Legion and defied Queen Azshara herself. Passing millennia have changed Elisande 's mind, and turned her into an ally of the demons. The time has come to face her.",ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745},{npcID=98002,x=0.528,y=0.514,zoneID=7846},{npcID=99179,x=0.528,y=0.596,zoneID=7902},{npcID=103023,x=0.43,y=0.468,zoneID=7877},{npcID=106199,x=0.666,y=0.46,zoneID=7875}},questType="raid"},
[43912] = {id=43912,name="The Nighthold: Gul'dan",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8025,description="Gul'dan believed that the Legion was the destiny of the orcs, and has not paused in his brutal pursuit. Now, at last, the time has come to end his demonic crusade, and dispense justice for all.",ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745},{npcID=98002,x=0.528,y=0.514,zoneID=7846},{npcID=99179,x=0.528,y=0.596,zoneID=7902},{npcID=103023,x=0.43,y=0.468,zoneID=7877},{npcID=106199,x=0.666,y=0.46,zoneID=7875}},questType="raid"},
