[44135] = {id=44135,name="7.0 Val'sharah - Treasure 055 - Sundersong Glade - zto",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[44136] = {id=44136,name="7.0 Val'sharah - Treasure 056 - The Undergorge - zto",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[44137] = {id=44137,name="Into the Fray",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="The Burning Legion has beaten us here, but so too have the Illidari. It looks like the demon hunters are holding their own, but just barely. Come, let's put that weapon of yours to use. I'll figure out our next move while you crush the Legion.",starts={{npcID=93337,x=0.45,y=0.428,zoneID=7334}},ends={{npcID=89362,x=0.434,y=0.434,zoneID=7334},{npcID=101927,x=0.434,y=0.434,zoneID=7334}},coords={x=0.45,y=0.428,source="quest_giver",zoneID=7334},questType="standard"},
[44138] = {id=44138,name="7.0 Val'sharah - Treasure 057 - Kel'delar - ZTO",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[44139] = {id=44139,name="7.0 Val'sharah - Treasure 058 - Dreadroot - zto",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7558,mapID=641,questType="standard"},
[44140] = {id=44140,name="From Within",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7334,description="Our demon hunters, Kor'vas Bloodthorn and Cyana Nightglaive took a small force of the Illidari across to Faronaar. Their mission was to weaken the Legion from within. I haven't heard from them in a while. It would be best if you could find and lead them to success. Agreed?",starts={{npcID=89362,x=0.434,y=0.434,zoneID=7334}},ends={{npcID=90255,x=0.412,y=0.504,zoneID=7334}},coords={x=0.434,y=0.434,source="quest_giver",zoneID=7334},questType="standard"},
[44142] = {id=44142,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=16,mapID=76,questType="standard"},
