[44511] = {id=44511,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=16,mapID=76,questType="standard"},
[44543] = {id=44543,name="The Battle for Broken Shore",level=10,requiredLevel=10,faction="horde",expansion=6,zoneID=14,description="This wind rider will take you to Broken Shore, . May your weapon bring you many kills today. The Warchief has already made landfall, I will wager you will simply need to follow the trail of demon blood.",ends={{npcID=100453,x=0.572,y=0.104,zoneID=14}},questType="standard"},
[44544] = {id=44544,name="Call of the Earthen Ring",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7745,description="At last, I've found you! I have a message from Advisor Sevel . The Earthen Ring has need of you, Farseer. Please return to the Heart of Azeroth at your soonest convenience. Advisor Sevel is eagerly awaiting your return.",ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},questType="standard"},
[44545] = {id=44545,name="Pressing the Assault",level=10,requiredLevel=10,faction="none",expansion=6,questType="standard"},
[44547] = {id=44547,name="Isle Hopping",level=10,requiredLevel=10,faction="none",expansion=6,questType="standard"},
[44548] = {id=44548,name="Scouring What Remains",level=10,requiredLevel=10,faction="none",expansion=6,questType="standard"},
[44549] = {id=44549,name="Master of the Isles",level=10,requiredLevel=10,faction="none",expansion=6,questType="standard"},
[44550] = {id=44550,name="Called to Acherus",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7543,description="Deathlord, your presence has been requested on Acherus. The war against the Burning Legion rages on and the Knights of the Ebon Blade await further orders. Please return to Acherus at your soonest convenience. Siouxsie the Banshee is awaiting your return.",questType="standard"},
[44555] = {id=44555,name="Khadgar's Discovery",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,mapID=627,description="Champion! Please come to the Violet Citadel immediately. I have made a discovery that I would like to share with you before the Council of Six.",questType="standard"},
[44557] = {id=44557,name="Finite Numbers",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=41,mapID=42,description="It seems not all the protections I put in place have been defeated. The Legion isn't able to open portals inside or near the tower... at least, not yet. They appear to be bringing reinforcements in through the catacombs running beneath Deadwind Pass . Disable them and you just might buy us the time we need to drive them out of Karazhan.",questType="group"},
[44561] = {id=44561,name="Seed of Hope",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Thalyssra was wise to send you in search of the arcan'dor, though she underestimates its power. She will learn - as will the others. But it will take time. And with hunger gnawing at their very souls, the Nightfallen will need your help to survive.",starts={{npcID=107126,x=0.368,y=0.466,zoneID=7637}},ends={{npcID=107126,x=0.368,y=0.466,zoneID=7637}},coords={x=0.368,y=0.466,source="quest_giver",zoneID=7637},questType="standard"},
[44562] = {id=44562,name="Growing Strong",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Magic has long been a vice of the elves. It shaped us, and lifted us out of the darkness - but without balance, it also threatens to unmake us. The shal'dorei are too proud to admit it, but they are the product of indulgence. They live without harmony. But I sense potential among the Nightfallen . Losing everything has humbled them. It has made them stronger. Stay the course, $p. Help the Nightfallen rise up.",starts={{npcID=107126,x=0.368,y=0.466,zoneID=7637}},ends={{npcID=107126,x=0.368,y=0.466,zoneID=7637}},coords={x=0.368,y=0.466,source="quest_giver",zoneID=7637},questType="standard"},
[44563] = {id=44563,name="Redemption for the Fallen",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Soon the change of seasons will be upon us, and the Nightfallen will take command of their fate. You have given them hope, and set them on the path to redemption. They need you now more than ever. We all do.",starts={{npcID=107126,x=0.368,y=0.466,zoneID=7637}},ends={{npcID=107126,x=0.368,y=0.466,zoneID=7637}},coords={x=0.368,y=0.466,source="quest_giver",zoneID=7637},questType="standard"},
[44569] = {id=44569,name="Inquisitor Volitix",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[44578] = {id=44578,name="Honor the Flame",level=1,requiredLevel=1,faction="none",expansion=6,description="The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, ?",questType="standard"},
[44581] = {id=44581,name="Spicing Things Up",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,questType="standard"},
[44584] = {id=44584,name="Short-Supply Reward",level=45,requiredLevel=45,faction="none",expansion=6,questType="standard"},
[44613] = {id=44613,name="Honor the Flame",level=1,requiredLevel=1,faction="alliance",expansion=6,zoneID=7637,mapID=680,starts={{npcID=114519,x=0.23,y=0.584,mapID=680}},ends={{npcID=114519,x=0.23,y=0.584,mapID=680}},coords={x=0.23,y=0.584,source="quest_giver",mapID=680},questType="standard"},
[44614] = {id=44614,name="Honor the Flame",level=1,requiredLevel=1,faction="horde",expansion=6,zoneID=7637,mapID=680,starts={{npcID=114518,x=0.304,y=0.454,mapID=680}},ends={{npcID=114518,x=0.304,y=0.454,mapID=680}},coords={x=0.304,y=0.454,source="quest_giver",mapID=680},questType="standard"},
[44636] = {id=44636,name="Building an Army",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="We must keep our eyes on the future. There will come a time when we will need an army. We've proven that the withered are not completely beyond redemption. They can be taught, and molded. I want you to be their combat trainer, . Come with me. We can use the nearby ruins as an arena to hone their abilities.",starts={{npcID=97140,x=0.368,y=0.466,zoneID=7637},{npcID=115736,x=0.364,y=0.458,zoneID=7637}},coords={x=0.368,y=0.466,source="quest_giver",zoneID=7637},questType="standard"},
[44663] = {id=44663,name="In the Blink of an Eye",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="Azeroth needs you, ! After scouring Ulduar and Karazhan for answers, we know the key to defeating the Legion: five ancient artifacts called the Pillars of Creation. To find them, Dalaran must be moved to the Broken Isles. As our leader Jaina is... absent, Kalecgos of the blue dragonflight has offered the Kirin Tor his aid. The Legion is assaulting our current position over Deadwind Pass. Hurry!",starts={{npcID=95234,x=0.526,y=0.562,zoneID=1637},{npcID=101004,x=0.404,y=0.778,zoneID=1519}},coords={x=0.526,y=0.562,source="quest_giver",zoneID=1637},questType="standard"},
[44667] = {id=44667,name="Will of the Valarjar",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7813,description="As we prepare to launch an attack on the Legion's own world, it is important to not give reprieve to our enemies in this one. As your armies seek to secure enemy gateways, you would do well to return to the Broken Isles and carry on the battle against those who stand against you.",questType="standard"},
[44669] = {id=44669,name="Vicious Whale Shark",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[44670] = {id=44670,name="Broodmother Lizax",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[44671] = {id=44671,name="The Muscle",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[44672] = {id=44672,name="Ancient Mana",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Without the Nightwell to feed upon, my comrades and I will have to live off the land itself. Ancient mana from the underground leylines can reach the surface in many forms, most commonly as crystals or gems. This stone will glow when ancient mana is nearby. Please gather as much as possible! It will be a precious resource in the weeks to come.",starts={{npcID=97140,x=0.368,y=0.466,zoneID=7637}},ends={{npcID=97140,x=0.368,y=0.466,zoneID=7637}},coords={x=0.368,y=0.466,source="quest_giver",zoneID=7637},questType="standard"},
[44673] = {id=44673,name="Commander Soraax",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7334,mapID=630,questType="standard"},
[44675] = {id=44675,name="Lady Rivantas",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[44676] = {id=44676,name="Llorian",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[44677] = {id=44677,name="Ancient Mana Tutorial Chest A",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[44678] = {id=44678,name="Ancient Mana Tutorial Chest B",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[44679] = {id=44679,name="Ancient Mana Tutorial Chest C",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[44680] = {id=44680,name="Leading by Example",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7877,description="We cannot let our current situation overshadow the Unseen Path's mission to protect the people of Azeroth. There are many in this world who could use our help. As our leader, you can set the example by aiding those in need.",starts={{npcID=107973,x=0.434,y=0.26,zoneID=7877}},ends={{npcID=107973,x=0.434,y=0.26,zoneID=7877}},coords={x=0.434,y=0.26,source="quest_giver",zoneID=7877},questType="standard"},
[44682] = {id=44682,name="Unparalleled Power",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7875,description="Power is all around us, , waiting to be harnessed. You must venture out into the world and claim it for the council! With our First wielding such unparalleled power, our enemies won't stand a chance.",starts={{npcID=106199,x=0.666,y=0.46,zoneID=7875}},ends={{npcID=106199,x=0.666,y=0.46,zoneID=7875}},coords={x=0.666,y=0.46,source="quest_giver",zoneID=7875},questType="standard"},
[44683] = {id=44683,name="Holding the Lines",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=41,description="Karazhan sits upon a confluence of ley lines. It's why this location was chosen for the tower in the first place... a fact that has not escaped the Legion's notice. If the demons are tapping into these lines of power, they must need their energy for something particularly menacing. You must cut off their access to the ley lines if we're to have a chance of retaking the tower, .",starts={{npcID=114310,x=0.47,y=0.754,zoneID=41}},ends={{npcID=114310,x=0.47,y=0.754,zoneID=41}},coords={x=0.47,y=0.754,source="quest_giver",zoneID=41},questType="group"},
[44684] = {id=44684,name="Corruption Runs Deep",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=41,description="Everything the Legion touches is marred by fingerprints of their corruption. If I can study the traces of magic they leave behind, perhaps I can discern their plans for Karazhan. This vial is specially reinforced to contain fel magic. If you bring me the essences of corrupted soil and water from near their portals, I believe we'll be closer to unraveling their scheme.",starts={{npcID=114631,x=0.47,y=0.754,zoneID=41}},ends={{npcID=114631,x=0.47,y=0.754,zoneID=41}},coords={x=0.47,y=0.754,source="quest_giver",zoneID=41},questType="group"},
[44685] = {id=44685,name="Reclaiming the Ramparts",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=41,description="With the ley lines protected we must move to secure the tower's perimeter. Around the tower are several locations where corruption continues to run rampant. Seek out these locations and secure them with these wards. With the progress we've made so far, bolstering our defenses should keep the remaining Legion's forces at bay just long enough for us to discover who's behind their efforts.",starts={{npcID=114310,x=0.47,y=0.754,zoneID=41}},ends={{npcID=114310,x=0.47,y=0.754,zoneID=41}},coords={x=0.47,y=0.754,source="quest_giver",zoneID=41},questType="group"},
[44686] = {id=44686,name="Thought Collection",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=41,description="While I examine these samples further, I ask that you seek out one of our patrols in the structure to the north. It appears they've captured one of the demons. Go, interrogate it. Find out anything you can. And hurry! I'm afraid time is no longer an ally.",starts={{npcID=114631,x=0.47,y=0.754,zoneID=41}},ends={{npcID=114631,x=0.47,y=0.754,zoneID=41}},coords={x=0.47,y=0.754,source="quest_giver",zoneID=41},questType="standard"},
[44689] = {id=44689,name="The Might of the Tirisgarde",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7879,description="The Tirisgarde has received requests from across the Broken Isles for aid in fighting the Burning Legion. While we will continue pursuing Archmage Vargoth, we cannot forget that our primary mission is to repel the demons and protect Azeroth.",questType="standard"},
[44690] = {id=44690,name="A Thirst For Blood",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7695,questType="standard"},
[44691] = {id=44691,name="Hungry Work",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="We must get Chief Telemancer Oculeth back on his feet as soon as possible. Find ancient mana, any way you can, and feed it to him.",starts={{npcID=97140,x=0.368,y=0.466,zoneID=7637}},ends={{npcID=98548,x=0.366,y=0.45,zoneID=7637}},coords={x=0.368,y=0.466,source="quest_giver",zoneID=7637},questType="standard"},
[44694] = {id=44694,name="One Battle at a Time",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8022,description="Before I became a demon hunter, I practiced the arcane arts. I still retain some of that knowledge, though the fel makes it all but impossible to use. One thing I can still manage is the occasional glimpse into faraway places. You've seen me use the nether crucible to do this. I'm afraid that things don't look too good. The forces that are arrayed against us are not limited to the Burning Legion. You must act quickly to keep the Broken Isles from being overwhelmed.",questType="standard"},
[44700] = {id=44700,name="Stormheim",level=10,requiredLevel=10,faction="alliance",expansion=6,zoneID=7502,description="It is good we found you, ! Sky Admiral Rogers has sent word for you to meet her in Dalaran. It sounded important. She awaits your presence in the Violet Citadel. Make haste!",starts={{npcID=107460,x=0.302,y=0.406,zoneID=7541}},ends={{npcID=96644,x=0.188,y=0.426,zoneID=1519}},coords={x=0.302,y=0.406,source="quest_giver",zoneID=7541},questType="standard"},
[44701] = {id=44701,name="Stormheim",level=10,requiredLevel=10,faction="horde",expansion=6,zoneID=7502,description="It is good we found you, ! Nathanos Blightcaller , Champion of the Banshee Queen herself, sent for you in Dalaran. He made it sound urgent. He should be waiting for you in the Violet Citadel. Make haste!",starts={{npcID=107460,x=0.302,y=0.406,zoneID=7541}},ends={{npcID=96683,x=0.612,y=0.088,zoneID=14}},coords={x=0.302,y=0.406,source="quest_giver",zoneID=7541},questType="standard"},
[44719] = {id=44719,name="Breaching the Sanctum",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="It is time. Valtrois is ready to destroy the barrier guarding the breach in the Sanctum. I will teleport you to the breach, then it falls on you to secure the area. Take these telemancy orbs . If you find you need support, use them to summon Withered. We must strike before the enemy can ready new defenses. Let me know when you are ready and we will begin.",starts={{npcID=115710,x=0.366,y=0.45,zoneID=7637}},ends={{npcID=115367,x=0.442,y=0.6,zoneID=7637}},coords={x=0.366,y=0.45,source="quest_giver",zoneID=7637},questType="standard"},
[44720] = {id=44720,name="A Call to Action",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7541,description="Champion, I require your aid. It seems Helya has shown her hand. Steel yourself then come to me.",starts={{npcID=119531,x=0.446,y=0.64,zoneID=7543}},ends={{npcID=92539,x=0.602,y=0.508,zoneID=7541}},coords={x=0.446,y=0.64,source="quest_giver",zoneID=7543},questType="standard"},
[44721] = {id=44721,name="Helya's Conquest",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7541,description="If Helya is making an advance on the Broken Isles, we will need to answer in turn. Go to Tideskorn Harbor and scout her forces. We will see if Helya is foolish enough to begin her campaign against me.",starts={{npcID=92539,x=0.602,y=0.508,zoneID=7541}},ends={{npcID=92539,x=0.602,y=0.508,zoneID=7541}},coords={x=0.602,y=0.508,source="quest_giver",zoneID=7541},questType="standard"},
[44722] = {id=44722,name="Disillusioned Defector",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="The atmosphere in the city has improved little, but we may find this to our advantage today. Silgryn asks for you at the Terrace. It seems even Elisande's forces are fleeing before her insanity. A defector has risen from the ranks and seeks to join our cause. See that this individual is well received, . We need all the friends we can get during these dark times.",starts={{npcID=115736,x=0.364,y=0.458,zoneID=7637}},ends={{npcID=114948,x=0.524,y=0.802,zoneID=7637}},coords={x=0.364,y=0.458,source="quest_giver",zoneID=7637},questType="standard"},
[44723] = {id=44723,name="More Like Me",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Greetings, Outlander. I am Victoire . I served Elisande while she maintained peace in the city. I fought beside demons and worse for the greater good. The massacre at the Waning Crescent made it clear that she no longer serves the Nightborne. She serves only herself. There are others who feel as I do. They simply need proof that there is another way. The Dusk Lily is not unknown to us- try showing it to those now guarding Astravar Harbor. They have seen the worst of Elisande's cruelty.",starts={{npcID=114956,x=0.52,y=0.79,zoneID=7637}},ends={{npcID=114956,x=0.52,y=0.79,zoneID=7637}},coords={x=0.52,y=0.79,source="quest_giver",zoneID=7637},questType="standard"},
[44724] = {id=44724,name="Missing Persons",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Our new friend brings us some disturbing information. She claims to have seen a large number of citizens dragged from Starcaller Retreat in chains. Their destination appears to be Astravar Harbor. Those taken to the harbor have yet to return, however. Worse yet, the area is now overrun with demons. I need you to find out where these people went. Infiltrate the harbor and gather any information you can. Start with the Legion filth- their corpses may point us in the right direction.",starts={{npcID=114948,x=0.524,y=0.802,zoneID=7637}},ends={{npcID=114948,x=0.524,y=0.802,zoneID=7637}},coords={x=0.524,y=0.802,source="quest_giver",zoneID=7637},questType="standard"},
[44725] = {id=44725,name="Hostage Situation",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Our own people, sacrificed to the Legion! We need to intercept a transport if we intend to put an end to this trade. I'm afraid this does mean you will be playing the part of a captive, my friend. Before voicing your concerns, try to have a little faith. We will follow behind in one of Deline's boats and break you out once we know where they are going. Go to the harbor and find a group of captives. Stand among them. Allow yourself to be taken. We will not be far.",starts={{npcID=114948,x=0.524,y=0.802,zoneID=7637}},ends={{npcID=115067,x=0.248,y=0.888,zoneID=7637}},coords={x=0.524,y=0.802,source="quest_giver",zoneID=7637},questType="standard"},
[44726] = {id=44726,name="In the Business of Souls",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="We will hold our position here while you find and slay the demon responsible for this camp. Ending Aargoss will not permanently stop this smuggling operation, but it may slow them down long enough for us to find another way to help these people. Go quickly. He is somewhere atop this ridge.",starts={{npcID=115067,x=0.248,y=0.888,zoneID=7637}},ends={{npcID=115067,x=0.248,y=0.888,zoneID=7637}},coords={x=0.248,y=0.888,source="quest_giver",zoneID=7637},questType="standard"},
[44727] = {id=44727,name="Smuggled!",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Please get me out of here! The bars are brittle but I am so weak... The others! There are so many others! Please help us!",starts={{npcID=115002,x=0.258,y=0.884,zoneID=7637}},ends={{npcID=115376,x=0.248,y=0.888,zoneID=7637}},coords={x=0.258,y=0.884,source="quest_giver",zoneID=7637},questType="standard"},
[44728] = {id=44728,name="REUSE ME",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[44729] = {id=44729,name="Trial of Valor: Odyn's Favor",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8440,description="The time to deal with that treacherous witch has come. I suspect you may be the one to deal the final blow, but I must be certain. See me in the Halls of Valor and we will test the strength of your will.",starts={{npcID=92539,x=0.602,y=0.508,zoneID=7541}},coords={x=0.602,y=0.508,source="quest_giver",zoneID=7541},questType="raid"},
[44731] = {id=44731,name="Whitewater Wash Treasure",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7503,mapID=650,questType="standard"},
[44732] = {id=44732,name="Morgalash",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[44733] = {id=44733,name="The Power of Corruption",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=41,description="The time has come at last. Deep within the cavernous underbelly of Karazhan lies a long-forgotten chamber. Based on what you learned from our demon friend, I believe this is where its mistress dwells. This demon's master must come from the highest ranks of the Burning Legion. This does not bode well for Karazhan. We need to secure Deadwind Pass , . You must find this demon and destroy it.",questType="group"},
[44734] = {id=44734,name="Fragments of the Past",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8443,description="Though your primary objective is to liberate the tower from the Legion's hold, I have... another request. Karazhan is a place where magic and history intertwine. Moments of the past have been known to take physical form, and these forms can possess great power. As you journey through Karazhan, watch for places where memories coalesce. These fragments could provide valuable insight into what's really going on inside that tower.",starts={{npcID=114310,x=0.47,y=0.754,zoneID=41}},ends={{npcID=114310,x=0.47,y=0.754,zoneID=41}},coords={x=0.47,y=0.754,source="quest_giver",zoneID=41},questType="dungeon"},
[44735] = {id=44735,name="Return to Karazhan: In the Eye of the Beholder",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8443,description="The Legion's intentions are clear. They intend to harness the tower's magical energy to communicate with other Legion worlds! I'm afraid we haven't much time, . You must ascend the tower and destroy this monstrosity before it is too late!",starts={{npcID=114310,x=0.47,y=0.754,zoneID=41}},ends={{npcID=114310,x=0.47,y=0.754,zoneID=41}},coords={x=0.47,y=0.754,source="quest_giver",zoneID=41},questType="dungeon"},
[44736] = {id=44736,name="Gates of the Nighthold",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Our combined armies are arrayed in front of the palace, ready to strike! I cannot believe the time has come. Your allied commanders are already there and we will join you. Make your way to Astravar Harbor and speak with Khadgar. He is coordinating the attack, or at least I think he is. See you there... and thanks for everything.",starts={{npcID=115736,x=0.364,y=0.458,zoneID=7637}},ends={{npcID=115039,x=0.548,y=0.728,zoneID=7637}},coords={x=0.364,y=0.458,source="quest_giver",zoneID=7637},questType="standard"},
[44738] = {id=44738,name="Full Might of the Elves",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Thalyssra managed to get all 3 to agree to the same thing? I am impressed with her skills of negotiation. Alright hero, Liadrin is already marching on Suramar . Join her forces. Tyrande will flank the city defenders and meet you deeper in. The Nightborne will bring up the rear and hold the territory for us. Oculeth and I will move the Kirin Tor forces to Astravar Harbor. With luck, we shall see you on the other side.",starts={{npcID=114909,x=0.41,y=0.518,zoneID=7637}},ends={{npcID=115039,x=0.548,y=0.728,zoneID=7637}},coords={x=0.41,y=0.518,source="quest_giver",zoneID=7637},questType="standard"},
[44739] = {id=44739,name="Ready for Battle",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8025,description="Thanks to your efforts and a lot of effort on the part of our new army, the Nightfallen are prepared for battle. What is more, we have managed to evacuate nearly all of the civilians between here and Astravar Harbor. I have drafted plans that can lead our combined forces through the city and take the harbor. Can you deliver these plans to Vereesa, Tyrande and Liadrin?",starts={{npcID=115736,x=0.364,y=0.458,zoneID=7637}},ends={{npcID=114909,x=0.41,y=0.518,zoneID=7637}},coords={x=0.364,y=0.458,source="quest_giver",zoneID=7637},questType="standard"},
[44740] = {id=44740,name="Staging Point",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="That is quite a corridor you and our allies have punched through the city. It will be difficult to hold but it will cut a wedge in Elisande's forces. Oculeth has been busy redirecting a telemancy beacon to this location but wanted to give you the honor of activating it.",starts={{npcID=115039,x=0.548,y=0.728,zoneID=7637}},ends={{npcID=115039,x=0.548,y=0.728,zoneID=7637}},coords={x=0.548,y=0.728,source="quest_giver",zoneID=7637},questType="standard"},
[44741] = {id=44741,name="Return to Karazhan: The Big Bag Theory",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8443,description="I'm sure you've heard, , that a bigger bag is always better. I disagree. I believe it's the quality of the bag that makes all the difference. Just look at those tattered things around your person. They make you look... well, quite plain. I'll prove it to you. Allegedly there are some bags in Karazhan that hold an almost infinite amount of items, but the materials required to make such bags are... well, you'll see.",starts={{npcID=93969,x=0.404,y=0.694,zoneID=7637}},ends={{npcID=93969,x=0.404,y=0.694,zoneID=7637}},coords={x=0.404,y=0.694,source="quest_giver",zoneID=7637},questType="standard"},
[44742] = {id=44742,name="Tavernkeeper's Fate",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="I have finished unraveling Ly'leth's message. I want you to come with me to her estate. It is long past time I returned to the city.",starts={{npcID=115736,x=0.364,y=0.458,zoneID=7637}},ends={{npcID=115247,x=0.432,y=0.788,zoneID=7637}},coords={x=0.364,y=0.458,source="quest_giver",zoneID=7637},questType="standard"},
[44743] = {id=44743,name="Tyrande's Command",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=8025,description="Shal'aran is bursting at the seams with refugees and rebels. We practically have an army now but not enough weapons or mana to keep everyone armed and un-withered. And in all of this, Tyrande has a battery of requests I simply do not have the time to deal with. Will you go to her? Her growing army is hard to miss in Meredil.",starts={{npcID=115736,x=0.364,y=0.458,zoneID=7637}},ends={{npcID=114838,x=0.416,y=0.514,zoneID=7637}},coords={x=0.364,y=0.458,source="quest_giver",zoneID=7637},questType="standard"},
[44752] = {id=44752,name="Essence Triangulation",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Vanthir... an example! That certainly explains why Elisande chose to hold him this long. We need to move quickly. I can track him, but I will need to find places where his Arcane Essence is strongest. This will not be an easy feat, not in a city this old, but with any luck there are a few places important enough to him that he left a little bit of himself behind. We should start in the promenade- he often visited it for business.",starts={{npcID=115248,x=0.432,y=0.788,zoneID=7637}},ends={{npcID=115248,x=0.432,y=0.788,zoneID=7637}},coords={x=0.432,y=0.788,source="quest_giver",zoneID=7637},questType="standard"},
[44753] = {id=44753,name="On Public Display",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Now that I have identified Vanthir's essence from the multitude of Suramar 's citizens, it may be that I can find his exact location. I believe you'll recall a similar ritual with our friend Theryn. Do not worry- there will be less screaming this time. Hopefully. Come. Let us find our missing tavernkeeper.",starts={{npcID=115248,x=0.432,y=0.788,zoneID=7637}},ends={{npcID=115557,x=0.522,y=0.79,zoneID=7637}},coords={x=0.432,y=0.788,source="quest_giver",zoneID=7637},questType="standard"},
[44754] = {id=44754,name="Waxing Crescent",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="His captor is familiar to me. He is one of Aluriel's lieutenants and a skilled spell-fencer at that. You will need Silgryn's help to retrieve the key to Vanthir 's prison. Our friend's life hangs in the balance. Even if we manage to wrestle him from the executioner's grasp, he may well Wither before we can act. I need you to take an Arcan'dor fruit to him. They are precious, and few, but for Vanthir this is the only chance he has. Go quickly, and good luck.",starts={{npcID=115557,x=0.522,y=0.79,zoneID=7637}},ends={{npcID=115604,x=0.488,y=0.67,zoneID=7637}},coords={x=0.522,y=0.79,source="quest_giver",zoneID=7637},questType="standard"},
[44756] = {id=44756,name="Sign of the Dusk Lily",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="Simply... astounding. I have not felt this clear of mind in so long. I am still weak... I need to rest. But first... Vanthir gestures to the top of his cage with a trembling hand.> Show them that the Dusk Lily triumphs this day.",starts={{npcID=115604,x=0.488,y=0.67,zoneID=7637}},ends={{npcID=115736,x=0.364,y=0.458,zoneID=7637}},coords={x=0.488,y=0.67,source="quest_giver",zoneID=7637},questType="standard"},
[44758] = {id=44758,name="What's the Cache?",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=7334,description="We're here for a cache of gunpowder. It seems to have been infused with some sort of fel power... it's extremely reactive. One of the leaders of the pirate forces here currently has it. Master Gunner Prix should be toward the back of the cove, near the water. Take what we need from her.",starts={{npcID=119821,x=0.576,y=0.634,zoneID=7334}},ends={{npcID=119821,x=0.576,y=0.634,zoneID=7334}},coords={x=0.576,y=0.634,source="quest_giver",zoneID=7334},questType="standard"},
[44760] = {id=44760,name="Blood On Your Hands",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7502,mapID=627,questType="standard"},
[44764] = {id=44764,name="Demon in Disguise",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=41,description="While you were... working your magic on that demon, I was able to make headway in distilling the corrupted essences down to a simpler, more manageable form. I've asked Khadgar to provide you with the concoction once he's had a look, but I must remind you - these essences are quite potent, often dangerous if not handled with the utmost of care. Speak with Khadgar when you are ready to begin.",starts={{npcID=114631,x=0.47,y=0.754,zoneID=41}},ends={{npcID=114310,x=0.47,y=0.754,zoneID=41}},coords={x=0.47,y=0.754,source="quest_giver",zoneID=41},questType="group"},
[44766] = {id=44766,name="Backup Plan",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7879,description="Dalaran may appear to be just a floating city, but it is actually our most powerful magical weapon. It will take time to repair the arcane defenses - time the Legion will use to their great advantage. It is imperative to come up with an interim plan, and quickly! Archmage Kalec is very knowledgeable about this sort of thing. Perhaps you should consult with him?",questType="standard"},
[44768] = {id=44768,name="Nyell's Workshop",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7879,description="From what I've overheard, this is Master Artificer Nyell 's workshop. His skills in construct creation are unparalleled! What a shame that he swore fealty to the Legion. I hate to destroy such a renowned craftsman, but we have no choice. If you are lucky, he might even have a spare shield generator sitting around.",questType="standard"},
[44770] = {id=44770,name="Secrets of the Shal'dorei",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7879,description="This workshop includes an extensive library of rare scrolls written by my people. We all benefit by sharing information, do you not agree? Perhaps if we bring back such a treasure trove the Tirisgarde will be more welcoming towards me and my kind... Please gather whatever you can.",questType="standard"},
[44771] = {id=44771,name="A Threat Rises",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7541,description="It is time I told you another tale. While you listen, would you be so kind as to pour me some grog? I've grown a terrible thirst. The keg is very old and the tap is a bit slow.",starts={{npcID=92539,x=0.602,y=0.508,zoneID=7541}},ends={{npcID=92539,x=0.602,y=0.508,zoneID=7541}},coords={x=0.602,y=0.508,source="quest_giver",zoneID=7541},questType="standard"},
[44775] = {id=44775,name="The Peak of Bones",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7541,description="While you were gone, we strategized what to do with the harness. We can utilize its power to bind the spirits of deceased drakes to you, raising them under your will as loyal soldiers. I sent Minerva to Thorim's Peak in Stormheim, where she has found a brood of deceased Thorignir. They will be prime targets. Speak to Grimwing for a flight to the mountain, then Minerva will fill you in.",starts={{npcID=113695,x=0.976,y=0.56,zoneID=7543},{npcID=113695,x=0.266,y=0.294,zoneID=7543}},ends={{npcID=115360,x=0.512,y=0.842,zoneID=7541}},coords={x=0.976,y=0.56,source="quest_giver",zoneID=7543},questType="standard"},
[44777] = {id=44777,name="REUSE ME",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7637,mapID=680,questType="standard"},
[44781] = {id=44781,name="The Council's Call",level=1,requiredLevel=1,faction="both",expansion=6,questType="standard"},
[44782] = {id=44782,name="Away From Prying Eyes",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=7502,description="Wars are not won solely with armies charging bravely across the battlefield, t. Sometimes, it is the actions of individuals that matter most, fighting battles few ever hear about. That is why - We should really discuss this somewhere a tad more private. Let's move up to the Purple Parlor, shall we?",questType="standard"},
[44785] = {id=44785,name="Tea Party",level=20,requiredLevel=20,faction="alliance",expansion=6,zoneID=8721,description="I...I-I'm sorry. I... I can't... A... Abby? Wh...",starts={{npcID=122493,x=0.546,y=0.49,zoneID=8721}},ends={{npcID=123123,x=0.578,y=0.478,zoneID=8721}},coords={x=0.546,y=0.49,source="quest_giver",zoneID=8721},questType="standard"},
[44787] = {id=44787,name="The Bonemother",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7541,description="It's time to call the mother, the true reason we came. She is strong, her sheer will and strength allowing her to face this peak in order to watch over the remains of her brood. While the Thorignir is a grand sight, I like my dragons a little more bony. She must die first. Remember the pyre where we met? She is its guardian, as the spirit was at the peak. If we light it, she will come.",ends={{npcID=113695,x=0.976,y=0.56,zoneID=7543},{npcID=113695,x=0.266,y=0.294,zoneID=7543}},questType="standard"},
[44789] = {id=44789,name="Holding the Ramparts",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7558,description="With their ground presence weakened the Legion has retaliated with additional forces. Our allies managed to track several of these demons to the skies above Black Rook. I fear they intend to establish a foothold. Take this hippogryph and scout the ramparts . Should this fear become a reality I ask that you deal with the threat swiftly.",starts={{npcID=118183,x=0.39,y=0.516,zoneID=7558}},ends={{npcID=118250,x=0.44,y=0.506,zoneID=7558}},coords={x=0.39,y=0.516,source="quest_giver",zoneID=7558},questType="standard"},
[44790] = {id=44790,name="Trial by Demonfire",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="We are out of time. I have reports that a pitlord has come to Meredil. I have dispatched a strike force. We cannot let this demon flank our army here, nor can we let him find Shal'Aran. It is time to temper these recruits in a real battle. Join our forces in Meredil, engage the demon, and help us ensure this new army of ours is not lost in its first conflict.",starts={{npcID=115499,x=0.398,y=0.51,zoneID=7637}},ends={{npcID=115499,x=0.398,y=0.51,zoneID=7637}},coords={x=0.398,y=0.51,source="quest_giver",zoneID=7637},questType="standard"},
[44800] = {id=44800,name="Against Magatha's Will",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7745,description="Well? What are you waiting for? Hand over the Doomstone.",starts={{npcID=120244,x=0.422,y=0.452,zoneID=400}},ends={{npcID=106519,x=0.304,y=0.518,zoneID=7745}},coords={x=0.422,y=0.452,source="quest_giver",zoneID=400},questType="standard"},
[44803] = {id=44803,name="Return to Karazhan: Master of the House",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8443,description="Inside the pocket watch is a worn note. \"The next affair will take place in Morgan's Plot, it will cause quite a stir! The following guests will be in attendance: Lord Ference, his preferred vintage is red. Baroness Millstipe, she will only attend on the promise of cheese. Strange woman. Baron Dreuger, a ravenous soul, any well spiced meat should keep him happy. As always, I shall ring the bell should I need you. - Medivh\"",ends={{npcID=115551,x=0.398,y=0.754,zoneID=41}},questType="standard"},
[44814] = {id=44814,name="Waning Refuge",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="We have done all we can here. Let us get everyone into the boat and get out while we still can. We have bought time for the others but nothing more.",starts={{npcID=115067,x=0.248,y=0.888,zoneID=7637}},ends={{npcID=114948,x=0.524,y=0.802,zoneID=7637}},coords={x=0.248,y=0.888,source="quest_giver",zoneID=7637},questType="standard"},
[44821] = {id=44821,name="In Dire Need",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=7502,description="The ill tidings you bear only increase the concerns the Council has been having. I know you have your hands full with the Tomb of Sargeras. Make no mistake, the battle for the tomb remains our top priority--but we must not think the Legion foolish enough to rely on brute force alone. They are far more cunning than that. Please, hear us out.",questType="standard"},
[44822] = {id=44822,name="Temporal Investigations",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="I knew the shal'dorei dabbled in time magic, but this is simply incredible... Elisande stopped time on our entire army! Come, let us investigate. Perhaps there is a way to break the spell - or at least discover how it is being maintained.",starts={{npcID=115039,x=0.548,y=0.728,zoneID=7637}},ends={{npcID=115039,x=0.548,y=0.728,zoneID=7637}},coords={x=0.548,y=0.728,source="quest_giver",zoneID=7637},questType="standard"},
[44825] = {id=44825,name="Wisp in the Willows",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=7558,description="Wisps are the spirits of our Night elven brethren who have become one with the forest. But their minds and the way they perceive things are very different than in life. You should bond with this little one. See through its eyes as it travels to the hidden pools and grows some trees.",questType="standard"},
[44827] = {id=44827,name="Citizens' Army",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7558,description="I can barely get these civilians to stand in a straight line. They are untrained, undisciplined, and underarmed. Still, they need to be ready for the real battle. Khadgar suggested we try some field training at the ruins of Black Rook Hold in Val'sharah. The risen forces of Lord Ravencrest apparently remember how to fight. Go, hero, and I will send some trainees to support you.",starts={{npcID=116256,x=0.398,y=0.512,zoneID=7637}},ends={{npcID=116256,x=0.398,y=0.512,zoneID=7637}},coords={x=0.398,y=0.512,source="quest_giver",zoneID=7637},questType="standard"},
[44829] = {id=44829,name="We Need Weapons",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="So many of the rebels want to help in the coming battle. Our people have the will, they lack only the means. They need weapons. From what Khadgar has told me, the fortress of Black Rook has plenty of munitions we could use. Travel to the fortress and place these beacons on some weapon caches there. Once placed, I can teleport them back.",starts={{npcID=115342,x=0.398,y=0.514,zoneID=7637}},ends={{npcID=115342,x=0.398,y=0.514,zoneID=7637}},coords={x=0.398,y=0.514,source="quest_giver",zoneID=7637},questType="standard"},
[44830] = {id=44830,name="Learning From the Dead",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="I heard you were traveling to Black Rook Hold. It was once home to the legendary Lord Ravencrest, a brilliant tactician. His knowledge may be exactly what we need to give us an edge against the Duskwatch. While you are at the Rook, keep your eyes peeled for any books that might have survived the ages that outline the Ravencrest's strategems.",starts={{npcID=115499,x=0.398,y=0.51,zoneID=7637}},ends={{npcID=115499,x=0.398,y=0.51,zoneID=7637}},coords={x=0.398,y=0.51,source="quest_giver",zoneID=7637},questType="standard"},
[44831] = {id=44831,name="Taking a Promenade",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=7637,description="These people are foreign to us, despite our common heritage. They have changed much in the years they have been cloistered away. We need to learn more about them, what they are capable of. We dispatched one of our scouts to infiltrate the Promenade and assess the defenses. The blood elves did the same, although I doubt their ability to be discreet. Both are long past due for reporting back to us. Find them and make sure they are safe or at least did not die in vain.",starts={{npcID=114963,x=0.428,y=0.514,zoneID=7637}},ends={{npcID=114963,x=0.428,y=0.514,zoneID=7637}},coords={x=0.428,y=0.514,source="quest_giver",zoneID=7637},questType="standard"},
[44832] = {id=44832,name="Scouting the Breach",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="If Ly'leth's information is accurate, there is a breach in the Sanctum of Order that could be our only way into the Nighthold. No doubt they have magically sealed it - take Valtrois and protect her while she examines the seal. She is an exceptional talent, and I have total faith in her ability to break whatever enchantment they have cooked up. Valtrois has her own methods of getting into the city and will meet you inside the Sanctum of Order.",starts={{npcID=115736,x=0.364,y=0.458,zoneID=7637}},ends={{npcID=115524,x=0.44,y=0.598,zoneID=7637}},coords={x=0.364,y=0.458,source="quest_giver",zoneID=7637},questType="standard"},
[44833] = {id=44833,name="The Seal's Power",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="The Nightwell is so overloaded that they could not spare anything for this seal. Instead, they are borrowing power from the ley lines. I have traced one of their power sources to Kel'balor. We should head there immediately so I can determine how best to disable this barrier. Yes of course I said \"we.\" Surely you do not expect me to go without my bodyguard, do you? I shall meet you there!",starts={{npcID=115524,x=0.44,y=0.598,zoneID=7637}},ends={{npcID=115736,x=0.364,y=0.458,zoneID=7637}},coords={x=0.44,y=0.598,source="quest_giver",zoneID=7637},questType="standard"},
[44834] = {id=44834,name="Nullified",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="The magus in charge of the defenses here is powerful. Perhaps too strong, even for the both of us. Fortunately, the sin'dorei know a thing or two about magic. The mage's barrier is strong, but we are clever. He has somehow channeled enough energy into his staff to power another set of defense portals, but he has left it out of his sight. Bring me the staff and an energy source from one of those constructs. I should be able to create just the thing we need to take that shield out.",starts={{npcID=115517,x=0.464,y=0.58,zoneID=7637}},ends={{npcID=115517,x=0.464,y=0.58,zoneID=7637}},coords={x=0.464,y=0.58,source="quest_giver",zoneID=7637},questType="standard"},
[44842] = {id=44842,name="Shield, Meet Spell",level=45,requiredLevel=45,faction="horde",expansion=6,zoneID=7637,description="There you have it, one arcane nullifier ! Using their weapon and magical signatures to cloak the spell, it should tear apart the shield as good as any spellbreaker would. Go teach that amateur spellslinger what it means to wage war against the sin'dorei!",starts={{npcID=115517,x=0.464,y=0.58,zoneID=7637}},ends={{npcID=115517,x=0.464,y=0.58,zoneID=7637}},coords={x=0.464,y=0.58,source="quest_giver",zoneID=7637},questType="standard"},
[44843] = {id=44843,name="Crystal Clearing",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=7637,description="This portal is a problem. With it they can summon countless reserves. The crystals nearby seem to be powering the gate. If we destroy those, we can set them back significantly.",starts={{npcID=115521,x=0.406,y=0.644,zoneID=7637}},ends={{npcID=115521,x=0.406,y=0.644,zoneID=7637}},coords={x=0.406,y=0.644,source="quest_giver",zoneID=7637},questType="standard"},
[44844] = {id=44844,name="Powering Down the Portal",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=7637,description="Destroying the crystals will stop them temporarily, but it will be meaningless if we do not deal with the person controlling the portal itself. I heard their overseer, Ingra, shouting orders for more power so that she could bring the stronger Legion lieutenants through the gate. We must stop her to truly seal the portal for good.",starts={{npcID=115521,x=0.406,y=0.644,zoneID=7637}},ends={{npcID=115521,x=0.406,y=0.644,zoneID=7637}},coords={x=0.406,y=0.644,source="quest_giver",zoneID=7637},questType="standard"},
[44845] = {id=44845,name="Break An Arm",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="The insurgents you marshaled gave me some bad news, . The arcanists loyal to Elisande have reactivated the Arm of the Magistrix . The most powerful construct ever attempted, it raged out of control and decimated an entire district before it was disabled. Truly they must be desperate to turn it against us. The scouts have spotted it in the Crimson Thicket to the north. We cannot allow it to reach full power if we are to succeed.",starts={{npcID=114908,x=0.416,y=0.516,zoneID=7637}},ends={{npcID=114908,x=0.416,y=0.516,zoneID=7637}},coords={x=0.416,y=0.516,source="quest_giver",zoneID=7637},questType="group"},
[44849] = {id=44849,name="Recruitment Drive",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7588,description="Helya's kvaldir have been raiding Azeroth's coasts for centuries, and many worthy vrykul who were destined to become my Valarjar were stolen. Now that their cursed queen is defeated, the souls held captive in Helheim can finally be freed to join us! Go to Helheim with Aerylia . I assure you she will bring you back safely.",ends={{npcID=116193,x=0.346,y=0.288,zoneID=7588}},questType="standard"},
[44850] = {id=44850,name="Arming the Army",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7588,description="The recent battles have greatly depleted our supplies, and we will need arms for our new Valarjar. The kvaldir have an abundance of weapons, armor, and other spoils from their raiding stockpiled in stolen crates. Confiscate whatever you can!",starts={{npcID=116193,x=0.346,y=0.288,zoneID=7588}},ends={{npcID=116193,x=0.346,y=0.288,zoneID=7588}},coords={x=0.346,y=0.288,source="quest_giver",zoneID=7588},questType="standard"},
[44858] = {id=44858,name="Trolling Them",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=8025,description="My army is disciplined, and they will follow my order not to engage the Sin'dorei in combat unless I give the command. However, it is with some level of shame that I must admit both armies have been attempting to harass the other with pranks, littering our respective camps with insults. Please, $p, we need someone both armies respect to collect these items before fighting breaks out.",starts={{npcID=114838,x=0.416,y=0.514,zoneID=7637}},ends={{npcID=114838,x=0.416,y=0.514,zoneID=7637}},coords={x=0.416,y=0.514,source="quest_giver",zoneID=7637},questType="standard"},
[44859] = {id=44859,name="Liadrin's Command",level=45,requiredLevel=45,faction="horde",expansion=6,zoneID=8025,description="Shal'Aran is bursting at the seams with refugees and rebels. We practically have an army now but not enough weapons or mana to keep everyone armed and un-withered. And in all of this, Lady Liadrin has a battery of requests I simply do not have the time to deal with. Will you go to her? Her growing army is hard to miss in Meredil.",starts={{npcID=115736,x=0.364,y=0.458,zoneID=7637}},ends={{npcID=114841,x=0.406,y=0.53,zoneID=7637}},coords={x=0.364,y=0.458,source="quest_giver",zoneID=7637},questType="standard"},
[44860] = {id=44860,name="Trolling Them",level=45,requiredLevel=45,faction="horde",expansion=6,zoneID=8025,description="My army is disciplined, and they will follow my order not to engage the kaldorei in combat unless I give the command. However, it is with some level of shame that I must admit both armies have been attempting to harass the other with pranks, littering our respective camps with insults. Please, $p, we need someone both armies respect to collect these items before fighting breaks out.",starts={{npcID=114841,x=0.406,y=0.53,zoneID=7637}},ends={{npcID=114841,x=0.406,y=0.53,zoneID=7637}},coords={x=0.406,y=0.53,source="quest_giver",zoneID=7637},questType="standard"},
[44861] = {id=44861,name="Arming the Rebels",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=8025,description="The Nightfallen rebellion is growing in number, but they have not fought a real war in ages. Victoire and Silgryn are doing their best to train the new arrivals, but could use an experienced hand. Go to them and show them some of the skills in battle you have picked up in your travels. I want those Nightfallen ready for battle when the time comes.",starts={{npcID=114838,x=0.416,y=0.514,zoneID=7637}},ends={{npcID=116256,x=0.398,y=0.512,zoneID=7637}},coords={x=0.416,y=0.514,source="quest_giver",zoneID=7637},questType="standard"},
[44862] = {id=44862,name="Arming the Rebels",level=45,requiredLevel=45,faction="horde",expansion=6,zoneID=8025,description="The Nightfallen rebellion is growing in number, but they have not fought a real war in ages. Victoire and Silgryn are doing their best to train the new arrivals and could use an experienced hand. Go to them and show them some of the skills in battle you have picked up in your travels. We need those Nightfallen ready for battle when the time comes.",starts={{npcID=114841,x=0.406,y=0.53,zoneID=7637}},ends={{npcID=116256,x=0.398,y=0.512,zoneID=7637}},coords={x=0.406,y=0.53,source="quest_giver",zoneID=7637},questType="standard"},
[44863] = {id=44863,name="Clearing the Air",level=20,requiredLevel=20,faction="both",expansion=6,zoneID=3519,description="Ancient weapons require ancient offerings to regain the knowledge on how to construct them. If you wish to learn how weapons forged from air are crafted, then you must first battle with beings born from it. Bring me their cores and I will gift you the knowledge you seek.",starts={{npcID=115546,x=0.64,y=0.716,zoneID=3703}},ends={{npcID=115546,x=0.64,y=0.716,zoneID=3703}},coords={x=0.64,y=0.716,source="quest_giver",zoneID=3703},questType="standard"},
[44865] = {id=44865,name="Butler to the Great",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=41,description="A ghostly dinner party awaits, ready for the spread and its dinner guests.",starts={{npcID=115551,x=0.398,y=0.754,zoneID=41}},ends={{npcID=115438,x=0.4,y=0.742,zoneID=41}},coords={x=0.398,y=0.754,source="quest_giver",zoneID=41},questType="standard"},
[44868] = {id=44868,name="Trial of Valor: Odyn's Judgment",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=8440,description="You've proven worthy to challenge Helya. Now with my blessing, the power to defeat her is yours.",questType="raid"},
[44869] = {id=44869,name="Talon Terror",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=616,description="I just received word that the Shrine of Aviana is under attack by the Burning Legion! While the Druids of the Talon here are taking their time planning and strategizing their defense, our brothers and sisters are being slaughtered where they stand. I cannot stand idly by while my home shrine is in danger. Please, come with me to save my people.",starts={{npcID=106299,x=0.448,y=0.514,zoneID=7846}},ends={{npcID=115802,x=0.41,y=0.426,zoneID=616}},coords={x=0.448,y=0.514,source="quest_giver",zoneID=7846},questType="standard"},
[44870] = {id=44870,name="Mouths to Feed",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="We have rescued many refugees, as you can see. Unfortunately this has revealed a new problem. The arcan'dor fruit is our salvation, but it does not bear enough fruit right now to cure everyone. We must rely on mana a little longer to tide the refugees over. Valtrois thinks that she may have a solution. Please go speak with her and see what she plans to do.",starts={{npcID=115736,x=0.364,y=0.458,zoneID=7637}},ends={{npcID=115371,x=0.37,y=0.464,zoneID=7637}},coords={x=0.364,y=0.458,source="quest_giver",zoneID=7637},questType="standard"},
[44873] = {id=44873,name="Oculeth Ex Machina",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7334,description="I have a plan to feed Shal'Aran. Now that I am no longer starving for mana I have had time to study ley lines in new regions. I detected an eddy of mana in the ley lines of Azsuna. I have plenty of magic at my disposal, but we must visit the ley line in person in order to properly redirect the energy to Shal'Aran. Oculeth has graciously offered to teleport us there, but I could use an assistant. Care to join me?",starts={{npcID=115371,x=0.37,y=0.464,zoneID=7637}},ends={{npcID=115693,x=0.6,y=0.142,zoneID=7334}},coords={x=0.37,y=0.464,source="quest_giver",zoneID=7637},questType="standard"},
[44874] = {id=44874,name="Unbeleyvable",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7334,description="Back to the task at hand! Take these ley line taps . We can use the resonant energies to properly redirect the flow, but they must be placed in precise locations. I will show you where. Your friend has agreed to... \"supervise\" us. Let us hope she just stays out of the way while the professionals take care of this.",starts={{npcID=115693,x=0.6,y=0.142,zoneID=7334}},ends={{npcID=115693,x=0.6,y=0.142,zoneID=7334}},coords={x=0.6,y=0.142,source="quest_giver",zoneID=7334},questType="standard"},
[44875] = {id=44875,name="The Art of Flow",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7334,description="All done, ! We have but one more step and Shal'Aran will have all the mana it needs. Now that I have better access to the ley line below I can break the pool so that it will flow through properly. Given the chaotic state of this ley line it will require all of my concentration to redirect the energy. I must warn you that we will attract attention while I am doing this. You will need to protect me while I complete the process. Speak to me when you are ready.",starts={{npcID=115693,x=0.6,y=0.142,zoneID=7334}},ends={{npcID=115693,x=0.6,y=0.142,zoneID=7334}},coords={x=0.6,y=0.142,source="quest_giver",zoneID=7334},questType="standard"},
[44876] = {id=44876,name="A Dance With Dragons",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7637,description="I must say I am impressed, . You and your friend were able to fix a ley line, and you are not even dragons! You both seem exhausted by this ordeal. Allow me to help you get back home.",starts={{npcID=115701,x=0.598,y=0.14,zoneID=7334}},ends={{npcID=115736,x=0.364,y=0.458,zoneID=7637}},coords={x=0.598,y=0.14,source="quest_giver",zoneID=7334},questType="standard"},
[44877] = {id=44877,name="Attack on the Roost",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=616,description="Skylord Shadegrove has been leading the defense of the shrine, but I think he's starting to lose hope. Clearly he needs some more firepower behind him! Let's take out these demons and fend off the attack. They'll never see it coming!",starts={{npcID=115802,x=0.41,y=0.426,zoneID=616},{npcID=119982,x=0.409,y=0.425,zoneID=616}},ends={{npcID=119982,x=0.409,y=0.425,zoneID=616}},coords={x=0.41,y=0.426,source="quest_giver",zoneID=616},questType="standard"},
[44885] = {id=44885,name="Shipwrecked Survivors",level=45,requiredLevel=45,faction="horde",expansion=6,description="It appears that we have allies here on the Broken Shore. A small band of shipwrecked soldiers have been surviving here since the first assault. Their strength and tenacity will bolster our ranks. Make your way to their encampment along the beach and bring them here. Tell them that reinforcements have arrived, and the battle against the Burning Legion waits for no one.",questType="standard"},
[44888] = {id=44888,name="Aviana's Grace",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=616,description="If this was only the distraction, where is the main force? Who else is under attack? We need to figure out who else is in danger! Aviana should know, she's got eyes everywhere. Let's go ask her. We should be able to contact her in the back room.",starts={{npcID=119982,x=0.409,y=0.425,zoneID=616}},ends={{npcID=115749,x=0.442,y=0.478,zoneID=616}},coords={x=0.409,y=0.425,source="quest_giver",zoneID=616},questType="standard"},
[44889] = {id=44889,name="Resource Management",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7543,description="Now that you possess Helya's Horn, the kvaldir are yours to command. We may as well put them to good use for a change. I've dispatched my Val'kyr, Danica, to the Broken Shore. She has identified a few Legion targets that should be eliminated. Aerylia will send you there when you are ready to leave.",ends={{npcID=116858,x=0.698,y=0.348,zoneID=7543}},questType="standard"},
[44896] = {id=44896,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=16,mapID=76,questType="standard"},
[44897] = {id=44897,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=16,mapID=76,questType="standard"},
[44898] = {id=44898,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=16,mapID=76,questType="standard"},
[44899] = {id=44899,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=16,mapID=76,questType="standard"},
[44900] = {id=44900,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=16,mapID=76,questType="standard"},
[44901] = {id=44901,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=16,mapID=76,questType="standard"},
[44902] = {id=44902,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=16,mapID=76,questType="standard"},
[44903] = {id=44903,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=16,mapID=76,questType="standard"},
