[45643] = {id=45643,name="Lean Shanks",level=1,requiredLevel=1,faction="horde",expansion=6,zoneID=1377,starts={{npcID=117432,x=0.34,y=0.818,zoneID=1377}},ends={{npcID=117432,x=0.34,y=0.818,zoneID=1377}},coords={x=0.34,y=0.818,source="quest_giver",zoneID=1377},questType="standard"},
[45644] = {id=45644,name="Oh Doloria, My Sweet Doloria",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,description="What ho! We are quite the dashing pair of adventurers, aren't we? Now that we have secured my belongings, a new path unfolds before us. I did not journey here simply to thwart the demon invasion, no! I came here in search of my beloved, my loved, Doloria . Whilst resting between slaying of dragons, I had a dream, nay, a vision. It told me Doloria had been kidnapped and taken to a floating city in the sky! It must be Dalaran . Quickly, squire! Mount up and meet me at Dalaran 's famous inn. Make haste!",starts={{npcID=118009,x=0.558,y=0.162,zoneID=7503}},coords={x=0.558,y=0.162,source="quest_giver",zoneID=7503},questType="standard"},
[45645] = {id=45645,name="A Fool's Errand",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7503,description="Oh yea sure, I'm, um, held here against my, you know, will, or something. Look bud, between you and me old Max here has no chance, but his heart is in the right place. I keep trying to run away and hide but he keeps finding me! I just don't have it in me to upset him with the truth. I've got an idea. Why don't you go kill some of those really big two headed \"Hill Bandits\" for me. Let's say they stole some jewelery from me, and you can use it to buy my freedom. Take your time, don't get hurt. Much.",questType="standard"},
[45648] = {id=45648,name="Missing in Action: Lord Darius Crowley",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=7543,description="Are you familiar with Lord Darius Crowley ? He is the worthy Gilnean warrior who was leading our forces against the Felrage naga nearby. Unfortunately the naga captured many of our soldiers during a recent skirmish. Lord Darius went after them and has not returned. I fear something terrible has happened to him. Please try to find him!",starts={{npcID=116858,x=0.698,y=0.348,zoneID=7543}},coords={x=0.698,y=0.348,source="quest_giver",zoneID=7543},questType="standard"},
[45652] = {id=45652,name="A \"Humble\" Request",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7745,description="t, we've received a... visitor. She orders entry, but the guards will not let her pass without approval. Please head up to the overlook as soon as you are able.",starts={{npcID=96746,x=0.33,y=0.6,zoneID=7745}},ends={{npcID=117482,x=0.354,y=0.76,zoneID=7745}},coords={x=0.33,y=0.6,source="quest_giver",zoneID=7745},questType="standard"},
[45706] = {id=45706,name="The Power of Thousands",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=400,description="I know I am not well liked here, and my Grimtotem and I were not invited to join you and your shaman here. However, I come to you with a proposition. The Legion is attacking my home. I've lost possession of some things that are... dear to me, and I have nowhere else to turn to. It pains me to ask... but I request your aid. If you help, I offer my people in service against the Legion.",starts={{npcID=117482,x=0.354,y=0.76,zoneID=7745}},ends={{npcID=120244,x=0.422,y=0.452,zoneID=400}},coords={x=0.354,y=0.76,source="quest_giver",zoneID=7745},questType="standard"},
[45723] = {id=45723,name="The Crone's Wrath",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=400,description="These demons come into my home, take my things, and capture my people? They will see my wrath. Destroy them, child. Surely you are capable of at least that.",starts={{npcID=120244,x=0.422,y=0.452,zoneID=400}},ends={{npcID=120244,x=0.422,y=0.452,zoneID=400}},coords={x=0.422,y=0.452,source="quest_giver",zoneID=400},questType="standard"},
[45724] = {id=45724,name="Snakes and Stones",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=400,description="When the demons attacked, they captured two very powerful possessions of mine: my companion Arikara and the Doomstone . While death matters not to Arikara, the Legion surely has ulterior plans for him. And the Doomstone ... such an artifact of power belongs in my hands, not theirs. We must split up to find them. For the world's sake, do be careful. I don't need you clumsily destroying everything.",starts={{npcID=120244,x=0.422,y=0.452,zoneID=400}},ends={{npcID=120244,x=0.422,y=0.452,zoneID=400}},coords={x=0.422,y=0.452,source="quest_giver",zoneID=400},questType="standard"},
[45725] = {id=45725,name="Breaking Chains",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=400,description="The Legion shall not make fools of the Grimtotem. Free my people, and we will grace you with our aid in the coming battle.",starts={{npcID=120244,x=0.422,y=0.452,zoneID=400}},ends={{npcID=120244,x=0.422,y=0.452,zoneID=400}},coords={x=0.422,y=0.452,source="quest_giver",zoneID=400},questType="standard"},
[45726] = {id=45726,name="The Tainted Marsh",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7503,description="I wasn't able to scout inside the village yet, however, there are more dangerous experiments going on to the south. They were befouling the unquiet spirits in the marshlands with more fel magic! I will rework this fel totem to draw out the fel energies they infused in those spirits. Please, cure what spirits you can, perhaps it will even give them some peace. If you want, I can even send you there!",starts={{npcID=117249,x=0.312,y=0.25,zoneID=7503}},ends={{npcID=117249,x=0.312,y=0.25,zoneID=7503}},coords={x=0.312,y=0.25,source="quest_giver",zoneID=7503},questType="standard"},
[45727] = {id=45727,name="Uniting the Isles",level=10,requiredLevel=10,faction="both",expansion=6,zoneID=7502,description="There are a great number of factions here on the Broken Isles. We must unite them if we want to stand a chance against the Legion. Prove your worth to them and report back to me.",questType="standard"},
[45729] = {id=45729,name="Sandworm Meat",level=1,requiredLevel=1,faction="alliance",expansion=6,zoneID=1377,starts={{npcID=117434,x=0.34,y=0.804,zoneID=1377}},ends={{npcID=117434,x=0.34,y=0.804,zoneID=1377}},coords={x=0.34,y=0.804,source="quest_giver",zoneID=1377},questType="standard"},
