[45747] = {id=45747,name="Cinder of Cynders",level=1,requiredLevel=1,faction="horde",expansion=6,zoneID=1377,description="The cinder seethes with the hatred that its former owner held for you.",ends={{npcID=117433,x=0.34,y=0.818,zoneID=1377}},questType="standard"},
[45748] = {id=45748,name="Pearl of Fathoms",level=1,requiredLevel=1,faction="horde",expansion=6,zoneID=1377,description="The pearl is immaculately smooth, and surprisingly dense.",ends={{npcID=117433,x=0.34,y=0.818,zoneID=1377}},questType="standard"},
[45749] = {id=45749,name="Salt of Shards",level=1,requiredLevel=1,faction="horde",expansion=6,zoneID=1377,description="The Abyssal Lord left behind a small pile of faintly-iridescent sand.",ends={{npcID=117433,x=0.34,y=0.818,zoneID=1377}},questType="standard"},
[45750] = {id=45750,name="Song of Zephyrs",level=1,requiredLevel=1,faction="horde",expansion=6,zoneID=1377,description="A swirling essence coalesces at the feet of the Duke.",ends={{npcID=117433,x=0.34,y=0.818,zoneID=1377}},questType="standard"},
[45751] = {id=45751,name="Coreforged Sigil of Skaldrenox",level=1,requiredLevel=1,faction="horde",expansion=6,zoneID=1377,description="The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was forged in flame.",ends={{npcID=117433,x=0.34,y=0.818,zoneID=1377}},questType="standard"},
[45752] = {id=45752,name="Glimmering Sigil of Whirlaxis",level=1,requiredLevel=1,faction="horde",expansion=6,zoneID=1377,description="The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was carved with biting winds.",ends={{npcID=117433,x=0.34,y=0.818,zoneID=1377}},questType="standard"},
[45753] = {id=45753,name="Diamondine Sigil of Kazum",level=1,requiredLevel=1,faction="horde",expansion=6,zoneID=1377,description="The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was carved from stone, then fused into a faultless diamond.",ends={{npcID=117433,x=0.34,y=0.818,zoneID=1377}},questType="standard"},
[45754] = {id=45754,name="Tidal Sigil of Skwol",level=1,requiredLevel=1,faction="horde",expansion=6,zoneID=1377,description="The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was crafted from coral and smoothed by the tides.",ends={{npcID=117433,x=0.34,y=0.818,zoneID=1377}},questType="standard"},
