[45873] = {id=45873,name="Champion: Eitrigg",level=45,requiredLevel=45,faction="horde",expansion=6,zoneID=7813,mapID=695,questType="standard"},
[45876] = {id=45876,name="Champion: Lord Darius Crowley",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=7813,mapID=695,questType="standard"},
[45883] = {id=45883,name="The Firelord's Offense",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7543,description="Smolderon calls from across the battlefield, shaman. Now it is his realm being violated. It seems urgent. I will clean up here.",starts={{npcID=117715,x=0.604,y=0.516,zoneID=7543}},ends={{npcID=115492,x=0.546,y=0.524,zoneID=7543}},coords={x=0.604,y=0.516,source="quest_giver",zoneID=7543},questType="standard"},
[45890] = {id=45890,name="Ancestors and Enemies",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7558,description="I want nothing more than to prove myself by joining our offensive on the Broken Shore, but I'm beginning to doubt my worthiness. You see, I found my family's sigil among the demonic runes I've been deciphering. Why the Moonfang crest would be known to the Legion is a mystery to me, but I trust you'll be able to find what connection lies between my ancestors and my enemies. What's left of their village can be found in Val'sharah.",ends={{npcID=119209,x=0.668,y=0.534,zoneID=7558}},questType="standard"},
[45902] = {id=45902,name="The Imp Mother's Gift",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=7502,description="While we have already given you what power we can, we would like to present to you a... cosmetic... upgrade to your artifact. On behalf of the Council of Six, Dalaran, and Azeroth, we thank you again, .",questType="standard"},
[45904] = {id=45904,name="The God-Queen's Gift",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,description="While we have already given you what power we can, we would like to present to you a... cosmetic... upgrade to your artifact. On behalf of the Council of Six, Dalaran, and Azeroth, we thank you again, .",questType="standard"},
