[45915] = {id=45915,name="The Folly of Levia Laurance",level=45,requiredLevel=45,faction="none",expansion=6,description="Levia Laurance was once a member of the Kirin Tor, long ago, and a good friend. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good. Levia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous for all of us if her knowledge fell into their hands. She was last seen at the Militant Mystic. Ask around there and see if you can pick up her trail.",questType="standard"},
[45916] = {id=45916,name="The Acolyte Imperiled",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7502,description="Truthfully, the Council knows little of Agatha, but she is more than just your average succubus. She has many allies within the sayaad, and is known to command armies of imps that swarm and overwhelm her foes. To seek her out is folly, but Ritssyn Flamescowl repays his debts. Come, let us examine what manner of fel powers this little mage of yours was stumbling her way through...",questType="standard"},
[45917] = {id=45917,name="Following the Scent",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7334,description="You will have to continue through the portal without me, . I have assisted you in locating your mage's whereabouts, so I consider my debt to Modera paid. However, I will lend you one of my felhounds to help track this mage down. If she is as powerful as Modera says, then it would be in everyone's best interest that Agatha not be allowed to keep her. Best of luck, , and try to bring Fhambar back in one piece.",ends={{npcID=116189,x=0.256,y=0.576,zoneID=7334}},questType="standard"},
[45971] = {id=45971,name="Infernal Phenomena",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7543,description="Do you hear that, shaman? The rumble of the earth as it tries to fight against the Legion's will. Their half-witted eredar are attempting to bend the forces of Azeroth to their will. How dare the Legion think they can corrupt my domain? They have assembled their infernals from Azeroth's stone - MY stone! Now they try to bring these new infernals to life. Sabotage their foolish rituals. Crush them! Show them Azeroth's true power!",starts={{npcID=117715,x=0.604,y=0.516,zoneID=7543}},ends={{npcID=117715,x=0.604,y=0.516,zoneID=7543}},coords={x=0.604,y=0.516,source="quest_giver",zoneID=7543},questType="standard"},
[45975] = {id=45975,name="Investigate the Broken Shore",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=139,mapID=23,description="All of us know the price we paid the last time we set foot upon the Broken Shore. I recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.",questType="standard"},
[45987] = {id=45987,name="Investigate the Broken Shore",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7813,description="All of us know the price we paid the last time we set foot upon the Broken Shore. I recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.",questType="standard"},
[45989] = {id=45989,name="An Urgent Warning",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7875,description="Been held prisoner... since the assault on... the Broken Shore... The demons... th-they are gathering... preparing... Had to escape... to warn you. They must... be stopped!",starts={{npcID=118423,x=0.586,y=0.372,zoneID=7875}},ends={{npcID=106199,x=0.666,y=0.46,zoneID=7875}},coords={x=0.586,y=0.372,source="quest_giver",zoneID=7875},questType="standard"},
