[45999] = {id=45999,name="The Legion Assault",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7541,mapID=634,questType="standard"},
[46000] = {id=46000,name="Arming Dalaran",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7879,description="Kathra'natir is powerless to stop us from harnessing his energy within the Nightborne Soulstone. We have been lucky thus far - our allies have kept news of the sabotage from spreading. We should repair Dalaran's weapons array immediately while luck is still on our side. Oh - the weapon platform is a bit inaccessible. I trust you are not afflicted by a fear of heights? I will open a portal.",questType="standard"},
[46002] = {id=46002,name="The Legion Assault - Viewed",level=0,requiredLevel=0,faction="both",expansion=6,zoneID=7541,mapID=634,questType="standard"},
[46020] = {id=46020,name="Crystal Containment",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7875,description="Kanrethad will be safe in my care, but something must be done about these crystals that hold his fel magic. If any should break, the energy inside would find its way back to our friend. I shouldn't need to tell you how devastating it would be if that were to happen. I will gather the crystals and meet you back at Dreadscar Rift.",starts={{npcID=115863,x=0.304,y=0.446,zoneID=7334},{npcID=115863,x=0.812,y=0.496,zoneID=7543}},ends={{npcID=105922,x=0.566,y=0.342,zoneID=7875}},coords={x=0.304,y=0.446,source="quest_giver",zoneID=7334},questType="standard"},
[46023] = {id=46023,name="Investigate the Broken Shore",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7877,description="All of us know the price we paid the last time we set foot upon the Broken Shore. I recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.",starts={{npcID=103023,x=0.43,y=0.468,zoneID=7877}},ends={{npcID=103023,x=0.43,y=0.468,zoneID=7877}},coords={x=0.43,y=0.468,source="quest_giver",zoneID=7877},questType="standard"},
