[46035] = {id=46035,name="End of the Risen Threat",level=45,requiredLevel=45,faction="alliance",expansion=6,zoneID=7502,description="Commander Shadowsong sends word that he is prepared to face the late Lord Erdris. I have a letter from him for you. I'm prepared to teleport you to his location, but there's a snag. In order to combat the worst of the fel corruption, you will need to use some Nethershards on the way in. Make sure you have some before speaking with me.",starts={{npcID=117871,x=0.456,y=0.622,zoneID=7543}},coords={x=0.456,y=0.622,source="quest_giver",zoneID=7543},questType="standard"},
