[46060] = {id=46060,name="Salvation",level=45,requiredLevel=45,faction="both",expansion=6,zoneID=7543,description="The valley is swarming with fel-corrupted creatures who are beyond saving, yet there still may be some that could use our help. Take this manaroot salve and apply it to any animals you see. If the fel magic hasn't taken hold, the salve might be able to mend their wounds.",starts={{npcID=119097,x=0.508,y=0.306,zoneID=7543}},ends={{npcID=119097,x=0.508,y=0.306,zoneID=7543}},coords={x=0.508,y=0.306,source="quest_giver",zoneID=7543},questType="standard"},
