[46064] = {id=46064,name="The Ways of the World",level=1,requiredLevel=1,faction="both",expansion=6,zoneID=3537,description="Mrrga ! Mrrga ... Mrrga ...",starts={{npcID=118575,x=0.428,y=0.128,zoneID=3537},{npcID=118577,x=0.434,y=0.136,zoneID=3537},{npcID=118578,x=0.424,y=0.132,zoneID=3537},{npcID=118579,x=0.432,y=0.128,zoneID=3537},{npcID=118580,x=0.424,y=0.132,zoneID=3537},{npcID=118582,x=0.434,y=0.136,zoneID=3537},{npcID=118583,x=0.424,y=0.132,zoneID=3537},{npcID=118584,x=0.436,y=0.134,zoneID=3537},{npcID=118586,x=0.434,y=0.134,zoneID=3537},{npcID=118587,x=0.434,y=0.134,zoneID=3537},{npcID=118589,x=0.434,y=0.134,zoneID=3537},{npcID=118590,x=0.434,y=0.138,zoneID=3537},{npcID=118592,x=0.428,y=0.134,zoneID=3537},{npcID=118594,x=0.422,y=0.132,zoneID=3537},{npcID=118595,x=0.434,y=0.134,zoneID=3537},{npcID=118596,x=0.434,y=0.138,zoneID=3537},{npcID=118597,x=0.428,y=0.128,zoneID=3537},{npcID=118598,x=0.422,y=0.13,zoneID=3537},{npcID=118599,x=0.422,y=0.134,zoneID=3537},{npcID=118600,x=0.434,y=0.134,zoneID=3537},{npcID=118601,x=0.426,y=0.132,zoneID=3537},{npcID=118602,x=0.434,y=0.136,zoneID=3537},{npcID=118603,x=0.436,y=0.136,zoneID=3537},{npcID=118605,x=0.436,y=0.134,zoneID=3537}},ends={{npcID=118571,x=0.436,y=0.134,zoneID=3537},{npcID=118575,x=0.428,y=0.128,zoneID=3537},{npcID=118577,x=0.434,y=0.136,zoneID=3537},{npcID=118578,x=0.424,y=0.132,zoneID=3537},{npcID=118579,x=0.432,y=0.128,zoneID=3537},{npcID=118580,x=0.424,y=0.132,zoneID=3537},{npcID=118582,x=0.434,y=0.136,zoneID=3537},{npcID=118583,x=0.424,y=0.132,zoneID=3537},{npcID=118584,x=0.436,y=0.134,zoneID=3537},{npcID=118586,x=0.434,y=0.134,zoneID=3537},{npcID=118587,x=0.434,y=0.134,zoneID=3537},{npcID=118589,x=0.434,y=0.134,zoneID=3537},{npcID=118590,x=0.434,y=0.138,zoneID=3537},{npcID=118591,x=0.432,y=0.136,zoneID=3537},{npcID=118592,x=0.428,y=0.134,zoneID=3537},{npcID=118594,x=0.422,y=0.132,zoneID=3537},{npcID=118595,x=0.434,y=0.134,zoneID=3537},{npcID=118596,x=0.434,y=0.138,zoneID=3537},{npcID=118597,x=0.428,y=0.